INSERT INTO `quest_steps` (`Id`, `QuestId`, `Name`, `Description`, `DialogId`, `OptimalLevel`, `Duration`, `ObjectiveIds`, `RewardIds`) VALUES
(55, 18, 'Le sang du wabbit GM', 'Wogew a besoin que vous préleviez le sang d\'un Wabbit un peu particulier à l\'aide d\'une seringue.', 11404, 70, 1, '102,115', '6529'),
(57, 18, 'Analyse de sang', 'Quelqu\'un doit analyser le sang du Wabbit GM.', -1, 70, 1, '104', '6531'),
(58, 18, 'Wogew Wabbit', 'Il ne reste plus qu\'à retourner voir Wogew avec l\'analyse de sang.', -1, 70, 1, '105', '6532'),
(74, 26, 'Le sous-sol de la Bibliothèque', 'Dans ce sous-sol, comme dans la plupart des sous-sols des bibliothèques, vous trouverez toutes sortes de livres ainsi que des toiles d\'araknes... mais l\'atmosphère qui règne en ces lieux est quelque peu mystérieuse...', -1, 50, 2, '133,330', '6038'),
(80, 26, 'Souterrain ténébreux', 'Une porte dérobée dans la montagne donne accès à un souterrain, encore faut-il trouver comment...', -1, 50, 2, '146,331', '6476'),
(81, 26, 'Souterrain mystérieux', 'Une dalle perchée en haut d\'une montagne et une porte dérobée... il va falloir trouver des volontaires pour arriver au bout de cette galerie...', -1, 50, 2, '147,332', '6477'),
(109, 35, 'On recherche Ogivol Scalarcin', 'Ogivol a été aperçu dans la Bordure de Brâkmar. Il est recherché pour avoir dérobé une foultitude de choses, et notamment des documents secrets.\nIl est condamné à l\'emprisonnement à Astrub.', -1, 50, 1, '313,205', '5360'),
(111, 34, 'On recherche Fouduglen l\'écureuil', 'Fouduglen parcourt la ville d\'Astrub à la recherche des glands succulents à se mettre sous la dent.', -1, 20, 1, '207,208', '5359'),
(113, 33, 'On recherche Brumen Tinctorias', 'Certains disent l\'avoir vu du côté de la Désolation de Sidimote. Il est recherché pour insoumission à l\'ordre cosmique.\nBrumen Tinctorias est condamné à l\'emprisonnement à Astrub.', -1, 60, 1, '209,210', '5358'),
(115, 32, 'On recherche Qil Bil', 'Certains disent avoir vu Qil Bil dans les environs du Cimetière des Torturés.\nQil Bil est recherché pour arrachage de membres.\nIl est condamné à l\'emprisonnement à Astrub.', -1, 70, 1, '310,312', '5357'),
(119, 30, 'On recherche Frakacia Leukocytine', 'Certains disent avoir vu Frakacia Leukocytine du côté de la Forêt d\'Astrub.\nElle est recherchée pour ponctions illégales d\'hémoglobine.\nCondamnée à l\'emprisonnement à Astrub.', -1, 30, 1, '213,214', '5356'),
(121, 29, 'On recherche Padgref Demoël', 'Il est probable que Padgref Demoël se trouve du côté du Bois de Litneg.\nIl est condamné à l\'emprisonnement à Astrub pour détérioration de Bouftou domestique et tapage nocturne.', -1, 130, 1, '215,216', '5355'),
(163, 26, 'Souterrain impénétrable', 'Gare au Dragoeuf ! Il va falloir traverser leur territoire pour accéder à cette nouvelle grotte...', -1, 50, 2, '333,334', '6500'),
(164, 26, 'Souterrain hasardeux', 'Ce souterrain risque de vous faire perdre patience !', -1, 50, 2, '335,336', '6501'),
(195, 109, 'Apprentissage : Écuyer', 'Des Brâkmariens ont détruit des greniers bontariens. Il faut  trouver un moyen de ravitailler les montures de la milice en allant trouver une solution auprès de Merlan, à l\'atelier des alchimistes.', 2834, 100, 1, '413,1639,1640,1641,1642,2948,1643,2947,2965,1644', '6446'),
(196, 110, 'Dans la peau d\'un espion', 'Suite à l\'incendie d\'entrepôts de nourriture par les Brâkmariens, Ebru of El veut savoir ce que les ennemis manigancent.', 21440, 100, 1, '1667,1668,1669,1670,1671,1672,1673,2967', '6447'),
(197, 111, 'Levez-vous et marchez', 'Elviana Tirips veut interroger les renégats bontariens mais avant de pouvoir le faire il faut les ressusciter.', 2841, 100, 1, '2946,412,1649,1650,1651,1652,1653', '6448'),
(199, 114, 'Lève-toi et marche', 'Divad ne parvient pas à ressusciter Terra Tibya pour l\'interroger. Il faut donc improviser un sort de résurrection qui en soit capable et c\'est la mission qui vous a été confiée.', 2866, 100, 1, '415,1634,1635,1636,1637,1638', '6450'),
(200, 112, 'Brâkmariens bras cassés', 'Les agents brâkmariens étant des incapables, Kaffra vous a demandé de vous rendre à Astrub et de convaincre le marchand bontarien Raymond Santho de ravitailler Brâkmar.', 21425, 100, 1, '416,2950,2951,2952,2949,1628,1629', '6237'),
(201, 115, 'On recherche Rok Gnorok', 'Rok a été aperçu dans les lacs enchantés.\nIl est condamné à l\'emprisonnement à Astrub.', -1, 90, 1, '421,422', '5361'),
(202, 116, 'On recherche Musha l\'Oni', 'Musha a été aperçu dans la baie de Cania.\nIl est condamné à l\'emprisonnement à Astrub.', -1, 80, 1, '423,424', '5362'),
(203, 117, 'On recherche Marzwel le Gobelin', 'Marzwel a été aperçu dans le massif de Cania.\nIl est condamné à l\'emprisonnement à Astrub.', -1, 60, 1, '425,426', '5363'),
(204, 118, 'On recherche Zatoïshwan', 'Zatoïshwan a été aperçu du côté de Feudala. \nIl est condamné à l\'emprisonnement à Astrub.', -1, 150, 1, '428,429', '5364'),
(206, 119, 'On recherche Aermyne \'Braco\' Scalptaras', 'Aermyne a été aperçue du côté de la forêt de Kalyptus.\nElle est condamnée à l\'emprisonnement à Astrub.', -1, 80, 1, '431,432', '5365'),
(208, 113, 'Le pont vers Terra Tibya', 'Ledrob Terceséc veut mettre la main sur les statuettes de Sumens.', 5661, 100, 1, '433,1674,1675,1676,1677,2957,2972,2961,1678,1679', '6253'),
(209, 124, 'Le secret de Terra Tibya', 'Terra Tibya est enfin ressuscitée. Reste à la persuader de vous révéler son secret.', 5649, 140, 2, '434,1664,1665,2968,2969,1666', '6454'),
(210, 123, 'À cœur saignant, rien d\'impossible', 'Vous devez vous emparer des statuettes symboles des biens et des maux de l\'humanité et les remettre à Kaffra. Elles sont cachées dans une mine abandonnée près du temple Enutrof.', 5647, 140, 2, '435,436', '6282'),
(211, 26, 'Souterrain rigoureux', 'Seul huit courageux aventuriers seront capables de venir à bout de ce souterrain !', -1, 50, 2, '446,447', '37'),
(224, 132, 'Des planches pour la charpente', 'Ramenez des planches à Kartier Tremai pour finir les toits du château d\'Allister.', 3057, 30, 1, '469', '6465'),
(225, 132, 'Des cailloux pour boucher les trous', 'Ramenez des pierres de granit à Kartier Tremai pour finir les murs du château d\'Allister.', 3058, 30, 1, '470', '6466'),
(226, 132, 'Du blé pour les ouvriers', 'Ramenez du blé à Kartier Tremai pour qu\'il nourrisse ses ouvriers.', 3059, 30, 1, '471', '6467'),
(227, 132, 'De la bonne viande', 'Ramenez des boulettes de viande à Kartier Tremai pour qu\'il nourrisse ses ouvriers.', 3060, 30, 1, '472', '41'),
(228, 133, 'Une belle table', 'Kartier Tremai veut épater sa future fiancée avec une belle table bien garnie.', 3064, 40, 2, '473,474,475,477,478,630', '6468'),
(229, 133, 'Un anneau au dessert', 'Kartier Tremai veut une bague de fiançailles.', 3065, 40, 2, '479', '6383'),
(230, 133, 'Une bague pour Monabella', 'Kartier Tremai veut inviter Monabella à son repas pour la demander en fiançaille.', 3066, 40, 2, '480,486', '6384'),
(231, 133, 'Kartier Tremai se rabat sur Verumacha', 'Il invite Verumacha à partager son dîner.', 3067, 40, 2, '481,487', '6385'),
(232, 133, 'Kartier Tremai préfère trinquer avec un ami', 'Il lui faut de la bière et un ami pour passer une bonne soirée.', 3068, 40, 2, '482,483', '42'),
(235, 134, 'Le sillage', 'Verumacha recherche un requin.', 3074, 20, 2, '488,489', '6387'),
(236, 134, 'Le vrai requin', 'Verumacha veut que je chasse le \"requiem\" du port.', 3076, 20, 2, '491', '6565'),
(237, 134, 'Les dents longues de la corruption', 'Le requin offre des Kamas à Verumacha.', 3081, 20, 2, '492,493,494', '6388'),
(238, 134, 'Dents de lait', 'Verumacha a envie d\'un peu de lait.', 3078, 20, 2, '495', '44'),
(239, 134, 'Le sourire du requin', 'Squale est content de la tournure des événements.', -1, 20, 2, '496', '45'),
(240, 135, 'Les ingrédients de la potion de lèche-bottes', 'Corne de Chef de Guerre Bouftou, Pétale de Rose Démoniaque, Kralamoure vidé et Graine de Pavot sont nécessaires pour réaliser une bonne potion de lèche-bottes.', 3164, 25, 2, '497,498,500,503', '5820'),
(241, 135, 'Une potion de lèche-bottes pour une laitchieuse', 'Il faut livrer la potion à Monabella.', 3085, 25, 2, '504,505', '6389'),
(242, 135, 'Une potion de lèche-bottes pour une affaire juteuse', 'Haraquiri voudra peut être de la potion pour ses affaires avec Allister.', 3086, 25, 2, '506,507', '46'),
(243, 136, 'Brasser la mousse', 'Guedin Loursgro a besoin de boire de la bière pour affronter le requin.', 3092, 30, 2, '509,510,511,512,513', '6390'),
(244, 136, 'De l\'eau dans le houblon', 'Guedin Loursgro a mal à la tête à force de mélanger les bières.', 3097, 30, 2, '514', '6391'),
(245, 136, 'Un peu de bière', 'Le docker boirait bien un coup pour se remonter le moral.', 3092, 30, 2, '515', '6392'),
(246, 137, 'Prison  et agence immobilière', 'Monabella aimerait récupérer l\'ancienne planque d\'un taulard pour l\'aménager à son goût.', 3102, 60, 2, '516,517', '6343'),
(247, 137, 'Paillote', 'Monabella veut une maison isolée loin de la cour.', 3103, 60, 2, '518,519', '6393'),
(248, 137, 'Monture et huile pour les vacances', 'Monabella a besoin d\'une dragodinde et d\'huile de tournesol pour partir se reposer au soleil dans sa future paillote.', 3104, 60, 2, '520,521', '6394'),
(249, 137, 'Un chacha pour une chieuchieuse', 'Monabella veut un chacha noir... Il paraît que ce genre de créature aime se faire les griffes sur la laine des bouftous de Tainéla.', 3105, 60, 2, '522', '47'),
(250, 138, 'Trafic de patates', 'Il faut livrer des sacs de patates à la prison du port.', 3113, 20, 1, '523', '6395'),
(251, 138, 'Une pelle à patates', 'Gemfé Labelle voudrait cultiver lui-même des patates pour son petit plaisir personnel.', 1564, 20, 1, '524', '48'),
(252, 138, 'Pauvre pomme', 'Gemfé veut que l\'on remercie Rocco Fidelio pour ses patates.', 3111, 20, 1, '525', '6396'),
(253, 139, 'Steaks de Dragodinde', 'Haraquiri, le boucher officiel d\'Allister a besoin de chair fraîche.', 3053, 55, 1, '526', '49'),
(259, 143, 'Au service du roi', 'Le roi aime monter, il faut lui trouver des dragodindes', 3308, 60, 1, '541', '52'),
(260, 144, 'Cavalerie légère', 'Vous avez décidé de fournir une monture fraîche à la milice.', 3315, 60, 1, '543', '53'),
(261, 145, 'Des bourrins pour les bourrins', 'Le milicien a été clair, il lui faut des dragodindes, et vite !', 3318, 60, 1, '544', '54'),
(262, 146, 'Cartographier la région des montagnes Koalak', 'Piélant le cartographe n\'est plus assez jeune pour les voyages lointains.', 3322, 40, 2, '545,546,547,548,549,550', '55'),
(263, 147, 'Une récolte facile', 'Des Orchidées poussent dans les montagnes Koalaks. Il faut en rapporter une bonne brassée à Maskara.', 11403, 40, 1, '551', '56'),
(264, 148, 'Une liste chargée', 'Koka Dekolak a besoin de plusieurs matières premières bien précises.', 12887, 65, 2, '553,554,555', '57'),
(265, 149, 'Une livraison alambiquée', 'Koka Dekolak veut encore des ressources bien particulières. Elles se trouvent en territoire Koalak.', 12886, 65, 2, '558,559,560,3515,3516', '58'),
(266, 150, 'Une dernière course pour Koka', 'Koka a encore une fois besoin de vos services de récolteur.', 12888, 85, 2, '562,563,564', '59'),
(271, 153, 'Poursuivre l\'aventure', 'Vous devez continuer à montrer votre détermination : allez promener votre carcasse dans le donjon des Squelettes.', 3371, 40, 2, '578,5481,579', '6401'),
(272, 153, 'Poursuivre l\'aventure', 'Vous devez continuer à montrer votre détermination : le donjon des Tofus vous attend.', 3371, 40, 2, '580,5482,581', '6402'),
(273, 154, 'Pour le titre', 'Pat vous sert d\'arbitre pour cette partie de la quête.', 3380, 40, 2, '582,5483,583', '6403'),
(274, 154, 'Pour le titre', 'Pat vous sert d\'arbitre pour ce round.', 3380, 50, 2, '584,5484,585', '6404'),
(275, 154, 'Pour le titre', 'Pat va juger de vos capacités.', 3380, 50, 2, '586,5485,587', '6405'),
(276, 154, 'Pour le titre', 'Pat vous observe de près.', 3380, 50, 2, '588,5486,589', '6406'),
(277, 154, 'Pour le titre', 'Pat a les yeux braqués sur vous.', 3380, 50, 2, '590,5487,591', '6407'),
(278, 154, 'Pour le titre', 'Pat ne vous quitte pas des yeux', 3380, 70, 2, '592,5488,593', '6408'),
(279, 154, 'Passer à la suite', 'Pat Akess vous a dirigé vers la personne suivante qui peut vous aider à prouver votre valeur.', -1, 70, 2, '594', '6409'),
(280, 153, 'Passer à la suite', 'Le Maître des clefs vous a envoyé voir le premier de ses amis.', 3371, 40, 2, '595', '6410'),
(282, 155, 'Allez voir ailleurs', 'Chris est très légèrement stressé. Mieux vaut faire rapidement ce qu\'il demande.', 3389, 90, 2, '597,5489,598', '6412'),
(283, 155, 'Ne pas traîner', 'Chris ne va pas mieux, il est préférable de se dépêcher avant que son état empire.', 3389, 100, 2, '599,5490,600', '6413'),
(284, 155, 'Vite vite vite', 'Malgré ses états d\'âme, Chris vous permet d\'aller plus avant dans votre chasse à la relique.', 3389, 100, 2, '601,5491,602', '6414'),
(285, 155, 'Un vrai défi', 'Chris vous envoie dans des endroits de plus en plus dangereux.', 3389, 100, 2, '603,5492,604', '6415'),
(286, 155, 'Encore un', 'Vous sentez que votre quête avance... lentement.', 3389, 110, 2, '605,5493,606', '6416'),
(287, 155, 'La der des der ?', 'Vous avez cru comprendre que c\'était votre dernière bataille avant la victoire.', 3389, 110, 2, '607,5494,608', '6417'),
(288, 155, 'Une simple étape', 'Malgré l\'âpreté des combats que vous avez dû livrer, ils n\'étaient qu\'une simple étape.', 3389, 110, 2, '609', '6418'),
(289, 156, 'Un message très clair', 'Kal, une sorte de machine, vous aide à poursuivre votre quête. Avec lui au moins, les objectifs sont clairs.', 3398, 110, 2, '610,5495,611', '6419'),
(290, 156, 'Des problèmes ?', 'Kal n\'a pu vous transmettre l\'intégralité de son message mais avec la clef vous devinez aisément ce que vous devez faire.', 3398, 120, 2, '612,5496,613', '6420'),
(291, 156, 'Défaillance technique', 'Kal n\'a pas résolu ses problèmes mais cela ne vous empêche pas de poursuivre votre quête.', 3398, 120, 2, '614,5497,615', '6421'),
(295, 156, 'Il manque un boulon', 'Kal reste bloqué mais vous donne les clefs.', 3398, 120, 2, '616,5498,617', '6422'),
(296, 156, 'La dernière clef', 'Kal vous a remis la dernière de ses clefs. Vous approchez du but.', 3398, 120, 2, '618,5499,619', '6423'),
(297, 156, 'Consécration ?', 'Kal n\'a plus rien à vous confier. Retournez voir le Maître des clefs.', -1, 120, 2, '620', '6347'),
(298, 157, 'Le maître à rubans', 'Le maître a décidé de vous imposer encore des épreuves. Cela devient lassant.', 3408, 120, 2, '621,5500,622', '6348'),
(299, 157, 'Le maître étalon', 'Le maître vous prend pour une vraie bête de guerre, encore une épreuve.', 3409, 140, 2, '623,5503,624', '6349'),
(300, 157, 'Le maître aux normes', 'Il semble que vous ne puissiez échapper à cette interminable liste de massacres. Si il faut en passer par là...', 3410, 160, 2, '625,5504,626', '6350'),
(301, 157, 'Le maître décolle', 'Ça y est enfin, le maître des clefs vous a confié votre dernière épreuve.', 3411, 180, 2, '627,5505,628', '5808'),
(302, 157, 'Enfin !', 'Ça y est, vous êtes au bout de vos peines. Metag doit tenir sa promesse maintenant. À vous l\'ultime relique de sa famille !', -1, 160, 2, '629', '6560'),
(306, 157, 'Le maître ou ne pas mettre', 'Cette fois-ci, le maître vous envoie vérifier qui a les plus grosses.', -1, 130, 2, '631,5501,632', '6561'),
(307, 157, 'Le maître du jeu', 'Dans ce cas précis, compter jusqu\'à trois, ni plus, ni moins, ne vous sera d\'aucune aide.', -1, 140, 2, '633,5502,634', '6562'),
(308, 158, 'Une mère affolée', 'Madame El est paniquée. Elle recherche ses enfants dans le village d\'Amakna.', 3430, 90, 2, '635', '6563'),
(309, 158, 'Le tour du village', 'Les villageois ont sûrement vu les enfants El. Interrogez certains d\'entre eux pour obtenir des informations.', 3433, 90, 2, '636,637,638', '6564'),
(310, 158, 'La petite cabane dans la forêt', 'Le jeune Jorg a parlé d\'une cabane secrète dans la forêt des dragodindes.', 3438, 90, 2, '639,643', '6351'),
(311, 158, 'Un plat unique', 'La cruelle Paindep menace de dévorer les enfants El si elle n\'a rien d\'autre de mieux à déguster. Un cuisinier comme le célèbre Bol Pokuz pourrait sans doute vous aider. Il tient un restaurant en Amakna.', 3442, 90, 2, '640,641', '5732'),
(312, 158, 'Au fourneau !', 'La recette de la Filtounga est entre vos mains. Il ne reste plus qu\'à réunir tous les ingrédients pour que Pol prépare le célèbre plat.', 3446, 90, 2, '642', '6352'),
(313, 158, 'Les ingrédients', 'Pol, le cuisiner va réaliser la recette si vous lui amenez tous les ingrédients.', 3448, 90, 2, '644,645,646,647,648,649,650,651,652,653,654,655,656,657,658,659', '6353'),
(314, 158, 'Restauration rapide', 'Pol a maintenant tout ce qu\'il faut pour préparer une Filtounga. Il ne reste qu\'à attendre.', 3449, 90, 2, '660', '6354'),
(315, 158, 'Service express', 'La Filtounga de Pol doit être prête maintenant.', -1, 90, 2, '661', '6355'),
(316, 158, 'La libération', 'Pol a terminé la Filtounga, Paindep devrait être satisfaite', 3452, 90, 2, '662', '61'),
(319, 161, 'Trouver la recette de la bière Bwork', 'Pinta Gone recherche la recette de la fameuse bière Bwork. Il pense qu\'elle se trouve dans une salle étrange dans le territoire Bwork.', 3461, 30, 2, '665,666,931', '6356'),
(320, 162, 'Jeu Trooll règles avancées', 'Raxitik est terrorisé. Il sait que les Bworks vont le livrer au Trooll pour qu\'il pratique une partie de jeu Trooll règles avancées avec lui. Il faut absolument éliminer ce Trooll qui menace l\'intégrité physique de Raxitik.', 3469, 80, 0, '668,669,698', '62'),
(321, 163, 'Tuer du Bwork', 'Gobatchef veut que les Bworks soient massacrés avant qu\'ils ne massacrent les Gobelins.', 3479, 30, 1, '670,671,672,673,695', '63'),
(322, 164, 'Krazybwork veut redevenir débile', 'Krazybwork a trop mangé de Gobelins lors de la bataille de Bworkdrift. Il est devenu intelligent et veut redevenir débile. Le mieux serait de lui mettre un bon coup sur la tête !', 3489, 30, 0, '674,697', '64'),
(323, 165, 'Bworkidais le paxifik', 'Baston ou pas baston ?', -1, 30, 0, '675,696', '65'),
(324, 166, 'Un scalpel utile', 'Bworknroll a besoin de morceaux pour composer sa compagne idéale.', 3511, 90, 2, '676,677,678', '6357'),
(325, 166, 'À découper en suivant les pointillés', 'Bworknroll a besoin de remplir sa créature d\'organes frais (et juteux).', 3513, 90, 2, '680,681,682,683', '6358'),
(326, 166, 'Ne pas oublier l\'essentiel : la moule !', 'Bworknroll a besoin d\'une moule qui sort de l\'eau pour finir sa créature de rêve.', 3516, 90, 2, '685,687', '66'),
(327, 161, 'Pinta Gone veut lire la recette', 'Il a déjà acheté tout le matériel pour sa brasserie de bière. Il ne lui manque que la recette.', 3461, 30, 2, '688', '67'),
(328, 167, 'Chaperonner Titi', 'Le père de Titi aimerait qu\'il devienne mage. Pour cela, il faut l\'amener chez le plus puissant des Bworks Mages avec de quoi manger.', 3528, 70, 1, '689,690,694', '6359'),
(330, 168, 'De tape et de crocs', 'Bworkepik veut des canines de gobelins pour décorer son intérieur.', 3551, 40, 2, '699', '69'),
(331, 169, 'Une baguette et une panoplie', 'Chef Bworkestre a besoin de prouver sa virilité à sa douce et tendre en demandant des kdô aux visiteurs de passage dans son charmant village.\nAvec une panoplie Prespic, il espère repousser les coups de rouleau à pâtisserie de sa bworkette d\'amour.', 3563, 40, 1, '714,715,716,717,718', '70'),
(334, 170, 'Ailes en kit', 'Gobriel en a assez que les autres Gobelins lui jettent des pierres à cause de la couleur de sa peau. Il voudrait devenir un ange.', 3583, 40, 1, '725,726,727,728', '73'),
(336, 177, 'Trouver la tanière de Bworkcine', 'C\'est là qu\'est retenue Gobrose.', -1, 30, 2, '734,735', '6360'),
(337, 177, 'Se remplir la panse', 'Bworkcine est prête à échanger son esclave contre son poids en bière bwork.', -1, 30, 2, '736', '6361'),
(338, 177, 'Accorder le prétendant', 'Gobrose et Gobmichet vont ils se réunir ?', -1, 30, 2, '737,738', '6362'),
(339, 177, 'Plumer Gobrose', 'Gobmichet est jaloux des pious de Gobrose. Seul les vibrations de son petit coeur de gobelin vert doivent faire palpiter celui de Gobrose.', -1, 30, 2, '739,743,740', '6363'),
(340, 177, 'Encore quelques palabres', 'Gobrose préfère être une esclave et élever des pious. Une triste réalité à apprendre à son prétendant...', -1, 30, 2, '741,742', '74'),
(374, 167, 'Titi a sa bourse d\'étude', 'Bworknroll a accepté d\'enseigner la magie à Titi. Annoncez la nouvelle à son père.', -1, 70, 1, '814', '85'),
(375, 167, 'Comme vous avez de grandes dents', 'Titi est prêt à vous suivre. N\'oubliez pas d\'emporter le Gâtrool, le Gratrooll et La cape rouge.', -1, 70, 1, '817,815', '6371'),
(376, 167, 'Inscription', 'Si Bworknroll accepte le paiement constitué de Gâtrool et de Gratrooll, avec une cape rouge en bonus, Titi pourra devenir mage.', -1, 70, 1, '816', '6557'),
(384, 208, 'Trouver le Sram', 'Yse Vewybad vous a parlé d\'un Sram important en Amakna... Où trouve-t-on des Srams en Amakna ?', 3868, 30, 0, '826,827', '6558'),
(385, 208, 'Trouver le repaire des Roublards', 'Yse Vewybad vous a donné des indications sur la position des Roublards. Allez donc voir du côté du cimetière.', 3871, 30, 0, '828,829,5460', '6559'),
(386, 209, 'La crypte, c\'est chic', 'Vous devez visiter les cinq cryptes du cimetière d\'Amakna.', 3875, 30, 1, '830,831,832,833,834,835', '6378'),
(387, 209, 'Ça roule pour les Roublards', 'Vous continuez vos recherches pour essayer de débusquer le maître des Roublards.', 3877, 30, 1, '836,837,838', '6379'),
(388, 209, 'Pour quelques Roublards de plus...', 'Vous devez vous infiltrer chez les Roublards et aller parler à Vil Smisse.', 3879, 30, 1, '839,5461', '6380'),
(390, 211, 'Dilemme dilemme...', 'Vous savez maintenant qu\'Yse Vewybad complote contre le Roi. Il va falloir prendre parti pour l\'un ou l\'autre.', 3899, 30, 0, '842', '6381'),
(394, 215, 'Trouver le prétendant', 'Il vous faut trouver un prétendant pour Allisteria, la fille du frère du roi.', 3911, 40, 1, '849,860,927,5463', '6382'),
(395, 216, 'Qui sait quoi ?', 'Vil Smisse veut que vous recueilliez des renseignements sur ce qui se prépare au château. Il faut donc trouver la personne qui saura vous en dire plus.', 3921, 40, 1, '853,854,855', '5963'),
(396, 216, 'Chercher la petite bête', 'Maintenant, vous savez que le roi doit marier sa nièce... mais avec qui ?', 3923, 40, 1, '856,857', '86'),
(399, 217, 'Wabbit powa', 'Il vous faut trouver un moyen de vous tranformer en Wabbit. Vil Smisse a parlé d\'une potion, et d\'après ce que vous savez, les potions sont fabriquées par les alchimistes. Il y a sans doute quelque part un alchimiste capable de vous aider...', 3941, 50, 2, '861', '6306'),
(400, 217, 'Et une formule, une !', 'Vous devez retrouver des alchimistes disséminés en Amakna.', 3942, 50, 2, '862,863,864,872', '6307'),
(401, 217, 'Après la recette, les ingrédients', 'Maintenant qu\'Uba a la formule, il ne lui manque plus que les ingrédients.', 3945, 50, 2, '865,866,867,868,869,870,929', '87'),
(402, 217, 'Fausse identité', 'Comme vous pouvez le voir, Uba Tessé vous a transformé en Wabbit. Il n\'y a plus qu\'à aller voir au château si vous pouvez faire capoter ce mariage.', 3941, 50, 2, '873,5462', '6308'),
(403, 218, 'Un œuf tout neuf', 'Vil Smisse vous a demandé de lui rapporter un œuf de tofu obèse. Encore faut-il trouver le nid...', 3957, 60, 1, '874,875,876', '6309'),
(404, 218, 'Gavage', 'Vous avez l\'œuf de Tofu obèse, mais un œuf ne va pas faire grand mal au prince... Il faut trouver de quoi gaver l\'oisillon à naître.', 3958, 60, 1, '877,878', '6310'),
(405, 219, 'Un cadeau empoisonné', 'Vil Smisse a décidé d\'éviter l\'approche directe et de faire les choses plus à la façon traditionnelle des Roublards - sournoisement.', 3961, 70, 1, '879', '6311'),
(406, 219, 'Tueurs à gage à engager', 'Vil Smisse ne pourra utiliser le blopisier empoisonné. Il se rabat donc sur l\'attaque de front. Pour cela, il veut engager des assassins, il a donc besoin d\'argent.', 3963, 70, 1, '880', '6312'),
(407, 220, 'Trouble-fête', 'Les assassins ont échoué à tuer le prince... Vil Smisse vous demande d\'aller engager un Lenald pour le trucider.', 3966, 80, 1, '881,926,5458', '6313'),
(408, 221, 'Sus au Tofu !', 'Vous savez où le prince d\'Wa est parti chasser, enfin à peu près... c\'est au sud de Cania. Reste à convaincre ce fameux prince d\'épouser Allisteria.', 3918, 50, 1, '883,884,885,886', '6314'),
(409, 222, 'Qui m\'aime me suive !', 'Le prince d\'Wa vous a demandé de lui constituer une suite digne de lui... Vu ses prouesses au combat, son régime particulier et son sens de l\'esthétisme, il faut bien quatre personnes pour l\'assister. Allez donc engager quelques habitants de Bonta. Il fau', 3992, 60, 2, '887,888,889,890,5465,5464', '88'),
(414, 224, 'Servir ou rendre service ?', 'L\'intendant San Lavalss vous demande d\'aider aux derniers préparatifs du mariage.', 4036, 70, 2, '909,910,911,5466', '6315'),
(415, 225, 'Au meurtre !', 'Le prince d\'Wa se fait attaquer, protégez-le !', 10772, 80, 2, '913,914', '6316'),
(416, 225, 'Bunny suit', 'Le prince d\'Wa vous a demandé de prendre sa place pour démasquer les assassins. Encore faut-il trouver quelqu\'un qui puisse vous transformer en Wabbit.', 4024, 80, 2, '915,916,917', '6317'),
(417, 225, 'Courses', 'Maintenant que la formule est complète, il faut les ingrédients.', 4033, 80, 2, '918,919,920,921,922,923,924', '89'),
(420, 229, 'Un déguisement pour Émeraude', 'Émeraude cherche désespérément une panoplie Koalak.', -1, 120, 2, '933,934,935,936,937,938,939', '5796'),
(421, 230, 'Répondre au questionnaire', 'Le Gardien du Pont de la Mort exige que vous répondiez correctement à ses questions.', -1, 80, 0, '940', '6319'),
(422, 231, 'Bien préparer son voyage', 'Le Capitaine Kradoc a besoin que vous lui rapportiez plusieurs objets pour qu\'il puisse vous emmener dans son bateau.', -1, 35, 1, '941,942,943,944', '6320'),
(423, 232, 'Le Coffret Maudit du Flib', 'Le bateau du Capitaine Kradoc s\'est lamentablement échoué sur l\'île des naufragés. Vous devez retrouver le Coffret Maudit du Flib et quelques objets pour réparer le bateau.', -1, 35, 1, '945,946,947,948', '6321'),
(424, 233, 'Vous ne passerez pas !', 'Le Chevalier Noir et Rose est fermement décidé à ne pas vous laisser passer. C\'est peut-être le bon moment d\'employer la force.', -1, 100, 1, '949', '91'),
(425, 234, 'Une potion pour le professeur', 'Le Professeur Fournesol a besoin d\'une Potion Bulbique pour se remettre au travail.', -1, 45, 1, '950', '92'),
(426, 235, 'Les machines d\'élevage', 'Polka Merer a besoin de machines d\'élevage pour ses créatures.', -1, 40, 1, '951,952,953,954,955', '93'),
(427, 236, 'Une histoire de farine', 'Paulette Pain-bèche la boulangère a l\'intention de recouper sa farine de Xavier le Boulanger avec différentes céréales. Elle a eu l\'idée, à vous de trouver ce qui lui faut !', -1, 40, 1, '956,957,958,959,960,961,962,963,964,965', '94'),
(428, 237, 'A la recherche du fils caché', 'Le Docteur Nauh a perdu son fils dans un laboratoire infesté de terribles créatures sauvages. Vous devez le retrouver et vous assurer qu\'il est encore en vie !', -1, 90, 1, '969,970', '95'),
(429, 238, 'Le docteur est morose', 'Le pauvre Docteur Morose a perdu sa femme. Aidez-le à la trouver dans la Jungle Sombre et tentez de la persuader à retrouver son mari pour qu\'il puisse reprendre ses recherches.', -1, 120, 1, '971,972', '96'),
(430, 239, 'L\'équipement amélioré', 'Spitte Fayeur recherche un casque et une cape de pilote améliorés. Seul un tailleur expérimenté pourra vous aider.', -1, 65, 1, '973,974', '97'),
(431, 240, 'Deux Dragodindes Sauvages pour Flip Flap', 'Flip Flap voudrait que vous lui rameniez un certificat de Dragodinde Rousse Sauvage ainsi qu\'un certificat de Dragodinde Amande Sauvage.', -1, 40, 1, '975,976', '98'),
(432, 241, 'Chasse sur la plage', 'Crocodaille Dandi aimerait que vous éliminiez certaines créatures sur la plage de Corail.', -1, 50, 1, '977,978,979,980,981,982,983,984,985', '99'),
(433, 241, 'Chasse dans les Plaines', 'Crocodaille Dandi aimerait que vous chassiez pour lui plusieurs créatures des Plaines.', -1, 95, 1, '986,987,988,989,990,991', '100'),
(434, 241, 'Chasse dans la Tourbière sans fond', 'Crocodaille Dandi aimerait que vous chassiez pour lui quelques créatures de la Tourbière sans Fond.', -1, 100, 1, '993,994,995', '101'),
(435, 241, 'Chasse dans la Jungle Sombre', 'Crocodaille Dandi aimerait que vous chassiez pour lui quelques créatures de la Jungle Sombre.', -1, 120, 1, '996,997,998,999,1000,1001,1002', '102'),
(436, 241, 'Chasse dans l\'Arbre Hakam', 'Crocodaille Dandi aimerait que vous chassiez pour lui quelques créatures de l\'Arbre Hakam.', -1, 150, 1, '1003,1004,1005,1006,1007', '103'),
(437, 242, 'Un exemple pour les Pirates', 'Kito vous a demandé de faire un exemple pour les Pirates qui lui lancent des boulets.', -1, 80, 1, '1008,1009,1010', '104'),
(438, 243, 'Le Chevalier Noir et Rose', 'Peggy la Porkass aimerait que vous affrontiez le terrible Chevalier Noir et Rose à sa place.', -1, 100, 1, '1011', '105'),
(440, 245, 'L\'échange maudit', 'Farle Ingalsse est sûrement la seule personne d\'Amakna capable de transformer cette épée maudite...', -1, 200, 1, '1013,1014', '106'),
(442, 246, 'La tour désordre', 'Trouvez dans Bonta un personnage important qui serait susceptible d\'être corrompu. Oto a suggéré de chercher dans la tour.', 854, 111, 2, '1016', '6324'),
(443, 246, 'Retour de la tour', 'Vous avez trouvé un morceau de papier très intéressant. Il faut le montrer à Oto.', 6218, 111, 2, '1017,10155,10156,10157', '6325'),
(444, 247, 'Les bons bars de Bonta', 'Il faut trouver des informations sur Xephirès. Les taverniers de Bonta pourraient peut-être fournir une piste.', 4268, 112, 1, '1018,1020,1021,1022,2623,2624,2625,1023', '5836'),
(445, 247, 'Abrakadabra, me voilà', 'Vous avez rapporté des informations utiles à Oto Mustam, qui vous a demandé de prendre la relève d\'un milicien. Vous devez chercher un Sram connaissant Xephirès, dans la forêt des Abraknydes.', 6227, 112, 1, '1024', '6326'),
(446, 247, 'Abrakadabra, c\'est encore moi', 'Exoram n\'est pas rassuré car il a entendu des bruits suspects et des rires narquois plus au nord. Si vous pouvez lui assurer que le chemin est dégagé, il vous donnera les informations prisées sur Xephirès.', -1, 112, 1, '1025', '6327'),
(447, 248, 'S\'infiltrer ou foncer dans le tas, telle est la question', 'D\'après vos découvertes, il semblerait qu\'Exoram soit retenu prisonnier dans le campement gobelin sauf s\'il est déjà mort.', 6248, 113, 1, '2629,2630,2631', '6328'),
(448, 248, 'Sur les traces du Sram', 'Exoram a été relâché vivant par les gobelins. Vous devez à nouveau partir sur ces traces pour lui mettre la main dessus.', 6234, 113, 1, '1027,2632,2633,2634', '6329'),
(451, 250, 'La rencontre', 'Maintenant que l\'endroit où Xephirès se trouve a été identifié, il faut le trouver à la taverne du Pandazaap et lui faire la proposition. Il y est à partir de 16 heures.', 4291, 114, 1, '1031,1032', '6334'),
(452, 250, 'Un échec... temporaire', 'Xephirès a refusé l\'offre, mais tout n\'est pas perdu. Un bijou saura l\'amadouer.', 4293, 114, 1, '2639,1033,1034', '6335'),
(453, 251, 'Joyau... ze fête', 'Vous devez récupérer des matériaux pour confectionner un joyau.', 4296, 115, 1, '1035,1036,1039,2641', '6336'),
(455, 252, 'L\'enlèvement de Sabine', 'Vous devez enlever Sabine et la mettre dans un endroit d\'où elle ne pourra pas s\'échapper.', 4297, 116, 1, '1040,2642', '6337'),
(456, 253, 'Vite, vite !', 'Milone serait apparemment sur le point d\'être cambriolé. Il faut vite aller empêcher cela.', 4314, 117, 1, '1041,1043,1028,1038,2656', '6066'),
(458, 255, 'Le facteur', 'Il faut trouver un moyen de faire passer la lettre à Xephirès. Il est souvent à la taverne du Pandazaap mais refuse désormais de vous parler.', 4324, 118, 1, '1044,1045', '6340'),
(459, 256, 'L\'entretien', 'Tout est prêt, il ne reste plus qu\'à retrouver Xephirès à la Taverne du Pandazaap pour lui remettre la lettre et fixer un rendez-vous pour sa réponse.', 4333, 119, 1, '1046,2978,2663', '6341'),
(460, 256, 'Victoire !', 'Xephirès a accepté les conditions et est prêt à trahir Bonta le moment venu. Oto sera satisfait d\'apprendre la nouvelle.', -1, 119, 1, '1048', '6342'),
(463, 258, 'Tournée des tavernes', 'Le bandit à qui appartenait l\'épée est probablement passé dans l\'une des tavernes. Par conséquent, les taverniers doivent savoir quelque chose.', 4351, 112, 1, '1052,2752,1053,10252,10253,10254', '6345'),
(464, 259, 'Repaire pépère', 'Amayiro vous a demandé d\'enquêter dans les plaines de Cania pour trouver le repaire des bandits. D\'après vos informations il serait non loin de la foire du trooll, un peu à l\'Ouest.', 4363, 113, 1, '1054,2904', '6346'),
(465, 259, 'Jolie minette', 'Votre rencontre avec les bandits vous a appris que Hersa Griffe Sombre en sait plus qu\'elle ne veut l\'admettre. Reste à lui parler sans se faire défigurer.', -1, 113, 1, '1055', '6258'),
(466, 260, 'Escorte Gueurle', 'Votre mission est d\'escorter la troupe de marchands de Gueurle jusqu\'à Astrub.', 6440, 114, 1, '1056,2756,2757,2758,2759,2760,2761,2762', '6033'),
(468, 260, 'Piège pour Ecaflips', 'Amayiro veut tendre une embuscade aux bandits, pour cela il a besoin d\'un bijou de grande valeur afin de les attirer dans son piège.', -1, 114, 1, '1058,1059,1060,2763,2764,2765,2766,2767', '6034'),
(469, 260, 'Mauvais hameçon ?', 'Le voyage s\'est passé sans encombre. Les bandits n\'ont pas attaqué... Amayiro attend votre rapport.', -1, 114, 1, '1061', '6054'),
(470, 260, 'Au rapport', 'Le convoi a été attaqué par des bandits Ecaflips semblables à ceux dont vous avez découvert le campement. Amayiro attend votre rapport pour convaincre le conseil d\'agir.', -1, 114, 1, '1062', '6260'),
(472, 262, 'Pour vivre, il faut des vivres', 'Sous la pression du conseil, Amayiro vous a retiré l\'enquête et vous êtes désormais de corvée de ravitaillement.', 4387, 116, 1, '1064,2779,2780,2781', '6261'),
(473, 263, 'Une bonne Rigalade', 'Rigal Main Crochue, au temple Sram, est réputé pour détenir de nombreuses informations, mais toute information à un prix. Reste à savoir à combien s\'élève la vôtre.', 4390, 117, 1, '1065', '6262'),
(474, 263, 'Il est frais mon poison', 'Vous devez trouver les réserves de poison de Brâkmar et dérober le registre des clients de l\'atelier des alchimistes. Bishom Pot pourra peut-être vous aider.', 4392, 117, 1, '1067,2787,2788', '6263'),
(475, 264, 'Affaire louche', 'Vous allez profiter de l\'absence de Xarthan pour vous introduire discrètement dans sa maison et la fouiller. Les services d\'un bricoleur compétent seront nécessaires.', 4397, 118, 0, '1068,1069', '6264'),
(476, 265, 'Bishom Pot, le retour', 'Amayiro soupçonne Brâkmar d\'être à l\'origine des problèmes de Bonta. Bishom Pot, espion milicien à Brâkmar, a peut-être appris quelque chose.', 4407, 119, 1, '1070,2796,2797', '6265'),
(477, 265, 'Le vieux bijoutier', 'Selon le chef des voleurs, le bijoutier de Brâkmar - Milone Corichel - aurait des informations.', 6497, 119, 1, '1071,1072', '6266'),
(478, 266, 'Attrape-nigaud', 'Un rendez-vous entre un Brâkmarien et le Bontarien corrompu va avoir lieu à la tour de Bonta. Il faut les capturer tous les deux si possible.', 4410, 120, 1, '1073,1074', '6267'),
(479, 267, 'Escarmouche', 'Un combat a actuellement lieu près de la Baie de Cania, sur la route à mi-chemin entre Bonta et Brâkmar. Il faut le rejoindre et aider Brâkmar à vaincre !', 4421, 131, 0, '1075', '6147'),
(480, 267, 'Retour vers Oto', 'La bataille est terminée, Oto Mustam attend votre rapport.', 4421, 131, 0, '1077', '6268'),
(481, 267, 'Kaffra Kyper', 'Oto Mustam veut avoir l\'avis de Kaffra Kyper pour son offensive contre Bonta.', -1, 131, 0, '1078,1079', '6269'),
(482, 268, 'En territoire ennemi', 'Vous devez vous infiltrer dans le bâtiment de la milice de Bonta et découvrir où vos ennemis entreposent leurs armes.', 4428, 132, 1, '1080', '6270'),
(483, 268, 'Une bien belle grosse caisse', 'Vous devez tromper la vigilance du gardien pour lui prendre les clefs de l\'entrepôt. Il vous faut ensuite dérober une caisse d\'équipement et l\'apporter à Mulic Bere pour expertise.', 3855, 132, 1, '1082,2682,2683,2684,2685', '6271'),
(485, 270, 'Récolte de poison', 'Les espions à Bonta ont besoin de poison : un poison rare détenu uniquement par les Disciples Zoths. Les espions se cachent dans les Havres d\'ivoire de Bonta.', 4441, 134, 1, '1085', '5741'),
(486, 271, 'Assassinat', 'Vous pouvez maintenant entrer dans la bibliothèque pour vous occuper du tacticien.', 4446, 135, 2, '1086', '6167'),
(487, 271, 'Pénétrer dans la bibliothèque', 'Les espions à Bonta ont échoué dans leur assassinat, il faut donc le faire à leur place. La cible est un tacticien qui réside dans la bibliothèque de Bonta mais gare aux chiens de garde.', 4446, 135, 2, '1087', '6273'),
(488, 272, 'Retour vers Oto', 'Vous vous êtes occupé du tacticien, il faut retourner voir Oto.', 4446, 135, 1, '1088', '6274'),
(489, 273, 'Retour vers Oto', 'Le tacticien ayant quitté la ville, vous pouvez raisonnablement laisser penser à Oto Mustam que vous l\'avez tué.', 4446, 135, 2, '1089', '6275'),
(490, 274, 'Jusqu\'à Brâkmar', 'Le tacticien a accepté de vous suivre jusqu\'à Brâkmar.', 4446, 135, 2, '1090', '6276'),
(491, 275, 'Nouveau danger qui fait peur', 'Plusieurs guerriers brâkmariens ont été vaincus et laissés pour morts sur la route menant à Astrub. Il faut aller enquêter là-bas mais avant, Oto Mustam veut une âme de Truchmuche.', 4464, 136, 1, '2704,1091,2705,2706,2707,1092', '6277'),
(492, 276, 'Marteau et enclume', 'Oto Mustam pense que Bonta est aidée par un forgeron mercenaire. Vous devez chercher dans les ateliers de forgerons ou de mineurs pour trouver des indices.', 4472, 137, 2, '1093,2708,2709', '6278'),
(493, 277, 'Dans la grotte Porcos', 'Vous devez tenter de rallier le forgeron de la grotte Porcos à la cause de Brâkmar.', 6347, 138, 1, '1095,1096,2710,2711,2712,2713', '6279'),
(494, 278, 'Interception brutale', 'Vous devez intercepter un convoi d\'armes qui va passer par l\'orée de la Forêt des Abraknydes pour rejoindre le Village des Brigandins. Des renforts seront les bienvenus.', 4480, 139, 2, '1097,2714,2715,2716', '6280'),
(495, 279, 'Pirate à quai', 'Grâce à Xephirès, vous savez que le navire bontarien La Descemer transporte de nombreux objets magiques dans ses cales. Vous devez le trouver et faire main-basse sur sa marchandise.', 4484, 140, 1, '1099,1100,2717,2718,2719,2720,2721,2722', '6281'),
(496, 280, 'Escarmouche', 'Un combat a actuellement lieu près de la Baie de Cania, sur la route à mi-chemin entre Bonta et Brâkmar. Il faut le rejoindre et aider Bonta à vaincre !', 4491, 131, 0, '1101', '6122'),
(497, 280, 'Au rapport', 'La bataille est terminée, Jerhyn Gholein attend votre rapport.', 4491, 131, 0, '2808,1102', '6283'),
(498, 281, 'Forger avec ses pieds', 'Vous devez enquêter sur le fournisseur de l\'équipement de la milice et mettre à l\'épreuve le forgeron qui le fabrique.', 4495, 132, 1, '1103,2809,2810,2811', '6284'),
(499, 282, 'Ainsi forgeront...', 'Il faut trouver un forgeron compétent qui accepterait de faire de l\'équipement pour Bonta.', 4502, 133, 2, '1104,1105,1106,2814,2815', '6055'),
(500, 282, 'Si près du but', 'Norb sait où se trouve le forgeron ermite, il vous reste à le convaincre de divulguer sa cachette. Peut-être qu\'Amayiro pourra vous aider.', -1, 133, 2, '1107,2966,2816,2817,2818,2819,2820,3018', '6285'),
(501, 283, 'Prospection immobilière', 'Nara vous a demandé de trouver un endroit isolé où installer sa forge et son matériel.', 4513, 134, 1, '1108,1109,2821,2822,2823', '6286'),
(502, 284, 'Lenglad en prend pour son grade', 'William Lenglad a de nouveau besoin d\'une leçon.', 4514, 135, 2, '1110,2833', '6287'),
(503, 285, 'Matières premières', 'Nara le forgeron, dans la mine du territoire Porcos, a besoin de matières premières pour forger un équipement standard destiné aux miliciens de Bonta.', 4519, 136, 1, '1111,2838,2839,2840,2841,2842,2843,2844', '6288'),
(504, 286, 'Danathor, qu\'est-ce que tu nous mijotes encore ?', 'Danathor semble avoir une nouvelle offre à vous faire. Probablement quelque chose de louche.', 4525, 137, 2, '1112,2845,2846', '6289'),
(508, 289, 'Sadikoi ?', 'Danathor a encore besoin de vos services pour mettre la main sur le grimoire du bwork mage des cavernes réputé pour avoir lancé l\'envoûtement de la Grafioze.', 4536, 139, 2, '1117,1118', '6290'),
(509, 290, 'Vol dans un nid de coucou', 'Amayiro veut tendre une embuscade aux Brâkmariens pour tester le nouveau matériel et la cohésion des miliciens.', 4543, 138, 1, '1119,1120,2858,2859,2860,2861', '6291'),
(510, 291, 'Plan d\'attaque', 'Amayiro craint un assaut imminent des Brâkmariens. Vous devez trouver leur plan d\'attaque pour permettre à Amayiro de leur préparer un comité d\'accueil digne de ce nom.', 4537, 140, 1, '1121', '6292'),
(514, 294, 'C\'est l\'or, Moon', 'Le soi-disant gardien de la Corne Edfrit serait dans la jungle interdite de l\'île de Moon. D\'après les rumeurs, vous devez porter une Fourbacoiffe et avoir bu du Gloutoburg pour qu\'il apparaisse.', 4567, 152, 1, '1129,1130', '6455'),
(515, 295, 'Amadoudoudou c\'est bon', 'Il faut trouver un moyen d\'amadouer Turorte pour mettre la main sur la Corne Edfrit. Les résidents de l\'île de Moon peuvent vous aider.', 4575, 153, 1, '1131,1132,2869', '6293'),
(519, 298, 'L\'espion blessé', 'Vous devez rattraper l\'espion blessé qui fait route vers Brâkmar et lui reprendre les documents.\nCependant, vous avez trouvé une lettre dans votre sac...', 4591, 156, 0, '1138,1139', '6062'),
(520, 299, 'Course contre la montre', 'Un espion bontarien est en train de fuir Brâkmar par l\'Est de la route. Il faut le retrouver et l\'escorter. Le temps vous est compté !', 4599, 157, 1, '1140', '6294'),
(521, 299, 'Récupération mouvementée', 'Vous avez trouvé l\'espion à temps mais les Brâkmariens ne comptent pas vous laisser les documents. Il vous faut les amener à Amayiro coûte que coûte.', -1, 157, 1, '1143,2878,3234', '6295'),
(526, 304, 'Un sombre pouvoir', 'Amayiro vous a demandé d\'interroger le Mage Ax pour connaître le mode d\'emploi de la Corne Edfrit et ses pouvoirs.', 4617, 159, 1, '1149,2881,2882,2883,2884', '6143'),
(529, 306, 'Recherches pour une corne', 'Le soi-disant gardien de la Corne Edfrit serait dans la jungle interdite de l\'île de Moon. D\'après les rumeurs, vous devez porter une Fourbacoiffe et avoir du Gloutoburg pour qu\'il apparaisse.', 4626, 152, 1, '1154,1155', '6297'),
(530, 307, 'Mettre la tortue sur le dos', 'Puisque vous n\'arrivez pas à soutirer des informations juste en demandant, il va falloir y aller d\'une façon plus directe...', 4629, 153, 1, '1157,2726,2727,1158', '6298'),
(531, 308, 'L\'ami des bêtes', 'Vous devez trouver d\'où vient Turorte. Un spécialiste des animaux pourra vous aiguiller dans vos recherches. Oshimo, responsable du chanil, est un bon point de départ.', 4633, 154, 0, '1159,2728,2729,2730', '6299'),
(533, 310, 'Retrouver l\'espion', 'Vous devez rapidement retrouver l\'espion blessé sur la route menant à Bonta, et récupérer les documents. L\'espion doit être plus proche de Bonta que de Brâkmar.', 4643, 156, 0, '1161', '6301'),
(534, 311, 'Le choix', 'Vous avez trouvé l\'espion à temps. Mais allez-vous suivre les ordres et récupérer les documents en le laissant là ?', -1, 156, 0, '1162,1163,2738', '6302'),
(535, 312, 'Un petit échec', 'Des traces de combat, deux armes laissées au sol, un Sram décédé : tout porte à croire que vous n\'êtes pas arrivé à temps.', -1, 156, 0, '1164,2739', '6303'),
(536, 313, 'Contre-espion', 'Un espion bontarien s\'est infiltré dans la tour et a volé des documents. Il faut utiliser un Zaap pour l\'intercepter, à l\'est de la route menant à Bonta, du côté de Brâkmar.', 4659, 157, 1, '1165,2740,1166,10328,10329,10330', '6304'),
(544, 317, 'Équiper les guerriers', 'Oto craint une attaque de Bonta et vous a demandé d\'équiper certains des guerriers de Brâkmar avec de l\'équipement spécial.', 4677, 160, 2, '1184,1185,1186,1187,1188', '6238'),
(545, 319, 'L\'épée maudite', 'Oto Mustam semble préoccupé par une lame maudite tandis que Domen continue de s\'intéresser à vous.', 4684, 171, 1, '1189,1190,1191,1193,2886,2887,2888', '5772'),
(546, 318, 'Un coupable idéal', 'Trev Pelsantery est accusé de traîtrise mais Amayiro le croit innocent. Il vous charge de demander sa version des faits à Trev, actuellement en prison, et de vérifier ses dires.', 4694, 171, 1, '1192,1194,1195,1196,2940,2941,1197', '6239'),
(548, 320, 'Allez, ce fer...', 'Oto Mustam a besoin de Fer Maudit pour sa lame. Apparemment Divad Dleifrepok sait comment transformer du fer normal en fer maudit.', 4716, 172, 2, '1198,2889,2890,2891,2892,2896,2897,2898,1199,1200,2899,1202,2900,2901,2902,2903', '6241'),
(551, 321, 'Un peu de juge hot', 'Le juge Satirev Onivin n\'aimant pas les enquêtes tirant en longueur, Amayiro vous envoie auprès de lui pour obtenir un délai. Il passe le plus clair de son temps dans le bâtiment de la milice.', 4740, 172, 2, '1205,1220,10331,10332,10333,10334,2942,2943,2944,1213', '5758'),
(552, 322, 'Poignée d\'amour', 'Oto Mustam a besoin de l\'aide des Huppermages pour forger son épée.', 4729, 173, 1, '10291,1203,1204,1206,2905,2906,2907,2910,2911,2908,2909,2912,10292,10293,2913', '6243'),
(558, 324, 'Plus, plus de puissance !', 'Lagren Doowile, à l\'étage inférieur de la milice, pourra vous aider à imprégner la lame de puissance.', 4770, 176, 2, '1221,1222,1224,10296,2936,2937,2938,2939', '6244'),
(559, 325, 'De drôles de témoins', 'Amayiro vous a demandé d\'interroger le témoin ayant accusé Trev Pelsantery de traîtrise jusqu\'à ce qu\'il dévoile quelque chose d\'intéressant. Vous le trouverez sûrement à la Taverne Alakarte.', 4775, 173, 1, '1225,1226,1227,3000,3001,3003,3005,3006,3007,3008,3009,3010,3011,3012,3013,3014,3015,3016,3017,3019,3020,3021,3022,3023,1228', '6245'),
(561, 326, 'Suivez l\'odeur', 'Amayiro vous a demandé de retrouvez le Sram qui a menacé Nissacram. Seul indice : il va régulièrement dans les égouts par la bouche d\'égout située au sud-est de la cité.', 4877, 174, 2, '3024,1229,1230', '6246'),
(562, 326, 'Un juge un peu marteau', 'Satirev Onivin a cassé son marteau et vous en demande un nouveau. Comme il est têtu, il refuse d\'utiliser autre chose qu\'un Marteau de Raclage.', 4806, 174, 2, '1233,1234,3025', '5907'),
(563, 326, 'L\'entrevue de Danathor', 'Danathor souhaite vous parler avant le procès, ça a l\'air urgent.', 4802, 174, 2, '1235,1236', '6247'),
(564, 327, 'L\'épée, ça sent mauvais', 'Il faut de l\'Eau Putride pour forger l\'épée maléfique.', 4811, 175, 1, '1237,1238,1239,2929,2930,2931,2932,10295,2934,2935', '6248'),
(565, 329, 'Des recherches sur la corne', 'Oto Mustam veut obtenir des informations supplémentaires sur la Corne Edfrit. Il vous a demandé de parler à son espion, Finche Aticus, dans Bonta.', 4817, 177, 2, '1240,1241,1242,3028,3029,3030,3031,3032,3033,3034', '6249'),
(566, 326, 'Un procès équitable', 'Ayant enquêté sur l\'affaire de la trahison de Trev Pelsantery, vous êtes amené à témoigner. À vous de choisir votre camp.', 6902, 174, 2, '1243,1244,1245,1246,1247', '6250'),
(567, 326, 'Après l\'effort, le réconfort', 'Vous avez participé au procès de Trev Pelsantery et votre avis a joué sur l\'issue du procès. Vous pouvez à présent retourner à vos occupations.', -1, 174, 2, '1248,1249', '5902'),
(568, 330, 'Maître chanteur', 'Vous devez convaincre des forgerons de vous fabriquer rapidement plusieurs dizaines d\'épées.', 22139, 178, 1, '1250,3035,3036,3037,3038,3039,3040,3041,3042,3043,3044,3045,3046,3047,3048,3049,3050,3051,3052,3053,3054,3055,3056', '6251'),
(578, 337, 'Ingérence en Amakna', 'Ayant reçu un rapport inquiétant indiquant la présence de troupes brâkmariennes sur le territoire d\'Amakna, Amayiro vous envoie rejoindre les troupes d\'élite bontariennes déjà sur place.', 4945, 181, 1, '1290,1291,1292,1293,1294,1296,10700,1298,3182,1299,3183,1340,1341,1342,1343,1344,1345,1347,3184,1348,1349', '6009'),
(584, 334, 'Si j\'avais un marteau', 'Amayiro vous a informé qu\'Ebru Of El a besoin de vos services. Vous pouvez le trouver à la Tour de Bonta.', 4893, 175, 1, '1268,1269,1270,1271,1272,1273,1274,1276,10269,10270,10271,10272,10273,3063,10274,3064,3066,3067,1275', '5755'),
(618, 352, 'Le trou d\'Uk', 'Ne supportant plus votre présence, Oto Mustam vous a mis aux ordres d\'une autre personnalité haut placée.', 23292, 181, 1, '1368,8202,10731,10732,1369,1370,3391,1371,1382,3392,3393,10733,10734,10735,10736,10737,3395', '6585'),
(679, 55, 'Battre le milicien', 'Vous devez battre le milicien Tarche, dans la salle adjacente à celle d\'Amayiro.', 921, 31, 0, '1480,9602', '6182'),
(680, 56, 'Interroger la Dame', 'Vous devez aller voir Dame Cloude pour lui demander ce qu\'il se passe.', 47078, 32, 0, '1481,1482', '6220'),
(681, 57, 'Donner des pains', 'Vous devez apporter 20 fougasses à Amayiro.', 47080, 33, 1, '1483', '5712'),
(682, 58, 'Les dents de Chafers', 'Vous devez arracher des dents de Chafers, exactement le nombre constituant un dentier humain, et les amener à Ned devant l\'atelier des chasseurs au sud de la ville.', 47083, 34, 1, '1484', '6221'),
(683, 59, 'Une tatanne pour le frérot', 'Vous devez battre le milicien Torche et ramener une preuve de votre victoire à Amayiro.', 716, 35, 0, '1485,9603', '6222'),
(684, 60, 'Visite chez le tavernier', 'Vous devez récupérer la carte d\'Amayiro et une bière auprès du tavernier Feubuk.', 47089, 36, 0, '1486,1487', '6224'),
(685, 61, 'Retrouver le Corbac', 'Vous devez retrouver le Corbac qui a volé le collier de la fille d\'un membre du conseil, le battre et récupérer le collier.', 718, 37, 0, '1488,9604,9605,9606', '6225'),
(686, 62, 'Traquer les buveurs', 'Vous devez faire le tour des tavernes de Bonta pour trouver les miliciens qui ne sont pas à leur poste et leur demander leur badge.', 719, 38, 0, '1489', '6226'),
(687, 63, 'Trouver la faille', 'Vous devez trouver quelque chose d\'intéressant sur le mécanisme qui permet d\'ouvrir la grande porte de Brâkmar.', 720, 39, 1, '1490,9607,9608,9609,9610', '6227'),
(688, 64, 'Chasse au sanglier', 'Vous devez trouver le sanglier agressif dans les champs de Bonta et le battre.', 20610, 40, 1, '1491,9611', '6228');
INSERT INTO `quest_steps` (`Id`, `QuestId`, `Name`, `Description`, `DialogId`, `OptimalLevel`, `Duration`, `ObjectiveIds`, `RewardIds`) VALUES
(689, 65, 'Entraînement au bâton', 'Amayiro vous a demandé dix bâtons de boisaille pour entraîner ses troupes.', 722, 51, 2, '1492,9621,9622,9623,9624,9625,9626,9627,9628', '6233'),
(690, 66, 'Tabasser le mauvais payeur', 'Le tavernier Tabasse doit une forte somme à Amayiro : vous devez le convaincre par tous les moyens de la payer.', 723, 52, 0, '1493', '6230'),
(691, 66, 'La réparation du katana', 'Vous devez demander à Kosuke le forgeron de réparer la lame d\'Amayiro en échange du chèque.', 47170, 52, 2, '1494,1595,9629,9630,9631', '6231'),
(692, 67, 'Communiquer avec l\'espion', 'Vous devez trouver Bishom Pot dans Brâkmar et lui soutirer les informations qu\'Amayiro a demandées.', 724, 53, 1, '1495,1496,9632,9633', '6232'),
(693, 68, 'Apporter la poudre', 'Vous devez apporter dix doses de poudre à canon à Amayiro. Vous pourrez les acheter à Moub Reicifitra, dans Bonta.', 725, 54, 0, '1497,9634,9635,9636', '6148'),
(694, 69, 'Colmater la brèche.', 'Les gardes à l\'entrée sud de la cité ont besoin d\'un coup de main.', -1, 55, 1, '1498,9860,9861,9862', '6599'),
(695, 70, 'D\'égouts temps', 'Vous devez trouver ce qui, dans les égouts, est en train de contaminer la population de Bonta.', 21182, 56, 1, '1499,9936,9937,9938,9939,9940', '6234'),
(696, 71, 'Collection de casques', 'Vous devez amener 15 casques de Chafers d\'Elite à Amayiro.', 727, 57, 1, '1500', '5995'),
(697, 72, 'Enquête sur la foire', 'Il faut chercher un formulaire auprès de Ture Inge, dans la milice, puis interroger le chef de la foire du Trool afin de détecter s\'il est un Brâkmarien ou non.', 729, 58, 1, '1501,1502,1503,9896,9897,9898', '6149'),
(698, 73, 'De la bouillie pour le Tabi', 'Apporter de la bouillie de fleurs de blops à Amayiro. Pour obtenir cette bouillie, il faut concasser quatre fleurs de blops de couleurs différentes dans un Concasseur Munster.', 739, 59, 2, '1504,9649,9650', '6161'),
(699, 74, 'Les informations du capitaine', 'Vous devez trouver un moyen pour entrer en communication avec feu le capitaine Tsog, afin d\'obtenir les informations qu\'il doit faire passer. Le capitaine Alrok connait l\'emplacement de la tombe de Tsog.', 731, 60, 1, '1505,9651,9652,9653,9654', '6162'),
(700, 75, 'De l\'agilité pour Amayiro', 'Amayiro vous a demandé vingt anneaux d\'agilité.', 732, 71, 1, '1506,9667,9668,9669,9670,9671,9672,9673,9674', '6163'),
(701, 76, 'L\'invocation inconnue', 'Amayiro vous a demandé de vous renseigner auprès de Zeurg, le maître de classe Osamodas, à propos d\'une invocation inconnue employée par Brâkmar.', 733, 72, 2, '1507,1508,9675,9676,9677,9678,9679', '6164'),
(702, 77, 'Amener les capes', 'Amayiro vous a demandé d\'apporter 10 capes bontariennes au capitaine Koda, à côté. Elles se confectionnent avec une teinture magique bleutée, une plume de crowneille et une laine de ramane strubien.', 1252, 73, 1, '1509,9681,9682,9683,9684', '6153'),
(703, 78, 'Patate chaude', 'Vous devez peler 250 pods de patates et les amener au cuisinier de la milice.', 735, 74, 1, '1510,9902,9903,9904', '6165'),
(704, 79, 'À la rescousse de Lyeno', 'Vous devez sauver le colonel Lyeno : il a disparu dans la partie est de la forêt des Abraknydes.', 736, 75, 1, '1511,1512,9722,9723,9724', '6166'),
(705, 80, 'Intendance', 'Danathor a demandé à vous rencontrer.', 737, 76, 1, '1517,1513,1727,1515,1516,9725', '6173'),
(709, 81, 'Un champo pour Amayiro', 'Amayiro vous a demandé de lui apporter un Champo ordinaire. Vous en trouverez sur les Maîtres Bolets.', 762, 77, 0, '1518,9726,9727,9728', '6168'),
(710, 82, 'Trouver le coupable', 'Trouvez l\'assassin de Rimaraf et amenez le formulaire rempli à Amayiro.', 738, 78, 0, '9731,9732,9733,1519,10123,10124,10125,9729', '6169'),
(712, 83, 'Poison de scorbute pour la prison', 'Suite au décès de son ami Rimaraf, Amayiro n\'a pas le moral et vous a envoyé aider le capitaine Essacarf.', 741, 79, 2, '1521,9735,9736,9737', '6171'),
(713, 84, 'Combat... pour rire', 'Vous devez trouver Dike Tarak dans le quartier nord et le défier.', 740, 80, 0, '1522,1523', '6172'),
(715, 85, 'Activités illicites', 'Des événements louches se trament dans le port de Bonta. Amayiro vous a demandé d\'enquêter.', 742, 91, 0, '1524,9750,9751,9752', '6174'),
(716, 86, 'Trouver une faille', 'Amayiro vous a demandé d\'explorer le Cimetière des Torturés, à l\'est de Brâkmar, et de voir s\'il y a une faille dans les défenses de la cité. Vous aurez sûrement besoin de matériel particulier.', 743, 92, 1, '1525,9753,9754,9755', '6229'),
(717, 87, 'Tête de bois', 'Amayiro vous a demandé de soutenir le colonel Lyeno.', 744, 93, 2, '1526,9756,9757,9758', '6175'),
(718, 88, 'Une requête', 'Vous avez reçu une lettre vous demandant assistance.', 745, 94, 1, '1527,1531,1528,9761,1529,9759,1530,1532', '6176'),
(720, 89, 'Le tabi de Grace', 'Grace Malcean, dans Bonta, a des problèmes avec son tabi.', -1, 95, 0, '1533,1534,9778,9779', '6070'),
(721, 90, 'Raid à Brâkmar', 'Amayiro vous a demandé de vaincre des guerriers brâkmariens avant qu\'ils n\'embarquent.', 20771, 96, 1, '1535,9780,9781', '6178'),
(722, 91, 'Une autre demande du cuistot', 'Le cuisinier de la milice a de nouveau demandé vos services.', 748, 97, 1, '1536,1537', '6179'),
(723, 92, 'Une leçon à donner', 'Un certain William Lenglad perturbe les habitants de Bonta : il faut aller le calmer, par la force.', 749, 98, 0, '1538,9782', '5798'),
(724, 93, 'Dans les geôles de Brâkmar', 'Amayiro vous a demandé de sauver Houé Dapyus, dans la prison de Brâkmar, et de le ramener à la milice bontarienne.', 750, 99, 1, '1539,9926,9927,9928', '6180'),
(725, 94, 'C\'est stupéfiant', 'Amayiro vous a demandé de poursuivre l\'enquête sur un trafic de stupéfiants.', 21165, 100, 2, '1540,9929,9930,9931,9932,9933,9934,9935', '6181'),
(726, 375, 'Désosser Mak', 'Battez Mak Gahan le Chafer et apportez un de ses os à Oto Mustam.', 812, 31, 0, '1541,9612', '6223'),
(727, 376, 'Offre d\'emploi', 'Oto Mustam veut savoir qui a assassiné l\'ancien patron de la Taverne du Chabrulé.', 813, 32, 0, '1542,9613,9614', '6183'),
(728, 377, 'Des potions énergétisantes', 'Oto Mustam a besoin de vingt potions Raide Dite.', 814, 33, 1, '1543', '5802'),
(729, 378, 'Un nouveau dentier', 'Vous devez arracher des dents de Chafer pour confectionner un dentier. Vous devez en amener exactement assez pour faire un dentier d\'humain... enfin, d\'humanoïde.', 815, 34, 1, '1544,9615', '6184'),
(730, 379, 'Redésosser Mak Gahan', 'Mak Gahan le Chafer veut sa revanche.', 816, 35, 0, '1545,9616', '6185'),
(731, 380, 'Amener les caisses', 'Il faut amener à Oto les caisses d\'armes blanches qui se trouvent à proximité de la tour des Ordres de Brâkmar.', 817, 36, 0, '1546', '6186'),
(732, 381, 'Une clé sur un écureuil', 'Vous devez retrouver un écureuil dans Brâkmar : il a volé une clé importante. Rapportez-la à Oto.', 48105, 37, 0, '1547,9617', '6187'),
(733, 382, 'Enquête importante', 'Faites le tour des gardes de Brâkmar et réalisez un compte-rendu des gardes qui ne prennent pas de pause.', 48326, 38, 0, '1548,9619,9618', '6188'),
(734, 383, 'Tabasser les Bontariens', 'Oto vous a demandé une bière de la Tabasse. La taverne de la Tabasse se trouve à Bonta.', 1090, 39, 1, '1549', '6556'),
(735, 384, 'Chasse au gland', 'Oto vous a demandé de débarrasser Brâkmar d\'un croc gland qui rôde autour de l\'enceinte.', 827, 40, 1, '1550,9620', '6189'),
(736, 385, 'Pauvre larve', 'Oto tient à ce que vous n\'oubliez pas qui est le chef et vous demande de lui rapporter de quoi se faire une mouillette.', -1, 51, 2, '1551,1552,9637,9638', '6272'),
(737, 386, 'Pauvre larve... dorée', 'Vous devez ramener la larve dorée à ses parents.', 1483, 52, 2, '1553,9639,9640,9641,9642,9643', '6190'),
(738, 387, 'Le rapport de l\'espion', 'Oto vous a demandé de trouver l\'espion Finche Aticus, à Bonta, et d\'exiger son rapport.', 823, 53, 1, '1554,1555,9644,9645', '6191'),
(739, 388, 'La relève', 'Vous devez demander au Guerrier Brank Thoof s\'il a du travail pour vous.', 825, 54, 0, '1556,9646,9647,9648', '6192'),
(740, 389, 'Les casques de Chafer', 'Oto veut quinze casques de Chafer d\'élite qu\'on trouve au Cimetière des Torturés.', 826, 55, 1, '1557', '6193'),
(741, 390, 'D\'égout pillé', 'Vous devez trouver ce qui, dans les égouts, est en train de contaminer la population de Brâkmar.', -1, 56, 1, '1558,9942,9943,9944,9945,9946', '6194'),
(742, 391, 'La bouillie de blops', 'Il faut apporter de la bouillie de blop concassés à Oto. Il peut vous donner la recette.', 828, 57, 1, '1559,9745,9746', '6195'),
(743, 392, 'À la recherche de poison magique', 'Vous devez trouver quelqu\'un dans Brâkmar qui sache préparer des poisons magiques.', 849, 58, 1, '1560,1562,9747,9748,9749', '6196'),
(744, 393, 'Les capes brâkmariennes', 'Oto vous a demandé cinq capes brâkmariennes. Il peut vous indiquer comment les fabriquer.', 830, 59, 2, '1561,9664,9666', '6197'),
(745, 394, 'Trouver le testament', 'Vous devez trouver le testament d\'Oto dans la tombe de son père, dans le cimetière des Torturés - la crypte est reconnaissable par la gerbe de fleurs déposée à l\'entrée.', 831, 60, 1, '1563,10116,10117,10118', '6198'),
(746, 395, 'La dèche d\'Oto', 'Oto n\'a plus un sou. Comment y remédier ?', 832, 71, 1, '1564,9689,9690,9691,9692,9693,9694,9695,9696,9697,9698,9699,9700,9701', '6199'),
(747, 396, 'Récolter la taxe', 'Vous devez récolter la nouvelle taxe d\'Oto dans chaque taverne de Brâkmar. Carte blanche pour tabasser les taverniers qui ne veulent pas payer.', 833, 72, 2, '1565,9702,9703,9704,9705,9706,9707,9708,9709,9710', '6200'),
(748, 397, 'Voler le Poumon', 'Oto veut que vous voliez le Poumon des plaines à Azra Lazarus, la bijoutière.', 834, 73, 1, '9711,1566,9712', '6201'),
(749, 398, 'Le grand épluchage', 'Vous devez éplucher des patates pour le dîner. La cuisine se trouve en bas de la milice.', -1, 74, 1, '1567,9899,9900,9901', '6008'),
(750, 399, 'Humilier Sbab ?', 'Oto vous a demandé d\'amener dix paires d\'oreilles de Koalaks Immatures à Sbab pour l\'horrifier. Mais il y a peut-être une autre solution si vous ne souhaitez pas le faire.', 860, 75, 1, '1568,9713,9714,9715', '6203'),
(751, 400, 'Aider Raaga', 'Trouvez Raaga dans les mines du nord et demandez-lui son rapport.', 837, 76, 1, '1569,1570,1571,1572,9716,9717', '6204'),
(752, 401, 'Retrouver l\'espion', 'Un espion a réussi à s\'échapper de Brâkmar avec des documents importants. Un des gardes au nord de Brâkmar l\'a peut-être vu.', 838, 77, 0, '1573,1574,9718', '6205'),
(753, 402, 'Retrouver les documents', 'Les documents secrets n\'étaient pas sur l\'espion. La faune des landes de Sidimote s\'en est peut-être emparée.', 839, 78, 0, '1575', '6206'),
(754, 403, 'Faire pénitence', 'Oto Mustam vous a envoyé jouer les larbins auprès de Penih Tencier.', 20715, 79, 2, '1576,9741,9742,9743', '6207'),
(755, 404, 'Défier Puja', 'Vous êtes censé défier Puja Mustam, le fils d\'Oto, et perdre. Mais vous n\'allez quand même pas vous laisser tuer par ce mioche ?', 840, 80, 0, '1577,9744', '6208'),
(756, 405, 'Joie de courte durée', 'Oto Mustam exige que vous mettiez fin à la joie qui se répand dans la cité.', -1, 91, 0, '1578,10119,10120', '6209'),
(757, 406, 'L\'attaque bontarienne', 'Vous devez repousser l\'attaque des Bontariens à l\'est de Brâkmar.', 850, 92, 1, '1579,1580,9905', '5749'),
(758, 407, 'Un assassin... à Bonta ?', 'Vous devez récupérer du poison dans l\'Antre de la Reine Nyée.', 853, 93, 2, '1581,1582,9906', '6210'),
(759, 408, 'Dent pour dent', 'Oto Mustam compte sur vous pour offrir à Mak Gahan un nouveau dentier.', 21128, 94, 1, '1583,9907,9908,9909,9910', '6211'),
(760, 409, 'Chasse aux fantômes', 'Vous devez inspecter la tour de Brâkmar et en chasser les fantômes qui la hantent.', 824, 95, 0, '1584,9911,9912', '6212'),
(761, 410, 'Arrivée à bon port', 'Vous devez mettre à mal un commando qui s\'entraîne dans le port de Bonta.', 846, 96, 1, '1585,9913,9914', '6213'),
(762, 411, 'Humiliation sans précédent', 'Vous devez aider Sbab a finir ses plats pour l\'émissaire Kanniboul.', 848, 97, 1, '1586,9915,9916,9917', '5999'),
(763, 412, 'L\'entretien', 'Oto Mustam veut que vous museliez l\'opposition.', 829, 98, 0, '1587,1588,1589', '6130'),
(766, 413, 'Sortie de prison', 'Vous devez sauver un guerrier qui a été capturé par Bonta : il se trouve dans la prison de la milice bontarienne, au sous-sol.', 851, 99, 1, '1592,9918,9919,9920', '6132'),
(767, 414, 'Mulanthropie', 'Oto Mustam souhaite renforcer la férocité des troupes d\'élite brâkmarienne et vous devez faire en sorte qu\'il y parvienne.', -1, 100, 2, '1593,1594,9921,9922,9923,9924,9925', '6061'),
(784, 120, 'À cœur vaillant, rien d\'impossible', 'Vous devez trouver un membre de la famille Terra et l\'emmener auprès de Jerhyn Gholein. Setag, le maître de classe Enutrof, pourra sans doute vous aider.', 2916, 140, 2, '1654,1655,1656,1657,2962,2963,1658', '6138'),
(785, 121, 'Interro surprise', 'Elviana Tirips veut savoir quelles informations les renégats bontariens ont données aux Brâkmariens et c\'est vous qui êtes en charge de l\'interrogatoire.', 5616, 140, 2, '1659,1660,1661,2954,2955,2956,10173,10174,1662,1663', '6139'),
(786, 122, 'La chasse aux renégats est ouverte', 'Vous devez retrouver un Huppermage renégat et le ramener à Bonta.', 2921, 140, 2, '10122,10175,10176,10177,10178,10179,10180,10181,10182,10183,10184,10185,10186', '6140'),
(788, 423, 'Apprentissage : Maître des Parchemins', 'Terra Cogita détient des informations sur l\'emplacement des statuettes de Sumens. Elviana Tirips vous a chargé de mettre la main dessus avant les Brâkmariens.', 5679, 180, 2, '1681,1682,1683,1684,1685,1686,1687,1688,3117,1689,1690,1691,1692', '6141'),
(789, 424, 'Apprentissage : Maître des Sévices', 'Vous avez été dupé par Terra Tibya. Divad exige que vous mettiez la main sur une statuette par vos propres moyens.', 5694, 180, 2, '1693,3133,1694,1695,1696,10353,10354,10355,1697,3134,3135,1698,1699,3139,3140', '6142'),
(790, 426, 'Apprentissage : Psychopathe', 'Brâkmar a déjà récupéré la première statuette de Sumens. Ledrob Terceséc vous demande de récupérer la deuxième, cachée dans le Temple du Grand Ougah.', 5711, 180, 2, '10358,10359,3136,3137,1702,10360,10361,10362,10363,3138,1701,1700', '6080'),
(792, 433, 'A la recherche du greffier déprimé', 'Tabach, Greffier de l\'Ordre du Coeur Vaillant, écume les tavernes depuis la disparition de son chat. Il faut le ramener auprès de Jerhyn Gholein.', -1, 60, 1, '1703,10089,10090,10091', '6144'),
(793, 434, 'A la recherche de la greffière', 'Ybaul, Greffière de l\'Ordre de l\'Esprit Salvateur, écume les tavernes à la recherche de ses frères. Il faut la ramener auprès d\'Elviana Tirips.', -1, 60, 1, '1704,10092,10093,10094', '6145'),
(794, 435, 'A la recherche du greffier attristé', 'Aigurraf, Greffier de l\'Ordre de l\'Œil Attentif, écume les tavernes depuis la disparition de sa souris. Il faut le ramener auprès d\'Ebru of El.', -1, 60, 1, '1705,10095,10096,10097', '6146'),
(795, 436, 'Os de cœur', 'Kaffra Kyper vous a demandé de régler le problème de Lache Welesa pour lui prouver votre valeur.', 1216, 60, 1, '1706,10098,10099,10100,10101,10102,10103', '5894'),
(796, 437, 'Poils au menton', 'Divad Dleifrepok vous a demandé de participer à un trafic d\'objets magiques pour lui prouver votre valeur.', 1217, 60, 1, '1707,10104,10105,10106,10107,10108,10109', '6453'),
(797, 438, 'Mauvais œil', 'Ledrob Terceséc vous a demandé de rencontrer Paul Hitik pour conclure une affaire en cours.', 1215, 60, 1, '1708,10110,10111,10112,10113,10114,10115', '6235'),
(798, 425, 'Apprentissage : Assassin Suprême', 'Ebru Of El vous a demandé de retrouver Dike Tarak, le neveu d\'Amayiro, enlevé lors d\'une sortie en classe verte dans les plaines de Cania.', 5721, 180, 2, '1709,1710,1711,1712,10356,10357,1713,1714,1715', '6150'),
(801, 421, 'Apprentissage : Champion Merveilleux', 'Jerhyn Gholein craint que Brâkmar envoie des agents voler la statuette de Sumens entreposée dans la tour de Bonta. Il vous charge de la protéger.', 5733, 180, 2, '1716,1717,1720,10386,10387,1721', '6151'),
(803, 422, 'Apprentissage : Champion du Chaos', 'Kaffra craint que Bonta envoie des agents voler la statuette de Sumens entreposée dans la tour de Brâkmar. Il vous charge de la protéger.', 5740, 180, 2, '1718,1719,1722,1723,1724,1725,3132,1726', '6462'),
