(991, 468, 'Vaincre le Dopeul', 'En cas de victoire contre le Dopeul, le maître des combats vous récompensera.', -1, 200, 0, '3178', '1276'),
(992, 469, 'Vaincre le Dopeul', 'En cas de victoire contre le Dopeul, le maître des combats vous récompensera.', -1, 200, 0, '3180', '1196'),
(994, 343, 'Petites faveurs entre amis', 'Il faut rallier les notables indécis à la cause de votre supérieur.', 0, 182, 1, '1319,1320,3186,1321,1322,10701,1323,1324,3187,1325,1326,1327,1328,1330,1331,1332,10702,10703,10704,10705,10706,10707,10708', '6254'),
(995, 470, 'Pélerinage sanglant', 'Affrontez le Dopeul de chacun des temples de classe.', -1, 200, 2, '3188,3189,3190,3191,3192,3193,3194,3195,3196,3197,3198,3199,4573,4591,5720,9511,10364,12179,18780', '142'),
(1021, 272, 'Abattre le tacticien', 'Vous avez décidé de recourir à la solution la plus extrême. La plus Brâkmarienne en somme.', 4446, 135, 2, '3396', '6018'),
(1034, 485, 'L\'Heure du Koalak', 'Warko Linch est en train de préparer un breuvage pour libérer les Koalaks de l\'emprise des Sadidettes à la solde de Skeunk.', 4971, 85, 1, '3462,3463,3464,3465', '152'),
(1035, 486, 'Percer le secret de la statue', 'Les Flaqueux ont enfoui leur secret au pied de la statue. Penchez-vous pour le ramasser.', -1, 30, 1, '3466', '5991'),
(1042, 489, 'Déplacement sur la carte', 'Cliquez sur le sol pour déplacer votre personnage.', -1, 1, 0, '3499', '6236'),
(1043, 489, 'Parler à un personnage', 'Cliquez sur {npc,2897::Ganymède}.', -1, 1, 0, '3501', '159'),
(1044, 489, 'Équiper un objet', 'Ouvrez l\'{ui,bannerMenu,gd_btnUis|uriName|btn_bag,1::inventaire}. Déplacez l\'{ui,storage,grid|objectGID|10785,1::anneau} vers l\'{ui,storage,slot_2,2::emplacement réservé à l\'anneau}.\nVous pouvez également l\'équiper en effectuant un double clic sur l\'{ui,s', -1, 1, 0, '3502', '6158'),
(1045, 489, 'Changer de carte', 'Pour changer de carte, déplacez votre curseur sur un des {transition,152305664,0,520,0,0::bords de l\'écran} et cliquez lorsqu\'une flèche apparaît.', -1, 1, 0, '3503', '6240'),
(1046, 489, 'Déclencher un combat', 'Cliquez sur le {monster,2785::globe céleste} pour lancer un combat.', -1, 1, 0, '3504', '6242'),
(1047, 489, 'Choisir sa position de départ', 'Cliquez sur une case rouge pour choisir votre position de départ et cliquez sur le {ui,banner,btn_readyOrSkip::bouton prêt} pour commencer le combat.', -1, 1, 0, '3507', '5428'),
(1048, 489, 'Se déplacer en combat', 'Se déplacer d\'une case coûte 1 {ui,banner,lbl_pm,2::point de mouvement} (PM). Déplacez votre personnage en cliquant sur une case. Vous récupérez vos {ui,banner,lbl_pm,2::PM} au début de votre prochain tour.', -1, 1, 0, '3508', '164'),
(1049, 489, 'Utiliser un sort', 'Sélectionnez {ui,bannerActionBar,gd_spellitemotes|slot|1,4::un sort} et cliquez sur la cible. La portée du sort est indiquée grâce aux cases bleues. Les sorts nécessitent des {ui,banner,lbl_pa,4::points d\'action} (PA) pour être lancés. Vous les récupérez ', -1, 1, 0, '3509', '165'),
(1050, 489, 'Fin de tour', 'Lorsque vous avez terminé vos actions, cliquez sur le bouton {ui,banner,btn_readyOrSkip::Terminer le tour} pour accélérer le déroulement du combat et regagner vos {ui,banner,lbl_pa,2::PA} et vos {ui,banner,lbl_pm,2::PM}.', -1, 1, 0, '3510', '166'),
(1051, 489, 'Gagner le combat', 'Continuez d\'attaquer votre cible pour gagner le combat. Terminez votre tour grâce au bouton {ui,banner,btn_readyOrSkip::Terminer le tour} pour regagner vos {ui,banner,lbl_pa,2::PA} et {ui,banner,lbl_pm,2::PM}.', -1, 1, 0, '3511', '167'),
(1052, 489, 'Commencer une quête', 'Parlez à {npc,2897::Ganymède} pour lancer une quête. Les personnages qui proposent des quêtes ont un point d\'exclamation au-dessus de leur tête.', -1, 1, 0, '3512', '168'),
(1053, 489, 'Défier le monstre', 'Pour continuer votre quête, vous devez aller sur la {transition,152306690,2,700,1,0::carte suivante} et lancer un combat contre {monster,2781::le monstre}.', -1, 1, 0, '3513', '169'),
(1055, 492, 'Combattre le bouftou céleste', 'Un combat qui met à l\'épreuve vos capacités.', 20644, 1, 0, '3514', '5994'),
(1059, 489, 'Conclure l\'apprentissage', 'Pour terminer votre quête, parlez à {npc,2897::Ganymède}. Les personnages qui peuvent valider des objectifs de quête ont un point d\'interrogation au-dessus de leur tête.', -1, 1, 0, '3529', '5893'),
(1060, 489, 'Équiper ses objets', 'Ouvrez l\'{ui,bannerMenu,gd_btnUis|uriName|btn_bag,1::inventaire} et équipez les objets.\nEn portant plusieurs pièces d\'une même panoplie, votre personnage gagne des bonus supplémentaires.', -1, 1, 0, '3530', '6214'),
(1061, 489, 'Terminer le combat', 'Gagnez le combat. Les tours de jeu ont désormais une durée limitée, faites attention à la {ui,banner,pb_time,4::jauge de temps restant}.', -1, 1, 0, '3531', '5892'),
(1062, 494, 'Le Grand Manitou', 'Vous devez vaincre le Manitou Zoth et apporter une preuve de votre victoire à Bob l\'Enutrof.', 7597, 150, 0, '3532', '172'),
(1063, 495, 'Usine à jouets', 'D\'abominables créatures ont cambriolé l\'entrepôt du Père Nowel. Vous devez récupérer les caisses de cadeaux qu\'elles ont volées, avec ou sans leur consentement, et les apporter à Félix Nowel.', -1, 30, 2, '3533,3534', '173'),
