(1093, 525, 'L\'histoire cachée', 'La légende de Goultard ne raconte pas toute sa vie. Suivez son histoire depuis son enfance pour percer ses secrets.', -1, 50, 0, '3591,3592,3593,3594,3618', '6001'),
(1094, 526, 'Gisgoul, ma patrie', 'L\'ambition des Brâkmariens n\'a pas de limite.', -1, 50, 1, '3595,3613,3596,3597,3614,3615,3617,3599,3600', '6002');
INSERT INTO `quest_steps` (`Id`, `QuestId`, `Name`, `Description`, `DialogId`, `OptimalLevel`, `Duration`, `ObjectiveIds`, `RewardIds`) VALUES
(1095, 526, 'Bwork qui tue rit, te saluant', 'Faites les courses de Léthaline.', -1, 50, 1, '3601,3602,3604', '6003'),
(1096, 526, 'Mauvais plan', 'Allez semer des petits cailloux blancs dans le Dédale du Dark Vlad.', -1, 50, 1, '3605,3606,3607,3608,3609', '5966'),
(1097, 526, 'Goultard-Z', 'Toutes les pièces sont placées, il faut porter le dernier coup.', -1, 50, 1, '3611,3612,3619', '5967'),
(1098, 527, 'Gisgoul, ma patrie', 'L\'ambition des Brâkmariens n\'a pas de limites.', -1, 50, 1, '3620,3621,3622,3623,3624,3625,3626,3627,3628', '5968'),
(1099, 527, 'La théorie du chaos', 'Débarrassez-vous de la source du mal.', -1, 50, 1, '3630,3631,3632,3633,3634,3635', '5969'),
(1100, 527, 'Mauvais plan', 'Contrecarrez les plans des Brâkmariens.', -1, 50, 1, '3636,3637,3638,3639,3640,3641', '5970'),
(1101, 527, 'Goultard-Z', 'Réglez vos comptes avec Léthaline.', -1, 50, 1, '3642,3643', '5971'),
(1107, 536, 'Chasse aux boufmouths', 'Clyde Parker vous a demandé de vous débarrasser des boufmouths, dans les champs de glace.', 7687, 110, 1, '3650', '203'),
(1108, 537, 'Chasse aux créatures de la forêt', 'Clyde Parker vous a demandé de vous débarrasser des créatures de la forêt, dans la forêt des pins perdus.', 7687, 120, 1, '3651', '204'),
(1109, 538, 'Chasse aux mansots', 'Clyde Parker vous a demandé de vous débarrasser des mansots, dans le lac gelé.', 7687, 130, 1, '3652', '205'),
(1110, 539, 'Chasse aux fantômes de pirates', 'Clyde Parker vous a demandé de vous débarrasser des fantômes de pirates, dans le berceau d\'Alma.', 7689, 150, 1, '3653', '206'),
(1111, 540, 'Chasse aux crapeurs', 'Clyde Parker vous a demandé de vous débarrasser des crapeurs, dans les larmes d\'Ouronigride.', 7689, 160, 1, '3654', '207'),
(1112, 541, 'Chasse aux créatures de lave', 'Clyde Parker vous a demandé de vous débarrasser des créatures de lave, dans l\'hypogée de l\'Obsidiantre.', 7689, 160, 1, '3655', '208'),
(1113, 530, 'Collecte de céréales', 'Fidèle à son habitude, Annette Daimpeau est partie dormir au lieu de ravitailler Frigostine. La boulangère vous a donc demandé de remplacer son employée.', 7694, 100, 0, '3656', '5981'),
(1114, 531, 'Collecte de fleurs', 'Ne pouvant laisser son atelier sans surveillance, Eric Azaraille vous a demandé de lui servir de fournisseur.', 7733, 100, 0, '3657', '5982'),
(1115, 532, 'Collecte de poissons', 'Avec l\'arrivée massive d\'aventuriers, les réserves de poisskailles diminuent à vue d\'oeil. C\'est pourquoi Clarisse Tosha vous a demandé de la ravitailler.', 7735, 100, 0, '3658', '5983'),
(1116, 534, 'Collecte de viandes', 'Avec l\'arrivée massive d\'aventuriers, les stocks de viandes diminuent à vue d\'oeil. C\'est pourquoi Al Shab vous a demandé de le ravitailler.', 8138, 100, 0, '4005', '5985'),
(1117, 533, 'Collecte de minerai', 'L\'exploitation des mines a pratiquement cessé depuis plusieurs décennies, et les réserves d\'obsidienne servant à la fonte d\'alliage sont à sec. Laurent Gebleuh vous a donc proposé de l\'aider à renflouer ses stocks.', 7737, 100, 0, '3659', '5984'),
(1118, 535, 'Collecte de bois', 'Le Chef Rhonté a besoin d\'une quantité astronomique de bois pour servir de combustible au système de dégel du port. Il vous a demandé un petit coup de main.', 7739, 100, 0, '3660', '5986'),
(1119, 555, 'C\'est l\'heure de l\'apéwicube', 'Vous avez trouvé une Plume Vibrante de mansot, mais impossible de connaître son utilité. Heureusement, vous avez entendu certains pêcheurs en parler en citant Kyrie Lawache. Peut-être pourra-t-elle vous en dire plus.', -1, 100, 0, '3661', '209'),
(1120, 542, 'La cave infestée', 'Aller dans la cave de Grand-père et exterminer la menace.', 7678, 100, 0, '3662', '5974'),
(1121, 542, 'Récompense méritée', 'Reparler à Grand-père et lui montrer les restes de rat bougri.', -1, 100, 0, '3663', '5713'),
(1123, 619, 'Savez-vous scalper les boufmouths ?', 'Truffo vous a demandé de calmer les ardeurs du Royalmouth, rendu agressif par la chaleur tropicale de la serre et le manque de nourriture.', 7685, 120, 2, '3666,3667,3668', '5821'),
(1124, 613, 'La maire m\'aide', 'Le mousse Haka vous a indiqué où trouver la mairesse, qui pourra vous renseigner sur la bourgade de Frigost et ses habitants.', 7691, 100, 0, '3669', '5976'),
(1125, 614, 'Site de rencontre', 'Afin de vous familiariser avec la bourgade, la maire Cantile vous a demandé de rencontrer plusieurs personnalités de Frigost.', 7709, 100, 1, '3674,3675,3676,3677,3678,3679,3680,3681,3682,3683,3684,3685,3686,3687,3688,3689,3690,3691,3692,3693,3694,3695,3696', '5977'),
(1126, 612, 'Le peuple migrateur', 'Le Capitaine Ardier vous a proposé une magnifique croisière sur son authentique navire pour aller visiter la lointaine île de Frigost.', -1, 100, 0, '3697,3698,3699,3700', '210'),
(1127, 556, 'Graines des champs', 'Afin de créer des espèces de céréales plus résistantes au froid, Cassiopée Hisane vous a demandé de lui apporter plusieurs types de graines.', 7747, 110, 2, '3701,3702,3703', '211'),
(1128, 557, 'Pin ou baguette ?', 'Cassioppée Hisane souhaite diversifier la production issue de la culture de céréales et a besoin de nouvelles variétés de graines, que l\'on trouve dans la forêt des pins perdus.', 7748, 120, 2, '3704,3705', '212'),
(1129, 558, 'Une santé de fer', 'Les mansots semblent plus résistants grâce à une alimentation riche en fer. Cassiopée Hisane vous a demandé d\'en massacrer plein pour récupérer leur réserve de graines.', 7749, 130, 2, '3706', '213'),
(1130, 559, 'Le sel de la terre', 'Le manque de sel a entraîné de nombreux cas d\'astrubisme chez les Frigostiens. Afin d\'endiguer ce fléau, Cassiopée Hisane veut essayer de cultiver des grains de sel dans une serre adaptée.', 7750, 150, 2, '3707', '214'),
(1131, 560, 'Altercations céréalières', 'Cassiopée Hisane veut croiser les frostizs avec les graines hades et hayes pour résister naturellement contre les parasites et les mauvaises herbes.', 7751, 160, 2, '3708,3709', '215'),
(1132, 561, 'Renforcement génétique', 'Cassiopée Hisane veut des graines de basalte pour renforcer la résistance aux changements brusques de température des frostizs, et des graines houilles pour les croiser avec des grains de sel.', 7752, 160, 2, '3710,3711', '216'),
(1133, 562, 'Céréales de nouvelle génération', 'Circé Réal veut expérimenter de nouveaux croisements de céréales et requiert votre aide.', 8118, 170, 2, '3712,3713', '217'),
(1134, 563, 'L\'agriculture, c\'est magique', 'Circé Réal a obtenu du maire que vous puissiez accéder à la forêt pétrifiée pour y récupérer des graines magiques.', 8258, 180, 2, '3714,3715', '218'),
(1135, 564, 'Les héros ramassent les orties', 'Insatisfaite des résultats précédents, Circé Réal a besoin de nouvelles graines provenant des crocs de verre.', 8261, 190, 2, '3716,3717', '219'),
(1136, 565, 'Miel en colique', 'Circé Réal souhaite développer davantage l\'agriculture en se basant sur les céréales des gloursons du mont Torrideau.', 8264, 190, 2, '3718,3719', '220'),
(1137, 615, 'Rube Eole', 'Vous devez apporter à Albert Paisse des échantillons de sang de boufmouth malade.', 7760, 120, 2, '3720', '5978'),
(1138, 615, 'Susceptibilité à fleur de peau', 'Albert Paisse a besoin d\'eau de mer isotonique. Seul le Capitaine Gneux sait comment s\'en procurer.', 7761, 100, 2, '3721,3722,3723,3724,3725,3726,3727', '5979'),
(1139, 615, 'Affronter La Bête', 'Vous devez réussir à prélever un échantillon de sang sur le cobaye d\'Albert Paisse.', 7779, 100, 2, '3728', '221'),
(1140, 554, 'Thérapeutique', 'Vous devez trouver une solution à l\'invasion de tiques qui parasitent les boufmouths.', 7783, 100, 2, '3729,3730,3731,3732,3733,3734,3735', '5980'),
(1141, 554, 'Tique psychodyslep', 'Wogew l\'hewmite pense qu\'Otomaï peut l\'aider dans ses recherches et vous envoie lui apporter des documents pour ce faire.', 7788, 100, 2, '3736,3737,3738', '222'),
(1142, 589, 'Problème de tuyauterie', 'Valy Domidat, la bricoleuse en chef, a disparu en allant réparer la tuyauterie de l\'atelier des paysans. Francky, son employé, vous a demandé de la retrouver.', 7795, 100, 1, '3739,3740', '6555'),
(1143, 589, 'Le glouglou qui fait glagla', 'Jean-Pierre Kofkof est intervenu après la dispute entre Valy Domidat et une étrangère. Il a peut-être remarqué quelque chose d\'inhabituel.', 7799, 100, 1, '3741,3742,3743', '223'),
(1144, 590, 'Fantastique balade en forêt', 'Plusieurs Frigostiens employés par le Chef Rhonté ont disparu dans la forêt des pins perdus. Vous devez découvrir ce qui leur est arrivé.', 7807, 120, 1, '3744,3745', '5739'),
(1145, 590, 'Quatre fantastiques retours en ville', 'Vous avez trouvé les rescapés, victimes d\'un étrange maléfice. Vous devez les escorter en ville, un par un.', 7808, 120, 1, '3746,3747,3748,3749,3750,3751,3752,3753,3754,3755,3756', '224'),
(1146, 591, 'Mauvais chasseur', 'Le chasseur Gérard a disparu. Clyde Parker, le chef de la milice, vous a chargé de le retrouver.', 7821, 140, 2, '3757,3758,3759,3760,3761,3762', '225'),
(1147, 616, 'Pin perdu, mais pas pour tout le monde', 'Le Chef Rhonté a besoin d\'énormes quantités de bois pour alimenter le chauffage des canons à vapeur.', -1, 120, 1, '3763,3764,3765,3766', '5987'),
(1148, 616, 'Du pin mais pas de jeu', 'Le Chef Rhonté a besoin d\'énormes quantités de bois pour alimenter le chauffage des canons à vapeur.', -1, 120, 1, '3767,3768,3769,3770', '226'),
(1149, 577, 'La faune et la fore', 'Damar, le chef des pêcheurs du lac gelé, a besoin de matériaux pour réparer le matériel de pêche.', 7845, 130, 2, '3771,3772,3773,3774,3775,3776,3777', '227'),
(1150, 577, 'Faux témoignage', 'Damar a besoin de l\'aide de Valy Domidat, la bricoleuse de Frigost.', 7846, 130, 2, '3778,3779,3780,3781', '228'),
(1151, 578, 'Éclaireurs mansots', 'Des mansots sont sur le point d\'attaquer. Vous devez absolument les vaincre : en cas de défaite, vous n\'aurez pas d\'autre chance. Si vous voulez venir à bout de cette mission, pas de reddition !', 51004, 130, 0, '3782,3783', '229'),
(1152, 628, 'Guerriers mansots', 'Des mansots sont sur le point d\'attaquer. Vous devez absolument les vaincre : en cas de défaite, vous n\'aurez pas d\'autre chance. Si vous voulez venir à bout de cette mission, pas de reddition !', 51005, 130, 0, '3784,3785', '230'),
(1153, 629, 'Vétérans mansots', 'Des mansots sont sur le point d\'attaquer. Vous devez absolument les vaincre : en cas de défaite, vous n\'aurez pas d\'autre chance. Si vous voulez venir à bout de cette mission, pas de reddition !', 51006, 130, 0, '3786,3787', '231'),
(1154, 579, 'Distribution de pichon', 'Damar veut profiter de la démoralisation des mansots pour rouvrir les lignes de ravitaillement en pichons.', 7853, 130, 1, '3788,3789,3790,3791,3792,3793,3794', '232'),
(1155, 580, '640, année exotique', 'Pour réhabiliter l\'ancien village de Frigost, Aurore Boréale a opté pour un mélange de bois de tremble et de planches en bois de kaliptus, que vous devez lui fournir.', 7866, 120, 1, '3795,3796', '233'),
(1156, 599, 'Un dopeul inoffensif', 'Cette peluche Féca doit bien appartenir à quelqu\'un, mais qui ?', -1, 110, 0, '3797', '234'),
(1157, 600, 'Gomme à tout faire', 'La gomme à mâcher est un outil indispensable pour le Xélor Mac Givré. Il sera ravi d\'en recevoir.', -1, 120, 0, '3798', '235'),
(1158, 566, 'Champs boulet', 'Bisale Vinlenta a besoin de fleurs en grande quantité pour son projet alternatif à l\'agriculture.', 7874, 110, 2, '3799,3800,3801', '236'),
(1159, 567, 'S\'en aller, tout simplement', 'Bisale Vinlenta est à la recherche de plantes pré-glaciation pour faire des croisements.', 7876, 120, 2, '3802,3803', '237'),
(1160, 568, 'La famille des rhubarbes à papa', 'Pour améliorer le goût des plantes, Bisale Vinlenta veut utiliser de la rhubarbe à papa, que seuls les mansots détiennent.', 7878, 130, 2, '3804', '238'),
(1161, 584, 'Ingratitude enfantine', 'Agnès Péha offre des timansots orphelins en échange de poisskailles.', 7881, 110, 0, '3805', '239'),
(1162, 581, 'Fondations', 'Aurore Boréale projette d\'ouvrir un hôtel entièrement taillé dans la glace. Afin d\'y parvenir, elle a besoin de nombreux outils.', 7882, 130, 2, '3806,3807,3808,3809', '240'),
(1163, 601, 'Le coffre et la demande', 'Le propriétaire du coffre familial récompensera sûrement quiconque le lui restituera.', -1, 150, 0, '3810', '241'),
(1164, 602, 'Livre à domicile', 'Vous pouvez donner le livre scellé à Hugo Frais l\'archiviste ou Hyppolite Tairmy le bibliothécaire.', -1, 170, 0, '3811', '5951'),
(1165, 620, 'Mon royaume pour un poisskaille', 'Waldos FieldChester Potcobble souhaite cuisiner un poisskaille royal lors d\'un dîner aux chandelles avec Aurore Boréale. Il vous a chargé de le lui fournir.', -1, 140, 2, '3812,3813,3814', '5822'),
(1166, 582, 'Hiver un jour, hiver toujours', 'Mac Givré a besoin de main-d\'oeuvre qualifiée. Vous devez convaincre la Maire de Frigost de le laisser prospecter dans la bourgade.', 7887, 130, 2, '3815,3816,3817,3818,3819,3820,3821,3822,3823,3824,3825', '5952'),
(1167, 582, 'Rube Eole', 'Craignant la propagation du rube, Mac Givré a besoin de plusieurs vaccins.', 7897, 130, 2, '3826,3827', '242'),
(1168, 592, 'Il se laisse aller sur les flots', 'Germain Danlsak souhaite savoir où son défunt père a caché son butin.', 7900, 150, 1, '3828,3829,3932', '5953'),
(1169, 592, 'Il rêvait d\'un long voyage sur un bateau', 'Lafairé Danlsak a accepté de vous révéler l\'emplacement de son butin si vous réussissez à libérer son âme.', -1, 150, 1, '3830,3831,3832,3833,3834', '243'),
(1170, 549, 'On recherche le YeCh\'Ti', 'Certains disent l\'avoir vu se diriger vers la Crevasse Perge après l\'un de ses forfaits, au nord de l\'île. Il doit être mis en cage à la Bourgade pour ses expéditions carnassières envers les Boufmouths d\'élevage.', -1, 170, 1, '3835,3836', '244'),
(1171, 548, 'On recherche Vengeuse Masquée', 'Certains prétendent avoir été attaqués près des sources thermales des larmes d\'Ouronigride. La Vengeuse Masquée est recherchée pour trouble de l\'ordre public et vengeance injustifiée.', -1, 160, 1, '3837,3838', '245'),
(1172, 547, 'On recherche Fantômayte', 'Certains prétendent l\'avoir aperçue en compagnie de fantômes. Elle est recherchée pour vol d\'un masque d\'argent et agressions répétées sur des furets domestiques.', -1, 150, 1, '3839,3840', '246'),
(1173, 545, 'On recherche Monsieur Pingouin', 'Certains prétendent avoir vu Monsieur Pingouin au milieu des mansots. Il est recherché pour vol de poisskaille et dégradation volontaire de pêcheur.', -1, 130, 1, '3841,3842', '247'),
(1174, 631, 'Alerte à Frigost', 'Albert paisse craint une épidémie de rube et vous demande de vacciner les malades.', 7910, 120, 1, '3843,3844,3845,3846,3847,3848,3849,3850', '248'),
(1175, 543, 'Mansoétude', 'Craignant son extinction, Ken Tucky souhaite recueillir des mamansots afin de préserver l\'espèce.', 7927, 130, 1, '3851,3852,3853,3854,3855,3856,3857', '249'),
(1176, 618, 'Reforestation', 'Pour lutter contre la déforestation, Panoramist vous a demandé de planter des graines.', 7936, 120, 1, '3858,3859,3860,3861,3862,3863,3864,3865,3866,3867,3868,3869,3870,3871,3872,3873,3874,3875,3876,3877,3878,3879,3880', '250'),
(1177, 636, 'Escorter le blessé', 'Vous devez escorter un chasseur blessé jusqu\'à la bourgade de Frigost, pour qu\'il soit pris en charge par le médecin Albert Paisse.', 7938, 120, 0, '3881', '251'),
(1178, 637, 'Escorter le pas doué', 'Vous devez escorter un chasseur blessé jusqu\'à la bourgade de Frigost, pour qu\'il soit pris en charge par le médecin Albert Paisse.', 7939, 120, 0, '3882', '252'),
(1179, 638, 'Escorter le mauvais chasseur', 'Vous devez escorter un chasseur blessé jusqu\'à la bourgade de Frigost, pour qu\'il soit pris en charge par le médecin Albert Paisse.', 7940, 120, 0, '3883', '253'),
(1180, 639, 'A vive allure', 'Pendant que Djauns surveille son trésor, vous devez récupérer un attelage de chienchiens des neiges et le lui apporter. Le temps vous est compté.', 7947, 150, 0, '3884,3885', '254'),
(1181, 641, 'YeCh\'Ti Bodoudou', 'Les Frigostiens ont monté une expédition punitive pour se débarrasser du YeCh\'Ti. Ils ont besoin de Fourrures intactes de Givrefoux pour tromper sa vigilance.', 7954, 170, 2, '3886', '255'),
(1182, 642, 'Concours d\'affreux bonmonstres', 'le petit Nico et ses amis font un concours dont vous êtes le jury. Il vous faut choisir lequel des bonmonstres de neige est le plus affreux.', 7964, 170, 0, '3887,3888,3889,3890,3891,3892', '5954'),
(1183, 635, 'Mets tes bottes', 'Larry Tutthe a besoin d\'un nouvel assistant et il vous a chargé du recrutement.', 7973, 160, 1, '3893,3894,3895,3896,3897', '5955'),
(1184, 635, 'Extrait d\'une inspection', 'Larry Tutthe est débordé et a besoin d\'un coup de main.', -1, 160, 1, '3898,3899,3900,3901,3902,3903,3904,3905', '256'),
(1185, 640, 'L\'eau d\'Ogivol Victor est une chance', 'Ogivol Victor a besoin de votre aide pour prélever de l\'eau minérale afin de l\'analyser et de la rendre potable.', 7983, 160, 2, '3906,3907,3908,3909,3910,3911,3912,3913,3914', '257'),
(1186, 640, 'Un être s\'éveille', 'Un alchimiste pourra vous aider à mieux cerner l\'identité de la créature trouvée dans les larmes d\'Ouronigride.', 7986, 160, 2, '3915,3916,3917,3918,3919,3920,3921,3922', '258'),
(1187, 644, 'Givrefoux givrés', 'Des givrefoux complètement givrés s\'en prennent aux voyageurs. Vous devez les vaincre.', 7992, 170, 0, '3923,3924', '259'),
(1188, 643, 'Meurtre de sang-froid', 'L\'esprit Zonier veut se venger de l\'agriculteur qui l\'a assassiné. Il vous a demandé d\'être son bras vengeur.', 8004, 100, 1, '3925,3926,3927,3928,3929,3930,3931', '5956'),
(1189, 634, 'Amour impossible', 'Groméo et Ginette ne peuvent pas se marier à cause d\'un différent opposant leurs familles. Ils vous implorent de trouver une solution.', 8028, 130, 2, '3933,3934,3935', '5957'),
(1190, 634, 'La vérité sort aussi de la bouche des adultes', 'Ginette a un plan pour découvrir ce qui s\'est réellement passé concernant le vol et c\'est vous qui allez le découvrir.', 8036, 130, 2, '3936,3937,3938,3939,3940,3941,3942,3943,3944,3945,3946,3947', '5958'),
(1191, 634, 'Réconciliation houleuse', 'Les Capoués semblent n\'avoir rien à se reprocher concernant le vol de céréales, mais quelque chose cloche. Reste à découvrir quoi.', -1, 130, 2, '3948,3949,3950,3951,3952,3953,3954,3955,3956', '5959'),
(1192, 634, 'Ginette, l\'imperfection au féminin', 'Ginette a été enlevée par un kaniglou. Groméo a tenté de la sauver, en vain. Il vous supplie de la délivrer.', 8060, 130, 2, '3957,3958,3959,3960', '260'),
(1193, 646, 'Entre 4 planches', 'Trouver et apporter des planches de différentes essences de bois.', -1, 130, 2, '3961,3962,3963,3964', '5960'),
(1194, 646, 'La philanthropie de l\'ouvrier charpentier', 'Trouver des outils pour confectionner les skis.', -1, 130, 2, '3978,3979,3967,3965,3966,3991', '5961'),
(1195, 646, 'Mise à pieds', 'Trouver un cordonnier pour confectionner les chaussures.', -1, 130, 2, '3968,3992', '5962'),
(1196, 646, 'Pour les skis, des fonds', 'Vendre les paires de skis.', -1, 130, 2, '3969,3970,3971,3972,3993', '261'),
(1197, 569, 'Marée basse', 'Pour donner un coup de main au médecin de Frigost, Bisale Vinlenta a besoin de 40  Saules en si.', 8070, 150, 2, '3973', '262'),
(1198, 570, 'Rose à lys, Rose à lys, ah !', 'Bisale Vinlenta a besoin de nouvelles plantes qui poussent uniquement dans les larmes d\'Ouronigride.', 8074, 160, 2, '3974,3975', '263'),
(1199, 571, 'Voyage au centre du tunnel', 'Pour anticiper une éventuelle période chaude, Bisale Vinlenta veut croiser les espèces de plantes actuelles avec celles de l\'hypogée de l\'Obsidiantre.', 8076, 160, 2, '3976,3977', '264'),
(1200, 593, 'Centrale à vapeur', 'Le naturaliste Pleni l\'Ancien est porté disparu dans les larmes d\'Ouronigride. A la demande de son neveu, Pleni le Jeune, Hyppolite Tairmy vous a engagé pour le retrouver.', 8081, 160, 1, '3980,3981,3982,3983,3984,3985,3986,3987,3988,3989,3990', '265'),
(1201, 630, 'Trouver et éliminer le Comte Harebourg', 'Le Comte Harebourg est accusé d\'avoir trompé les Frigostiens et causé la glaciation. Une forte prime est promise à quiconque l\'éliminera.', 0, 200, 1, '3994,3995,3996', '4378'),
(1203, 572, 'Faire un bon voyage', 'Eric Azaraille compte sur vous pour récupérer des lys dans la crevasse Perge.', 8125, 170, 2, '3997,3998', '266'),
(1204, 594, 'La lettre d\'Annette', 'Annette Daimpeau souhaite que vous retrouviez son fiancé Dan Lavy, disparu avant la glaciation, et que vous lui remettiez une lettre.', 8129, 160, 2, '3999,4000,4001,4002', '6554'),
(1205, 594, 'La vengeance d\'Annette', 'Annette veut se venger de la mort de Dan Lavy.', 8135, 160, 2, '4003,4004', '267'),
(1206, 605, 'Cadeau pour une inconnue', 'Trouver la personne idéale à qui offrir la Broche en nacre.', -1, 160, 0, '4008', '6989'),
(1207, 648, 'Fyqmpsfs mft njoft', 'Izxbo Lfopcz wpvt b efnboef ef wbjodsf vo hpcfmjo ebot mft njoft qpvs rv\'jm qvjttf mvj efspcfs vof qfqjuf', 8153, 180, 2, '4009', '5964'),
(1208, 649, 'Une bourgade chaleureuse', 'Vous devez faire connaissance avec les habitants de la bourgade et vous protéger contre le rube.', 8156, 120, 2, '4010,4062,4063,4064,4065', '269'),
(1209, 650, 'On se gèle', 'Les pêcheurs du lac gelé ont besoin d\'aide.', 8158, 140, 2, '4011,4066', '270'),
(1210, 651, 'Dix de perdus, combien de retrouvés ?', 'Des Frigostiens sont portés disparus. La maire Cantile vous a confié l\'enquête.', 8160, 170, 2, '4012,4067,4068,4069,4070,4071,4072,4073', '271'),
(1211, 652, 'Cultures biologiques', 'Lucette Brifian vous a prévenu que les paysans peuvent avoir besoin de votre aide. Renseignez-vous auprès de Cassiopée Hisane ou Bisale Vinlenta.', 8419, 190, 2, '4236,4013', '272'),
(1212, 653, 'De cervelle et d\'acier', 'Lucette Brifian vous a invité à vous mesurer aux créatures qui se sont installées dans les donjons de l\'île de Frigost.', 8421, 190, 2, '4240,4241,4242,4243,4244,4245,4246,4247,4014', '273'),
(1213, 654, 'Ennemis d\'état', 'Lucette Brifian vous a signalé que des têtes ont été mises à prix.', 14846, 190, 2, '4248,4249,4250,4251,4252,4253,4254,4015', '4376'),
(1214, 656, 'Combat loyal', 'Vous devez vaincre votre adversaire en un seul combat. Bonne chance.', 8170, 200, 0, '4016', '274'),
(1215, 546, 'On recherche Katigrou', 'Certains prétendent avoir reçu un kaniglou orange sur la tête en se promenant dans la forêt des pins perdus. Katigrou est recherché pour atterrissage mortel.', -1, 140, 1, '4017,4018', '275'),
(1216, 544, 'On recherche Bouflouth', 'Certains prétendent avoir aperçu Bouflouth dans les champs de glace. Il est activement recherché pour consommation et digestion de butin sans l\'accord de son propriétaire.', -1, 120, 1, '4019,4020', '276'),
(1217, 657, 'Barnabé dans l\'espace', 'Retrouvez Barnabé. Il a été enlevé et emmené en dehors de ce monde.', 8174, 200, 1, '4021,9528,9529,9530,9531,9532,9533,9534,9535', '6613'),
(1218, 617, 'Forêt en sursis', 'Bambelle a besoin de votre aide pour demander conseil auprès du bricoleur Francky.', 8180, 120, 2, '4022,4023,4024,4025,4026,4027,4028,4029,4030', '277'),
(1219, 617, 'Détournement de fond de cuve', 'Bambelle a besoin d\'une copie des plans des canalisations à proximité de sa scierie. Des originaux se trouvent en possession d\'Hugo Frais l\'archiviste et Valy Domidat la bricoleuse.', 8182, 120, 2, '4031,4032,4033,4034,4035,4036,4037,4038,4039,4040', '278'),
(1220, 658, 'Remettre la lettre à Abdhoul Heure', 'Vous devez remettre discrètement la lettre à Abdhoul Heure.', 8188, 160, 1, '4041', '279'),
(1221, 659, 'Remettre la lettre à Jean-Pierre Kofkof', 'Vous devez remettre discrètement la lettre à Jean-Pierre Kofkof.', 8188, 163, 1, '4042', '280'),
(1222, 660, 'Remettre la lettre à Bisale Vinlenta', 'Vous devez remettre discrètement la lettre à Bisale Vinlenta.', 8188, 166, 1, '4043', '281'),
