(1902, 583, 'L\'ombre et la glace', 'Vous devez fabriquer une combinaison pour venir en aide à des pêcheurs disparus dans les entrailles du lac gelé.', 14186, 140, 1, '7142,7143,7144,7145,7146,7147,7148,7149,7150', '4334'),
(1903, 1286, 'Lumière sur l\'ombre', 'Il vous est conseillé de recruter des compagnons pour vous aventurer dans les profondeurs du lac gelé.', 0, 140, 1, '7151,7152,7153', '4335'),
(1904, 1287, 'Qu\'est-ce qu\'on a fait des tuyaux ?', 'L\'agent de la compagnie Asfog et Fils a été agressé près des chaudières et vous a demandé d\'enquêter.', 14937, 150, 1, '7432,7433,7434,7436,7437,7438,7439,7440,7441,7442,7443', '4336'),
(1905, 1288, 'Lâcher les gaz', 'Dolores Kimo vous a avoué qu\'elle a enseigné des méthodes de sabotage à des ouvriers du lac. L\'enquête continue.', 14957, 150, 1, '7444,7445,7446,7447,7448,7449,7450,7451,7452,7453,7454,7455,7456', '4337'),
(1906, 1309, 'Il faut mettre un terme aux maîtres', 'Vous avez décidé de rendre visite aux maîtres-artisans du château de Harebourg pour leur botter les fesses. Vous ignorez comment vous est venue cette idée, sûrement que cette petite voix dans votre tête qui vous pousse à massacrer tout ce qui se trouve su', 0, 200, 2, '7164,7165,7166,7167,7168,7169,7170,7171', '5761'),
(1907, 1294, 'Le cinquième élément', 'La troupe du Baron d\'Ouillard n\'est plus assez nombreuse pour exterminer les créatures du château de Harebourg. Darwin Chester compte sur vous pour leur prêter main forte.', 0, 200, 1, '7154', '4338'),
(1908, 1295, 'Pousse mousse', 'La troupe du Baron d\'Ouillard n\'est plus assez nombreuse pour exterminer les créatures du château de Harebourg. Darwin Chester compte sur vous pour leur prêter main forte.', 0, 200, 1, '7155', '4339'),
