(2032, 1420, 'Ecaflip sourit aux audacieux', 'Et si vous tentiez votre chance aujourd\'hui ? En faisant une partie de Kama Baraka, vous pouvez gagner une potion de Kerubim, ou plein d\'autres surprises ! Alors, qu\'attendez-vous ? Il ne vous en coûtera que 421 kamas, taxes comprises. La maison ne fait p', 0, 50, 0, '7840', '5740'),
(2033, 846, 'Caltes stlatégiques', 'Le Lenald des Temps Anciens vous a proposé de vous apprendre à joueur aux cartes en échange de cartes en bois volées par les Wabbits.', 15907, 80, 2, '7848,7849,7850', '5172'),
