(2037, 842, 'Voyage au centre du Wabbit', 'Sans autre piste, vous n\'avez pas le choix. Vous devez trouver le campement de l\'expédition de Jules Cwevawd.', 0, 56, 1, '7878,7879,7880,7881,7882', '5175'),
(2038, 843, 'Des pwinces pas très charmants', 'Il est temps de découvrir la vérité sur les pwinces déchus.', 0, 60, 2, '7883,7884,7885,7886,7887,7888,7889', '5176'),
(2039, 844, 'Ça rend aimable', 'Lilou vous a demandé de lui apporter des cawottes fraîches.', 16027, 60, 1, '7890', '5177'),
(2040, 845, 'Les pwinces déchus', 'Vous êtes attendu pour la scène de combat avec les pwinces déchus.', 16029, 60, 1, '7891,7892', '5178'),
(2041, 1421, 'Troubles à Bonta', 'Des agents de Brâkmar ont été aperçus dans certains quartiers de Bonta. Leur présence ne saurait être tolérée : il vous a donc été demandé de remédier à la situation. Vous êtes libre d\'utiliser la force si nécessaire ; en fait, c\'est même hautement consei', 0, 200, 1, '7893,7894,7895,7896', '5745'),
(2042, 1422, 'Troubles à Brâkmar', 'Des agents de Bonta ont été aperçus dans certains quartiers de Brâkmar. Leur présence ne saurait être tolérée : il vous a donc été demandé de remédier à la situation. Vous êtes libre d\'utiliser la force si nécessaire ; en fait, c\'est même hautement consei', 0, 200, 1, '7897,7898,7899,7900', '5746'),
(2043, 1423, 'Protéger et sévir', 'Le Captain Amakna, le super-héros le plus célèbre du Monde des Douze, vous a demandé de corriger les voyous qui s\'en prennent aux villageois. Entre héros, il faut s\'entraider : vous avez donc accepté. De plus, cela remplacera votre gymnastique quotidienne', 0, 200, 1, '7901,7902,7903,7904', '6594'),
(2044, 1424, 'Quelque chose de pourri au royaume d\'Amakna', 'Le Captain Amakna a décidé de faire appel à vous, son meilleur assistant, car il a un super doute à propos de l\'une des conseillères du roi Allister. Qui est Makia Vhel, et pourquoi a-t-elle poussé les différents dirigeants du Monde des Douze à signer un ', 16262, 100, 2, '7905,7906,7907,7908,7909,7910,7911,7912,7913,7914,7915,7916,7917,7918', '5747'),
(2045, 1425, 'Ainsi font les petites marionnettes', 'Votre super mission : vaincre Dramak le Manigancien, un super-vilain qui tire les ficelles depuis son théâtre invisible pour manipuler les puissants de ce monde. C\'est le moment de prouver que vous êtes un vrai héros, et pas une simple marionnette obéissa', 16284, 100, 2, '7919,7920,7921,7922,7923', '5179'),
(2046, 1426, 'Il faut que cha brille', 'Une maison aussi réputée que celle de Kerubim se doit d\'être propre et brillante comme un sou neuf. Le maître des lieux ayant de nombreux poils dans la main, il a préféré confier l\'entretien hebdomadaire de la boutique à un professionnel, vous en l\'occure', 16275, 200, 1, '7924,7925,7926,7928,7927,7929,7930', '5950'),
(2050, 1430, 'On recherche Ali Grothor', 'Ali Grothor a été aperçu du côté de la tourbière Nauséabonde, sur l\'île d\'Otomaï. \nIl est condamné à l\'emprisonnement à la milice d\'Amakna.', 0, 130, 1, '7937,7938', '5366'),
(2051, 1431, 'Un défilé de Wobots', 'Vous devez inspecter le Terrier du Wa Wabbit.', 16358, 80, 2, '7940,7941,7942,5571', '5756'),
(2052, 1432, 'Tour de marionnettes', 'Vous devez inspecter le Théâtre de Dramak.', 16364, 100, 2, '7943,7944,7945', '5757'),
(2053, 1433, 'L\'ivresse des profondeurs', 'Le Capitaine Grog est intéressé par le rhum consommé par les Mercemers : il vous a donc demandé de descendre dans la base abyssale pour récupérer une petite cargaison de bouteilles. D\'après le capitaine, ce rhum a une grande valeur auprès des connaisseurs', 0, 200, 0, '7946', '6057'),
(2054, 1438, 'Les Mercemers sont bien outillés', 'Votre mission : cogner sur les Mercemers présents dans les salles de la base abyssale jusqu\'à ce qu\'ils lâchent leurs boîtes à outils. Voilà un travail qui vous convient parfaitement ; lorsque vous bricolez, vous préférez jouer le rôle du marteau plutôt q', 0, 200, 1, '7954', '5759'),
(2055, 1434, 'On recherche les Guman', 'Les super-vilains ont été aperçus près du Champ des Ingalsse. Ils doivent être capturés puis enfermés dans une prison de haute sécurité.', 0, 30, 1, '7947,7948', '5367'),
(2056, 1435, 'On recherche Gadoo', 'Le super-vilain se cacherait dans les Marécages Sans Fond. Il doit être capturé puis enfermé dans une prison de haute sécurité.', 0, 60, 1, '7949,7950', '5368'),
(2057, 1436, 'On recherche Amy l\'empoisonneuse', 'La super-vilaine se cache dans la Jungle Obscure. Elle doit être capturée puis enfermée dans une prison de haute sécurité.', 0, 140, 1, '7951,7952', '5369'),
(2058, 1437, 'On recherche l\'Hyperscampe', 'Le super-vilain se cache dans la Salle des Abîmes. Il doit être capturé puis enfermé dans une prison de haute sécurité.', 0, 200, 1, '7953,7955', '5370'),
(2059, 1439, 'Pêche aux krabouilleurs', 'Estave Guiffel vous a demandé de capturer quelques spécimens de krabouilleurs, ces crabes mécaniques qui se promènent dans les Salles des Courants et des Abîmes. Pour amadouer les automates, vous allez recourir à la bonne vieille méthode : leur taper dess', 0, 200, 0, '7956', '5180');
INSERT INTO `quest_steps` (`Id`, `QuestId`, `Name`, `Description`, `DialogId`, `OptimalLevel`, `Duration`, `ObjectiveIds`, `RewardIds`) VALUES
(2060, 1440, 'KO pour Bosko Tho', 'Si vous battez Bosko Tho, vous aurez accès à l\'ascenseur des salles des abîmes, ce qui vous fera gagner du temps lors de vos déplacements dans la base abyssale. Prêt à monter sur le ring ?', 0, 200, 0, '7957', '5181'),
(2061, 1441, 'À bas Kralab Rah', 'Vous voulez utiliser l\'ascenseur qui se trouve dans les salles des courants ? Il va vous falloir convaincre Kralab Rah de la pertinence de vos exigences. En d\'autres termes, montrez-lui qui est le patron.', 0, 200, 0, '7958', '5182'),
(2062, 1442, 'Relevez les niveaux', 'Muni d\'un appareil topographique dernier cri, vous allez arpenter la base abyssale en long, en large et en travers. Tâchez de ne pas vous faire repérer pendant que vous prenez vos repères.', 0, 200, 2, '7959,7960,7961,7962,7963,7964,7965,7966,7967,7968,7969,7970', '5184'),
(2063, 1443, 'Prise de notes', 'Théo Dolith est fasciné par les calculs de Merkator, aussi vous a-t-il demandé d\'aller récupérer quelques feuilles de notes laissées par le Cartographe dans l\'Aquadôme. Au passage, vous risquez d\'être obligé de multiplier les combats afin de procéder à qu', 0, 200, 2, '7971,7972,7973,7974,7975,7976,7977', '5185'),
(2064, 1444, 'Pollution, je dis non', 'Une catastrophe écologique menace le royaume d\'Allister : les eaux de la rivière ont été polluées ! Selon le Captain Amakna, le coupable serait Merkator, un super-vilain qui ourdit des plans machiavéliques dans les abysses sufokiennes. En tant que défense', 0, 200, 2, '7978,7979,7980,7981,7982,7983,7984,7985,7992,7993,7994,7995,7996,7997,7998,7999,8000,8001,8002,8003,8004,8005', '5183'),
(2065, 1446, 'Formation des première année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 30, 1, '8007,8008,8009,8010', '5186'),
(2066, 1447, 'Formation des deuxième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 50, 1, '8011,8012,8013,8014', '5196'),
(2067, 1448, 'Formation des troisième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 70, 1, '8015,8016,8017,8018', '5197'),
(2068, 1449, 'Formation des quatrième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 90, 1, '8019,8020,8021,8022', '5198'),
(2069, 1450, 'Formation des cinquième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 110, 1, '8023,8024,8025,8026', '5199'),
(2070, 1451, 'Formation des sixième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 130, 1, '8027,8028,8029,8030', '5200'),
(2071, 1452, 'Formation des septième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 150, 1, '8031,8032,8033,8034', '5201'),
(2072, 1453, 'Formation des huitième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 170, 1, '8035,8036,8037,8038', '5202'),
(2073, 1454, 'Formation des neuvième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 190, 1, '8039,8040,8041,8042', '5203'),
(2074, 1455, 'Formation des dixième année', 'Skale vous a demandé de combattre un des prisonniers en compagnie d\'une recrue pour la former et évaluer ses capacités. La recrue doit participer au combat jusqu\'à la fin, sous peine de devoir recommencer le combat.', 16485, 200, 1, '8043,8044,8045,8046', '5204'),
(2075, 1445, 'L\'école fantastique', 'Skale souhaite que vous participiez à la formation des justiciers en herbe.', 16485, 200, 0, '8006', '5727'),
(2076, 1456, 'Stage de combat improvisé', 'Korbax souhaite évaluer la capacité des recrues à combattre en équipe. Pour ce faire, il vous demande d\'assister chacune d\'entre elles dans un combat contre un des prisonniers.', 16560, 50, 2, '8047,8048,8049,8050,8051', '5205'),
(2077, 1457, 'Apprentissage en tirage d\'oreilles', 'Korbax souhaite évaluer la capacité des recrues à combattre en équipe. Pour ce faire, il vous demande d\'assister chacune d\'entre elles dans un combat contre un des prisonniers.', 16571, 90, 2, '8052,8053,8054,8055,8056,8057,8058,8059', '5206'),
(2078, 1458, 'Licence en distribution de pains', 'Korbax souhaite évaluer la capacité des recrues à combattre en équipe. Pour ce faire, il vous demande d\'assister chacune d\'entre elles dans un combat contre un des prisonniers.', 16594, 130, 2, '8060,8061,8062,8063,8064', '5207'),
(2079, 1459, 'Maîtrise en flanquage de rouste', 'Korbax souhaite évaluer la capacité des recrues à combattre en équipe. Pour ce faire, il vous demande d\'assister chacune d\'entre elles dans un combat contre un des prisonniers.', 16607, 170, 2, '8065,8066,8067,8068,8069,8070,8071,8072', '5208'),
(2080, 1460, 'Doctorat en bottage de fesses', 'Korbax souhaite évaluer la capacité des recrues à combattre en équipe. Pour ce faire, il vous demande d\'assister chacune d\'entre elles dans un combat contre un des prisonniers.', 16625, 200, 2, '8073,8074,8075,8076,8077,8078,8079,8080,8081,8082,8083', '5209'),
(2081, 1461, 'L\'armée des ombres', 'Le maître de la Dimension Obscure menace les habitants du Monde des Douze. À en croire Lumino, seul un héros peut se dresser contre lui. Oui, c\'est bien de vous que l\'on parle, ne jouez pas les modestes. Mais avant de foncer tête baissée, il serait judici', 0, 190, 2, '8084,8085,8086,8087,8088,8089,8090,8091,8092,8093,8094,8095,8096,8097,8098,8099,8100,8101,8102,8103,8104,8105', '5210'),
(2082, 1462, 'La magicienne des marécages', 'Après vous avoir avoué qu\'il y avait bien un Dofus sur Pandala, Ronald vous a demandé de rencontrer une puissante magicienne qui pourrait vous aider à trouver les œufs des Dragons Primordiaux... enfin, après bien des pérégrinations, vous allez pouvoir ent', 16658, 40, 0, '8106', '5734'),
(2083, 1463, 'Retourner voir le Dark Vlad, toujours sans mourir', 'La magicienne Mériana vous a convaincu de partir en quête du Dofus Émeraude. La pensée de tenir entre vos mains un œuf de Dragon Primordial vous galvanise. Il ne vous reste plus qu\'à repartir faire un tour dans la forêt Maléfique pour y défier le Dark Vla', 16699, 45, 1, '8107,8108,8109,8110,8111,8112,8113,8114,8115,8116,8117,8118,8119,8120,8121,8122', '5211'),
(2084, 1464, 'Qui botte le cul des Culs Bottés ?', 'Pour contempler les fameuses bottes du Dark Vlad subtilisées par Bowisse, vous allez devoir prouver que vous êtes un artisan digne de ce nom.', 16763, 50, 1, '8123,8124,8125,8126,8127', '5212'),
(2085, 1465, 'Le voleur d\'âmes', 'Toungousa doit affronter un esprit malveillant pour faire ses preuves en tant que shamane. Il semble que cet esprit soit lié à l\'histoire du Dark Vlad... mais il refuse de se manifester. Aidez Toungousa en capturant les âmes des gardiens de donjons nécess', 16778, 70, 2, '8128,8129,8130,8131,8132,8133,8134,8135,8136,8137,8138', '5213'),
(2086, 1466, 'L\'amour perdu de Nabur', 'Nabur a été le maître de nombreux héros . Après plus de trois siècles d\'un repos bien mérité dans le cimetière de Bonta, il a décidé de quitter sa tombe pour aller prendre l\'air. Peut-être avait-il une affaire en suspens ? Le Dark Vlad serait responsable ', 16807, 90, 1, '8139,8140,8141,8142,8143,8144,8145,8146,8147,8148,8149,8150,8151,8152,8153', '5214'),
(2087, 1467, 'Naissance d\'une vocation', 'Selon le Captain Starky, un éleveur ulcéré aurait payé des voyous pour qu\'ils profanent la statue du dieu Iop qui trône à l\'entrée de la milice. Il semblerait que cette affaire soit liée à la présence du Dark Vlad quelques jours plus tôt. Identifiez le co', 16830, 100, 2, '8154,8155,8156,8157,8158,8159,8160,8161,8162,8163,8164,8165,8166,8167,8168,8169,8170,8171', '5215'),
(2089, 1469, 'Les bandits de Cania', 'Le Dark Vlad s\'avère un adversaire bien plus coriace que prévu. Si vous voulez avoir une chance de le vaincre, vous aurez besoin de faire appel au pouvoir du talisman de Prysmaradoth. Pour créer cet objet, il vous faut des écailles de dragon détenues par ', 16879, 100, 2, '8173,8174,8175,8176', '5218'),
(2090, 1470, 'Draconanthropie', 'Vous avez trouvé les trois écailles de Prysmaradoth : il vous faut maintenant les autres objets nécessaires à la fabrication du talisman. Si vous aimez l\'ambiance des cimetières, des chenils abandonnés et des salles de rituels, vous allez être servi.', 16886, 100, 2, '8177,8178,8179,8180', '5216'),
(2091, 1471, 'Ultime réminiscence', 'Vous voilà en route pour Incarnam, la terre céleste où naissent les héros. Voilà qui devrait vous rappeler des souvenirs... au bout du voyage, le Dark Vlad et le Dofus Émeraude !', 16892, 120, 2, '8181,8182,8183,8184,8185,8186,8187,8188,8189,8190,8191,8192,8193,8194,8195,8196,8197,8198,8199,8200', '5217'),
(2093, 1473, 'L\'accusé de la réception', 'Dejah Kob, sénéchal au château d\'Amakna, vous a confié une mission capitale : trouver les ingrédients nécessaires à la confection d\'un hors-d\'œuvre inoubliable. Grâce à votre aide, la réception de l\'ambassadeur sera un succès. Comme toujours.', 17126, 150, 2, '8203,8204,8205,8206,8207,8208,8209,8210,8211,8212,8213,8214,8215,8216,8217', '5219'),
(2094, 1474, 'Les monstres aboient, la diligence casse', 'Le cousin de Gusta Lavôtre a disparu. La plupart des gens s\'en fichent royalement, mais vous n\'êtes pas comme ça : vous ne vivez que pour rendre service et pour aider ceux qui sont dans le besoin. Tant d\'abnégation dans un si petit corps, comment est-ce p', 17166, 155, 2, '8218,8219,8220,8221,8222,8223,8224,8225,8226,8227,8228,8229,8250,8230,8231,8232,8233', '5220'),
(2095, 1475, 'Chachyène de vie', 'Il est probable qu\'Hulos le boulanger soit retenu contre son gré par les Kanigs des Dents de Pierre. C\'est inadmissible. Il est temps de remédier à cette situation.  Et s\'il faut en venir aux mains, vous ne vous en plaindrez pas.', 17215, 160, 2, '8234,8235,8236,8237,8238,8239,8280,8240,8241,8242,8243', '5221'),
(2096, 1476, 'Où que les bêtes aillent', 'Le marchand Lalat vous a demandé d\'enquêter sur la disparition de l\'un de ses convois de bétail.', 17238, 155, 1, '8244,8245,8246,8247,8248,8249,8251,8252,8253,8254,8255,8256,8257,8258,8259', '5222'),
(2097, 1477, 'Niera bien qui niera le dernier', 'Félybrêle ne s\'étant pas montrée coopérative, vous devez trouver d\'autres moyens de faire progresser votre enquête.', 0, 155, 1, '8260,8261,8262,8263,8264,8265,8266,8267,8268,8269,8270,8271,8272,8273,8274,8275,8276,8277,8278,8279', '5223'),
(2098, 1478, 'Remède miracle', 'Vous avez accepté de participer à l\'élaboration d\'une concoction pour lever le maléfice pesant sur Émidaphat Soum.', 17323, 155, 0, '8281,8282,8283,8284,8285,8286,8287', '5224'),
(2099, 1479, 'L\'art triste', 'Le sculpteur Émidaphat Soum étant blessé, vous vous êtes engagé à lui donner un coup de main pour achever ses œuvres.', 17351, 155, 1, '8288,8289,8290,8291,8292,8293,8294,8295,8296,8297,8298,8299,8300,8301,8302,8303', '5225'),
(2100, 1480, 'Un mâle et fils', 'Orgiana, une esclave des Kanigs, est sans nouvelle de son époux et de son enfant. Bien qu\'elle n\'ait rien à vous offrir, vous avez accepté de partir à leur recherche.', 17419, 155, 1, '8304,8305,8306,8307,8308,8309,8310,8311,8312,8313,8314,8315,8316,8317,8318,8319,8320,8321,8322,8323', '5226'),
(2101, 1481, 'Boulétisation', 'À force de jouer les gros bras et de foncer dans le tas sans réfléchir, vous avez empêché les Kanigs de renvoyer un Shushu dans la Shukrute. Il est temps à présent de réparer vos erreurs.', 17435, 160, 1, '8324,8325,8326,8327,8328,8329,8330,8331,8332,8333,8334,8335,8336', '5227'),
(2102, 1482, 'La Malle aux trésors', 'Un Enutrof rencontré à Astrub vous a appris qu\'une immense partie de chasse aux trésors avait été lancée dans tout le Monde des Douze. Première étape de ce grand jeu d\'exploration : visiter la Malle aux trésors, la demeure ancestrale de la famille Terra. ', 0, 20, 0, '8337', '5729'),
(2103, 1483, 'Terra Carta', 'Discutez avec les différents membres de la famille Terra afin d\'en apprendre davantage sur cet illustre clan Enutrof.', 0, 200, 0, '8338,8339,8340,8341', '5730'),
(2104, 1484, 'Voyage, voyage', 'Le sergent Zlatzom vous a invité à entrer dans le quartier général des Voyageurs dimensionnels. Cette visite sera le point de départ d\'une aventure qui vous mènera bien loin de chez vous... voilà l\'occasion de voir du pays !', 0, 200, 0, '8346,8347,8348,8349,8350,8351,8352', '5736'),
(2105, 1485, 'La porte d\'Enutrosor', 'Vous avez accepté d\'aider les Voyageurs dans leur exploration des Dimensions Divines. Votre première mission : découvrir un portail menant à Enutrosor, le monde souterrain du dieu Enutrof.', 0, 200, 1, '8344,8345,8353,8354', '5737'),
(2106, 1486, 'Orichomania', 'La collectrice Megisthe vous a demandé de mesurer la concentration d\'orichor dans certaines zones précises de la dimension Enutrosor. La mission semble simple et sans danger... du moins s\'il n\'y a aucun imprévu.', 0, 200, 1, '8355,8356,8357,8358,8360,8359,8361,8362,8363', '5735'),
(2107, 1487, 'Elle va finir par se faire coffrer', 'Le capitaine Gladis vous a confié une mission de la plus haute importance : escorter une jeune recrue en Enutrosor et l\'aider à s\'aguerrir en affrontant des Koffrefors. Avec un mentor tel que vous, elle va faire un massacre.', 0, 100, 1, '8364,8365,8366,8367,8368', '5228'),
(2108, 1488, 'Crache Test', 'Le Major Qiu souhaite que vous expérimentiez l\'une de ses nouvelles inventions : le cracheur de pépites. Il a insisté pour que vous testiez cette arme d\'entraînement sur les Phorreurs de la dimension Enutrosor.', 0, 150, 1, '8369,8370,8371,8372', '5229'),
(2109, 1489, 'Touchez pas à Grisebigle', 'Une Enutrofette fraîchement recrutée par l\'ordre des Voyageurs a disparu. Le colonel Oneuil vous a demandé de la retrouver et de la ramener à l\'avant-poste. Pour vous aider dans votre mission de sauvetage, le colonel vous a confié un détecteur de balise. ', 0, 200, 1, '8373,8374,8375,8376,8377,8378,8379,8380,8381', '5230'),
(2110, 1490, 'La quatrième dimension', 'Rol Sterding se pose des questions existentielles sur la dimension Enutrosor. Pour tenter d\'y répondre, il vous a chargé d\'explorer la carrière Aurifère : grâce aux informations enregistrées par un holodateur expérimental, Rol espère pouvoir déterminer à ', 0, 150, 1, '8382,8383,8384,8385,8386,8387', '5231'),
(2111, 1491, 'Échantillonnage', 'Fasciné par les créatures dimensionnelles, le docteur Gaw souhaite étudier les Enutrofors. Comme il n\'a pas le temps de se rendre dans la Retraite des Éternels, il vous a chargé de recueillir des échantillons de leur sang. Attendez-vous à de la résistance', 0, 200, 1, '8388', '5232'),
(2112, 1492, 'On ne prête qu\'à Richard', 'Le professeur Maximilio veut améliorer les relations entre le roi Nidas et l\'ordre des Voyageurs. Pour cela, il souhaite rentrer dans les petits papiers d\'un Enutrofor très influent auprès du roi : Richard le Trésorier. Ce dernier semble fasciné par la te', 0, 200, 0, '8389,8390,8391,8392,8393', '5233'),
(2113, 1493, 'Pour quelques kamas de plus', 'Richard le Trésorier vous a demandé de retrouver un Koffrefor qui a été enlevé par des brigands venus du Monde des Douze. Le coffre magique contiendrait un objet d\'une immense valeur.', 0, 200, 1, '8394,8395,8396,8397,8398,8399,8400,8401,8402,8403', '5234'),
(2114, 1494, 'Tout ce qui brille n\'est pas or', 'Le trésorier est inquiet : un kama de plomb a été découvert dans les coffres de la banque royale. S\'agit-il d\'un incident de fabrication, ou bien d\'une contrefaçon ? Richard suspecte une ancienne confrérie de faux-monnayeurs de préparer un mauvais coup. i', 0, 200, 1, '8404,8405,8406,8407,8408,8409', '5235'),
(2115, 1495, 'Un morceau de roi', 'Richard se fait du souci pour le roi Nidas : il craint que le monarque n\'ait attrapé une maladie au contact des aventuriers. Comme le souverain des Enutrofors déteste les médecins, c\'est à vous qu\'il incombe de lui arracher le poil de nez nécessaire à l\'é', 0, 200, 2, '8410,8411', '5236'),
(2116, 1496, 'Prime de Lèche-Majesté', 'À force de travailler pour Richard le Trésorier, vous êtes parvenu à vous faire remarquer. Résultat : le roi Nidas veut vous voir. Espérons qu\'il ne vous en veut pas de lui avoir tiré les poils du nez.', 0, 200, 1, '8412,8413,8414,8415,8416,8417,8418,8419', '5237'),
(2117, 1497, 'La meilleure défense, c\'est l\'attaque', 'Le professeur Maximilio souhaite aider son amie Dyane Phossé à combattre les braconniers. Trouvez les brutes qui traquent les phorreurs pour leurs défenses et montrez-leur ce que ça fait que d\'être chassé.', 0, 150, 1, '8420,8421,8422,8423', '5238'),
(2118, 1498, 'Phorreurs dans la brume', 'Les braconniers capturent des phorreuses amoureuses et se servent d\'elles afin attirer d\'autres phorreurs dans leurs filets. Dyane Phossé a trouvé la solution pour contrer les méthodes employées par les chasseurs : asperger les phorreuses avec de la sueur', 0, 150, 0, '8424,8425,8426,8427,8428,8429,8430', '5239'),
(2119, 1499, 'Le phormidiable au corps', 'Certains phorreurs mâles deviennent très agressifs avec l\'âge. Ils vivent alors à l\'écart de la harde, mais ils constituent parfois une menace pour les autres phorreurs. Dyane Phossé vous a demandé d\'aller calmer l\'un de ces vieux grincheux.', 0, 150, 0, '8431,8432,8433', '5240'),
(2120, 1500, 'La pelle de la Phorrée', 'Dyane Phossé a trouvé des textes anciens évoquant un rituel aujourd\'hui tombé en désuétude. Une danse connue sous le nom de Phorrée était pratiquée lors de la cérémonie qui unissait un Enutrofor à un phorreur ; une pelle sacrée était utilisée durant la Ph', 0, 150, 2, '8434,8437,8439', '5241'),
(2121, 1501, 'Pompe à fric', 'L\'Agent Kohmer Sial a besoin de votre aide.', 17491, 100, 1, '8435,8436,8438,8538,8539,8540,8541,8542,8543,8544,8545,8546,8440,8441,8442', '5242'),
(2122, 1502, 'Déphorrestation', 'L\'Agent Sart a besoin de votre aide.', 17500, 150, 1, '8443,8444,8445,8446,8447,8448,8449,8450,8451', '5243'),
(2123, 1503, 'Le silence est d\'or', 'L\'Agent Pruneaude a besoin de votre aide.', 17509, 200, 1, '8452,8453,8454,8455,8456,8457,8458,8459,8460,8461,8462,8463,8464,8465', '5244'),
(2124, 1504, 'Koffrologie', 'Le Professeur Maximilio veut étudier la faune locale et a besoin de votre aide pour y parvenir.', 17567, 100, 0, '8466,8467,8468,8469,8470,8471,8472,8473,8474,8475,8476,8477,8478,8479,8480,8481', '5245'),
(2125, 1505, 'Trésorphelinat', 'Pour pousuivre ses recherches sur les Koffrerors avec l\'aval de la Koffrérie, le Professeur Maximilio a accepté de leur rendre un service.Évidemment, c\'est vous qui vous y collez.', 17591, 100, 1, '8482,8483,8484,8485,8486,8487,8488,8489,8490,8491,8492', '5246'),
(2126, 1506, 'Malladie', 'Le Professeur Maximilio vous a demandé d\'enquêter sur le mal étrange qui touche ses Koffrefors.', 17627, 100, 2, '8493,8494,8495,8496,8497,8498,8499', '5247'),
(2127, 1507, 'Les grandes galeries', 'Des membres de la Confrérie des Forreurs avec un F sont bloqués dans une galerie souterraine et comptent sur votre aide pour les sortir de là.', 17534, 150, 0, '8500,8501,8502,8503,8504', '5248'),
(2128, 1508, 'Un cœur d\'or', 'Vous êtes pris d\'une irrésistible envie d\'aider votre prochain par pure charité.', 0, 150, 1, '8505,8506,8507,8508,8509,8510,8511,8512,8513,8514,8515,8516,8517,8518', '5249'),
(2129, 1509, 'Maudite générosité', 'Pour vous débarrasser de la malédiction vous rendant généreux, vous allez devoir suivre les consignes de Williamwadui.', 17560, 150, 1, '8519,8520,8521,8522,8523,8524,8525,8526', '5250'),
(2130, 1515, 'Reconnaissance de dette', 'Gravia a demandé votre assistance pour l\'aider à récupérer son argent.', 17753, 200, 1, '8527,8528,8529,8530,8531,8532,8533,8534,8535,8536', '5251'),
(2131, 1517, 'Un œuf pour Ecaflip', 'Kerubim Crépin veut faire un cadeau à son père, le dieu Ecaflip : un œuf fécondé de Haute Truche. Neuf vies, ça vaut bien un œuf tout neuf !', 0, 130, 2, '8537', '5252'),
(2132, 1518, 'On recherche la Maxi-Malle', 'La Maxi-Malle se cache dans le Creuset des Fortunés d\'Enutrosor, elle est recherchée par les voyageurs dimensionnels pour avoir gobé un grand nombre d\'aventuriers, dont l\'un des leurs.', 0, 100, 1, '8547,8548', '5371'),
(2133, 1519, 'On recherche Aigripoil', 'Aigripoil se cache dans la Carrière Aurifère d\'Enutrosor, il est recherché par les voyageurs dimensionnels pour avoir orchestré une rebellion contre eux.', 0, 150, 1, '8549,8550', '5372'),
(2134, 1520, 'On recherche Voldelor', 'Voldelor se cache dans la Retraite des éternels d\'Enutrosor, il est recherché pour tentatives de meurtres sur les sans-barbes d\'Enutrosor.', 0, 200, 1, '8551,8552', '5373'),
(2135, 1510, 'Espionnage industriel', 'Des rumeurs circulent sur la présence d\'une taupe au sein de la Koffrérie. Pépénible vous a chargé d\'enquêter.', 17791, 200, 1, '8553,8554,8555,8556,8557,8558,8559,8560,8561,8562,8563,8564', '5253'),
(2136, 1511, 'Prise d\'otages', 'Démasqué, René a préféré prendre des Enutrofors en otages que de se rendre. Le gardien Paspartou vous a demandé un coup de main pour arranger la situation.', 17820, 200, 1, '8565,8566,8567,8568,8569,8570,8571,8572,8573,8574', '5254'),
(2137, 1512, 'La grève de la fin', 'Suite aux récents incidents, de nombreux membres de la Koffrérie se sont mis en grève et ont fait de vous leur médiateur.', 17847, 200, 0, '8575,8576,8577,8578,8579,8580,8581,8582,8583,8584', '5255'),
(2138, 1513, 'Malle des profondeurs', 'Un accident se serait produit dans les profondeurs d\'Enutrosor. Le Sergent Frinklan vous a chargé de l\'enquête.', 17957, 200, 1, '8585,8586,8587,8588,8589,8590,8591', '5256'),
(2139, 1516, 'Laissé en plan', 'Vous avez trouvé un vieux plan d\'Enutrosor. Ribériche pourra peut-être vous en dire davantage à son sujet.', 0, 200, 1, '8592,8593,8594,8595,8596,8597,8598,8599', '5257'),
(2140, 1514, 'Coiffeur de génie', 'Léonard compte sur vous pour le réhabiliter.', 17991, 200, 2, '8600,8601,8602,8603,8604,8605,8606,8607,8608,8609,8610,8611,8612,8613,8614,8615', '5258'),
(2141, 1521, 'Le livre des Taures', 'Vous voilà parti en quête du Dofus Pourpre. Avant que vous ne fonciez tête baissée dans l\'antre du Minotoror, Mériana voudrait que vous mettiez la main sur un ancien grimoire. D\'après la magicienne, l\'une des formules retranscrites dans le livre pourrait ', 0, 110, 2, '8633,8650,8651,8652,8653,8654,8655,8656,8657', '5264'),
(2142, 1522, 'Taures et détours', 'Armé d\'une puissante magie, vous êtes paré pour rencontrer le maître du labyrinthe du Minotoror. Encore faut-il que vous parveniez jusqu\'à lui sans vous perdre en chemin.', 0, 120, 2, '8634,8658,8659,8660,8661,8662,8663,8664,8665', '5265'),
(2143, 1523, 'Le trésor de Totankama', 'Vous avez passé un marché avec le Minotot, le véritable gardien du Dofus Pourpre : il vous remettra le Dofus en échange du Masque de Totankama. Pour trouver cet objet légendaire, il vous faudra suivre les indications gravées sur une vieille tablette de pi', 0, 130, 2, '8635,8666,8667,8668,8669,8670,8671,8672,8699,8700', '5266'),
(2144, 1524, 'Il faut battre le lait quand il est chaud', 'La Perle de Lait Doré est l\'un des trois objets nécessaires pour contrer la malédiction de Totankama. Si vous voulez éviter de finir momifié, vous allez devoir fabriquer cette pierre pour le moins étrange.', 0, 130, 2, '8636,8673,8674,8675,8676,8677,8678', '5267'),
(2145, 1525, 'Regrets d\'éternailes', 'La Poudre d\'éternaile est l\'un des trois objets nécessaires pour contrer la malédiction de Totankama. Si vous voulez éviter d\'être rongé par les remords, vous allez devoir partir à la chasse aux papillons.', 0, 130, 1, '8684,8637,8679,8680,8681,8682', '5268'),
(2146, 1526, 'L\'anneau de Tot', 'L\'anneau de Tot est l\'un des trois objets nécessaires pour contrer la malédiction de Totankama. Si vous voulez éviter de mourir prématurément, vous allez devoir mettre la main sur cet anneau.', 0, 130, 2, '8638,8683,8685,8686,8687,8688,8689,8690', '5269'),
(2147, 1527, 'Comment perdre ses plumes', 'Après votre périple dans le labyrinthe du Minotoror, vous avez été suivi par un Tofu. Mériana pense que ce volatile est victime d\'une malédiction. Accomplissez une bonne action, libérez-le de son tourment... sans faire usage de violence à son encontre, ce', 0, 130, 2, '8639,8691,8692,8693,8694,8695,8696,8697,8698', '5270'),
(2148, 1528, 'Une âme en peine', 'Le Minotot vous a trompé : votre âme est à présent prisonnière du labyrinthe. Pour vous tirer d\'affaire et récupérer votre moi spirituel, vous allez devoir vaincre le minogolem séculaire.', 0, 130, 1, '8640,8701,8702', '5271'),
(2149, 1529, 'Le pouvoir derrière le trône', 'Ulcérée de constater que vous avez été trompé, la propriétaire du Refuge des Cent Détours a décidé de vous aider : elle vous a remis une clef qui vous permettra d\'accéder à la salle du Dofus Pourpre. Pour utiliser cette clef, vous aurez besoin d\'un Taure.', 0, 130, 2, '8703,8704,8705,8706,8707,8708,8709,8710,8711', '5272'),
(2150, 1530, 'La cité de l\'indicible mal', 'Il semble que les Voyageurs Dimensionnels ne se soient pas faits que des amis... Pourquoi Gein le Silencieux a-t-il tenté d\'assassiner l\'Explorancienne ? C\'est ce que vous allez tenter de découvrir.', 0, 200, 1, '8642,8712,8719,8720,8721,8722,8723,8724', '6581'),
(2151, 1531, 'Messager clandestin', 'Franche Smisse veut convier plusieurs chefs de bande à une réunion, et c\'est vous qui êtes chargé de distribuer les invitations. Attendez-vous à rencontrer du beau monde.', 0, 200, 1, '8643,8729,8733,8736,8737,8742,8738,8739,8740,8741', '5717'),
(2152, 1532, 'La voix de son maître', 'Qui a volé la voix de Gein le silencieux ? Zap Gobdon a sa petite idée sur la question... Avec votre aide, il espère attirer l\'assassin légendaire dans les filets des Voyageurs.', 0, 200, 1, '8743,8744,8745,8746,8747,8748,8750,8753,8755,8756', '5718'),
(2153, 1533, 'Ça katche ou ça passe', 'L\'agent Durhan a besoin de s\'endurcir pour devenir un champion digne de ce nom. Vous êtes son nouvel entraineur. Montrez-lui comment se bat un héros et rouez de coups quelques katcheurs.', 18138, 130, 1, '8645,8775,8788,8789,8790', '5259'),
(2154, 1534, 'Nécrotiques, tiques, tiques', 'Le Docteur Gaw vous a demandé de capturer quelques nécrotiques dans les Catacombres. Il ne vous reste plus qu\'à vous en aller à Srambad, tout simplement, aventurier pauvre et chantant, avec votre filet à la main.', 0, 180, 1, '8646,8797,8798,8799,8800', '5260'),
(2155, 1535, 'Faux-semblants', 'Vous allez tester la nouvelle invention du Major Qiu : un générateur d\'illusions. Comme souvent avec le Major, vous aurez peut-être quelques surprises, mais avouez-le, vous adorez ça.', 0, 200, 1, '8647,8813,8814,8815,8817,8818', '5261'),
(2156, 1536, 'La pêche au poison', 'Gladys vous a demandé de lui rapporter du jus de nécrotique : elle compte l\'utiliser pour son prochain programme d\'entraînement... ce n\'est sans doute qu\'un prétexte pour pouvoir martyriser les nouvelles recrues.', 0, 180, 1, '8863', '5262'),
(2157, 1537, 'Mémoires d\'outre-tombe', 'Rol Sterding vous a chargé de discuter avec quelques crânes parlants. Vous avez accepté cette mission peu orthodoxe sans sourciller. Après tout, vous avez déjà fait des choses plus étranges.', 0, 200, 1, '8649,8855,8856,8859,8860,8861,8864,8862', '5263'),
(2158, 1538, 'Fanfouille', 'L\'Agent Gklung a besoin de votre aide.', 18030, 130, 1, '8713,8714,8715,8716,8717,8718,9031', '5278'),
(2159, 1539, 'Les troupiers', 'Les agents ont besoin de votre aide dans les Catacombres.', 18051, 180, 1, '8725,8726,8727,8728,8730,8731,8732,8734,8735,8749,8751,8752,8754', '5279'),
(2160, 1540, 'Balance la sauce', 'L\'Agent Ray Seuc a besoin de votre aide.', 18079, 200, 1, '8757,8758,8759,8760,8761,8762,8764,8765', '5280'),
(2161, 1541, 'La seinoise', 'Kathy Brennan vous demande de poursuivre l\'enquête liée au meurtre de deux Voyageurs Dimensionnels.', 18099, 130, 1, '8766,8767,8768,8769,8770,8771,8772,8773,8774', '5281'),
(2162, 1542, 'Ça se katche', 'Vous devez trouver la trace des Malveilleurs dont vous a parlé Bonnie Menteuse, à condition qu\'elle vous ait dit la vérité.', 0, 130, 1, '8776,8777,8778,8779,8780,8781,8782,8783,8784,8785,8786,8787', '5282'),
(2163, 1543, 'Un ring pour les gouverner tous', 'Le chef des Malveilleurs semble impliqué dans le meurtre des Voyageurs. Il va falloir découvrir la vérité.', 18690, 130, 2, '8791,8792,8793,8794,8795,8796', '5283'),
(2164, 1544, 'Épidémiologie', 'Kathy Brennan a besoin d\'étudier les Nécrotiques pour déterminer les origines de leur agressivité.', 18166, 180, 1, '8801,8802,8803,8804,8805,8806,8807,8808,8809,8810,8811,8812', '5284'),
(2165, 1545, 'Tique attaque', 'Kathy Brennan s\'est associée à l\'organisation d\'Hyrda pour faire progresser les recherches sur les Nécrotiques.', 18176, 180, 1, '8819,8820,8821,8822,8823,8824,8825', '5285'),
(2166, 1546, 'Sa Majesté des Nécrotiques', 'La Serpentine des Fosses 12 pense tenir une piste et vous a chargé de la vérifier.', 18195, 180, 1, '8826,8827,8828,8829,8830,8831,8832,8833,8834,8835,8836,8837,8838,8839,8840', '5286'),
(2167, 1547, 'L\'art me ment', 'Des Voyageurs sont atteints d\'une maladie inconnue et vous êtes chargé d\'en découvrir la cause.', 18257, 180, 2, '8841,8842,8843,8844,8845,8846,8847,8848,8849,8850,8851,8852,8853,8854,8857,8858', '5287'),
(2168, 1553, 'Viande fraîche', 'Tchô Wabbit vous a embauché pour retrouver le Prince Albert.', 18859, 180, 1, '8865,8866,9032,9033,9034,8867,8868,8869,8870,8871', '5293'),
(2169, 1555, 'Comme un poison dans l\'eau', 'Le Docteur Deal Linger est persuadé de l\'empoisonnement de l\'alimentation des Nécrotiques. Il vous a demandé de l\'assister dans son enquête.', 18125, 180, 1, '8872,8873,8874,8875,8876,8877,8878,8879,8880,8881,8882,8883,8884', '5295'),
(2170, 1556, 'La chapelle noire', 'Un crâne vous a accusé de meurtre. Vous devez sauver votre peau.', 18630, 200, 1, '8885,8886,8887,8888,8889,8890,8891', '5296'),
(2171, 1558, 'Depuis l\'enfer', 'L\'organisation d\'Al Capote est persuadée de votre culpabilité. Cependant, elle vous laisse une dernière chance de prouver votre innocence si vous lui apportez l\'assassin.', 18394, 200, 1, '8892,8893,8894,8895,8896,8897,8898,8899,8900,8901,8902,8903,8904,8905,8906,8907,8908,8909,8910,8911,8912', '5298'),
(2172, 1559, 'Courir après des ombres', 'L\'ombre de plusieurs Douziens a mystérieusement disparu. Comme ce phénomène s\'étend aux Voyageurs Dimensionnels, Volron Dumhaz vous a demandé d\'enquêter.', 18422, 200, 1, '8913,8914,8915,8916,8917,8918,8919,8920', '5299'),
(2173, 1560, 'Sortir de l\'ombre', 'Vous avez échoué à interrompre le rituel et capturer les voleurs. cependant, il vous reste une chance de mettre la main sur leur butin à Srambad.', 18620, 200, 1, '8921,8922,8923,8924,8925,8926,8927,8928,8929', '5300'),
(2174, 1563, 'On recherche Gein', 'Gein se cache au Haut Ténébreux de Srambad, il est recherché pour tentative d\'assassinat sur l\'Explorancienne.', 0, 200, 1, '8930,8931', '5374'),
(2175, 1564, 'On recherche la Mouchâme', 'La Mouchâme se cache dans les Catacombres de Srambad, elle est recherchée pour agression envers des voyageurs dimensionnels.', 0, 180, 1, '8932,8933', '5375'),
(2176, 1565, 'On recherche Pantèroz', 'Pantèroz se cache dans les Ruelles des Eaux-Suaires de Srambad, elle est recherchée pour agression envers les voyageurs dimensionnels.', 0, 130, 1, '8934,8935', '5376'),
(2177, 1566, 'Prise de sang', 'Le Docteur Gaw a besoin de grandes quantités de sérum de Krokille ainsi que de sang de Dragon pour tenter de guérir le mal dimensionnel qui touche plusieurs Voyageurs.', 0, 200, 2, '8936,8937', '5273,5274'),
(2178, 1554, 'La morte Adèle', 'Vous êtes embauché par Sinedia Zieunoir pour une simple mission d\'assassinat.', 18951, 180, 1, '8938,9036,9037,9038,9039,9040,9041,9042,9043,9044,9045,9046,9047,9048,9049,9050,9051,9052', '5294'),
(2179, 1561, 'La grosse commission', 'Vous n\'avez pas compris ce qui vous arrive.', 18448, 200, 1, '8952,8953,8954,8955,8956,8957,8958,8959,8960,8961,8962,8963,8964,8965,8966,8967,8968,8969,8970,8971,8972,8973,8974', '5301'),
(2180, 1562, 'Os sitôt dit, aussitôt fait', 'Patxi Misce vous a embauché pour aider les mosdeleurs dans leur projetde circuit touristique culturel mettant en valeur leur talent artistique.', 18511, 200, 1, '8939,8940,8941,8942,8943,8944,8945,8946,8947,8948,8949,8950,8951', '5302'),
(2181, 1557, 'Présumé coupable', 'Il semblerait qu\'on vous prenne pour un assassin. À moins que ce soit le cas mais que vous ne vous en souveniez pas.', 18354, 200, 0, '8975,8976,8977,8978,8979,8980,8981,8982,8983', '5297'),
(2182, 1548, 'Les sentiers de la perdition', 'Vous allez infiltrer le syndicat du crime pour découvrir si des Voyageurs Dimensionnels sont corrompus.', 18713, 200, 1, '8984,8989,8990,8991,8992,8993,8994,8995,8996', '5288'),
(2183, 1549, 'Le Bazar du Bizarre', 'Silverbwork vous a confié quelques tâches de routine avant de passer aux choses sérieuses.', 18748, 200, 0, '8985,8997,8998,8999,9000,9001,9002,9003,9004', '5289'),
(2184, 1550, 'Un Chafer dans le placard', 'Silverbwork vous a confié plusieurs tâches en rapport avec les événements récents.', 18782, 200, 1, '8986,9012,9013,9014,9015,9016,9017,9018', '5290'),
(2185, 1551, 'Bouchées à la reine', 'Un quiproquo avec Flèche Mauve a bien failli vous coûter la vie. À présent, votre enquête peut continuer normalement.', 18800, 200, 1, '8987,9019,9020,9021,9022,9023', '5291'),
(2186, 1552, 'La cour des miracles', 'Suite au sacrifice de Flèche Mauve, vous avez décidé de rapporter à la Reine des Voleurs les récents événements.', 18812, 200, 2, '8988,9024,9025,9026,9027,9028,9029,9030', '5292'),
(2187, 1567, 'Nostalgie, quand tu nous tiens', 'Une étrange maladie sévit chez les Voyageurs Dimensionnels. Vous vous êtes porté volontaire pour endiguer l\'épidémie. Votre prochaine destination : Vulkania, terre natale de nombreuses créatures draconiques.', 0, 200, 0, '9035', '5715'),
(2188, 1568, 'Qui dit baume', 'Jangakuq a besoin de votre aide pour apaiser les souffrances de Kidibom.', 18998, 200, 2, '9053,9054,9055,9056,9057,9058,9059,9060,9061,9062,9063,9064,9065,9066,9067,9068,9069,9070', '5305'),
(2189, 1569, 'Grand corps malade', 'Vous avez proposé au capitaine Pol Ouatnos de l\'aider à nettoyer le Roc des Salbatroces.', 19028, 200, 1, '9071,9072,9073,9074,9075,9076,9077,9078,9079,9080,9081', '5304'),
(2190, 1570, 'Ponctions létales', 'Ninae Charpe a besoin de réaliser des tests pour mieux connaître les krobes. Elle vous a demandé de prélever du kroboplasme sur les macro-organismes qui prolifèrent sur le roc des Salbatroces et dans le ventre de la Baleine.', 19057, 200, 1, '9082,9083,9084,9085,9086,9087,9088', '5303'),
(2191, 1571, 'Le maître des zaaps', 'Le colonel Oneuil craint que le générateur installé en haut de la tour des Voyageurs ne soit arrivé en bout de course. Aidez le major Qiu à trouver une solution pour que les aventuriers du Monde des Douze puissent continuer à explorer les dimensions divin', 19198, 200, 1, '9250,9089,9242,9243,9244,9245,9246,9247,9248,9249', '5714'),
(2192, 1572, 'Énergie renouvelable', 'Le Maître des zaaps vous a chargé de récupérer de l\'orichor instable. Ça tombe bien, vous adorez manipuler des substances dangereuses, comme en témoignent les reliquats de crottes de nez collés aux bouts de vos doigts.', 19225, 200, 1, '9090,9253,9254,9255,9256,9257,9258,9259,9277,9260', '6582'),
(2193, 1573, 'Traitement de choc', 'La création de la batterie éternelle ne s\'est pas déroulée comme prévu : le maître des zaaps semble figé dans le temps. Le Doc Emiette Borgne prétend pouvoir tirer la Xélor de ce mauvais pas...', 19265, 200, 1, '9091,9278,9279,9280,9281,9282', '6583'),
(2195, 1575, 'Les voleurs de couleurs', 'Le colonel Oneuil vous a demandé de faire la chasse aux Hordémons afin de reprendre ce qu\'ils ont volé aux Voyageurs. Si vous avez du mal à distinguer les couleurs, foncez dans le tas : il finira bien par en sortir quelque chose.', 19609, 170, 1, '9093,9094,9095', '5307'),
(2197, 1577, 'Terminutor : le jugement de la machine', 'L\'ultime combat contre le Terminutor n\'aura pas lieu dans le futur : il sera livré dans le présent.', 19607, 170, 1, '9097,9369,9370', '5309'),
(2199, 1579, 'Juste une illusion', 'Vous avez toujours rêvé de jouer les méjaires ? Vous voilà exaucé ! Veillez à ne pas perdre votre déguisement si vous voulez amadouer le Docteur Blême. Au pire, le Collecteur Sup pourra toujours vous fournir un autre voile eidolonique en échange d\'orichor', 19437, 200, 1, '9099,9329,9330,9331', '5311'),
(2200, 1580, 'Maboul de cristal', 'Après avoir cueilli des racines, vous voilà engagé pour une mission un brin plus physique : un dangereux Égaré sévit au sud des Lendemains incertains. Montrez-lui que les Voyageurs ne sont pas du genre à se laisser faire.', 19455, 200, 1, '9100,9332,9333,9334', '5312'),
(2201, 1581, 'L\'armée des 12 dingues', 'Des Égarés vont lancer une attaque suicide contre l\'avant-poste des Voyageurs. S\'il y a une personne suffisamment ding... compétente pour les mettre hors d\'état de nuire, c\'est bien vous !', 19477, 200, 1, '9101,9335,9336,9337,9338,9339,9340,9341,9342,9343,9344,9345,9346,9347,9348', '5313'),
(2202, 1582, 'La vérité est au fond du puits', 'Le Doc Borgne a fait quelques découvertes concernant le Docteur Blême, et le Docteur Gaw a des révélations à vous faire... Il y a décidément beaucoup de docteurs dans cette histoire.', 19542, 200, 2, '9107,9349,9350,9363,9364,9365,9366,9367', '5314'),
(2203, 1583, 'Les démons de midi', 'Le Doc Emiette Borgne veut en savoir plus sur les Hordémons qui hantent le Jour présent. Connaissant votre sens aigu de la diplomatie, il vous a demandé d\'aller interroger quelques-uns d\'entre eux.', 19294, 170, 1, '9103,9283,9284,9285,9286', '5315'),
(2204, 1584, 'Aux origines du mal', 'Toujours désireux d\'en apprendre davantage sur les Hordémons, le Doc vous a envoyé faire un petit tour au Muséum. Voilà qui vous changera des tavernes et autres lieux sordides que vous fréquentez habituellement.', 19309, 170, 1, '9104,9287,9288,9301,9308,9309,9310', '5316'),
(2205, 1585, 'De fil en aiguille', 'En dehors des gardiens du Xélorium, une seule personne peut recoudre la déchirure temporelle qui a permis aux Hordémons d\'envahir le domaine privé du Grand Chronomaître : Henual, le Surveillant du Temps. Il ne reste plus qu\'à le convaincre de vous aider.', 19364, 170, 1, '9105,9312,9313,9319,9314,9315,9316,9317,9318', '5317'),
(2206, 1586, 'La Vie, l\'Hormonde et le Reste', 'Comment XLII et ses Hordémons ont-ils pu revenir dans le Xélorium malgré l\'intervention d\'Henual ? Le mieux est de poser gentiment la question au chef des envahisseurs... enfin, pas si gentiment que ça.', 19396, 170, 2, '9106,9320,9321,9322', '5318'),
(2208, 1588, 'Anomalies temporelles', 'Vous devez rencontrer l\'agent Nick Couteau et lui venir en aide au besoin.', 19088, 120, 1, '9109,9110,9111,9112,9113,9114,9115,9116,9117,9118,9119,9368,9120,9121', '5320'),
(2209, 1589, 'Failles spatio-temporelles', 'Vous devez vous assurer que l\'agent Valérien n\'a pas d\'ennuis avec les Hordémons.', 19097, 170, 1, '9122,9123,9124,9125,9126,9127,9128,9129', '5321'),
(2210, 1590, 'Déchirures temporelles', 'Le sergent Zetroc a besoin de renforts contre les Égarés.', 19108, 200, 1, '9130,9131,9132,9133,9134,9135,9136,9137,9138,9139,9140,9141,9142,9143', '5322'),
(2211, 1591, 'C\'est ton destin', 'Le Doc Emiette Borgne vous a demandé de lui apporter des œufs.', 19249, 120, 0, '9144', '5323'),
(2212, 1592, 'Retour vers le présent', 'Vous avez accepté d\'aider le Doc Emiette Borgne à ramener à leur époque les Voyageurs Dimensionnels perdus dans le temps.', 19254, 120, 1, '9145,9146,9147,9148,9149', '5324'),
(2213, 1593, 'Prisonniers du temps', 'Malgré l\'échec de la mission précédente, le Doc Emiette Borgne n\'a pas dit son dernier mot.', 19261, 120, 2, '9150,9151,9152,9153,9154,9155,9156,9157', '5325'),
(2214, 1594, 'C\'est quoi ton 06 ?', 'Vous vous êtes donné comme défi de rendre un Hordémon romantique.', 19619, 170, 1, '9371,9372,9373,9374,9375,9376,9377,9378,9379,9380,9381,9382,9383,9384,9385,9386,9387,9388,9389', '5326'),
(2215, 1595, 'Aujourd\'hui à jamais', 'Vous avez accepté une mission de vérification d\'armement.', 19115, 170, 1, '9158,9159,9160,9161,9162,9163,9164,9165,9166,9167,9168,9169,9170,9171,9172,9173,9174,9175,9176,9177,9178,9179', '5327'),
(2216, 1596, 'Tout ce qu\'il te faut, c\'est tuer', 'Pris dans une boucle temporelle, vous cherchez un moyen d\'en sortir.', 19136, 170, 1, '9180,9181,9182,9183,9184,9185,9186,9187,9188,9189,9190,9191,9192,9193,9195,9196', '5328'),
(2217, 1597, 'Futur antérieur', 'Vous enquêtez sur l\'explosion qui a failli raser l\'avant-poste des Voyageurs Dimensionnels.', 19154, 200, 1, '9229,9230,9231,9232,9233,9234,9235,9236,9237,9238,9239,9240,9241', '5329'),
(2218, 1598, 'Guerre temporelle', 'Vous devez enquêter sur l\'agression d\'un groupe d\'Archiduks.', 19649, 200, 1, '9261,9262,9263,9264,9265,9266,9267,9268,9269,9270,9271,9272,9273,9274,9275,9276,9390,9391,9392,9393', '5330'),
(2219, 1599, 'L\'étendue Gödelique', 'Des Égarés ont insisté pour que vous rencontriez quelqu\'un d\'important.', 19338, 200, 1, '9289,9290,9291,9292,9293,9294,9295,9296,9297,9298,9299,9300,9302,9303,9304,9305,9306,9307', '5331'),
(2220, 1600, 'Les visiteurs du futur', 'Vous avez accepté d\'aider Florin à retrouver son ami Haël.', 19157, 200, 1, '9197,9198,9199,9200,9201,9202,9203,9204,9205,9206,9207', '5332'),
(2221, 1601, 'Les sables du temps', 'Les Égarés se préparent à éliminer les Voyageurs Dimensionnels et vous devez les en empêcher.', 19412, 200, 2, '9208,9209,9210,9211,9212,9213,9214,9215,9216,9217,9218,9219,9220,9221,9222,9223,9224,9225,9226,9227,9228', '5333'),
(2222, 1602, 'Demain ne meurt jamais', 'Vous devez attraper le crapaud temporel ayant avalé le rapport de l\'agent Da.', 19554, 200, 1, '9351,9352,9353,9354,9355,9356,9357,9358,9359,9360,9361,9362', '5334'),
(2224, 1604, 'On recherche Morblok', 'Morblok se cache dans les Chemins d\'hier, il est recherché pour agression envers des voyageurs dimensionnels.', 0, 120, 1, '9323,9324', '5377'),
(2225, 1605, 'On recherche Hin', 'Hin se cache dans le Jour présent, il est recherché pour agression envers des voyageurs dimensionnels.', 0, 170, 1, '9325,9326', '5378'),
(2226, 1606, 'On recherche Sicogne', 'Sicogne se cache dans les Lendemains incertains, il est recherché pour agression envers des voyageurs dimensionnels.', 0, 200, 1, '9327,9328', '5379'),
(2227, 1607, 'Aventure miniature', 'Vous pensiez avoir tout vu, mais c\'est la première fois que vous vous lancez dans une quête à cause d\'une croquette... À en juger par l\'aura divine qui brille autour d\'elle, cette croquette n\'est pas un vulgaire aliment pour chacha. Pourquoi ne pas interr', 0, 200, 1, '9394,9395,9396,9397,9398,9399,9400,9401', '5336'),
(2228, 1608, 'Le disparu de Sufokia', 'Tatine s\'inquiète pour l\'un de ses amis qui ne donne plus de nouvelles. N\'écoutant que votre bon cœur, vous avez proposé votre aide pour retrouver le cher disparu. Votre générosité est décidément sans égale.', 19745, 200, 2, '9402,9403,9404,9405,9406,9407,9408,9409,9417,9410,9411,9412,9413,9414,9415,9416', '5337,5338,5339,5340,5341'),
(2229, 1609, 'Rendez-vous avec la mort', 'Un messager vous a fait comprendre que vous êtiez attendu au temple de Sram. Une petite voix intérieure et grelottante vous supplie de ne pas donner suite à cette invitation, mais si vous commencez à écouter votre instinct de survie, vous passerez votre j', 19988, 200, 1, '9467,9468,9469,9470', '6595'),
(2230, 1610, 'Secret de fabrication', 'Vous devez contacter l\'agent Bloude, à la tour des Voyageurs, pour obtenir une preuve des agissements de l\'Explorancienne.', 20005, 200, 1, '9418,9419,9420,9421,9422,9423,9424,9425,9426,9427,9428,9429,9430,9431,9432,9433,9434,9435,9436,9437,9438,9439,9440', '5342'),
(2231, 1611, 'S\'emparer des commandes', 'Vous devez vous rendre à Srambad pour y récupérer le colis destiné à Gein.', 20006, 200, 1, '9441,9442,9443,9465,9444,9445,9446,9447,9448,9449,9450,9451,9452,9453,9454,9455,9456,9457,9458,9459,9460,9461,9462,9463,9464,9466', '5343'),
(2232, 1612, 'C\'est dans la boîte', 'Gein s\'intéresse à une vieille légende consignée dans l\'Historibus Compendium, un ouvrage conservé dans le Muséum du Xélorium. Il vous a donc demandé de vous rendre sur place : vous devriez ainsi en apprendre un peu plus sur cette légende, et vérifier s\'i', 20008, 200, 1, '9471,9472,9473,9474,9475,9476,9477,9478,9480,9479,9481,9482,9483,9484', '6596'),
(2233, 1613, 'Crise d\'identité', 'Le moment est venu de dévoiler aux chefs des Voyageurs la véritable identité de l\'Explorancienne. Il reste à espérer que les officiers vous croiront quand vous leur apprendrez la vérité. À force de vivre dans le mensonge, on finit par s\'y habituer.', 20060, 200, 1, '9485,9486,9487,9488,9489,9490,9491,9492,9493,9494,9495,9496,9497,9498', '6597'),
(2234, 1614, 'La quête de l\'oiseau du temps', 'Vous avez rencontré un étrange personnage qui semble hanté par des visions provenant du Xélorium... Si vous l\'aidez, peut-être obtiendrez-vous quelques éclaircissements sur certains événements auxquels vous avez été mêlé.', 20216, 200, 1, '9499,9500,9501,9502,9503,9504,9505', '6598'),
(2235, 1616, 'Dévotion au Roi-Dieu', 'Pour montrer votre dévotion envers votre divinité tutélaire, vous devez vous rendre au temple qui lui est consacré.', 30471, 30, 0, '9506,9507,9508,9509', '5408'),
(2236, 1617, 'Chasse au Dopeul Eliotrope', 'En cas de victoire contre le Dopeul, le maître des combats vous récompensera.', 0, 200, 0, '9510', '5344'),
(2237, 1615, 'Un rayon de soleil', 'Lester est inquiet d\'être sans nouvelle de son ami Hicha et vous a demandé de le retrouver.', 20180, 20, 1, '9516,9517,9518,9519,9520,9521,9522,9523,9524,9525,9526,9527', '5354'),
(2238, 1618, 'C\'est tout Simple', 'Le fils de Saule semble avoir échappé à la tuerie perpétrée par les Arak-haï, mais il a disparu depuis l\'attaque. Parviendrez-vous à le retrouver afin de le guider en lieu sûr ?', 20489, 90, 1, '9536,9537,9538,9539,9540,9541,9542,9543,9544,9545,9546,9547,9548', '5380'),
(2239, 1619, 'Arak-haï en pagaille', 'Le colonel Rumo vous a demandé d\'évaluer la menace constituée par les Arak-haï : le roi Allister doit-il craindre une attaque sur le village ? Faut-il prendre des mesures drastiques pour éradiquer ces créatures ? À vous d\'apporter des éléments de réponse ', 20504, 90, 2, '9549,9550,9551,9552,9553,9554,9555,9556,9557,9558,9559', '5381'),
(2240, 1620, 'Munster lève le mystère', 'Avant de déclarer la guerre à la Reine Nyée et à sa progéniture, Cornelia Granpa veut en savoir plus sur les origines des Arak-haï. D\'où viennent ces créatures ? Le magicien Hel Munster pourrait vous aider à résoudre ce mystère.', 20520, 90, 2, '9560,9561,9562,9563,9564,9565,9566,9567,9568,9569,9570,9571,9572', '5382'),
(2241, 1621, 'L\'art de la langue de bois', 'Quelque chose ne tourne pas rond dans la Forêt Sombre... Silvosse vous a investi du pouvoir de parler aux végétaux afin que vous puissiez mener l\'enquête.', 20561, 140, 2, '9573,9574,9575,9576,9577,9578,9579,9580,9581,9582,9583,9584,9585,9586,9587', '5383'),
(2242, 1622, 'On recherche Tyranne la Terrible', 'Tyranne la Terrible a été aperçue du côté de la Forêt Sombre. \nElle est condamnée à l\'emprisonnement dans les geôles d\'Amakna.', 0, 80, 1, '9588,9595', '5384'),
(2243, 1623, 'On recherche Naganita', 'Naganita a été aperçue du côté de l\'île de Kartonpath. \nElle est condamnée à l\'emprisonnement dans les geôles d\'Amakna.', 0, 100, 1, '9589,9596', '5385'),
(2244, 1624, 'On recherche Nenufor Tilotus', 'Nenufor Tilotus a été aperçu du côté de la Tourbière sans fond. \nIl est condamné à l\'emprisonnement dans les geôles d\'Amakna.', 0, 120, 1, '9590,9597', '5386'),
(2245, 1625, 'On recherche Fojumo', 'Fojumo a été aperçu du côté du Cirque de Cania. \nIl est condamné à l\'emprisonnement dans les geôles d\'Amakna.', 0, 140, 1, '9591,9598', '5387'),
(2246, 1626, 'On recherche Anatak Diskedor', 'Anatak Diskedor a été aperçu du côté des Dents de Pierre. \nIl est condamné à l\'emprisonnement dans les geôles d\'Amakna.', 0, 160, 1, '9592,9599', '5388'),
(2247, 1627, 'On recherche le Guerrier du K.O', 'Le Guerrier du K.O. a été aperçu du côté du Mont Torrideau. \nIl est condamné à l\'emprisonnement dans les geôles d\'Amakna.', 0, 180, 1, '9593,9600', '5389'),
(2248, 1628, 'On recherche le Grand Kongoku', 'Le Grand Kongoku a été aperçu du côté des Salles des Embruns, dans la base abyssale de Merkator. \nIl est condamné à l\'emprisonnement dans les geôles d\'Amakna.', 0, 200, 1, '9594,9601', '5390');
INSERT INTO `quest_steps` (`Id`, `QuestId`, `Name`, `Description`, `DialogId`, `OptimalLevel`, `Duration`, `ObjectiveIds`, `RewardIds`) VALUES
(2249, 1629, 'L\'anneau de tous les dangers', 'Vous allez apprendre à récolter des ressources, puis vous fabriquerez votre premier objet. Ce ne sera que le début d\'une longue carrière d\'artisan !', 20673, 2, 0, '9655,9656,9657,9658,9659,9660,9661,9662,10015,9663', '6159'),
(2250, 1630, 'Sous le regard des dieux', 'On dit que la valeur n\'attend pas le nombre des années... Les dieux ont les yeux rivés sur vous : vous allez leur en mettre plein la vue en affrontant les créatures de Maître Darm.', 20675, 2, 0, '9680,9685,9720,10121,10016,9734', '6170'),
(2251, 1631, 'Réponses à tout', 'Avant de quitter le temple céleste, prenez le temps de contempler les Dofus et le Monde des Douze... et n\'oubliez pas de saluer votre dieu au passage !', 20709, 2, 0, '9730,9738,9739,9740', '6177'),
(2252, 1632, 'Le village dans les nuages', 'Les habitants du village d\'Incarnam sont prêts à aider les aventuriers. N\'hésitez pas à aller les saluer !\nPour vous aider à trouver votre chemin, utilisez le système de {ui,subQuestUi,btn_loc_m_gd_objectives_0,4::localisation d\'objectif} afin d\'afficher ', 20780, 3, 0, '9762,9763,9764,9765,9766,9767,9768', '5410'),
(2253, 1633, 'Mort au rat !', 'Le tavernier semble avoir un hôte indésirable dans sa cave. Expulsez le rat pour toucher votre récompense.', 0, 7, 0, '9895,9769,9770,9771', '5391'),
(2254, 1634, 'Espoirs et tragédies', 'Fécaline la Sage semble en connaitre un rayon sur les Dofus : elle vous a conseillé un ouvrage sur le sujet. Vous êtes un héros, ce ne sont pas quelques pages et un peu d\'encre qui vont vous faire perdre courage !', 20918, 5, 0, '9772,9773,9774,9775,9776,9777', '5411'),
(2255, 1635, 'Dans la gueule du Milimilou', 'Pour récupérer les Dofus de Hargnok, vous êtes prêt à tout, y compris à affronter le terrible Milimilou. Waouh.', 20926, 8, 0, '9783,9784,9785,9786,9787', '5409'),
(2257, 1637, 'La galette secrète', 'Anta Brok vous a confié une recette secrète : saurez-vous préparer une galette sans faire de boulette ?', 20976, 7, 0, '9805,9806,9807,9808,9809,9810', '5425'),
(2258, 1638, 'Cryptologie', 'Kardorim sera probablement très mécontent de vous voir vous promener dans sa crypte... raison de plus pour le réduire au silence, lui et sa bande de chafers.', 20830, 10, 1, '9811,9812,9813', '5424'),
(2259, 1639, 'Transport peu commun', 'Pour en apprendre un peu plus sur la nature des zaaps, ces étranges portes magiques, Ternette Nhin vous a conseillé de rencontrer Xélora Fistol.', 20808, 3, 0, '9814,9815,9816', '5419'),
(2260, 1640, 'Des vestiges de légende', 'Les dieux ont parfois tendance à laisser traîner leurs affaires sur Incarnam. Sans doute est-ce pour marquer les esprits et attiser la ferveur de leurs disciples. Ou peut-être sont-ils simplement distraits, allez savoir.', 20814, 5, 0, '9817,9818,9819,9820,9821,9822', '5420'),
(2261, 1641, 'Vu du ciel', 'Vous êtes du genre à prendre les choses de haut ? Jetez donc un coup d\'œil aux longues-vues installées sur les bord de l\'île céleste, vous ne serez pas déçu.', 20819, 6, 0, '9823,9824,9825,9826,9827', '5421'),
(2262, 1642, 'Mise à l\'épreuve', 'La Caporale Mynerve va vous faire passer un test d\'aptitude afin de déterminer si vous êtes digne d\'entrer dans la milice céleste.', 20877, 3, 0, '9828,9829,9830,9831', '5412'),
(2263, 1643, 'Champs de bataille', 'Le capitaine vous a confié une tâche simple mais utile : montrer aux esprits rebelles qui peuplent les champs qu\'il est temps pour eux de s\'incarner. L\'utilisation de la violence pour les convaincre est hautement recommandée.', 20881, 5, 0, '9832,9833,9834,9835,9836', '5413'),
(2264, 1644, 'Coups d\'épée dans l\'eau', 'Le capitaine des Kerubims vous a demandé de mouiller la chemise et de chasser des gloots pour faire un exemple.', 20887, 6, 0, '9837,9838,9839,9840', '5414'),
(2265, 1645, 'Décime-moi des bouftous', 'Votre mission : inciter les esprits des bouftous à abandonner les pâturages célestes pour commencer une nouvelle vie. Avec un peu de chance, si vous parvenez à en faire partir quelques-uns, les autres suivront.', 20888, 7, 0, '9841,9842,9843,9844,9845', '5415'),
(2266, 1646, 'Chasse aux chapardams', 'Les esprits félins de la forêt d\'Incarnam ont besoin d\'être réprimandés, sans quoi ils risquent de dépasser les limites. En tant que suppléant de la milice céleste, vous êtes habilité à leur tirer les oreilles, voire les moustaches.', 20889, 8, 0, '9846,9847,9848,9849', '5416'),
(2267, 1647, 'Leçon d\'humilité', 'Cette Kruella mérite une bonne correction !', 20890, 8, 0, '9850,9851', '5417'),
(2268, 1648, 'Des chafers qui marchent', 'Le capitaine vous a chargé de retrouver un sac de bijoux volé par un chafer. Profitez-en pour faire un peu de nettoyage dans le cimetière.', 20893, 9, 0, '9852,9853,9854,9855,9856,9859,9857,9858', '5418'),
(2269, 1649, 'Produits naturels', 'Afin de tester vos compétences, Berb Nhin vous a demandé de confectionner quelques produits bien connus des artisans d\'Incarnam. Les ateliers du village sont à votre disposition, vous pouvez les utiliser pour accomplir votre travail.', 21043, 5, 0, '9863,9864,9866,9867,9868,9870', '5427'),
(2270, 1650, 'La hache et la pioche', 'La nouvelle tâche demandée par Berb Nhin : couper du bois et extraire du minerai afin de fabriquer une planche et de la ferrite. Les ateliers du village vous permettront de mener ce travail à bien.', 21050, 6, 0, '9871,9872,9873,9874', '5422'),
(2271, 1651, 'Boune un jour, boune toujours', 'La panoplie du Boune : un classique indémodable ! Vous allez fabriquer une amulette S\'Mesme, un anneau Plussain, des Incrustes, une ceinture Spamette, une cape S\'loque et un chapeau Floude. Vous pourrez ensuite vous pavaner avec cette tenue que vous aurez', 21056, 7, 1, '9875,9877,9878,9879,9880,9881,9882,9883,9884,9885,9886,9887', '5426'),
(2272, 1652, 'Le choix des armes', 'Berb vous soumet à une dernière épreuve : fabriquer des armes dignes de ce nom. En prime, vous devez confectionner une clef de la Crypte de Kardorim. Si vous n\'avez pas peur de vous aventurer dans un donjon, elle vous sera peut-être utile...', 21062, 8, 0, '9888,9889,9890,9891,9892,9893,9894', '5423'),
(2273, 1653, 'Plongeon et dragon', 'D\'après Mériana, Aguabrial cherche un nouveau gardien pour le Dofus Turquoise. C\'est le moment de vous manifester ! Première chose à faire : récupérer les clefs détenues par le Chêne Mou et le Dragon Cochon afin de décrocher une entrevue avec le Dragon. U', 21482, 140, 2, '9947,9948,9949,9950,9951,9952,9953,9954,9955,9956,9957,9958,9959,9960,9961,9962,9963,9964', '5434'),
(2274, 1654, 'Extinction des feux', 'Bonne nouvelle : Aguabrial et son ami Ereziah ont retenu votre candidature pour devenir le nouveau gardien du Dofus Turquoise. Mauvaise nouvelle : vous allez devoir affronter l\'esprit d\'un Dragon consumé par la colère ! Voilà un défi à votre mesure...', 21488, 140, 2, '10130,9965,9966,10158,9967,9968,9969,9971,9972,9973,9974,9975,9976,9977,9978,9979,9980,10131,9981,9982,9983,9984', '5435'),
(2275, 1655, 'Un peu de pigment', 'Malgré l\'accent prononcé de Marylork, vous avez compris ce dont il avait besoin... Vous voilà donc parti à la chasse aux champignons.', 0, 6, 0, '9970', '5429'),
(2276, 1656, 'On dirait le Sud', 'Vous allez devoir récupérer des totems magiques afin d\'obliger l\'esprit de Furye à se manifester. Le premier de ces totems est enfoui quelque part au sud d\'Amakna... Pour le déterrer, il vous faut une pelle enchantée. Vous voilà donc parti à la recherche ', 21502, 140, 2, '9985,9986,10132,9987,9988,9989,9990,9991,9992,9993,9994,9995,9996,9997,10133,9998,9999,10000,10001', '5436'),
(2277, 1657, 'La méchante sorcière de l\'Est', 'Après votre promenade en Amakna, une petite excursion sur l\'île de Frigost devrait vous rafraîchir les idées. Espérons que la sorcière Badmorva se montrera coopérative... sans sa marque, vous ne pourrez pas déterrer le totem de l\'Est.', 21515, 150, 2, '10002,10003,10004,10005,10006,10007,10008,10009,10010,10011,10012,10013,10014', '5437'),
(2278, 1658, 'Autel du Nord', 'Vous vous êtes à peine remis des rigueurs du climat frigostien que Mériana vous annonce que vous devrez bientôt retourner sur l\'île glacée ! La vie de héros n\'est décidément pas de tout repos... Pourrez-vous profiter de votre passage au village des Brigan', 21521, 160, 2, '10017,10018,10019,10020,10021,10022,10023,10024,10025,10026,10027,10028,10029,10030,10031,10032,10033,10034,10035,10036', '5438'),
(2279, 1659, 'Il était une foi dans l\'Ouest', 'Le dernier totem est celui de l\'Ouest. Mériana vous a prévenu : vous aurez peut-être des surprises en essayant de le récupérer... ça tombe bien, vous adorez les surprises. Direction l\'île d\'Otomaï pour obtenir la bénédiction de Foluk !', 21524, 180, 2, '10037,10038,10039,10040,10041,10042,10043,10044', '5439'),
(2280, 1660, 'La bénédiction de Viti', 'Pour obtenir la bénédiction de Viti, le dieu de l\'Est, vous devez vaincre des gardiens de donjon dans leurs antres respectifs en combattant sous l\'influence de certaines idoles. Harmonie Daule située près de l\'église d\'Amakna devrait vous aider à les conf', 21688, 150, 2, '10045,10046,10047,10050', '5440'),
(2281, 1661, 'La bénédiction de Thomahon', 'Vous voulez obtenir la bénédiction de Thomahon, le dieu du Nord ? Il ne vous reste plus qu\'à faire mordre la poussière à certains gardiens de donjon... mais pour prouver votre valeur, vous devrez non seulement les vaincre sur leurs propres territoires, ma', 21733, 160, 2, '10054,10051,10052,10053,10055', '5441'),
(2282, 1662, 'La bénédiction de Foluk', 'Rassemblez quelques idoles en allant voir Harmonie Daule près de l\'église d\'Amakna, et partez tirer les oreilles des gardiens de donjon qui figurent sur la liste noire de Foluk, le dieu de l\'Ouest : si vous revenez vainqueur, vous obtiendrez sa bénédictio', 21752, 180, 2, '10056,10057,10060,10062', '5442'),
(2283, 1663, 'Une âme en colère', 'Votre quête touche à sa fin : vous devez maintenant vous préparer à la confrontation avec Furye. Seul, vous n\'avez aucune chance : vous allez donc recruter des esprits aquatiques qui combattront pour vous. Si vous remportez la victoire, le Dofus Turquoise', 21530, 180, 2, '10063,10064,10065,10066,10067,10068,10069,10070,10071,10072,10074,10073,10075', '5443'),
(2285, 125, 'Apprentissage : Chasseur d\'Âmes', 'Vous devez prouver à Ledrob Terceséc que vous disposez des aptitudes nécessaires pour devenir Chasseur d\'Âmes.', 0, 140, 2, '10126,10187,10188,10189,10190,10191', '6300'),
(2290, 257, 'Renseignements à la Bagrutte', 'Le marchand de vin local a disparu. Le tavernier de la Bagrutte a peut-être des renseignements.', 4340, 111, 2, '1049,1050,1051,2750,10128,10129,2751', '6257'),
(2291, 1665, 'L\'ombre et la proie', 'L\'Huppermage Jed Reivrepel est à la recherche d\'une apprentie qui a disparu après le vol de l\'Œil de Grougalorasalar. Joris vous a confié la mission de la retrouver.', 21667, 140, 2, '10135,10136,10137,10154,10138,10139,10140,10141,10142,10143,10144,10145,10146,10147,10148,10149,10150,10151,10152,10153', '5444'),
(2292, 1666, 'Partir un jour sans retour', 'Partir un jour sans bagages... que des ailes et un casque... Sans se retourner, jouer au boulet... Le nez dans le sable, se prélasser !', 21839, 50, 0, '10162,10163', '5447'),
(2293, 1667, 'Un parfum de vacances', 'Ce séjour sur l\'île de Moon s\'annonce vraiment bien... Quoi de mieux qu\'un Dofus comme souvenir de vacances ?', 21866, 50, 1, '10164,10165,10166,10167,10168,10169,10170,10171', '5448'),
(2294, 1668, 'Un indigeste chez les indigènes', 'Puant la charogne comme le cadavre putréfié d\'un bouftou, vous vous enfoncez dans la forêt des Masques. Il ne vous reste plus qu\'à espérer que le chef des Kannibouls n\'a pas un goût prononcé pour la viande avariée.', 21875, 60, 2, '10172,10192,10193,10194', '5449'),
(2295, 1669, 'Squelettes et amulette', 'Pour obtenir l\'aide de Mamie Voudou, vous allez devoir rendre visite au Chouque. Comme tout bon fan de parcs d\'attraction, vous rêvez de visiter un bateau pirate et une maison hantée ? En montant à bord de la Perlouze, vous ferez les deux en même temps.', 21891, 90, 2, '10209,10195,10196,10197,10198,10199,10200,10201,10202,10203,10204', '5450'),
(2296, 1670, 'Rendez-vous avec la lune', 'Il vous reste un peu de jardinage à faire avant de grimper à l\'arbre de Moon : Mamie Voudou vous a suggéré d\'enterrer la pousse de ginsengoku au pied d\'un totem. Pour accélérer la croissance du végétal, il vous faut de l\'engrais cent pour cent naturel... ', 21911, 100, 2, '10205,10206,10207,10208', '5451'),
(2297, 1671, 'Le radeau ivre', 'Kaponor vous a demandé de l\'aider à construire le radeau qui lui permettra de quitter l\'île de Moon. De nombreuses tâches vous attendent ! Rendez-vous chez les Kannibouls pour dégoter des tonneaux et des cordes en liane. Coupez quelques kokokos et quelque', 21961, 100, 2, '10210,10211,10212,10213,10214,10215,10216,10217', '5445'),
(2298, 1672, 'Sur les traces des Moonies', 'Vous voilà parti pour une chasse au trésor. Celle-ci n\'étant pas organisée par le clan Terra, il n\'y a aucune garantie de résultat. Un professionnel vous dirait que seuls les fous se lancent dans ce genre d\'expédition sans une étude approfondie du terrain', 0, 90, 1, '10218,10219,10220,10221,10222,10224,10225,10227,10226,10228', '5452'),
(2299, 1673, 'Le combat des chefs', 'Certains aventuriers pressés et illettrés adorent les quêtes de Fred Hex, mais ce n\'est pas forcément votre cas. Pourtant, un héros en vacances reste un héros, toujours prêt à aider son prochain : vous avez donc accepté la mission confiée par le livreur e', 21982, 90, 1, '10231,10232,10233,10234,10235,10236,10237,10238,10239,10240', '5454'),
(2300, 1674, 'On recherche Trukipik', 'Trukipik a été aperçu du côté de l\'île de Moon. \nIl est condamné à l\'emprisonnement dans les geôles d\'Amakna.', 0, 100, 1, '10229,10230', '5446'),
(2301, 1675, 'Bas les masques', 'Kara Hibe veut vendre des objets exotiques à ses clients du continent : il vous a donc demandé de l\'aider à se constituer un stock. Chassez les Kannibouls et dépouillez-les de leurs masques avec toute la cruauté qui vous caractérise.', 22018, 60, 1, '10241,10242,10243,10244', '5455'),
(2302, 1676, 'Serrons-nous la main', 'Quand le Chouque repère un voleur sur son bateau, il n\'y va pas de main morte : il lui coupe la paluche avant de jeter l\'intrus du haut de la falaise. Mais s\'approprier la main baladeuse d\'un aventurier peut causer quelques soucis, surtout lorsque l\'on es', 22024, 90, 1, '10245,10246,10247,10251,10248,10249,10250', '5453'),
(2303, 293, 'Une rumeur intéressante', 'Une rumeur affirme qu\'il existe une corne disposant de puissants pouvoirs magiques. Les habitants de Sufokia auraient des informations supplémentaires.', 4561, 151, 1, '1126,10255,10256,10257,10258,2866,2867,1128', '6305'),
(2304, 305, 'Une rumeur alléchante', 'D\'après vos sources, le tavernier de Sufokia aurait des informations sur une puissante corne magique.', 4623, 151, 1, '1151,10259,10260,10261,10262,2723,2724,1156', '6338'),
(2305, 302, 'Bandanarthrie', 'Vous devez récupérer le bandana de Turorte.', 4607, 155, 2, '1144,1145,2873,2874,2875,2876,2877', '6524'),
(2306, 309, 'Une faille dans sa carapace', 'Il faut fabriquer un grattoir à dos que Turorte puisse utiliser. Étant le meilleur forgeron de Brâkmar, Mulic Bere pourra vous aider à réaliser cet outil particulier.', 4635, 155, 2, '1160,2731,10263,2732,10266,10267', '5771'),
(2307, 333, 'Des personnes de confiance', 'Amayiro a besoin de personnes de confiance pour participer à la mise en scène des faux pouvoirs de la Corne Edfrit.', 4880, 160, 2, '1260,1261,1262,1263,1264,1265,1266,2885', '6068'),
(2308, 314, 'L\'art de cuisiner sans se fatiguer, ou presque', 'Vous devez trouver les recettes des ingrédients listés sur le papier remis par Oto Mustam.', 4660, 158, 1, '1167,2741,2742,2743,2744,2745,2746,2747,2748,2749,1168,1169', '6069'),
(2309, 303, 'Une Corne Edfrit sans sel', 'Convaincre Turorte d\'échanger le Bandana Rapiécé contre la Corne Edfrit. Vous avez besoin d\'une Fourbacoiffe et d\'une Bouteille de Gloutoburg pour qu\'elle vous apparaisse.', 4610, 158, 1, '1146,1147,2880,10279,10280,1148', '5748'),
(2310, 315, 'Affrontement !', 'Vous devez négocier l\'emplacement de la Corne Edfrit contre un Grattoir à dos Spentox auprès de Turorte, mais qui sait ce qui vous attend dans la jungle interdite de Moon ?', 4668, 159, 1, '1170,10290,1171,1172,3461,1173', '6005'),
(2312, 1677, 'Les paroles s\'envolent, les aigris restent', 'Hazel a du mal à comprendre pourquoi on lui a livré des enclumes à la place des chaudrons qu\'elle avait commandés. Elle vous a demandé de mener l\'enquête.', 22251, 12, 1, '10302,10303,10304,10305,10306,10307,10308,10309,10310,10311,10312,10313,10314,10315,10316', '5456'),
(2313, 1678, 'Dévotion à la Balance Krosmique', 'Pour montrer votre dévotion envers la Balance Krosmique, vous devez vous rendre au temple qui lui est consacré.', 30471, 30, 0, '10317,10318,10319,10320', '5457'),
(2314, 1679, 'Chasse au Dopeul Huppermage', 'En cas de victoire contre le Dopeul, le maître des combats vous récompensera.', 0, 200, 0, '10322', '5458'),
(2315, 1680, 'On recherche Sam Sagaz', 'Sam Sagaz a été aperçu dans les prairies d\'Astrub.\nIl est condamné à l\'emprisonnement dans les geôles de la milice.', 0, 20, 1, '10335,10336', '5468'),
(2316, 1681, 'On recherche Maître Boulet', 'Maître Boulet a été aperçu dans la clairière de Brouce Boulgoure.\nIl est condamné à l\'emprisonnement dans les geôles de la milice.', 0, 30, 1, '10337,10338', '5469'),
(2317, 1682, 'On recherche Roub\' Ignolles', 'Roub\' Ignolles a été aperçu dans le cimetière d\'Amakna.\nIl est condamné à l\'emprisonnement dans les geôles de la milice.', 0, 40, 1, '10339,10340', '5470'),
(2318, 1683, 'On recherche Bouss Baybe', 'Bouss Baybe a été aperçue dans la plaine des Porkass.\nElle est condamnée à l\'emprisonnement dans les geôles de la milice.', 0, 50, 1, '10341,10342', '5471'),
(2319, 1684, 'On recherche Nono le Wobot', 'Nono le Wobot a été aperçu sur l\'îlot de la Couronne.\nIl est condamné à l\'emprisonnement dans les geôles de la milice.', 0, 60, 1, '10343,10344', '5472'),
(2320, 1685, 'On recherche Armada l\'Invincible', 'Armada l\'Invincible a été aperçue dans l\'Arche d\'Otomaï.\nElle est condamnée à l\'emprisonnement dans les geôles de la milice.', 0, 70, 1, '10345,10346', '5473'),
(2321, 1686, 'On recherche Dragodingo', 'Dragodingo a été aperçue dans le territoire des Dragodindes.\nElle est condamnée à l\'emprisonnement dans les geôles de la milice.', 0, 80, 1, '10347,10348', '5474'),
(2322, 1687, 'On recherche Degolas', 'Degolas a été aperçu sur le Chemin du Crâne.\nIl est condamné à l\'emprisonnement dans les geôles de la milice.', 0, 90, 1, '10349,10350', '5475'),
(2323, 1688, 'On recherche le Prince Marchand', 'Le Prince Marchand a été aperçu dans le Territoire des Porcos.\nIl est condamné à l\'emprisonnement dans les geôles de la milice.', 0, 100, 1, '10351,10352', '5476'),
(2324, 332, 'Le roi Estitch', 'Oto Mustam veut que vous régliez son problème d\'épée.', 22431, 180, 2, '10371,10372,10373,10374,10375,10376,10377,10378,10379,10380,10381,10382,10383,10384,10385', '5725'),
(2325, 1689, 'Puce de Luxe', 'Vous devez remettre un plan à l\'agent Gélik pour l\'aider à mener à bien sa mission.', 22471, 110, 1, '10388,10389,10390,10391,10392,10393,10394', '5504'),
(2326, 1690, 'Le jeu du Chaminou', 'Vous devez récupérer le rapport de l\'agent Taï.', 22484, 160, 1, '10395,10396,10397,10398,10399,10400,10401,10402', '5505'),
(2327, 1691, 'Le conquérant', 'Vous devez mettre l\'agent Kull aux arrêts.', 22508, 200, 1, '10403,10404,10405,10406,10407,10408,10409,10410,10411,10412,10413', '5510'),
(2328, 1692, 'Ça saute aux œufs', 'Le docteur Gaw a besoin d\'œufs d\'ecaflipuces pour ses expériences. Comment, vous êtes encore là ? Dépêchez-vous de fouiller les Pierres de l\'élévation et d\'apporter les œufs au sergent Baste... et que ça saute !', 22724, 110, 1, '10414', '5477'),
(2329, 1693, 'Chacun cherche son chacha', 'Le Major Qiu est sans nouvelles de son animal familier : celui-ci a disparu après avoir franchi un portail vers la dimension Ecaflipus. N\'écoutant que votre courage (ou désireux de rompre votre ennui), vous avez décidé de partir à la recherche de Chester ', 22757, 200, 1, '10415,10569,10570,10571,10572,10573,10574,10575,10576,10577,10578,10579,10580,10581,10582,10583', '5488,5489,5490,5491,5492'),
(2330, 1694, 'Question de réputation', 'Chaknoris ne fait pas que lire les descriptions dans son journal de quête, il lit aussi TOUS les dialogues des PNJ... mais bon, c\'est Chaknoris.', 22826, 200, 1, '10416,10584,10585,10586,10587,10588', '5493,5494,5495,5496,5497'),
(2331, 1695, 'Matou vu', 'Il est déjà assez difficile de retrouver un chacha disparu, mais si en plus ledit chacha disparaît à la première occasion, cela devient carrément impossible. Et à l\'impossible, nul n\'est tenu... sauf vous, bien entendu.', 22815, 200, 1, '10417,10589,10590,10591,10592,10593,10596,10594,10595', '5498,5499,5500,5501,5502'),
(2332, 1696, 'Balade en Ecaflipus', 'Kerubim vous a proposé de faire un petit tour dans la dimension du dieu Ecaflip. Voilà une offre qui ne se refuse pas.', 30370, 200, 1, '10418,10560,10561,10562,10563,10564,10565,10566,10567,10568', '6590'),
(2333, 1699, 'Sanctuaires de famille', 'Rol Sterding voudrait localiser avec précision les sanctuaires de certains fils d\'Ecaflip. Il ne vous l\'a pas précisé, mais vous feriez bien de ne rien casser si vous vous permettez d\'explorer les lieux... Vous ne voudriez pas encourir la colère d\'un reje', 22932, 160, 1, '10419,10613,10611,10612,10614,10615,10616,10617,10618,10619', '5479'),
(2334, 1700, 'Dimensions absurdes', 'Vous avez accepté d\'aider la jeune Ecalice a résoudre son problème de taille... Les mauvaises langues pourraient dire que c\'est parce que vous avez le même souci, mais pour notre part, nous savons que vous n\'agissez que par pur altruisme.', 22986, 200, 1, '10420,10639,10640,10641,10642,10643,10644,10645,10646,10647,10648,10649,10650', '5480'),
(2335, 1701, 'Une parodie de jeustice', 'Ecalice risque d\'être condamnée pour avoir mangé une part de tarte. Il se peut bien que vous soyez pour quelque chose dans cette affaire : votre honneur et votre honnêteté vous commandent donc d\'intervenir lors du procès. Si vous n\'êtes doté d\'aucune de c', 23081, 200, 1, '10421,10651,10652,10653,10654,10655,10656,10657,10658', '5481'),
(2336, 1702, 'De l\'autre côté du Chalœil', 'Les gardes du Grand Jeu semblent avoir abandonné la poursuite, mais ils ne laisseront pas Ecalice quitter le temple avec la tête sur les épaules. Vous devez trouver une solution... Si vous ne savez que faire, essayez de trouver quelqu\'un qui vous mettra l', 23014, 200, 2, '10422,10659,10660,10661,10662,10663', '5482'),
(2337, 1703, 'Acides animés', 'Le professeur Groschinder cherche un matériau capable de résister à l\'acide sécrété par les ecaflipuces : il vous a donc confié plusieurs boucliers à tester. N\'oubliez pas de les équiper avant de foncer tête baissée, sans quoi votre sacrifice ne servirait', 22903, 110, 1, '10598,10453,10597,10599,10600,10601,10602', '5483'),
(2338, 1698, 'GaBuZoMeu', 'Chadoc a besoin de votre aide pour endiguer l\'épidémie de chakungunya.', 22603, 160, 1, '10423,10424,10425,10426,10427,10428,10429,10430,10431,10432,10433,10434,10435,10436,10437,10438,10439,10440,10441,10442,10443,10444,10445,10446,10447,10448,10449,10450,10451,10452', '5511'),
(2339, 1704, 'Faut pas pousser', 'Après avoir testé des boucliers, vous passez maintenant à des appareils nettement plus complexes : des automates pousse-puces. Il ne reste plus qu\'à espérer qu\'ils ne vous pousseront pas dans vos derniers retranchements.', 22908, 110, 1, '10454,10603,10604,10605,10606,10607', '5484'),
(2340, 1705, 'Testé et approuvé', 'Un agent a été envoyé dans un miausolée infesté d\'ecaflipuces dans le but de tester une version améliorée du fameux bouclier en etork. Le professeur craint que l\'expérience n\'ait tourné court... Vous êtes donc envoyé en renfort dans l\'antre du pounicheur.', 22921, 110, 2, '10455,10608,10609,10610', '5485'),
(2341, 1706, 'La chance aux chanceux', 'Un certain Martin Gal prétend avoir trouvé la formule d\'un élixir qui permet d\'avoir une veine incroyable. Il a besoin d\'ingrédients pour fabriquer sa potion : vous avez accepté de lui fournir le nécessaire contre paiement.', 23113, 160, 1, '10456,10664,10665,10666,10667,10668', '5486'),
(2342, 1707, 'Karkass mania', 'Vous avez rencontré un fan de boufbowl qui rêve de suivre les traces de son idole, le champion Khan Karkass. Comme vous ne vivez que pour rendre service aux autres, mêmes aux Iops, vous avez accepté de lui servir de guide.', 22970, 200, 1, '10457,10620,10621,10622,10623,10624,10625,10626,10627,10628,10629,10630,10631,10632,10633,10634,10635,10636,10637,10638', '5487'),
(2343, 1712, 'Il s\'en est fallu d\'un poil', 'Vous devez récupérer le Chaldor, un bien Enutrof caché dans le temple de Kerubim Crépin.', 22653, 200, 1, '10458,10459,10460,10461,10462,10463,10464,10465,10466,10467,10468,10469,10470,10471,10472,10473,10474,10475,10476,10477,10478', '5513'),
(2344, 1714, 'On recherche Atcham', 'Chi, Fou et Mi ont été aperçus à de nombreuses reprises dans le Temple de Kerubim. Sous ces noms ridicules se cache en réalité Atcham, qui est recherché pour agression envers des voyageurs dimensionnels.', 0, 200, 1, '10480,10481', '5503'),
(2345, 1708, 'De mauvais poil', 'Vous enquêtez sur un moyen de neutraliser la felithropie.', 22685, 160, 1, '10482,10483,10484,10485,10486,10487,10488,10489,10490,10491,10492,10493,10494,10495,10496,10497,10498', '5506'),
(2346, 1709, 'L\'As du Volans', 'Vous continuez d\'assister Groschinder tout en cherchant qui est le commanditaire de sa tentative d\'enlèvement.', 23154, 160, 1, '10499,10500,10501,10502,10503,10504,10505,10506,10507,10508,10509,10510,10511,10512,10513,10514,10515,10516,10517,10518', '5507'),
(2347, 1697, 'Où est Charblie ?', 'Chavanna vous a demandé de l\'aider à retrouver Charblie.', 0, 160, 1, '10519,10520,10521,10522,10523,10524,10525,10526,10527,10528,10529,10530,10531,10532,10533,10534,10535,10536,10537,10538,10539,10540,10541,10542,10543,10544,10545,10546,10547,10548,10549,10550,10551,10552,10553,10554,10555,10556,10557,10558,10559', '5512'),
(2348, 1710, 'En Rouge et Noir', 'Vous devez convaincre Ush Galesh de libérer les Matougarous de son emprise.', 22772, 160, 2, '10669,10670,10671', '5508'),
