(2385, 1748, 'Les sept Mercemers', 'Des sabotages ont été rapportés à Sufokia et vous avez décidé d\'enquêter dessus.', 24124, 200, 0, '11139,11140,11141,11142,11143,11144,11145,11146,11147', '5540'),
(2386, 1749, 'Mémoires d\'un amnésique', 'Markaris a perdu la mémoire et demande votre aide pour la recouvrer.', 24169, 200, 1, '11148,11149,11150,11151,11152,11153,11154,11155,11156,11157,11158,11159,11160,11161,11162,11163,11164,11165,11166,11167,11168,11169,11170,11171,11172', '5542'),
