(2399, 1762, 'On recherche Takomako', 'Takomako a été aperçu dans l\'Abîme de R\'lyugluglu.', 0, 200, 1, '11265,11266', '5518'),
(2401, 1764, 'Le vieux gob et la mer', 'Santiagob veut attraper un gros poisson. Comme vous ne pouvez rien refuser à un gobelin, vous vous êtes porté volontaire pour réaliser son rêve.', 24465, 200, 1, '11269,11270,11271,11272,11273', '5549'),
