(2030, 'Barricade du Dopeul', 'Le Renvoi de Sorts permet de renvoyer un sort occasionnant une perte de PDV ou de PA.', 0x08b55708b65708b75708b85708b95708ba57, '1', 'Buff'),
(2031, 'Bouclier Féca du Dopeul', 'Ce bouclier réduit (en pourcentage) les dégâts reçus.', 0x08bb5708bc5708bd5708be5708bf5708c057, '1', 'Buff'),
(2032, 'Attaque Nuageuse du Dopeul', 'Occasionne des dommages Eau et vole de la chance.', 0x08c15708c25708c35708c45708c55708c657, '1', 'Debuff'),
(2033, 'Glyphe Enflammé du Dopeul', 'Ce glyphe brûle les personnes se trouvant dans sa zone.', 0x08c75708c85708c95708ca5708cb5708cc57, '1', 'Mark'),
(2034, 'Glyphe d\'Aveuglement du Dopeul', 'Ce glyphe fait perdre des PA.', 0x08cd5708ce5708cf5708d05708d15708d257, '1', 'Mark'),
(2036, 'Glyphe Optique du Dopeul', 'Ce glyphe immobilise tous les joueurs, alliés comme ennemis.', 0x08d95708da5708db5708dc5708dd5708de57, '1', 'Mark'),
