(2039, 'Bastion du Dopeul', 'L\'immunité permet de rendre le lanceur ou un allié invincible pendant quelques tours.', 0x08eb5708ec5708ed5708ee5708ef5708f057, '1', 'Buff'),
(2040, 'Dragonique du Dopeul', '', 0x08f15708f25708f35708f45708f55708f657, '1', 'Agressive'),
(2041, 'Canine du Dopeul', 'Ce sort permet d\'augmenter les PM des invocations et dans une moindre mesure, des alliés.', 0x08f75708f85708f95708fa5708fb5708fc57, '1', 'Agressive'),
(2042, 'Piqûre Motivante du Dopeul', 'Augmente considérablement la Vitalité, les Dommages, les PM et les PA d\'une invocation du lanceur.', 0x08fd5708fe5708ff57088058088158088258, '1', 'Buff'),
(2043, 'Fossile du Dopeul', '', 0x088358088458088558088658088758088858, '1', 'Agressive'),
