(2045, 'Plumeau du Dopeul', 'Occasionne des dommages Air pour chaque Tofu vivant invoqué par le lanceur.', 0x088f58089058089158089258089358089458, '1', 'Agressive'),
(2046, 'Tofu noir du Dopeul', '', 0x089558089658089758, '1', 'Summon'),
