(2052, 'Bouftou noir du Dopeul', '', 0x08b95808ba5808bb58, '1', 'Summon'),
(2053, 'Sac Animé du Dopeul', 'Ce sort permet à son lanceur de donner vie à son Sac. Ce dernier protégera un de ses alliés jusqu\'à sa destruction.', 0x08bf5808c05808c15808c25808c358, '1', 'Summon'),
(2054, 'Chance du Dopeul', 'Ce sort permet au lanceur d\'augmenter sa chance.', 0x08c55808c65808c75808c85808c95808ca58, '1', 'Buff'),
(2055, 'Lancer de Pelle du Dopeul', 'Le Lancer de Pelle inflige des dégâts de Terre.', 0x08cb5808cc5808cd5808ce5808cf5808d058, '1', 'Agressive'),
(2056, 'Pelle Fantomatique du Dopeul', 'La Pelle Fantomatique inflige des dégâts de Feu et peut retirer les effets qui enchantent la cible.', 0x08d15808d25808d35808d45808d55808d658, '1', 'Debuff'),
(2057, 'Maladresse du Dopeul', 'La Maladresse enlève des PM à un ennemi.', 0x08d75808d85808d95808da5808db5808dc58, '1', 'Debuff'),
(2058, 'Lancer de Pièces du Dopeul', 'Ce sort permet de lancer de très loin des pièces d\'or factices sur un ennemi, et lui inflige des dégâts d\'Eau.', 0x08dd5808de5808df5808e05808e15808e258, '1', 'Agressive'),
(2059, 'Maladresse de Masse du Dopeul', 'La Maladresse de Masse fait perdre des PA à tous les ennemis.', 0x08e35808e45808e55808e65808e75808e858, '1', 'Debuff'),
(2060, 'Accélération du Dopeul', 'L\'Accélération permet d\'augmenter les PM du lanceur ou d\'un allié.', 0x08e95808ea5808eb5808ec5808ed5808ee58, '1', 'Buff'),
(2061, 'Pelle du Jugement du Dopeul', 'la Pelle du Jugement occasionne de faibles dégâts d\'Eau et retire des PM sur un coup critique.', 0x08ef5808f05808f15808f25808f35808f458, '1', 'Agressive'),
(2062, 'Pelle Animée du Dopeul', 'Invoque une pelle qui repousse les ennemis et réduit leurs résistances aux pertes de PM.', 0x08f55808f65808f75808f85808f95808fa58, '1', 'Summon'),
(2063, 'Pelle Massacrante du Dopeul', 'La Pelle Massacrante inflige de terribles dégâts d\'Eau à un ennemi.', 0x08fb5808fc5808fd5808fe5808ff58088059, '1', 'Agressive'),
(2064, 'Sournoiserie du Dopeul', 'La Sournoiserie est l\'une des rares attaques à distance de cette classe, elle inflige des dégâts de Terre.', 0x088159088259088359088459088559088659, '1', 'Agressive'),
(2065, 'Coup Sournois du Dopeul', 'Inflige des dégâts de Terre à l\'adversaire et le fait reculer de plusieurs cases.', 0x088759088859088959088a59088b59088c59, '1', 'Agressive'),
(2066, 'Poison insidieux du Dopeul', 'Empoisonne la cible pendant plusieurs tours en lui causant des dégâts de type Air.', 0x088d59088e59088f59089059089159089259, '1', 'Agressive');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(2067, 'Fourvoiement du Dopeul', 'Le Fourvoiement permet d\'augmenter la force et l\'agilité du Lanceur, tout en infligeant des dégâts Air à un ennemi.', 0x089359089459089559089659089759089859, '1', 'Debuff'),
(2068, 'Piège Empoisonné du Dopeul', 'Le Piège Empoisonné empoisonne le joueur qui le déclenche.', 0x089959089a59089b59089c59089d59089e59, '1', 'Mark'),
(2069, 'Invisibilité du Dopeul', 'L\'Invisibilité permet de se rendre invisible.', 0x089f5908a05908a15908a25908a35908a459, '1', 'Buff'),
(2070, 'Attaque Mortelle du Dopeul', 'L\'Attaque Mortelle inflige énormément de dégâts de Terre à un ennemi et peut le tuer sur un coup critique.', 0x08a55908a65908a75908a85908a95908aa59, '1', 'Agressive'),
(2071, 'Piège de Silence du Dopeul', 'Le Piège de Silence fait perdre des PA au joueur qui le déclenche.', 0x08ab5908ac5908ad5908ae5908af5908b059, '1', 'Mark'),
(2072, 'Piège de Masse du Dopeul', 'Le Piège de Masse inflige de sérieux dégâts de terre à celui qui le déclenche et aux joueurs alentours.', 0x08b15908b25908b35908b45908b55908b659, '1', 'Mark'),
(2073, 'Ralentissement du Dopeul', 'Le Ralentissement retire des PA à un ennemi. Un même joueur ne peut être ciblé qu\'une fois par tour.', 0x08b75908b85908b95908ba5908bb5908bc59, '1', 'Debuff'),
(2074, 'Contre du Dopeul', 'Le Contre permet de renvoyer des dégâts.', 0x08bd5908ae990108af990108b0990108b1990108b29901, '1', 'Agressive'),
(2075, 'Aiguille du Dopeul', 'Ce sort projette une grande aiguille sur l\'adversaire pour lui infliger des dégâts de Feu.', 0x08c35908c45908c55908c65908c75908c859, '1', 'Agressive'),
(2076, 'Dévouement du Dopeul', 'Ce sort permet d\'augmenter les PA des alliés du lanceur.', 0x08c95908ca5908cb5908cc5908cd5908ce59, '1', 'Buff'),
(2077, 'Frappe de Xélor du Dopeul', 'La Frappe de Xélor inflige des dégâts de type Terre.', 0x08cf5908d05908d15908d25908d35908d459, '1', 'Agressive'),
(2078, 'Rayon Obscur du Dopeul', 'Le Rayon Obscur occasionne des dégâts de Feu importants.', 0x08d55908d65908d75908d85908d95908da59, '1', 'Agressive'),
(2079, 'Horloge du Dopeul', 'Ce sort inflige des dégâts de type Eau et vole des PA à la cible.', 0x08db5908dc5908dd5908de5908df5908e059, '1', 'Agressive'),
(2080, 'Cadran de Xélor du Dopeul', 'Ce sort permet de placer un écran de protection devant le lanceur.', 0x08e15908e259, '1', 'Summon'),
(2081, 'Vol du Temps du Dopeul', 'Ce sort vole des PA à un ennemi pour les donner au lanceur.', 0x08e75908e85908e95908ea5908eb5908ec59, '1', 'Agressive'),
(2082, 'Sablier de Xélor du Dopeul', 'Le Sablier de Xélor inflige des dégâts de Feu et fait perdre des PA à un ennemi.', 0x08ed5908ee5908ef5908f05908f15908f259, '1', 'Debuff'),
(2083, 'Roulette du Dopeul', 'La Roulette lance des effets aléatoires sur vos adversaires, vos alliés et parfois tous les personnages présents dans votre combat.', 0x08f35908f45908f55908f65908f75908f859, '1', 'Buff'),
(2084, 'Trèfle du Dopeul', 'Le Trèfle augmente les coups critiques.', 0x08f95908fa5908fb5908fc5908fd5908fe59, '1', 'Buff'),
(2085, 'Topkaj du Dopeul', 'Topkaj inflige d\'importants dégâts de Feu.', 0x08ff5908805a08815a08825a08835a08845a, '1', 'Agressive'),
(2086, 'Bluff du Dopeul', 'Le Bluff inflige aléatoirement des dégâts d\'Air ou d\'Eau.', 0x08855a08865a08875a08885a08895a088a5a, '1', 'Agressive'),
(2087, 'Rekop du Dopeul', 'Ce sort inflige des dégâts monstrueux de Feu, Terre, Eau et Air, mais a une chance sur deux de faire perdre un point d\'action.', 0x088b5a088c5a088d5a088e5a088f5a08905a, '1', 'Agressive'),
(2088, 'Odorat du Dopeul', 'Décuple l\'odorat de tous les participants du combat présents autour du lanceur, ce qui occasionne une déconcentration ou une motivation...', 0x08915a08925a08935a08945a08955a08965a, '1', 'Buff'),
