(2103, 'Bond du Dopeul', 'Ce sort permet de sauter.', 0x08eb5a08ec5a08ed5a08ee5a08ef5a08f05a, '1', 'Teleport'),
(2104, 'Duel du Dopeul', '', 0x08f15a08f25a08f35a08f45a08f55a08f65a, '1', 'Debuff'),
