(2106, 'Couper du Dopeul', 'Le sort Couper permet de frapper un ennemi et de le ralentir en infligeant des dégâts de type Feu.', 0x08fd5a08fe5a08ff5a08805b08815b08825b, '1', 'Agressive'),
(2107, 'Puissance du Dopeul', 'La Puissance permet d\'augmenter (en pourcentage) les dégâts infligés par le lanceur ou un allié.', 0x08835b08845b08855b08865b08875b08885b, '1', 'Buff'),
(2108, 'Vitalité du Dopeul', 'Cet envoûtement permet d\'augmenter la vitalité de son lanceur.', 0x08895b088a5b088b5b088c5b088d5b088e5b, '1', 'Healing'),
(2109, 'Tempête de Puissance du Dopeul', 'La Tempête de Puissance inflige des dégâts de Feu.', 0x088f5b08905b08915b08925b08935b08945b, '1', 'Agressive'),
(2110, 'Colère de Iop du Dopeul', 'Inflige des dommages d\'élément terre et augmente les dommages du sort au quatrième tour après avoir été lancé.', 0x08955b08965b08975b08985b08995b089a5b, '1', 'Agressive'),
(2111, 'Epée de Iop du Dopeul', 'L\'Épée de Iop permet d\'infliger énormément de dégâts de Terre à plusieurs ennemis.', 0x089b5b089c5b089d5b089e5b089f5b08a05b, '1', 'Agressive'),
(2112, 'Flèche Magique du Dopeul', 'Ce sort inflige des dégâts de Feu à distance.', 0x08a15b08a25b08a35b08a45b08a55b08a65b, '1', 'Agressive'),
(2113, 'Tir Critique du Dopeul', 'Tir Critique permet de bénéficier d\'un bonus au coup critique.', 0x08a75b08a85b08a95b08aa5b08ab5b08ac5b, '1', 'Buff'),
(2114, 'Flèche Glacée du Dopeul', 'La Flèche Glacée blesse un ennemi et lui faire perdre des PA.', 0x08ad5b08ae5b08af5b08b05b08b15b08b25b, '1', 'Agressive'),
(2115, 'Tir Puissant du Dopeul', 'Le Tir Puissant multiplie par 2 les dégâts des autres sorts.', 0x08b35b08b45b08b55b08b65b08b75b08b85b, '1', 'Buff'),
(2116, 'Oeil de Taupe du Dopeul', 'Réduit la portée des personnages ciblés.', 0x08b95b08ba5b08bb5b08bc5b08bd5b08be5b, '1', 'Debuff'),
(2117, 'Flèche de Recul du Dopeul', 'La Flèche de Recul inflige des dégâts de type Air en faisant reculer l\'ennemi lors de l\'impact.', 0x08bf5b08c05b08c15b08c25b08c35b08c45b, '1', 'Agressive'),
(2118, 'Flèche d\'Immobilisation du Dopeul', 'La Flèche d\'Immobilisation est capable, en plus des dégâts qu\'elle inflige, d\'immobiliser un ennemi.', 0x08c55b08c65b08c75b08c85b08c95b08ca5b, '1', 'Agressive'),
(2119, 'Flèche Punitive du Dopeul', 'La Flèche Punitive est extrêmement dure à lancer, mais peut mettre un joueur KO sur un coup critique', 0x08cb5b08cc5b08cd5b08ce5b08cf5b08d05b, '1', 'Buff'),
(2120, 'Tir Eloigné du Dopeul', 'Le Tir Eloigné permet d\'augmenter la portée des sorts du lanceur.', 0x08d15b08d25b08d35b08d45b08d55b08d65b, '1', 'Buff'),
(2121, 'Flèche Destructrice du Dopeul', 'La Flèche Destructrice inflige des dégâts de Terre à un ennemi.', 0x08d75b08d85b08d95b08da5b08db5b08dc5b, '1', 'Agressive'),
(2122, 'Flèche Persécutrice du Dopeul', '', 0x08dd5b08de5b08df5b08e05b08e15b08e25b, '1', 'Agressive'),
(2123, 'Flèche Absorbante du Dopeul', 'La Flèche Absorbante permet de voler de la vie à un ennemi.', 0x08e35b08e45b08e55b08e65b08e75b08e85b, '1', 'Agressive'),
(2124, 'Flèche Explosive du Dopeul', 'La Flèche Explosive occasionne des dégâts à un ennemi et aux personnes qui l\'entourent.', 0x08e95b08ea5b08eb5b08ec5b08ed5b08ee5b, '1', 'Agressive'),
(2125, 'Maîtrise de l\'Arc du Dopeul', 'La Maîtrise de l\'Arc augmente les dégâts physiques.', 0x08ef5b08f05b08f15b08f25b08f35b08f45b, '1', 'Buff'),
(2126, 'Tremblement du Dopeul', 'Le Tremblement inflige des dégâts à tous les joueurs de la zone.', 0x08f55b08f65b08f75b08f85b08f95b08fa5b, '1', 'Agressive'),
(2127, 'La Folle du Dopeul', 'La Folle est une poupée créée avec des ossements de Chafer. Elle se fera un plaisir d\'énerver les ennemis du lanceur.', 0x08fb5b08fc5b08cbc20108ccc20108cdc20108cec201, '1', 'Agressive'),
(2128, 'Ronce du Dopeul', 'La Ronce inflige des dégâts physiques à un ennemi.', 0x08815c08825c08835c08845c08855c08865c, '1', 'Agressive'),
(2129, 'Herbe Folle du Dopeul', 'L\'Herbe Folle inflige des dégâts et fait perdre des points de mouvement.', 0x08875c08885c08895c088a5c088b5c088c5c, '1', 'Debuff'),
(2130, 'La Surpuissante du Dopeul', 'La Poupée Surpuissante peut invoquer de petites poupées fourbes qui réduisent le nombre de points de mouvement des ennemis et leurs résistances aux pertes de points de mouvement.', 0x088d5c08cfc20108d0c20108d1c20108d2c20108d3c201, '1', 'Agressive'),
(2131, 'Ronce Insolente du Dopeul', 'La Ronce Insolente s\'enfonce dans le sol pour ressortir et retirer tous les envoûtements d\'un joueur.', 0x08935c08945c08955c08965c08975c08985c, '1', 'Debuff'),
(2132, 'La Sacrifiée du Dopeul', 'Cette poupée se jette sur l\'ennemi en explosant.', 0x08995c089a5c08d4c20108d5c20108d6c20108d7c201, '1', 'Agressive'),
(2133, 'La Gonflable du Dopeul', 'La Poupée Gonflable augmente les points de mouvement et peut guérir un allié ou le  lanceur.', 0x089f5c08a05c088ea40108d8c20108d9c20108dac201, '1', 'Agressive'),
(2134, 'Ronces Multiples du Dopeul', 'La Ronce Multiple peut toucher plusieurs joueurs.', 0x08a55c08a65c08a75c08a85c08a95c08aa5c, '1', 'Agressive'),
(2135, 'Ronce Apaisante du Dopeul', 'La Ronce Apaisante permet de ralentir un ennemi mais lui rend des PDV.', 0x08ab5c08ac5c08ad5c08ae5c08af5c08b05c, '1', 'Debuff'),
(2136, 'La Bloqueuse du Dopeul', 'La Bloqueuse, comme son nom l\'indique, gêne les adversaires en se plaçant sur leur trajectoire.', 0x08b15c08b25c08b35c088fa40108dbc20108dcc201, '1', 'Agressive'),
(2137, 'Ronces Agressives du Dopeul', 'Les Ronces Agressives infligent d\'énormes dégâts, mais ne peuvent pas être utilisées à chaque tour.', 0x08b75c08b85c08b95c08ba5c08bb5c08bc5c, '1', 'Agressive'),
(2138, 'Larme du Dopeul', 'Ce sort permet d\'infliger des dégâts de type Eau.', 0x08bd5c08be5c08bf5c08c05c08c15c08c25c, '1', 'Agressive'),
(2139, 'Vent Empoisonné du Dopeul', 'Le Vent Empoisonné empoisonne tous les joueurs présents dans la zone, amis comme ennemis, et leur retire de l\'intelligence pendant plusieurs tours.', 0x08c35c08c45c08c55c08c65c08c75c08c85c, '1', 'Agressive'),
(2140, 'Puissance Sylvestre du Dopeul', 'Ce sort permet au lanceur de se transformer en arbre afin d\'être protégé quelques tours.', 0x08c95c08ca5c08cb5c08cc5c08cd5c08ce5c, '1', 'Debuff'),
(2141, 'Sacrifice Poupesque du Dopeul', 'Ce sort permet de regagner de la vie en punissant une invocation.', 0x08cf5c08d05c08d15c08d25c08d35c08d45c, '1', 'Agressive'),
(2142, 'Connaissance des Poupées du Dopeul', 'La Connaissance des Poupées permet d\'invoquer plusieurs poupées.', 0x08d55c08d65c08d75c08d85c08d95c08da5c, '1', 'Buff'),
(2143, 'Poison Paralysant du Dopeul', 'Le Poison Paralysant inflige des dégâts de Feu lorsque des PA sont utilisés.', 0x08db5c08dc5c08dd5c08de5c08df5c08e05c, '1', 'Agressive'),
(2144, 'Châtiment Forcé du Dopeul', 'Augmente la force du Sacrieur lorsqu\'il perd des points de vie.', 0x08e15c08e25c08e35c08e45c08e55c08e65c, '1', 'Buff'),
(2145, 'Pied du Sacrieur du Dopeul', 'Ce sort d\'attaque au corps à corps inflige des dégâts de type Terre.', 0x08e75c08e85c08e95c08ea5c08eb5c08ec5c, '1', 'Agressive'),
(2146, 'Châtiment Osé du Dopeul', 'Augmente la chance du Sacrieur lorsqu\'il perd des points de vie.', 0x08ed5c08ee5c08ef5c08f05c08f15c08f25c, '1', 'Buff'),
(2147, 'Attirance du Dopeul', 'Attire une cible vers le Sacrieur.', 0x08f35c08f45c08f55c08f65c08f75c08f85c, '1', 'Agressive'),
(2148, 'Assaut du Dopeul', 'Assaut permet de frapper un ennemi à distance et de lui infliger des dégâts de type Air.', 0x08f95c08fa5c08fb5c08fc5c08fd5c08fe5c, '1', 'Agressive'),
(2149, 'Châtiment Agile du Dopeul', 'Augmente l\'agilité du Sacrieur lorsqu\'il perd des points de vie.', 0x08ff5c08805d08815d08825d08835d08845d, '1', 'Buff'),
(2150, 'Dissolution du Dopeul', 'Vole des points de vie dans l\'élément Eau autour du Sacrieur.', 0x08855d08865d08875d08885d08895d088a5d, '1', 'Agressive'),
(2151, 'Absorption du Dopeul', 'Ce sort permet à son lanceur de voler la vie d\'un ennemi en infligeant des dégâts de Feu.', 0x088b5d088c5d088d5d088e5d088f5d08905d, '1', 'Agressive'),
(2152, 'Châtiment Spirituel du Dopeul', 'Augmente l\'intelligence du Sacrieur lorsqu\'il perd des points de vie.', 0x08915d08925d08935d08945d08955d08965d, '1', 'Buff'),
(2153, 'Punition du Dopeul', 'Occasionne des dommages neutres. Plus la vie du Sacrieur est proche de la moitié du total de ses points de vie, plus les dommages occasionnés sont importants.', 0x08975d08985d08995d089a5d089b5d089c5d, '1', 'Agressive'),
(2154, 'Furie du Dopeul', 'Ce sort permet au lanceur d\'augmenter ses dommages.', 0x089d5d089e5d089f5d08a05d08a15d08a25d, '1', 'Agressive'),
(2155, 'Schnaps du Dopeul', 'Ce sort permet de baisser les resistances \"Feu\" d\'un ennemi.', 0x08a35d08a45d08a55d08a65d08a75d08a85d, '1', 'Agressive'),
(2156, 'Epouvante du Dopeul', 'Repousse et réduit les coups critiques de la cible.', 0x08a95d08aa5d08ab5d08ac5d08ad5d08ae5d, '1', 'Debuff'),
(2157, 'Vulnérabilité du Dopeul', '', 0x08af5d08b05d08b15d08b25d08b35d08b45d, '1', 'Buff'),
(2158, 'Ethylo du Dopeul', '', 0x08b55d08b65d08b75d08b85d08b95d08ba5d, '1', 'Agressive'),
(2159, 'Vague à Lame du Dopeul', 'Ce sort permet d\'infliger des dégâts d\'Eau.', 0x08bb5d08bc5d08bd5d08be5d08bf5d08c05d, '1', 'Agressive'),
(2160, 'Flasque Explosive du Dopeul', 'Ce sort permet de lancer une bouteille d\'alcool qui explose en touchant le sol, infligeant des dégâts de Feu à tous les joueurs se trouvant dans la zone d\'effet.', 0x08c15d08c25d08c35d08c45d08c55d08c65d, '1', 'Agressive'),
(2161, 'Pandatak du Dopeul', 'Ce sort permet de solliciter des Pandawas (infligeant des dégâts de type Terre) de la famille du lanceur afin qu\'ils l\'aident contre ses ennemis.', 0x08c75d08c85d08c95d08ca5d08cb5d08cc5d, '1', 'Agressive'),
(2162, 'Poing Enflammé du Dopeul', 'Le Poing Enflammé inflige des dégâts de Feu. L\'état d\'ébriété est nécessaire pour lancer ce sort.', 0x08cd5d08ce5d08cf5d08d05d08d15d08d25d, '1', 'Agressive'),
(2163, 'Souffle Alcoolisé du Dopeul', 'Ce sort permet d\'infliger des dégâts de type Air. L\'état d\'ébriété est nécessaire pour lancer ce sort.', 0x08d35d08d45d08d55d08d65d08d75d08d85d, '1', 'Agressive'),
(2164, 'Gueule de Bois du Dopeul', 'La Gueule de Bois permet de mettre un coup de tête à un ennemi, lui infligeant des dégâts de type Terre. L\'état d\'ébriété est nécessaire pour lancer ce sort.', 0x08d95d08da5d08db5d08dc5d08dd5d08de5d, '1', 'Agressive'),
(2165, 'Souillure du Dopeul', 'Ce sort lance un effet aléatoire afin de déconcentrer l\'ennemi. L\'état d\'ébriété est nécessaire pour lancer ce sort.', 0x08df5d08e05d08e15d08e25d08e35d08e45d, '1', 'Debuff'),
(2166, 'Pandanlku du Dopeul', 'Ce sort permet au lanceur d\'augmenter ses PM ou ceux d\'un allié. Ce sort nécessite l\'état d\'ébriété pour être lancé.', 0x08e55d08e65d08e75d08e85d08e95d08ea5d, '1', 'Buff'),
(2167, 'Lien Spiritueux du Dopeul', 'Ce sort permet d\'invoquer un vieux maître Pandawa. L\'état d\'ébriété est nécessaire pour lancer ce sort.', 0x08eb5d08ec5d, '1', 'Summon'),
(2168, 'Destin d\'Ecaflip du Dopeul', '[@ref : utilisé par le dopeul de temple Eca; sort de ref : 120]', 0x08f15d08f25d08f35d08f45d08f55d08f65d, '1', 'Agressive'),
(2169, 'Griffe de Ceangal du Dopeul', '[@ref : utilisé par le dopeul de temple Eca; sort de ref : 112]', 0x08f75d08f85d08f95d08fa5d08fb5d08fc5d, '1', 'Debuff'),
(2170, 'Peur du Dopeul', 'Pousse un allié ou un ennemi sur la case ciblée.', 0x08fd5d08fe5d08ff5d08805e08815e08825e, '1', 'Agressive'),
(2171, 'Flagelle', '', 0x08855e08865e08875e08885e08895e088a5e, '1', 'Agressive'),
(2172, 'Pain bourpif', '', 0x088c5e088d5e088e5e088f5e08905e08915e, '1', 'Agressive'),
(2173, 'Motivation Gluante', '', 0x08985e08eaa30108eba30108eca301, '1', 'Debuff'),
(2174, 'Koque Chok', '', 0x089d5e089e5e089f5e08a05e08a15e, '1', 'Agressive'),
(2186, 'Amour corrompu', '[NO_TRAD]', 0x08d15f08d25f08d35f08d45f08d55f08d65f, '1', 'Agressive'),
(2187, 'Pater Familias', '', 0x08dd5f08de5f08df5f08e05f08e15f08e25f, '1', 'Debuff'),
(2188, 'Coup de Poing Enflammé', 'Le Poing Enflammé inflige des dégâts de Feu. L\'état d\'ébriété est nécessaire pour lancer ce sort.', 0x08e35f08e45f08e55f08e65f08e75f08e85f, '1', 'Agressive'),
(2190, 'Vulnérabilité Incandescente', 'Ce sort permet de baisser les resistances \"Feu\" d\'un ennemi.', 0x08ef5f08f05f08f15f08f25f08f35f08f45f, '1', 'Debuff'),
(2191, 'Goulaf\'', 'Permet de dévorer un ennemi pour se régénérer, mais rend le lanceur vulnérable.', 0x08f55f08f65f, '1', 'Agressive'),
(2192, 'Avoir maux à ches dints', '', 0x08fb5f08fc5f08fd5f08fe5f08ff5f088060, '1', 'Teleport'),
(2193, 'Che tout fraîque', 'Empêche le joueur de se téléporter.', 0x088160088260, '1', 'Agressive'),
(2194, 'Ch\'est du lèque mes louppes', 'Diminue les dommages de la cible et augmente ceux du lanceur.', 0x088760088860, '1', 'Debuff'),
(2195, 'Ti t\'as bou', 'Diminue les PA et PM de la cible, et augmente les dommages du lanceur.', 0x088d60088e60, '1', 'Agressive'),
(2196, 'Qu\'i est mieffe c\'ti-là', 'Fait perdre des PM à la cible.', 0x089360089460089560089660089760089860, '1', 'Teleport'),
