(2850, 'Extraction du Dopeul', 'Vol de vie Feu en ligne.', 0x08a5910108a6910108a7910108a8910108a9910108aa9101, '1', 'Agressive'),
(2851, 'Explobombe du Dopeul', 'Pose une bombe qui occasionne des dommages Feu. Explose automatiquement en occasionnant des dommages plus faibles si elle est lancée directement sur une cible.', 0x08ab910108ac910108ad910108ae910108af910108b09101, '1', 'Summon'),
(2852, 'Détonateur du Dopeul', 'Déclenche l\'explosion d\'une bombe à distance.', 0x08b1910108b2910108b3910108b4910108b5910108b69101, '1', 'None'),
(2853, 'Tornabombe du Dopeul', 'Pose une bombe qui occasionne des dommages Air et retire des PM. Explose automatiquement en occasionnant des dommages plus faibles si elle est lancée directement sur une cible.', 0x08b7910108b8910108b9910108ba910108bb910108bc9101, '1', 'Summon'),
(2854, 'Dagues Boomerang du Dopeul', 'Occasionne des dommages Air en arc de cercle.', 0x08bd910108be910108bf910108c0910108c1910108c29101, '1', 'Agressive'),
(2855, 'Bombe à Eau du Dopeul', 'Pose une bombe qui occasionne des dommages Eau et retire des PA. Explose automatiquement en occasionnant des dommages plus faibles si elle est lancée directement sur une cible.', 0x08c3910108c4910108c5910108c6910108c7910108c89101, '1', 'Summon'),
(2856, 'Rémission du Dopeul', 'Repousse les alliés ou ennemis qui attaquent la cible depuis une case adjacente.', 0x08c9910108ca910108cb910108cc910108cd910108ce9101, '1', 'Agressive');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(2857, 'Botte du Dopeul', 'Repousse une bombe et augmente ses dommages. Repousse un allié ou un ennemi d\'une case.', 0x08cf910108d0910108d1910108d2910108d3910108d49101, '1', 'Agressive'),
(2858, 'Roublardise du Dopeul', 'Crée plusieurs images du Roublard pour tromper les adversaires, et lui permet de se téléporter. Les images disparaissent si elles reçoivent des dommages. Le sort passe le tour en cours du Roublard.', 0x08d5910108d6910108d7910108d8910108d9910108da9101, '1', 'Debuff'),
(2859, 'Resquille du Dopeul', 'Occasionne des dommages Eau en anneau autour du Roublard et retire 1 PA.', 0x08db910108dc910108dd910108de910108df910108e09101, '1', 'Agressive'),
(2860, 'Pulsar du Dopeul', 'Occasionne des dommages Feu et utilise tous les PM disponibles. Plus le pourcentage de PM utilisé par le sort est important, plus les dommages occasionnés par le sort sont importants.', 0x08e1910108e2910108e3910108e4910108e5910108e69101, '1', 'Agressive'),
(2861, 'Espingole du Dopeul', 'Occasionne des dommages Air en diagonale avec une zone d\'effet en ligne perpendiculaire.', 0x08e7910108e8910108e9910108ea910108eb910108ec9101, '1', 'Agressive'),
(2862, 'Tromblon du Dopeul', 'Occasionne des dommages Eau en cône et applique un malus de vie insoignable.', 0x08ed910108ee910108ef910108f0910108f1910108f29101, '1', 'Debuff'),
(2864, 'Feu de Brousse du Dopeul', 'Ce sort permet d\'infliger des dégâts de type Feu et Eau.', 0x08fd910108fe910108ff9101088092010881920108829201, '1', 'Agressive'),
(2901, 'Lasme', 'Permet de réduire les dommages reçus et permet de ne plus être ni repoussé ni taclé, mais empêche de tacler ses adversaires. Réservé aux invocations.', 0x088093010881930108829301088393010884930108859301, '1', 'Buff'),
(2903, 'Martelo du Dopeul', 'Vole de vie dans l\'élément Terre et applique un malus de Fuite sur la cible.', 0x08eb930108ec930108ed930108ee930108ef930108f09301, '1', 'Agressive'),
(2904, 'Appui du Dopeul', 'Occasionne des dommages dans 3 éléments sur ennemi et permet de s\'éloigner de sa cible.', 0x08f1930108f2930108f3930108f4930108f5930108f69301, '1', 'Agressive'),
(2905, 'Masque du Pleutre du Dopeul', 'Applique le Masque du Pleutre, interdit l\'utilisation des armes et augmente la Fuite du lanceur et des alliés.', 0x08f7930108f8930108f9930108fa930108fb930108fc9301, '1', 'Buff'),
(2906, 'Picada du Dopeul', 'Occasionne des dommages Air et applique un malus de Tacle à la cible.', 0x08fd930108fe930108ff9301088094010881940108829401, '1', 'Agressive'),
(2907, 'Reuche du Dopeul', 'Rapproche le lanceur de la cible.', 0x088394010884940108859401088694010887940108889401, '1', 'Agressive'),
(2908, 'Tortoruga du Dopeul', 'Applique un bouclier sur la cible.', 0x08899401088a9401088b9401088c9401088d9401088e9401, '1', 'Buff'),
(2909, 'Masque de Classe du Dopeul', 'Applique le Masque de Classe et augmente le Tacle du lanceur et des alliés en zone.', 0x088f94010890940108919401089294010893940108949401, '1', 'Buff'),
(2910, 'Rétention du Dopeul', 'Vole de la vie dans l\'élément Air et retire des PM à la cible.', 0x0895940108969401089794010898940108999401089a9401, '1', 'Agressive'),
(2911, 'Masque du Psychopathe du Dopeul', 'Applique le Masque du Psychopathe et augmente les dommages du lanceur et des alliés.', 0x089b9401089c9401089d9401089e9401089f940108a09401, '1', 'Buff'),
(2912, 'Furia du Dopeul', 'Rapproche le lanceur de la cible, occasionne des dommages Terre sur ennemis et augmente les dommages fixes du lanceur pendant le tour en cours.', 0x08a1940108a2940108a3940108a4940108a5940108a69401, '1', 'Agressive'),
(2913, 'Distance du Dopeul', 'Occasionne des dommages Eau sur ennemi et repousse la cible en ligne.', 0x08a7940108a8940108a9940108aa940108ab940108ac9401, '1', 'Agressive'),
(2914, 'Plastron du Dopeul', 'Applique un bouclier en zone sur le lanceur et les alliés.', 0x08ad940108ae940108af940108b0940108b1940108b29401, '1', 'Buff'),
(2915, 'Fougue du Dopeul', 'Rend la cible insensible au Tacle et augmente ses dommages, mais la rend insoignable.', 0x08b3940108b4940108b5940108b6940108b7940108b89401, '1', 'Buff'),
(2916, 'Débandade du Dopeul', 'Téléporte à courte portée et augmente les PM.', 0x08b9940108ba940108bb940108bc940108bd940108be9401, '1', 'Teleport'),
(2917, 'Cabriole du Dopeul', 'Téléporte sur la case ciblée, occasionne des dommages Air en croix et augmente les dommages du lanceur pour le tour en cours.', 0x08bf940108c0940108c1940108c2940108c3940108c49401, '1', 'Teleport'),
(2918, 'Appeau du Dopeul', 'Vole de la vie dans l\'élément Eau sur ennemis et attire la cible en ligne.', 0x08c5940108c6940108c7940108c8940108c9940108ca9401, '1', 'Agressive'),
(2919, 'Transe du Dopeul', 'Applique un bouclier sur une cible alliée mais diminue temporairement ses PV.', 0x08cb940108cc940108cd940108ce940108cf940108d09401, '1', 'Debuff'),
(2920, 'Apathie du Dopeul', 'Occasionne des dommages Terre et retire des PM à la cible.', 0x08d1940108d2940108d3940108d4940108d5940108d69401, '1', 'Agressive'),
(2921, 'Boliche du Dopeul', 'Augmente les dommages de poussée pour le tour en cours, rapproche le lanceur de sa cible, occasionne des dommages Eau sur ennemis et repousse la cible.', 0x08d7940108d8940108d9940108da940108db940108dc9401, '1', 'Agressive'),
(2922, 'Mascarade du Dopeul', 'Réduit temporairement la vie de tous les alliés et ennemis.', 0x08dd940108de940108df940108e0940108e1940108e29401, '1', 'Debuff'),
(2924, 'Sort d\'Affermage', 'Repousse d\'une case les ennemis au contact du lanceur.', 0x08e4940108e5940108e6940108e7940108e8940108e99401, '1', 'Agressive'),
