(3279, 'Invocation Royale de Tofu', 'Ce sort permet d\'invoquer un Tofu qui partira au combat pour vous.', 0x088f9d0108909d0108919d0108929d0108939d01, '1', 'Summon'),
(3283, 'Coud\'marto', '', 0x08ac9d0108ad9d0108ae9d0108af9d0108b09d01, '1', 'Agressive'),
(3284, 'Flibuste du Dopeul', 'Vole des PV dans l\'élément Feu en diagonale.\nActive l\'élément Feu sur la Harponneuse.', 0x08b19d0108b29d0108b39d0108b49d0108b59d0108b69d01, '1', 'Agressive'),
(3285, 'Ancrage du Dopeul', 'Occasionne des dommages Terre.\nActive l\'élément Terre sur la Harponneuse.', 0x08b79d0108b89d0108b99d0108ba9d0108bb9d0108bc9d01, '1', 'Agressive'),
(3286, 'Courant du Dopeul', 'Occasionne des dommages Eau et attire la cible en diagonale.\nActive l\'état Magnétor sur la Tactirelle.', 0x08bd9d0108be9d0108bf9d0108c09d0108c19d0108c29d01, '1', 'Agressive'),
(3287, 'Armure de Sel du Dopeul', 'Protège les tourelles et les alliés des attaques à distance.\nLes protections sont plus faibles sur les alliés.', 0x08c39d0108c49d0108c59d0108c69d0108c79d0108c89d01, '1', 'None'),
(3288, 'Scaphandre du Dopeul', 'Les retraits de PA reçus augmentent les PM.\nAugmente les dommages et les dommages de poussée des cibles.', 0x08c99d0108ca9d0108cb9d0108cc9d0108cd9d0108ce9d01, '1', 'Buff'),
(3289, 'Ressac du Dopeul', 'Repousse la cible en diagonale, occasionne des dommages Terre et active le mode \"Poussée\" sur la Tactirelle.', 0x08cf9d0108d09d0108d19d0108d29d0108d39d0108d49d01, '1', 'Agressive'),
(3290, 'Marée du Dopeul', 'Echange de position avec la cible en diagonale.', 0x08d59d0108d69d0108d79d0108d89d0108d99d0108da9d01, '1', 'Agressive'),
(3291, 'Vapor du Dopeul', 'Occasionne des dommages Feu en zone.\nActive le mode \"Feu\" sur la Harponneuse.', 0x08db9d0108dc9d0108dd9d0108de9d0108df9d0108e09d01, '1', 'Agressive'),
(3292, 'Longue Vue du Dopeul', 'Occasionne des dommages Eau sur les ennemis.\nActive le mode \"Eau\" sur la Harponneuse.\nApplique un état sur la cible pour qu\'elle puisse être ciblée par le sort spécial de la Tactirelle.', 0x08e19d0108e29d0108e39d0108e49d0108e59d0108e69d01, '1', 'Agressive'),
(3293, 'Secourisme du Dopeul', 'Soigne la cible.\nApplique un état sur la cible pour qu\'elle puisse être ciblée par le sort spécial de la tourelle défensive.', 0x08e79d0108e89d0108e99d0108ea9d0108eb9d0108ec9d01, '1', 'Healing'),
(3294, 'Selpâtre du Dopeul', 'Occasionne des dommages Feu.\nActive l\'état \"Feu\" sur la Harponneuse.\nApplique un malus de dommages à la cible sur réception de dommages Feu.', 0x08ed9d0108ee9d0108ef9d0108f09d0108f19d0108f29d01, '1', 'Agressive'),
(3295, 'Embuscade du Dopeul', 'Occasionne des dommages Feu, Eau et Terre.\nApplique un état sur la cible pour qu\'elle puisse être ciblée par le sort spécial de la Harponneuse.', 0x08f39d0108f49d0108f59d0108f69d0108f79d0108f89d01, '1', 'Agressive'),
(3296, 'Ecume du Dopeul', 'Occasionne des dommages Eau en zone.\nActive le mode \"Eau\" sur la Harponneuse.', 0x08f99d0108fa9d0108fb9d0108fc9d0108fd9d0108fe9d01, '1', 'Agressive'),
(3297, 'Foène du Dopeul', 'Occasionne des dommages Terre.\nOccasionne des dommages Terre supplémentaires sur réception de dommages Terre.\nActive le mode \"Terre\" sur la Harponneuse.', 0x08ff9d0108809e0108819e0108829e0108839e0108849e01, '1', 'Agressive'),
