(4199, 'Sang de Firefoux', '', 0x08cba901, '0', 'Healing'),
(4200, 'Sang de Firefoux', 'À chaque fin de tour du lanceur, soigne les alliés en zone autour de lui.\nLes soins sont doublés sur les Multiman.', 0x08cca901, '1', 'Agressive'),
(4201, 'Kazam', '', 0x08cda90108ebf70308ecf70308c9fc03, '0', 'None'),
(4202, 'Kazam', 'Occasionne des dommages Neutre en zone.\nAu début du tour d\'une cible, occasionne des dommages Neutre aux ennemis et soigne les alliés à son contact.\n\nN\'affecte pas le lanceur.', 0x08cea90108eff70308f0f703, '1', 'Agressive'),
(4203, 'Tambourino', '', 0x08cfa901, '0', 'Healing'),
(4204, 'Tambourino', 'Occasionne des dommages Neutre.\nSoigne également les alliés dans un cercle de 2 cases autour du lanceur.', 0x08d0a90108f1f70308f2f703, '1', 'Agressive'),
(4205, 'Illumination', '', 0x08d1a90108f5f70308f6f70308c8fc03, '0', 'None'),
(4207, 'Illumination', 'Repousse les cibles en zone.\nSoigne les alliés dans une croix de 2 cases autour de chacune des cibles si elles subissent des dommages de poussée.', 0x08d2a90108f3f70308f4f703, '1', 'Agressive'),
(4208, 'Cicatrice', 'Soigne les alliés en zone.', 0x08d3a90108e3f70308e4f703, '1', 'Healing'),
(4209, 'Écran', 'Réduit les dommages reçus à distance par les alliés en zone.', 0x08d4a90108e5f70308e6f703, '1', 'None'),
(4210, 'Divergence', 'Occasionne des dommages Neutre aux ennemis ou soigne les alliés.\nLes effets sont plus importants sur les cibles ayant moins de 50% de leurs points de vie, et le sont d\'autant plus sur celles ayant moins de 20% de leurs points de vie.', 0x08d5a90108e7f70308e8f703, '1', 'Agressive'),
(4211, 'Sang de Scarafeuille', '', 0x08d6a901, '0', 'Buff'),
(4212, 'Sang de Scarafeuille', 'À chaque fin de tour du lanceur, augmente la Fuite des alliés en zone autour de lui.\nAugmente également la Portée des Multiman dans la zone d\'effet.', 0x08d7a901, '1', 'Agressive'),
(4213, 'Calcin', '', 0x08d8a9010887f8030888f80308dffa03, '0', 'None'),
(4214, 'Calcin', 'Occasionne des dommages Feu aux ennemis en zone. \nLes dommages sont plus importants sur les ennemis dans l\'état Scorifié.\n\nAu prochain tour du lanceur, occasionne des dommages Feu aux ennemis dans un cercle de 2 cases autour de chacune des cibles.', 0x08d9a9010889f803088af803, '1', 'Agressive'),
(4215, 'Scorification', '', 0x08daa901088ff8030890f80308c5fc03, '0', 'None'),
(4216, 'Scorification', 'Pose un piège qui applique un poison Feu de début de tour sur les ennemis et l\'état Scorifié sur les entités en zone.', 0x08dba9010891f8030892f803, '1', 'Mark'),
(4217, 'Reculade', 'Éloigne le lanceur de la cible et occasionne des dommages Feu aux ennemis.\nLes dommages sont plus importants sur les ennemis dans l\'état Scorifié.', 0x08dca9010893f8030894f803, '1', 'Agressive'),
(4218, 'Charbo', 'Vole de la Portée et occasionne des dommages Feu.\nLes dommages sont plus importants sur les cibles dans l\'état Scorifié.', 0x08dda901088df803088ef803, '1', 'Agressive'),
(4219, 'Scaraflamme', 'Repousse la cible, occasionne des dommages Feu aux ennemis et leur retire des PM.\nLa poussée est plus importante sur les cibles dans l\'état Scorifié.', 0x08dea901088bf803088cf803, '1', 'Agressive'),
(4220, 'Cuticule Répulsive', '', 0x08dfa9010883f8030884f80308c4fc03, '0', 'None'),
(4221, 'Cuticule Répulsive', 'Pendant 2 tours, si la cible subit des dommages en mêlée, repousse son attaquant.\nLui retire également des PM si l\'attaquant est un ennemi.\n\nLa poussée est plus importante sur les attaquants dans l\'état Scorifié.', 0x08e0a9010885f8030886f803, '1', 'Agressive'),
(4222, 'Sang de Kralamoure', '', 0x08e1a901, '0', 'Buff'),
(4223, 'Sang de Kralamoure', 'À chaque fin de tour du lanceur, augmente les Retraits PA et PM des alliés en zone autour de lui.\nAugmente également les PA des Multiman dans la zone d\'effet.', 0x08e2a901, '1', 'Agressive'),
(4224, 'Samourashi', '', 0x08e3a90108defa03, '0', 'None'),
(4225, 'Samourashi', 'Augmente les PA de l\'allié ciblé.\nAugmente les PA des entités dans un cercle de 2 cases autour de cet allié au tour suivant.', 0x08e4a90108f7f70308f8f703, '1', 'Buff'),
(4226, 'Bétane', 'Occasionne des dommages Eau aux ennemis et réduit la durée des effets sur la cible.', 0x08e5a9010881f8030882f803, '1', 'Agressive'),
(4227, 'Alevin', 'Rend l\'allié ciblé Intaclable et augmente sa Puissance et ses PM.', 0x08e6a90108f9f70308faf703, '1', 'Buff'),
(4228, 'Scission', 'Partage les dommages entre les alliés en zone.\nN\'affecte pas les invocations.', 0x08e7a90108fbf70308fcf703, '1', 'Buff'),
(4229, 'Coup de Filet', 'Occasionne des dommages Eau et retire des Esquives PA et PM.', 0x08e8a90108fff7030880f803, '1', 'Buff'),
(4230, 'Nasse', 'Occasionne des dommages Eau et retire du Tacle.', 0x08e9a90108fdf70308fef703, '1', 'Agressive'),
(4231, 'Sang Ténébreux', '', 0x08eaa901, '0', 'Buff'),
(4232, 'Sang Ténébreux', 'À chaque fin de tour du lanceur, augmente la Puissance des alliés en zone autour de lui.\nLa Puissance est doublée sur les Multiman.', 0x08eba901, '1', 'Agressive'),
(4233, 'Cartilage', 'Téléporte le lanceur sur la première case disponible entre la cible et lui et occasionne des dommages Neutre aux ennemis en zone.', 0x08eca901088ff9030890f903, '1', 'Teleport'),
(4234, 'Diabolo Chiste', 'Érode la cible et occasionne des dommages Neutre.\nLes dommages du sort sont augmentés au tour suivant.', 0x08eda9010891f9030892f903, '1', 'Debuff'),
(4235, 'Ombroglio', 'Vole de la Puissance et occasionne des dommages Neutre en zone.\nN\'affecte pas le lanceur.', 0x08eea9010893f9030894f903, '1', 'Agressive'),
(4236, 'Colère Noire', 'Rend le lanceur Insoignable pour augmenter sa Puissance.\nPendant 1 tour, s\'il reçoit des dommages, sacrifie ses résistances pour augmenter les dommages du sort Vengeance Nocturne.', 0x08efa90108effb0308f0fb03, '1', 'Buff'),
(4237, 'Vengeance Nocturne', 'Occasionne des dommages Neutre aux ennemis en zone autour du lanceur.', 0x08f0a901088bf903088cf903, '1', 'Agressive'),
(4238, 'Agonie Crépusculaire', 'Occasionne des dommages Neutre et vole des PM.', 0x08f1a901088df903088ef903, '1', 'Agressive'),
(4239, 'Sang de Corbac', '', 0x08f2a901, '0', 'Buff'),
(4240, 'Sang de Corbac', 'À chaque fin de tour du lanceur, augmente les Dommages Poussée des alliés en zone autour de lui.\nAugmente également les PM des Multiman dans la zone d\'effet.', 0x08f3a901, '1', 'Agressive'),
(4241, 'Becquetage', 'Téléporte le lanceur sur la case ciblée, occasionne des dommages Air aux ennemis et repousse les cibles en zone.\nLa poussée n\'affecte pas le lanceur.', 0x08f4a9010899f803089af803, '1', 'Agressive'),
(4242, 'Envolée', 'Augmente les PM, la Fuite et les Dommages Poussée des alliés en zone.', 0x08f5a901089df803089ef803, '1', 'Buff'),
(4243, 'Nimbostratus', '', 0x08f6a901089ff80308a0f803, '0', 'Agressive'),
(4244, 'Nimbostratus', 'Pose un piège mono-cellule qui attire les cibles, occasionne des dommages Air aux ennemis et leur retire des PM dans une croix de 3 cases.', 0x08f7a90108a1f80308a2f803, '1', 'Mark'),
(4245, 'Bec Aiguisé', 'Vole de la Fuite et occasionne des dommages Air.', 0x08f8a9010895f8030896f803, '1', 'Debuff'),
(4246, 'Explumession', 'Augmente les Dommages Poussée du lanceur et repousse la cible.', 0x08f9a901089bf803089cf803, '1', 'Buff'),
(4247, 'Souitche', 'Échange de position avec la cible et occasionne des dommages Air aux ennemis.', 0x08faa9010897f8030898f803, '1', 'Agressive'),
(4248, 'Sang d\'Abraknyde', '', 0x08fba901, '0', 'Buff'),
(4249, 'Sang d\'Abraknyde', 'À chaque fin de tour du lanceur, augmente les résistances des alliés en zone autour de lui.\nLes résistances sont doublées sur les Multiman.', 0x08fca901, '1', 'Agressive'),
(4250, 'Attraction Sylvestre', 'Applique l\'état Indéplaçable sur le lanceur, augmente ses résistances et attire les ennemis en zone.', 0x08fda90108ddf70308def703, '1', 'Buff'),
(4251, 'Écorce Protectrice', '', 0x08fea901, '0', 'Healing'),
(4252, 'Écorce Protectrice', 'Le lanceur subit les dommages à la place de l\'allié ciblé et lui applique l\'état Protégé :\n• Soigne la cible si le lanceur subit des dommages.', 0x08ffa90108dff70308e0f703, '1', 'Healing'),
(4253, 'Pirouette', 'Téléporte le lanceur sur la case ciblée et occasionne des dommages Terre aux ennemis en zone.', 0x0880aa0108d5f70308d6f703, '1', 'Teleport'),
(4254, 'Bûchette', 'Vole de la vie dans l\'élément Terre en zone.', 0x0881aa0108d7f70308d8f703, '1', 'Agressive'),
(4255, 'Marbus Fractus', 'Occasionne des dommages Terre et retire de la Puissance et de la Fuite.', 0x0882aa0108d9f70308daf703, '1', 'Debuff'),
(4256, 'Déflorage', 'Échange de position avec la cible et occasionne des dommages Terre aux ennemis.', 0x0883aa0108dbf70308dcf703, '1', 'Agressive'),
