(4411, 'Faille Dimensionnelle', '', 0x08f2ac0108b3f90308b4f903, '0', 'Agressive'),
(4412, 'Faille Dimensionnelle', 'Téléporte le lanceur sur la case ciblée et occasionne des dommages Air aux ennemis en zone. \nÀ la fin de son tour, pose un glyphe de fin de tour qui occasionne des dommages Air aux ennemis et téléporte à la position de début de tour.\nAugmente les PM des alliés qui ont échangé de position suite à la téléportation.\n\nEmpêche l\'utilisation du sort Feinte pour le tour en cours.', 0x08f3ac0108aff90308b0f903, '1', 'Agressive'),
(4413, 'Gravité Renforcée', 'Applique l\'état Pesanteur sur les cibles, vole de la vie dans l\'élément Eau et retire des PM aux ennemis en zone autour du lanceur.', 0x08f4ac0108c7f90308c8f903, '1', 'Agressive'),
(4414, 'Brûlure', 'Retire des PA et vole de la vie dans l\'élément Feu aux ennemis en zone.', 0x08f5ac0108b8f90308b9f903, '1', 'Debuff'),
(4415, 'Déviation', '', 0x08f6ac0108c3f90308c4f903, '0', 'Healing'),
(4416, 'Déviation', 'Sur un allié : l\'allié ciblé subit les dommages à la place du lanceur, le rend Intaclable et lui augmente sa Puissance.', 0x08f7ac0108c5f90308c6f903, '1', 'Agressive'),
(4417, 'Feinte', 'Téléporte le lanceur symétriquement par rapport à la cible et vole de la vie dans l\'élément Air aux ennemis. \nS\'il échange de position avec un allié, augmente les PA du lanceur et de cet allié.\n\nÀ la fin du tour du lanceur, le téléporte à sa position de début de tour.\nS\'il échange de position avec un allié, augmente les PM du lanceur et de cet allié.\n\nEmpêche l\'utilisation du sort Faille Dimensionnelle pour le tour en cours.', 0x08f8ac0108b5f90308b6f903, '1', 'Agressive'),
(4418, 'Instabilité', '', 0x08f9ac0108baf90308bbf90308c7fc03, '0', 'None'),
(4419, 'Instabilité', 'Repousse les cibles et occasionne des dommages Terre aux ennemis en zone.\nPendant 2 tours, si le lanceur subit des dommages en mêlée, vole de la vie dans l\'élément Terre à son attaquant.', 0x08faac0108c1f90308c2f903, '1', 'Agressive'),
(4420, 'Faille Dimensionnelle', '', 0x08fbac01, '0', 'None'),
