(4443, 'Glyphe Revigorant', 'Pose un glyphe de fin de tour qui soigne les alliés.', 0x08a7ad01089ff90308a0f903, '1', 'Mark'),
(4445, 'Vaudouche', 'Soigne les alliés dans une croix de 2 cases autour de la cible et occasionne des dommages Eau.', 0x08a9ad0108a3f90308a4f903, '1', 'Healing'),
(4446, 'Attraction Bienfaitrice', '', 0x08aaad0108a7f90308a8f903, '0', 'Buff'),
(4447, 'Attraction Bienfaitrice', 'Attire et soigne les alliés en zone autour du lanceur.\nPendant 1 tour, si le lanceur subit des dommages, augmente la Puissance des alliés dans un cercle de 2 cases autour de lui.', 0x08abad0108a5f90308a6f903, '1', 'Agressive'),
(4448, 'Éthernuement', '', 0x08acad0108a9f90308aaf90308c0fc03, '0', 'None'),
(4449, 'Éthernuement', 'Repousse la cible et éloigne le lanceur d\'elle.\nPendant 1 tour, si le lanceur ou la cible subissent des dommages, soigne les alliés à leur contact.', 0x08adad0108abf90308acf903, '1', 'Agressive'),
(4450, 'Intoxication', '', 0x08aead01089bf903089cf90308befc0308bffc03, '0', 'Agressive');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(4451, 'Intoxication', 'Applique un poison Terre de début de tour sur la cible.\nPendant 2 tours, si la cible subit des dommages, soigne les alliés dans un cercle de 2 cases autour d\'elle.', 0x08afad010899f903089af903, '1', 'Agressive'),
(4452, 'Nuée Ardente', 'Occasionne des dommages Feu et retire de la Portée.', 0x08b0ad010897f9030898f903, '1', 'Agressive'),
