(4465, 'Effluves Spectraux', '', 0x08bdad0108e1f90308e2f90308d0fc03, '1', 'None'),
(4466, 'Effluves Spectraux', 'Repousse les cibles depuis le centre en zone. \nN\'affecte pas le lanceur.\n\nSur le Feu Funèbre allié ciblé ou dans la zone d\'effet : les effets du sort sont réappliqués et retire également des PM aux ennemis dans une croix de 2 cases autour de lui.\nAffecte également le lanceur.', 0x08bead0108e3f90308e4f903, '1', 'Agressive'),
(4467, 'Feu Funèbre', 'Invoque un Feu Funèbre statique qui retire des PM aux ennemis dans un cercle de 2 cases autour de lui à sa mort.\n\nIl ne peut y avoir qu\'un seul Feu Funèbre par équipe. Si le Feu Funèbre est encore en vie et que celui-ci est ré-invoqué, l\'ancien est tué pour laisser place au nouveau.', 0x08bfad01, '1', 'Agressive'),
(4468, 'Entrave Mortelle', '', 0x08c0ad01, '1', 'Agressive'),
(4469, 'Hantise', '', 0x08c1ad0108cbf90308ccf90308cdfc0308cefc0308cffc03, '1', 'Debuff'),
(4470, 'Hantise', 'Occasionne des dommages Air et retire des PM et du Tacle aux ennemis.\n\nSur le Feu Funèbre allié : occasionne des dommages Air, retire du Tacle et des PM aux ennemis dans un cercle de 2 cases autour de lui.', 0x08c2ad0108d3f90308d4f903, '1', 'Agressive'),
(4471, 'Faisceau Spectral', '', 0x08c3ad0108d9f90308daf90308ccfc03, '1', 'Debuff'),
(4472, 'Faisceau Spectral', 'Occasionne des dommages Terre et retire de la Portée aux ennemis et repousse la cible.\n\nSur le Feu Funèbre allié : occasionne des dommages Terre et retire de la Portée aux ennemis et repousse les cibles depuis le centre dans un cercle de 2 cases autour de lui.', 0x08c4ad0108d7f90308d8f903, '1', 'Agressive'),
(4473, 'Clairvoyance', '', 0x08c5ad0108dbf90308dcf90308d1fc03, '1', 'None'),
(4474, 'Clairvoyance', 'Dévoile les entités invisibles et retire de la Puissance aux ennemis en zone.\n\nSur le Feu Funèbre allié dans la zone d\'effet : les effets du sort sont réappliqués dans un cercle de 2 cases autour de lui.', 0x08c6ad0108ddf90308def903, '1', 'Debuff'),
(4475, 'Ricochet', 'Réduit immédiatement les dommages subis à distance par l\'allié ciblé.\nAugmente la Puissance et les dommages subis par la cible au tour suivant.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08c7ad0108dff90308e0f903, '1', 'Buff'),
