(4707, 'Fiole Revigorante', 'Invoque une Fiole Revigorante statique qui soigne les alliés et déclenche l\'explosion des Fioles du lanceur dans un cercle de 2 cases autour d\'elle à sa destruction.\n\nPendant 3 tours, pour chaque tour où la Fiole Revigorante reste en vie, ses effets deviennent plus importants.\n\nLa Fiole est détruite si elle subit des dommages.', 0x08eeaf0108e4f80308e5f803, '1', 'Summon'),
(4708, 'Fiole d\'Acide', 'Invoque une Fiole d\'Acide statique qui occasionne des dommages Terre aux ennemis et déclenche l\'explosion des Fioles du lanceur dans un cercle de 2 cases autour d\'elle à sa destruction.\n\nPendant 3 tours, pour chaque tour où la Fiole d\'Acide reste en vie, ses dommages finaux sont augmentés.', 0x08efaf0108e6f80308e7f803, '1', 'Summon'),
(4709, 'Alchimie', '', 0x08f0af0108d4f80308d5f80308e0fa0308e1fa0308e2fa03, '0', 'Agressive'),
(4710, 'Alchimie', 'Rapproche le lanceur de la cible.\n\nSur un ennemi :\n• Occasionne des dommages Air.\n\nSur une Fiole d\'Acide alliée :\n• Occasionne des dommages Air aux ennemis dans un cercle de 2 cases autour d\'elle.\n\nSur une Fiole Revigorante alliée :\n• Soigne les alliés dans un cercle de 2 cases autour d\'elle.', 0x08f1af0108d6f80308d7f803, '1', 'Agressive'),
(4711, 'Attirance Chimique', 'Applique l\'état Chimique, attire la cible et occasionne des dommages Feu aux ennemis.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08f2af010886f9030887f903, '1', 'Agressive'),
(4712, 'Fiolixine', '', 0x08f3af01, '0', 'Agressive'),
(4713, 'Fiolixine', 'Sur une Fiole alliée :\n• Attire toutes les cibles dans l\'état Chimique vers la Fiole.\n• Retire des PM à tous les ennemis dans l\'état Chimique.', 0x08f4af010888f9030889f903, '1', 'Agressive'),
(4716, 'Débordement', 'Détruit toutes les Fioles du lanceur pour poser un glyphe de début de tour sous chacune d\'elles selon la Fiole :\n• Fiole d\'Acide : occasionne des dommages Terre aux ennemis.\n• Fiole Revigorante : soigne les alliés.', 0x08f7af0108fcf80308fdf803, '1', 'Agressive'),
