(4837, 'Furia du Chasseur de Primes', 'Rapproche le lanceur de la cible, occasionne des dommages Terre sur ennemis et augmente les dommages fixes du lanceur pendant le tour en cours.', 0x0895b1010896b1010897b1010898b1010899b101089ab101, '1', 'Agressive'),
(4838, 'Cabriole du Chasseur de Primes', 'Téléporte sur la case ciblée, occasionne des dommages Air en croix et augmente les dommages du lanceur pour le tour en cours.', 0x089bb101089cb101089db101089eb101089fb10108a0b101, '1', 'Teleport'),
(4839, 'Fougue du Chasseur de Primes', 'Rend la cible insensible au Tacle et augmente ses dommages, mais la rend insoignable.', 0x08a1b10108a2b10108a3b10108a4b10108a5b10108a6b101, '1', 'Buff'),
