(4979, 'Voyage du Perchoir', '', 0x08cab201, '0', 'Agressive'),
(4980, 'Désordre Dimensionnel', 'Applique l\'état Désordonné sur tous les Perchoirs Cosmiques du lanceur et inverse leurs effets.\n\nÀ la fin du prochain tour du lanceur :\n• Le Perchoir soigne les alliés dans un cercle de 2 cases autour de lui.\n• Il échange de position avec un allié dans l\'état Voyageur.\n• Il occasionne des dommages Feu aux ennemis dans un cercle de 2 cases autour de sa position d\'arrivée.\n• Détruit le Perchoir.\n\nN\'affecte pas les Perchoirs dans l\'état Temporisateur.\nLes effets ne peuvent pas être désenvoûtés.', 0x08cbb20108cef80308cff803, '1', 'Agressive'),
(4981, 'Transcendance', 'Applique l\'état Voyageur sur l\'allié ciblé : \n• Applique l\'état Passeur sur le lanceur.\n• Les Perchoirs échangent de position avec la cible et non avec le lanceur.\n\nRelancer le sort sur le lanceur retire les effets et lui réapplique l\'état Voyageur.\n\nIl ne peut y avoir qu\'un seul allié sous les effets du sort et ses effets sont retirés à la mort de la cible. \nN\'affecte pas les Perchoirs.', 0x08ccb20108ccf80308cdf803, '1', 'Agressive'),
(4982, 'Voyage du Perchoir', '', 0x08cdb20108b7f80308b8f803, '0', 'Agressive'),
(4983, 'Voyage', 'Échange de position avec un allié dans l\'état Voyageur et augmente ses PM.', 0x08ceb20108caf80308cbf803, '1', 'Agressive'),
(4984, 'Instabilité Moléculaire', 'Applique l\'état Instable sur l\'ennemi ciblé et lui vole de la vie dans l\'élément Terre.\n\nLes Perchoirs occasionnent des dommages Terre supplémentaires aux ennemis dans l\'état Instable.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08cfb20108c7f80308c8f803, '1', 'Agressive'),
(4985, 'Voyage du Perchoir', '', 0x08d0b20108c3f80308c4f803, '0', 'Agressive'),
(4987, 'Voyage du Perchoir', '', 0x08d2b20108d9b20108bdf80308bef80308bff80308c0f803, '0', 'Agressive'),
(4988, 'Voyage du Perchoir', '', 0x08d3b20108c1f80308c2f803, '0', 'Agressive'),
(4989, 'Méditation Céleste', 'Applique l\'état Temporisateur sur le lanceur et tous ses Perchoirs Cosmiques :\n• Retire des PM non esquivables au lanceur.\n• Augmente la Puissance du lanceur à chaque fois qu\'il échange de position.\n• Empêche la destruction des Perchoirs au prochain tour du lanceur.\n\nDans 3 tours, les Perchoirs sont détruits et occasionnent des dommages Feu aux ennemis en zone.\n\nN\'affecte pas les Perchoirs dans l\'état Désordonné. \nLes effets ne peuvent pas être désenvoûtés.', 0x08d4b20108a4f80308a5f803, '1', 'Agressive'),
(4990, 'Perchoir Cosmique', 'Invoque un Perchoir Cosmique statique.\nApplique également l\'état Voyageur sur le lanceur s\'il n\'est pas dans l\'état Passeur.\n\nAu début du prochain tour du lanceur :\n• Le Perchoir occasionne des dommages Feu aux ennemis dans un cercle de 2 cases autour de lui.\n• Il échange de position avec un allié dans l\'état Voyageur.\n• Il soigne les alliés dans un cercle de 2 cases autour de sa position d\'arrivée.\n• Détruit le Perchoir.', 0x08d5b20108c5f80308c6f803, '1', 'Summon'),
(4992, 'Voyage du Perchoir', '', 0x08d7b201, '0', 'Healing'),
(4993, 'Méditation Céleste', '', 0x08d8b20108a6f80308a7f80308b3fc0308b5fc0308bbfc03, '0', 'Agressive'),
