(5473, 'Affront du Dopeul', 'Occasionne des dommages Air aux ennemis. \nSoigne les alliés dans l\'état \"Portail\".', 0x08b3bd0108b4bd0108b5bd0108b6bd0108b7bd0108b8bd01, '1', 'Agressive'),
(5474, 'Affliction du Dopeul', 'Occasionne des dommages Eau.\nSoigne les alliés ciblé au début de leur tour s\'ils sont dans l\'état Portail.', 0x08b9bd0108babd0108bbbd0108bcbd0108bdbd0108bebd01, '1', 'Agressive'),
(5475, 'Commotion du Dopeul', 'Occasionne des dommages Terre en croix aux ennemis.\nAttire les cibles vers la cellule ciblée.', 0x08bfbd0108c0bd0108c1bd0108c2bd0108c3bd0108c4bd01, '1', 'Agressive'),
(5476, 'Rayon de Wakfu du Dopeul', 'Occasionne des dommages Feu en ligne aux ennemis.\nSoigne les alliés dans l\'état \"Portail\".', 0x08c5bd0108c6bd0108c7bd0108c8bd0108c9bd0108cabd01, '1', 'Agressive'),
(5477, 'Offense du Dopeul', 'Occasionne des dommages Feu sur les ennemis.', 0x08cbbd0108ccbd0108cdbd0108cebd0108cfbd0108d0bd01, '1', 'Agressive'),
(5478, 'Thérapie du Dopeul', 'Occasionne des dommages Terre aux ennemis.\nSoigne les alliés dans l\'état \"Portail\".', 0x08d1bd0108d2bd0108d3bd0108d4bd0108d5bd0108d6bd01, '1', 'Agressive'),
(5479, 'Brimade du Dopeul', 'Occasionne des dommages Air et pousse les cibles.', 0x08d7bd0108d8bd0108d9bd0108dabd0108dbbd0108dcbd01, '1', 'Agressive'),
