(5482, 'Poing fulgurant du Dopeul', 'Occasionne des dommages Eau aux ennemis. Repousse la cible si elle est dans l\'état \"Portail\".', 0x08e4bd0108e5bd0108e6bd0108e7bd0108e8bd0108e9bd01, '1', 'Agressive'),
(5483, 'Audace du Dopeul', 'Occasionne des dommages Eau.\nLe lanceur se rapproche de sa cible mais perd 2PM.', 0x08eabd0108ebbd0108ecbd0108edbd0108eebd0108efbd01, '1', 'Agressive'),
