(5741, 'Invocation de Cyanog', 'Invoque un esprit qui inflige 6 (8,10) dommages par tour à tous ses adversaires en ligne avec lui.', 0x08b4c401, '1', 'Summon'),
(5742, 'Invocation de Goémus', 'Invoque un esprit qui inflige 2 dommage par tour et fait perdre 1 PM pour 2 tours à tous ses adversaires en ligne avec lui.', 0x08b5c401, '1', 'Summon'),
(5743, 'Motivation de Kelpe', '', 0x08b6c401, '0', 'Buff'),
(5744, 'Invocation de Kelpe', 'Invoque un esprit qui donne 1 PA supplémentaire chaque tour à son lanceur.', 0x08b8c401, '1', 'Summon'),
(5745, 'Invocation de Norie', 'Invoque un esprit qui explose lors de sa mort, infligeant 9 dommages à tous les adversaires proches.', 0x08b9c401, '1', 'Summon'),
