(8393, 'Dofus Émeraude', 'À la fin du tour, confère 100% du niveau du propriétaire en points de bouclier pour chaque ennemi au contact.\nLes invocations ne sont pas comptabilisées.', 0x08f3800208f4800208f58002, '0', 'Buff'),
(8394, 'Dofus Ocre', 'Donne 1 PA pour 1 tour si le porteur n\'a subi aucun dommages ennemis depuis le précédent tour de jeu.\nSinon, donne 20 Fuite.', 0x08f7800208f8800208f98002, '0', 'Buff'),
(8395, 'Dofus Pourpre', 'Pour chaque attaque reçue, les dommages finaux occasionnés sont augmentés de 1% pendant 1 tour.\nLes effets peuvent se cumuler 10 fois.', 0x08fa800208dc8202, '0', 'Buff'),
(8396, 'Dofus Vulbis', 'Augmente les dommages occasionnés de 10% pour 1 tour si le porteur n\'a subi aucun dommages ennemis depuis le précédent tour de jeu.\nSinon, donne 20 Tacle.', 0x08fb800208fc800208fd8002, '0', 'Buff'),
