(8474, 'Mâtin', 'Occasionne des dommages Terre.\nLes dommages subis par le lanceur sont réduits de 15% pendant 1 tour.\nAugmente la Rage.', 0x08ff8102, '1', 'Agressive'),
(8477, 'Radius', 'Occasionne des dommages Eau.\nSi la cible est la Proie, le lanceur gagne 1 PM.', 0x08828202, '1', 'Agressive'),
