(8485, 'Molosse du dopeul', 'Occasionne des dommages Terre.\nLes dommages subis par le lanceur sont réduits de 15% pendant 1 tour.\n\nAugmente la Rage.', 0x08a2820208a3820208a4820208a5820208a6820208a78202, '1', 'Agressive'),
(8486, 'Cubitus du dopeul', 'Occasionne des dommages Eau.\nSi la cible est la Proie, le lanceur gagne 1 PM.', 0x08a8820208a9820208aa820208ab820208ac820208ad8202, '1', 'Agressive'),
(8487, 'Carcasse du dopeul', 'Occasionne des dommages Air.\nSi la cible est la Proie, les dommages du sort sont augmentés pendant 3 tours.', 0x08ae820208af820208b0820208b1820208b2820208b38202, '1', 'Agressive'),
(8488, 'Proie du dopeul', 'La cible devient une Proie.\nQuand elle est attaquée, son attaquant est soigné de 25% des dommages occasionnés.', 0x08b4820208b5820208b6820208b7820208b8820208b98202, '1', 'Debuff'),
(8489, 'Pelage protecteur du dopeul', 'Applique un bouclier sur la cible.\n\nSi la cible subit des dommages de poussée, elle perd le bouclier et la Rage du lanceur augmente.', 0x08ba820208bb820208bc820208bd820208be820208bf8202, '1', 'Buff'),
(8490, 'Tibia du dopeul', 'Occasionne des dommages Eau autour du lanceur et repousse.\n\nAugmente la Rage.', 0x08c0820208c1820208c2820208c3820208c4820208c58202, '1', 'Agressive'),
(8491, 'Apaisement du dopeul', 'Réduit la Rage du lanceur pour se soigner.', 0x08c6820208c7820208c8820208c9820208ca820208cb8202, '1', 'Healing'),
(8492, 'Limier du dopeul', 'Occasionne des dommages Air.\n\nSi la cible est la Proie, augmente la Puissance du lanceur.', 0x08cc820208cd820208ce820208cf820208d0820208d18202, '1', 'Agressive'),
(8493, 'Cerbère du dopeul', 'Occasionne des dommages Terre.\nSi la cible est la Proie, applique un malus de Fuite.', 0x08d2820208d3820208d4820208d5820208d6820208d78202, '1', 'Agressive'),
