(8879, 'Confluence', 'Sur allié : se rapproche de la cible.\nSur ennemi : attire la cible.', 0x08f7880208f8880208f9880208fa880208fb880208fc8802, '1', 'Agressive'),
(8880, 'Victime', 'La cible devient une Proie.\nQuand elle est attaquée, son attaquant est soigné de 25% des dommages occasionnés.', 0x08fd880208fe880208ff8802088089020881890208828902, '1', 'Debuff'),
(8881, 'Toison protectrice', 'Applique un bouclier sur la cible.\n\nSi la cible subit des dommages de poussée, elle perd le bouclier et la Rage du lanceur augmente.', 0x088389020884890208858902088689020887890208888902, '1', 'Buff'),
(8882, 'Pisteur', 'Occasionne des dommages Air.\n\nSi la cible est la Proie, augmente la Puissance du lanceur.', 0x08898902088a8902088b8902088c8902088d8902088e8902, '1', 'Agressive'),
(8883, 'Répulsion chimique', 'Repousse de deux cases et occasionne des dommages de feu aux ennemis.', 0x088f8902, '1', 'Agressive'),
