(12473, 'Raulepique', 'Renvoie des dégâts magiques ou physiques.', 0x08fab802, '1', 'Buff'),
(12474, 'Auto-destruction', '', 0x08fbb802, '1', 'Agressive'),
(12475, 'Célérité du Piou', 'Célérité du Piou (niveau 200) :\n• Lorsque le porteur se fait tacler, il gagne 2 PM pendant 1 tour (cumulable 1 fois).', 0x08feb80208b9ce03, '1', 'Buff'),
(12477, 'Épargne du Koalak', 'Épargne du Koalak (niveau 200) :\n• Lorsque le porteur se fait tacler, il gagne 1 PA pendant 1 tour (cumulable 1 fois).', 0x0881b90208d7cf03, '1', 'Buff'),
(12479, 'Évasion du Kitsou', 'Évasion du Kitsou (niveau 200) :\n• À chaque début de tour, le porteur gagne 5 de Fuite pendant 1 tour par ennemi à 2 cases ou moins de lui.', 0x0884b9020885b90208e3b90208c8d703, '1', 'None'),
(12480, 'Toile de l\'Arakne', 'Toile de l\'Arakne : \n• À chaque fin de tour, le porteur gagne 5 de Tacle pendant 1 tour par ennemi à 2 cases ou moins de lui.', 0x0886b9020887b90208e4b90208f4ce03, '1', 'None'),
(12481, 'Hystérie de la Truche', 'Hystérie de la Truche (niveau 200) :\n• Au début du combat, le porteur sacrifie 1% de résistance pour gagner 6 de Fuite et 3 de Tacle par ennemi.', 0x0888b9020889b902, '1', 'Buff'),
(12482, 'Soif du Moskito', 'Soif du Moskito (niveau 200) :\n• Le porteur sacrifie 10% de ses dommages finaux pour se soigner de 10% des dommages qu\'il inflige à ses ennemis pendant son tour de jeu.', 0x088ab902088bb9020881ba02, '1', 'Agressive'),
(12483, 'Impatience du Wabbit', 'Impatience du Wabbit (niveau 200) :\n• Au début du combat, le porteur gagne 1% de dommages finaux pour chaque ennemi, mais perd 2% de dommages finaux à chaque mort d\'un ennemi (hors invocations) présent au début du combat.', 0x088db9020895b9020896b9020897b90208c7d403, '1', 'Debuff'),
(12484, 'Brutalité du Trool', 'Brutalité du Trool (niveau 200) :\n• Au début du combat, le porteur sacrifie 1% de dommages finaux par ennemi pour gagner 2% de dommages finaux à chaque mort d\'un ennemi (hors invocations) présent au début du combat (cumulable 5 fois).', 0x0890b9020898b9020899b90208c9d70308cad703, '1', 'Buff'),
(12485, 'Précision du Bwork', 'Précision du Bwork (niveau 200) :\n• Lorsque le porteur débute son tour au contact d\'un ennemi, il gagne 3% de dommages à distance pendant 1 tour, sinon il gagne 3% de dommages en mêlée pendant 1 tour.', 0x0891b9020892b9020893b9020894b902, '1', 'Buff'),
(12486, 'Rage du Mulou', 'Rage du Mulou (niveau 200) :\n• Le porteur gagne 5% de dommages finaux pendant 2 tours à chaque mort d\'un allié (hors invocations) présent au début du combat (cumulable 2 fois).', 0x089bb902089cb902089db90208abd103, '1', 'Buff'),
(12487, 'Générosité du Bwak', 'Générosité du Bwak (niveau 200) :\n• Lorsque le porteur termine son tour au contact d\'un ennemi, il sacrifie 2% de dommages à distance pour son prochain tour pour donner 2% de dommages à distance à ses alliés pendant 1 tour (cumulable 1 fois).', 0x089fb90208a0b90208e5b90208c5cd03, '1', 'Debuff'),
(12488, 'Douceur de la Boufette', 'Douceur de la Boufette (niveau 200) :\n• À chaque début de tour, le porteur sacrifie 5% de dommages en mêlée pour donner 5% de dommages en mêlée aux alliés à son contact pendant 1 tour (cumulable 1 fois).', 0x08a3b90208a4b90208e6b90208c5d403, '1', 'Debuff'),
(12489, 'Robustesse du Craqueleur', 'Robustesse du Craqueleur (niveau 200) :\n• Au début du combat, le porteur sacrifie 2% de résistance par allié pour donner 3% de résistance à ses alliés.', 0x08a5b90208a6b902, '1', 'Debuff');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(12490, 'Protection de la Krokille', 'Protection de la Krokille (niveau 200) :\n• Au début du combat, le porteur gagne 75% du niveau de chaque allié en bouclier, mais perd 5% de résistance à chaque mort d\'un allié (hors invocations) présent au début du combat.', 0x08a7b90208a8b90208abb90208acb90208a0d103, '1', 'Debuff'),
(12492, 'Gourmandise du Gloutoblop', 'Gourmandise du Gloutoblop (niveau 200) :\n• Lorsqu\'un allié (hors invocations) présent au début du combat meurt, le porteur est soigné de 20% de ses points de vie.\nL\'effet peut être déclenché 3 fois maximum par combat.', 0x08adb90208aeb90208afb90208bccd03, '1', 'Healing'),
(12493, 'Invocation Cristaux', '', 0x08b1b90208b2b90208b3b90208b4b902, '1', 'Summon'),
(12494, 'Aléorictus', '', 0x08b5b902, '1', 'Agressive'),
(12495, 'Essor Animation', '', 0x08b6b902, '1', 'None'),
(12496, 'Catapultage Animation', '', 0x08b7b902, '1', 'None'),
(12497, 'Immortalité du Chafer', 'Immortalité du Chafer (niveau 200) :\n• Lorsqu\'un allié (hors invocations) présent au début du combat meurt, le porteur gagne 100% du niveau de cet allié en bouclier pour le reste du combat.\nL\'effet peut être déclenché 5 fois maximum par combat.', 0x08b8b90208b9b90208bab90208d5cd03, '1', 'None'),
(12498, 'Écorce de l\'Abraknyde', 'Écorce de l\'Abraknyde (niveau 200) :\n• Lorsque le porteur subit une tentative de retrait de PM, il gagne 75% de son niveau en bouclier pendant 1 tour (cumulable 1 fois).', 0x08bbb90208bcb902, '1', 'Buff'),
(12499, 'Altruisme du Champa', 'Altruisme du Champa (niveau 200) :\n• Lorsque le porteur termine son tour au contact d\'un allié, il sacrifie 1 PA pour son prochain tour pour donner 1 PA aux alliés à son contact pendant 1 tour (cumulable 1 fois).', 0x08bdb90208beb90208bfb90208e8b902, '1', 'Debuff'),
(12500, 'Bienveillance de la Tofoune', 'Bienveillance de la Tofoune (niveau 200) :\n• Lorsque le porteur termine son tour au contact d\'un allié, il sacrifie 1 PM pour son prochain tour pour donner 1 PM aux alliés à son contact pendant 1 tour (cumulable 1 fois).', 0x08c0b90208c1b90208c2b90208e9b902, '1', 'Debuff'),
(12501, 'Appel du Pandore', 'Appel du Pandore (niveau 200) :\n• À chaque fin de tour, le porteur sacrifie 1 PM pour son prochain tour pour chaque invocation non statique qu\'il contrôle et leur donne 1 PM pendant 1 tour.', 0x08c3b902, '1', 'Agressive'),
(12502, 'Entrave du Dragoeuf', 'Entrave du Dragoeuf (niveau 200) :\n• Lorsque le porteur tacle un ennemi, il gagne 100% de son niveau en bouclier pendant 1 tour.', 0x08c6b90208c7b902, '1', 'Buff'),
(12503, 'Dévouement de la Domoizelle', 'Dévouement de la Domoizelle (niveau 200) :\n• À chaque fin de tour, le porteur transfère 5% de ses points de vie aux alliés à son contact.', 0x08c8b90208b6ce0308b7ce0308bace03, '1', 'None'),
(12504, 'Hystéria', '', 0x08cbb90208ccb90208cdb902, '1', 'Agressive'),
(12505, 'Toxicité du Scorbute', 'Toxicité du Scorbute (niveau 200) :\n• À chaque début de tour, le porteur s\'inflige des dommages dans son meilleur élément d\'attaque pour en infliger aux entités à son contact à la fin de son tour.', 0x08ceb90208cfb90208d0b902, '1', 'Agressive'),
(12506, 'Empathie de la Boursoin', 'Empathie de la Boursoin (niveau 200) :\n• Le porteur bénéficie d\'un bonus de 10% de soins occasionnés sur les joueurs et compagnons alliés pendant son tour de jeu. Il perd ce bonus dès que l\'un d\'entre eux meurt.', 0x08d1b90208d2b90208feb90208ffb9020880ba0208bed103, '1', 'None'),
(12507, 'Aléorictus', '', 0x08d4b902, '1', 'Agressive'),
(12508, 'Aléorictus Zone A', '', 0x08d5b902, '1', 'Agressive'),
(12509, 'Aléorictus Zone B', '', 0x08d6b902, '1', 'Agressive'),
(12510, 'Aléorictus Zone C', '', 0x08d7b902, '1', 'Agressive'),
(12511, 'Aléorictus Zone D', '', 0x08d8b902, '1', 'Agressive'),
(12512, 'Aléorictus', '', 0x08d9b902, '1', 'Debuff'),
(12513, 'Aléorictus', '', 0x08dab902, '1', 'Agressive'),
(12514, 'Pétale enchanteur', '', 0x08dbb902, '1', 'None'),
(12515, 'Mowfal Animation', '', 0x08dcb902, '1', 'None'),
(12516, 'Panache Reroll VIP antifail', '', 0x08ddb902, '1', 'None'),
(12517, 'Croquelure', '', 0x08e7b902, '1', 'None'),
(12519, 'Soif du Moskito', 'Soif du Moskito :\n• Le porteur inflige 10% de dommages finaux en moins, mais bénéficie de 10% de vol de vie (dommages directs).', 0x08f1b90208f8d60308f9d60308cbd703, '1', 'None'),
(12520, 'Appel du Pandore', '', 0x08f6b902, '1', 'Agressive'),
(12521, 'Appel du Pandore', '', 0x08f9b90208a1d103, '1', 'None'),
(12522, 'Empathie de la Boursoin', '', 0x08fcb902, '1', 'Buff'),
(12526, 'Géomancie', '', 0x088cba02, '1', 'Buff'),
(12531, 'Boulet Émeraude', '', 0x0892ba02, '1', 'Agressive'),
(12532, 'Radiations Glyphe qui lance un sort', '', 0x0893ba02, '1', 'Agressive'),
(12533, 'Radiations', '', 0x0894ba02, '1', 'Agressive'),
(12535, 'Étreinte bourgeonnante', '', 0x0899ba02089aba02089bba02089cba02089dba02089eba02, '1', 'Summon'),
(12543, 'Cauchemar de Batofu', '', 0x08adba02, '1', 'Debuff'),
(12548, 'Dragonique', 'Occasionne des dommages Feu en zone.\n\nConfère une Dragocharge si une entité est touchée.', 0x08b5ba0208a4d10208a5d102, '1', 'Agressive'),
(12549, 'Canine', 'Occasionne des dommages Air et retire du Tacle.\n\nConfère une Tofucharge (nécessite une cible).', 0x08b8ba0208b9ba0208baba02, '1', 'Agressive'),
(12550, 'Envol', 'Échange de position avec une invocation Osamodas du lanceur et occasionne des dommages Air aux ennemis dans une zone de 2 cases autour du lanceur et de l\'invocation.\nLes dommages sont appliqués qu\'une seule fois par lancer et si l\'échange de position est possible.\n\nConfère une Tofucharge si un ennemi autour du laneur est touché.\nConfère une Tofucharge si un ennemi autour de l\'invocation est touché.', 0x08bbba0208c7d30208c8d302, '1', 'Agressive'),
(12551, 'Souffle du Dragon', 'Repousse les entités (hors lanceur) de l\'équipe adverse à la cible à son contact et occasionne des dommages Feu aux ennemis ou soigne les alliés.\n\nConfère une Dragocharge (nécessite une cible).', 0x08bcba0208eadb0208ebdb02, '1', 'Agressive'),
(12554, 'Piqûre Motivante', 'Augmente les dommages finaux occasionnés, la Vitalité, les PA et les PM d\'une invocation du lanceur.\n\nLes effets sont transmis lorsque l\'Informo se transforme.', 0x08c3ba0208c4ba0208c5ba02, '1', 'Buff'),
(12555, 'Fossile', 'Occasionne des dommages Terre et retire des PM.\n\nConfère une Bouftocharge (nécessite une cible).', 0x08c6ba0208c7ba0208c8ba02, '1', 'Agressive'),
(12557, 'Fouet', 'Attire les invocations Osamodas du lanceur vers le centre de la zone.\nSi la case est occupée, téléporte les invocations Osamodas symétriquement par rapport à la cible.', 0x08ccba0208c2d102, '1', 'Agressive'),
(12559, 'Résistance Naturelle', 'Rend une invocation Osamodas du lanceur Invulnérable.\n\nL\'effet est transmis lorsque l\'Informo se transforme.', 0x08d2ba02, '1', 'None'),
(12560, 'Plumeau', 'Occasionne des dommages Air.\nLes dommages sont augmentés pour chaque Tofu du lanceur présent sur le terrain.\n\nConfère une Tofucharge (nécessite une cible).', 0x08d3ba0208dfd10208e0d102, '1', 'Agressive'),
(12563, 'Frappe du Craqueleur', 'Occasionne des dommages Terre aux ennemis en zone.\n\nConfère une Bouftocharge si au moins un ennemi est touché.\nConfère une seconde Bouftocharge si au moins trois ennemis sont touchés.', 0x08dcba0208eed10208efd102, '1', 'Agressive'),
(12564, 'Rappel', 'Tue une invocation alliée.\n\nSur un Tofu, un Bouftou, un Crapaud ou un Dragonnet du lanceur : confère une charge invocatrice selon la famille de l\'invocation et rend 2 PA au lanceur avant de la tuer.\nLe temps de relance du sort d\'invocation associé n\'est pas appliqué.', 0x08dfba0208f1d102, '1', 'Agressive'),
(12579, 'Rappel', '', 0x08fdba02, '0', 'Agressive'),
(12580, 'Béco Mélanique', 'Occasionne des dommages Air et retire du Tacle.', 0x08feba0208ffba020880bb02, '1', 'Agressive'),
(12581, 'Béco Soufflé', 'Augmente les PM du lanceur.\nRepousse la cible et rapproche le lanceur.', 0x0881bb02, '1', 'Agressive'),
(12590, 'Attirance Laineuse', 'Attire la cible.\n\nEmpêche l\'utilisation du sort Morsure Précipitée pour le tour en cours.', 0x0895bb02, '1', 'Agressive'),
(12591, 'Aéropique', 'Donne 1 PM au lanceur pour chaque ennemi dans la zone d\'effet et leur occasionne des dommages Air en zone.', 0x0896bb0208d3d402, '1', 'Agressive'),
(12600, 'Croc Répulsif', 'Occasionne des dommages Air aux ennemis et repousse la cible.\n\nConfère une Tofucharge (nécessite une cible).', 0x08a2bb0208e5d302, '1', 'Agressive'),
(12601, 'Onde Aquatique', 'Occasionne des dommages Eau aux ennemis et augmente les dommages d\'invocations subis par l\'ennemi ciblé.\n\nConfère une Crapocharge (nécessite une cible).', 0x08a3bb0208cad10208cbd102, '1', 'Agressive'),
(12604, 'Sédimentation', 'Occasionne des dommages Terre et retire de la Puissance aux ennemis.\n\nConfère une Bouftocharge (nécessite une cible).', 0x08a6bb0208bcd102, '1', 'Agressive'),
(12605, 'Tourbillon', 'Occasionne des dommages Eau aux ennemis.\n\nSur un Crapaud du lanceur : occasionne des dommages Eau aux ennemis en zone. La zone dépend du Crapaud :\n• Mélanique : Croix d\'une case.\n• Albinos : Carré d\'une case.\n• Verdoyant : Cercle de 2 cases.\n\nConfère une Crapocharge (nécessite une cible).', 0x08a7bb02088ed202, '1', 'Agressive'),
(12606, 'Baume Protecteur', 'Applique l\'état Embaumé sur une invocation alliée :\n• Applique immédiatement un bouclier sur la cible, et au début de chacun de ses tours.\n\nIl ne peut y avoir qu\'une seule invocation dans l\'état Embaumé par équipe.\nSi le sort est lancé sur une autre invocation, ses effets sont retirés de la cible précédente.\n\nLes effets ne peuvent pas être désenvoûtés, ne sont pas réappliqués sur une invocation déjà dans l\'état Embaumé et sont transmis lorsque l\'Informo se transforme.', 0x08a8bb0208bdd10208bed102, '1', 'Agressive'),
(12608, 'Cravache', 'Applique des effets de déplacement selon la famille de la charge invocatrice et le nombre de charges :\n• Tofucharge : repousse la cible de 1 à 3 cases.\n• Bouftocharge : attire la cible de 1 à 3 cases.\n• Crapocharge : rapproche le lanceur de 1 à 3 cases.\n• Dragocharge : éloigne le lanceur de 1 à 3 cases.', 0x08aabb02, '1', 'Agressive'),
(12609, 'Déplumage', 'Pose un piège mono-cellule qui occasionne des dommages Air aux ennemis dans un cercle de 2 cases si une invocation Osamodas alliée le déclenche.\n\nConfère une Tofucharge s\'il est déclenché par une invocation Osamodas alliée.', 0x08abbb02, '1', 'Mark'),
(12612, 'Cœur de Dragon', 'Occasionne des dommages Feu aux ennemis et soigne les alliés dans un cercle de 2 cases autour des Dragonnets du lanceur.\nLes soins sont réduits de moitié sur le lanceur.\n\nConfère une Dragocharge.', 0x08aebb02, '1', 'Agressive'),
(12614, 'Constriction', 'Vole de la vie dans l\'élément Terre.\n\nConfère une Bouftocharge (nécessite une cible).', 0x08b0bb02, '1', 'Agressive'),
(12615, 'Geyser', 'Occasionne des dommages Eau.\n\nConfère une Crapocharge (nécessite une cible).', 0x08b1bb0208d0bb0208d1bb02, '1', 'Agressive'),
(12617, 'Relais', 'Lie l\'allié ciblé à l\'invocation du lanceur la plus proche de lui :\n• Augmente les PA de l\'allié ciblé.\n• Échange les positions des deux entités si elles sont à 5 cases ou moins l\'une de l\'autre.\n\nLes effets se dissipent à la mort de l\'invocation ou de l\'allié.\nLa liaison ne peut pas être appliquée sur un allié ou une invocation sous les effets du sort.', 0x08b3bb02, '1', 'Agressive'),
(12618, 'Favoritisme', 'Applique l\'état Favori sur une invocation du lanceur :\n• Réduit les dommages subis par l\'invocation.\n• À chaque début de tour de l\'invocation, augmente ses dommages finaux occasionnés.\n\nIl ne peut y avoir qu\'une seule invocation dans l\'état Favori par Osamodas.\nSi le sort est lancé sur une autre invocation, ses effets sont retirés de la cible précédente.\n\nLes effets ne peuvent pas être désenvoûtés, ne sont pas réappliqués sur une invocation déjà dans l\'état Favori et sont transmis lorsque l\'Informo se transforme.', 0x08b4bb0208ccd502, '1', 'Agressive'),
(12619, 'Remplacement', 'Tue un Tofu, Bouftou, Crapaud ou Dragonnet du lanceur pour les remplacer par une nouvelle invocation identique en lui augmentant sa Vitalité pour chaque palier de points de vie de la cible initiale.\n\nLes intervalles de relance initiaux des sorts de la nouvelle invocation ne sont pas appliqués si l\'invocation remplacée était présente pendant au moins un tour.\nLes effets des sorts Baume Protecteur, Piqûre Motivante, Favoritisme et Résistance Naturelle sont transmis à la nouvelle invocation.', 0x08b5bb02, '1', 'Agressive'),
(12626, 'Relais', '', 0x08bdbb0208d8bb02088dd20208fdd30208aeeb02, '1', 'Buff'),
(12632, 'Béco Albinos', 'Occasionne des dommages Air.\nOccasionne des dommages Air plus faibles la deuxième fois sur une même cible dans le tour en cours.', 0x08c3bb0208b1d20208b2d202, '1', 'Agressive'),
(12695, 'Bécorune de Repli', '', 0x089cbc02088ce902, '1', 'Teleport'),
(12696, 'Bécorune de Repli', 'Pose une rune qui téléporte le lanceur dessus à la fin de son tour.\nLa téléportation ne peut s\'effectuer que si la rune n\'est pas occupée.\n\nLe coût en PA du sort est remboursé.', 0x089dbc02089ebc02, '1', 'Agressive'),
(12698, 'Bécompresseur', 'Occasionne des dommages Air aux ennemis en zone et pose une rune.\nLancer le sort une deuxième fois dans le même tour en étant sur la rune téléporte les entités dans la zone d\'effet symétriquement par rapport au lanceur.', 0x08a1bc0208b8d20208b9d202, '1', 'Agressive'),
(12699, 'Le Fouet d\'Osamodas', '', 0x08a2bc02, '1', 'Agressive'),
(12700, 'Le Fouet d\'Osamodas', '', 0x08a3bc0208a4bc0208c0d00208c1d00208c1d302, '1', 'None'),
(12705, 'Soif de Sang', 'Vole de la vie dans l\'élément Neutre. \nSoigne le lanceur et tous les alliés dans l\'état Perfusion à hauteur de 50% des dommages occasionnés à la cible.', 0x08abbc0208acbc0208adbc02, '1', 'Agressive'),
(12714, 'Soif de Sang', '', 0x08b7bc0208d2810308ffb3030880b403, '0', 'Debuff'),
(12718, 'Le Sang de Sacrieur', '', 0x089ed002, '0', 'Agressive'),
(12723, 'Furie', 'Occasionne des dommages Air. N\'affecte pas le lanceur.\nLes dommages sont plus importants selon la Souffrance du lanceur.', 0x08d7bc0208dbbc02, '1', 'Agressive'),
(12724, 'Fulgurance', 'Téléporte le lanceur sur la première case disponible entre la cible et lui et occasionne des dommages Air aux ennemis en ligne jusqu\'à la case ciblée.', 0x08d8bc0208d9bc02, '1', 'Teleport'),
(12725, 'Supplice', 'Vole de la vie dans l\'élément Terre.\nLes entités qui attaquent la cible sont soignées d\'une partie des dommages occasionnés.', 0x08ddbc0208debc02, '1', 'Agressive'),
(12726, 'Projection', 'Téléporte le lanceur symétriquement par rapport à la cible et occasionne des dommages Eau aux ennemis.', 0x08e0bc02, '1', 'Agressive'),
(12727, 'Nervosité', 'Occasionne des dommages Eau en zone. N\'affecte pas le lanceur.\nLes dommages sont plus importants selon la Souffrance du lanceur.', 0x08e3bc0208e4bc0208e5bc02, '1', 'Agressive'),
(12728, 'Stase', 'Vole de la vie dans l\'élément Eau et réduit les chances de Critique.', 0x08e6bc0208e7bc02, '1', 'Agressive'),
(12729, 'Afflux', 'Attire les cibles vers le centre et occasionne des dommages Terre aux ennemis en zone.', 0x08e9bc02, '1', 'Agressive'),
(12730, 'Douleur Cuisante', 'Occasionne des dommages Feu en zone. N\'affecte pas le lanceur.\nLes dommages sont plus importants selon la Souffrance du lanceur.', 0x08ecbc0208edbc0208eebc02, '1', 'Agressive'),
(12731, 'Décimation', 'Occasionne des dommages Terre en zone.\nLes dommages sont plus importants selon la Souffrance du lanceur.\n\nN\'affecte pas le lanceur.', 0x08efbc0208f3bc0208f4bc02, '1', 'Agressive'),
(12732, 'Bain de Sang', 'Augmente le Tacle du lanceur pour chaque ennemi dans la zone d\'effet et vole de la vie dans l\'élément Terre en zone.\nLe vol de vie n\'affecte pas le lanceur.', 0x08f0bc0208f1bc0208f2bc02, '1', 'Agressive'),
(12733, 'Assaut', 'Échange de position avec la cible et occasionne des dommages Air aux ennemis.', 0x08f5bc0208f6bc0208f7bc02, '1', 'Agressive'),
(12734, 'Absorption', 'Vole de la vie dans l\'élément Feu et retire de la Puissance.', 0x08f8bc0208f9bc0208fabc02, '1', 'Agressive'),
(12735, 'Attirance', 'Attire la cible.\nSi la cible est un allié, lui applique également l\'état Perfusion. N\'affecte pas le lanceur.\n\nLa portée maximale du sort augmente avec la Souffrance du lanceur :\n• Souffrance 1 à 2 : +1 PO\n• Souffrance 3 à 4 : +2 PO\n• Souffrance 5 à 6 : +3 PO\n• Souffrance 7 à 8 : +4 PO\n• Souffrance 9 à 10 : +5 PO', 0x08fbbc0208fcbc0208fdbc02, '1', 'Agressive'),
(12736, 'Transposition', 'Échange de position avec la cible.\n\nLa portée maximale du sort augmente avec la Souffrance du lanceur :\n• Souffrance 1 à 2 : +3 PO\n• Souffrance 3 à 4 : +4 PO\n• Souffrance 5 à 6 : +5 PO\n• Souffrance 7 à 8 : +6 PO\n• Souffrance 9 à 10 : +7 PO', 0x08febc0208ffbc020880bd02, '1', 'Agressive'),
(12737, 'Mutilation', 'Sacrifie une partie des points de vie du lanceur pour augmenter sa Puissance.\nÀ chaque début de tour du lanceur, sacrifie de nouveau une partie de ses points de vie pour augmenter son état de Mutilation tant que le sort est actif.\nRelancer le sort retire les effets appliqués et lance le sort Coagulation.\n\nCoagulation : applique un bouclier sur le lanceur.\nLe bouclier est plus important selon l\'état de Mutilation.', 0x0881bd020895d3020896d302, '1', 'Agressive'),
(12738, 'Transfusion', 'Transfère 10% des points de vie du lanceur aux alliés en zone.\nSi au moins un allié est dans l\'état Perfusion, transfère 10% supplémentaires aux alliés dans l\'état.', 0x0884bd020885bd020886bd02, '1', 'Agressive'),
(12739, 'Sacrifice', 'Le lanceur subit les dommages à la place des alliés dans la zone d\'effet.\n\nSur des Épées du lanceur : les tue pour lui transférer 50% de leurs points de vie restants.', 0x0887bd020888bd020889bd02, '1', 'Agressive'),
(12740, 'Folie Sanguinaire', 'Vole de la vie dans le meilleur élément d\'attaque du lanceur.\nRebondit sur l\'entité la plus proche dans une zone de 2 cases.\nLe vol de vie est doublé sur les Épées du lanceur.\n\nN\'affecte pas le lanceur.', 0x08f7d002, '1', 'Agressive'),
(12741, 'Punition', 'Occasionne des dommages dans le meilleur élément d\'attaque du lanceur et des dommages Neutre selon ses points de vie érodés.', 0x088dbd020882d502, '1', 'Agressive'),
(12743, 'Berserk', 'Sacrifie une partie des points de vie du lanceur et lui applique l\'état Insoignable pour augmenter ses dommages aux sorts.\nRelancer le sort retire les effets appliqués mais ne rend pas les points de vie sacrifiés.\n\nLe coût en PA du sort est remboursé de moitié à son activation.', 0x0891bd0208d9f702, '1', 'Buff'),
(12744, 'Épée Vorace', 'Invoque une Épée Vorace maîtrisable qui vole de la vie dans l\'élément Neutre et soigne le lanceur et tous les alliés dans l\'état Perfusion à hauteur de 50% des dommages qu\'elle occasionne.', 0x0894bd020895bd020896bd02, '1', 'Summon'),
(12745, 'Condensation', 'Occasionne des dommages Eau aux ennemis et attire les cibles vers le lanceur en zone.', 0x0897bd02089bd302089cd302, '1', 'Agressive'),
(12746, 'Ravage', 'Rapproche le lanceur de la cible et occasionne des dommages Terre aux ennemis.', 0x0898bd020899d302089ad302, '1', 'Agressive'),
(12747, 'Immolation', 'Sacrifie une partie des points de vie du lanceur pour occasionner des dommages Feu en zone.\nLes dommages n\'affectent pas le lanceur.', 0x0899bd020894d302, '1', 'Debuff'),
(12748, 'Hémorragie', 'Vole de la vie dans l\'élément Air et retire du Tacle.', 0x089abd02088fd3020890d302, '1', 'Agressive'),
(12749, 'Aversion', 'Occasionne des dommages Feu aux ennemis en zone et repousse les cibles depuis le centre de la zone.', 0x089bbd02, '1', 'Agressive'),
(12750, 'Hécatombe', 'Réduit les soins reçus par les cibles et vole de la vie dans l\'élément Feu en zone.\nN\'affecte pas le lanceur.', 0x089cbd02, '1', 'Buff'),
(12751, 'Entaille', 'Sacrifie une partie des points de vie du lanceur pour occasionner des dommages Terre.', 0x089dbd02, '1', 'Debuff'),
(12752, 'Carnage', 'Sacrifie une partie des points de vie du lanceur pour occasionner des dommages Air en zone.', 0x089ebd02, '1', 'Debuff'),
(12753, 'Désolation', 'Retire des PM et vole de la vie dans l\'élément Air en zone.', 0x089fbd020891d302, '1', 'Debuff'),
(12754, 'Riposte', 'Rapproche le lanceur de la cible. \n\nPendant 1 tour, rapproche le lanceur de l\'ennemi ciblé si le lanceur subit des dommages ennemis.\n\nLa portée du sort augmente avec la Souffrance du lanceur :\n• Souffrance 2 à 4 : +1 PO\n• Souffrance 5 à 7 : +2 PO\n• Souffrance 8 à 10 : +3 PO\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08a0bd02, '1', 'Agressive'),
(12755, 'Déchaînement', 'Sacrifie une partie des points de vie du lanceur pour occasionner des dommages Eau en zone.\nLes dommages n\'affectent pas le lanceur.', 0x08a1bd020892d302, '1', 'Debuff'),
(12756, 'Hostilité', 'Occasionne des dommages Feu aux ennemis et repousse la cible.', 0x08a2bd02089dd302089ed302, '1', 'Agressive'),
(12757, 'Dissolution', 'Vole de la vie dans l\'élément Eau et retire de la Fuite en zone.\nN\'affecte pas le lanceur.', 0x08a3bd02, '1', 'Agressive'),
(12758, 'Perfusion', 'Applique l\'état Perfusion sur les alliés (hors lanceur) en zone.\n\nPendant 2 tours, les alliés dans l\'état Perfusion sont soignés d\'une partie des dommages occasionnés au lanceur.\nCet effet ne peut pas être désenvoûté.', 0x08a4bd020893d302, '1', 'Agressive'),
(12759, 'Libation', 'Sacrifie une partie des points de vie du lanceur pour le soigner à la fin de son prochain tour.\nLes soins sont plus importants selon sa Souffrance.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08a5bd0208a1d302, '1', 'Agressive'),
(12760, 'Châtiment', 'Applique l\'état Pesanteur sur les cibles en zone et un bouclier sur le lanceur.\nApplique un bouclier supplémentaire sur le lanceur pour chaque ennemi touché.', 0x08a6bd020897d302, '1', 'Agressive'),
(12761, 'Couronne d\'Épines', 'Applique l\'état Couronne d\'Épines sur le lanceur :\n• Renvoie 100% des dommages finaux subis en mêlée à ses attaquants ennemis.\n\nSi le lanceur est en Souffrance 6 ou plus, lui applique l\'état Couronne d\'Épines du Martyr :\n• Renvoie 100% des dommages finaux subis en mêlée aux ennemis dans un cercle de 2 cases autour de lui.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08a7bd02089fd30208a0d302, '1', 'Agressive'),
(12762, 'Pacte de Sang', 'Augmente la Vitalité du lanceur mais sacrifie temporairement une partie de ses points de vie.', 0x08a8bd02, '1', 'Healing'),
(12763, 'Fluctuation', 'Rend Intaclable le lanceur et augmente ses PM.\nSi le lanceur est en Souffrance 6 ou plus, rend également Intaclables ses Épées et leur donne 2 PM pour 1 tour.\n\nLe bonus de PM sur le lanceur est plus important selon sa Souffrance :\n- Souffrance 1 : 1 PM\n- Souffrance 2 à 4 : 2 PM\n- Souffrance 5 à 7 : 3 PM\n- Souffrance 8 à 10 : 4 PM\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08a9bd02, '1', 'Buff'),
(12764, 'Pénitence', 'Échange de position avec l\'allié ciblé.\nPendant 1 tour, si l\'allié subit des dommages, échange de position avec lui.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08aabd02, '1', 'Agressive'),
(12765, 'Épée Dansante', 'Invoque une Épée Dansante maîtrisable qui occasionne des dommages Neutre aux ennemis, attire et augmente la Fuite de tous les alliés dans l\'état Perfusion.', 0x08abbd020898d302, '1', 'Summon'),
(12767, 'Perfusion', '', 0x08adbd0208b5bd0208cdf702, '0', 'None'),
(12769, 'Pénitence', '', 0x08afbd0208ebea03, '0', 'None'),
(12770, 'Riposte', '', 0x08b0bd0208b6bd020889b403, '0', 'Agressive'),
(12771, 'Condensation', '', 0x08b1bd02, '0', 'Agressive'),
(12772, 'Berserk', '', 0x08b3bd02, '0', 'Debuff'),
(12775, 'Coagulation', '', 0x08b8bd02, '0', 'Buff'),
(12777, 'Ivresse', 'Invoque un Tonneau de l\'Ivrogne qui soigne son invocateur lorsqu\'il est porté et lui applique l\'état Saoul quand il est jeté.\nLe lanceur soigne également ses alliés dans un cercle de 2 cases autour du point d\'impact.\n\nLe coût en PA des sorts Karcham et Chamrak est remboursé si le lanceur porte son Tonneau.\n\nSi le Tonneau du lanceur est encore en vie et que le sort est relancé, l\'ancien est tué pour laisser place au nouveau.', 0x08babd02, '1', 'Agressive'),
(12778, 'Méditation Ivre', 'Augmente la Vitalité, l\'Agilité et les PM du lanceur.', 0x08bdbd0208bebd02, '1', 'Buff'),
(12779, 'Révérence Alcoolisée', 'Jette l\'invocateur porté par le lanceur sur la case ciblée.\n\nNécessite l\'état Porteur.', 0x08c0bd02, '1', 'None'),
(12780, 'Picole', 'Applique l\'état Saoul sur le lanceur.\n\nSi le lanceur est dans l\'état Saoul : applique l\'état Sobre et augmente les PM du lanceur.', 0x08c3bd0208dfd502, '1', 'Agressive'),
(12781, 'Paume Explosive', 'Occasionne des dommages Feu.\nLe coût en PA du sort est augmenté après le premier lancer.\n\n• Si le lanceur est dans l\'état Sobre : la zone d\'effet devient un cercle de 2 cases pour le tour en cours.\n• Si le lanceur est dans l\'état Saoul : les dommages du sort sont augmentés pour le tour en cours.\nChaque effet est cumulable une fois.\n\nLes dommages n\'affectent pas le lanceur.', 0x08c4bd0208f9dd0308fadd03, '1', 'Agressive'),
(12782, 'Schnaps', 'Occasionne des dommages Air et retire du Retrait PM en zone.\n\nSi le lanceur est dans l\'état Saoul : occasionne des dommages Air et retire du Retrait PA en zone.\n\nN\'affecte pas le lanceur.', 0x08c7bd0208c8bd0208c9bd02, '1', 'Agressive'),
(12783, 'Épouvante', 'Repousse la cible.\n\nSi le lanceur est dans l\'état Saoul : réduit les chances d\'effectuer un coup critique et repousse la cible.\nLa poussée est plus faible dans l\'état Saoul.', 0x08cabd0208cbbd0208ccbd02, '1', 'Agressive'),
(12784, 'Souffle Alcoolisé', 'Occasionne des dommages Air aux ennemis et repousse les cibles en zone.\n\nNécessite l\'état Saoul.', 0x08cdbd0208cebd02, '1', 'Agressive'),
(12785, 'Bambouseraie', 'Invoque plusieurs Petits <font color=\"#ebc304\">{spell,12824,1::Bambous}</font> en zone.\n\nLes Bambous meurent au début du prochain tour du lanceur, et sont indépendants de son nombre maximal d\'invocations.', 0x08d0bd02, '1', 'Summon'),
(12786, 'Ribote', 'Applique l\'état Saoul sur le lanceur et occasionne des dommages Terre.\n\nSi le lanceur est dans l\'état Saoul : occasionne des dommages Terre et retire de la Fuite.', 0x08d3bd0208d4bd02, '1', 'Agressive'),
(12787, 'Karcham', 'Porte la cible en appliquant l\'état Porteur sur le lanceur et en augmentant la Portée du sort.\n\nSi le lanceur est dans l\'état Porteur : jette la cible sur la case ciblée.\n\nNécessite l\'état Sobre.', 0x08d6bd0208a1be0208a2be02, '1', 'None'),
(12788, 'Propulsion', 'Jette la cible sur la case ciblée, occasionne des dommages Air aux ennemis et repousse les cibles en zone.\n\nNécessite l\'état Porteur.', 0x08d7bd0208d8bd020882de03, '1', 'Agressive'),
(12789, 'Stabilisation', 'Applique l\'état Enraciné sur la cible et augmente l\'Esquive PM.\n\nNécessite l\'état Sobre.', 0x08dabd0208dbbd0208dcbd02, '1', 'Buff'),
(12790, 'Éviction', 'Téléporte le lanceur symétriquement par rapport à la cible et occasionne des dommages Terre aux ennemis.\n\nSi le lanceur est dans l\'état Saoul : téléporte la cible symétriquement par rapport au lanceur et occasionne des dommages Terre aux ennemis en zone.', 0x08ddbd0208debd0208a2e103, '1', 'Agressive'),
(12791, 'Ethylo', 'Occasionne des dommages Eau et augmente la Portée du lanceur.\n\nSi le lanceur est dans l\'état Saoul : occasionne des dommages Eau et retire de la Portée.', 0x08e0bd0208e1bd0208e2bd02, '1', 'Agressive'),
(12792, 'Souillure', 'Réduit la durée des effets sur la cible et retire de la Puissance aux ennemis.\n\nNécessite l\'état Saoul.', 0x08e3bd0208e4bd0208e5bd02, '1', 'Debuff'),
(12793, 'Pandikulation', 'Jette la cible sur la case ciblée, attire les cibles vers le centre et occasionne des dommages Feu aux ennemis en zone.\n\nNécessite l\'état Porteur.', 0x08e6bd0208e7bd0208e8bd02, '1', 'Agressive'),
(12794, 'Vague à Lame', 'Occasionne des dommages Eau aux ennemis et repousse les cibles en zone.\n\nSi le lanceur est dans l\'état Saoul : occasionne des dommages Eau en zone.\nLa portée du sort est réduite de moitié mais les dommages sont plus importants.', 0x08e9bd0208eabd02, '1', 'Agressive'),
(12796, 'Flasque Explosive', 'Occasionne des dommages Feu en zone.\nN\'affecte pas le lanceur.\n\nLa portée du sort est réduite de moitié mais les dommages sont plus importants si le lanceur est dans l\'état Saoul.', 0x08efbd0208f0bd020890de03, '1', 'Agressive'),
(12797, 'Pandatak', 'Occasionne des dommages Terre en zone.\n\nLa portée du sort est réduite de moitié mais les dommages sont plus importants si le lanceur est dans l\'état Saoul.', 0x08f2bd02, '1', 'Agressive'),
(12798, 'Pandanlku', 'Augmente les PM de l\'allié ciblé.\n\nNécessite l\'état Saoul.', 0x08f5bd0208a5e103, '1', 'Buff'),
(12799, 'Lien Spiritueux', 'Invoque un Pandawasta maîtrisable qui retire de la Fuite, de la Puissance et tacle les adversaires.\nIl peut également augmenter ses caractéristiques pendant le combat ou porter le lanceur dans l\'état Sobre si ce dernier l\'attaque en mêlée.\n\nLe Pandawasta réduit de 50% les dommages immédiats alliés.\n\nSi le Pandawasta du lanceur est encore en vie et que le sort est relancé, l\'ancien est tué pour laisser place au nouveau.\n\nNécessite l\'état Saoul.', 0x08f8bd0208f9bd02, '1', 'Agressive'),
(12800, 'Coup de Bambou', 'Retire de la Fuite et de la Puissance.', 0x08fbbd0208fcbd02, '1', 'Debuff'),
(12803, 'Gueule de Bois', 'Applique l\'état Sobre sur le lanceur et occasionne des dommages Terre.\nLes dommages sont plus importants si le lanceur est sorti de l\'état Saoul pendant le tour en cours.', 0x0884be0208e2d50208f7dd03, '1', 'Agressive'),
(12804, 'Bombance', 'Applique l\'état Saoul sur le lanceur.\n\nSi le lanceur est dans l\'état Saoul : applique l\'état Sobre et rend 1 PA au lanceur.', 0x0885be0208ddd50208ded502, '1', 'Agressive'),
(12805, 'Souffle Enflammé', 'Occasionne des dommages Feu et réduit les chances de Critique en zone.\n\nNécessite l\'état Saoul.', 0x0886be02089ae103, '1', 'Agressive'),
(12806, 'Consolation', 'Attire et soigne l\'allié ciblé.', 0x0887be0208e3d502, '1', 'Agressive'),
(12807, 'Engourdissement', 'Augmente les PM du lanceur pour chaque entité dans la zone d\'effet (cumulable 3 fois) et occasionne des dommages Air en zone.\n\nSi le lanceur est dans l\'état Saoul : occasionne des dommages Air et retire des PM en zone.\n\nN\'affecte pas le lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0888be0208e5d502, '1', 'Agressive'),
(12808, 'Eau-de-vie', 'Jette la cible sur la case ciblée, occasionne des dommages Eau aux ennemis et soigne les alliés en zone.\nN\'affecte pas le lanceur.\n\nNécessite l\'état Porteur.', 0x0889be020883de030884de03, '1', 'Agressive'),
(12809, 'Liqueur', 'Applique l\'état Saoul sur le lanceur et vole de la vie dans l\'élément Air.', 0x088abe02, '1', 'Agressive'),
(12810, 'Chamrak', 'Porte la cible en appliquant l\'état Porteur sur le lanceur et en augmentant la Portée du sort.\n\nSi le lanceur est dans l\'état Porteur : jette la cible sur la case ciblée sans ligne de vue.\n\nNécessite l\'état Sobre.', 0x088bbe0208edd502, '1', 'None'),
(12811, 'Brancard', 'Jette la cible sur la case ciblée, attire les entités survolées vers la case ciblée, rapproche le lanceur de la cible et occasionne des dommages Terre aux ennemis en ligne jusqu\'à la case ciblée.\n\nNécessite l\'état Porteur.', 0x088cbe0208c5fb0308c6fb03, '1', 'Agressive'),
(12813, 'Varappe', 'Augmente le nombre de lancer maximal par tour et par cible des sorts Karcham ou Chamrak du lanceur et rend l\'allié ciblé Intaclable.\n\nLes effets ne peuvent pas être désenvoûtés.\n\nNécessite l\'état Sobre.', 0x088ebe02, '1', 'Buff'),
(12814, 'Nausée', 'Éloigne le lanceur de la cible et occasionne des dommages Air aux ennemis.\n\nSi le lanceur est dans l\'état Saoul : réduit les Résistances Poussée et occasionne des dommages Air aux ennemis.\nLa portée du sort est réduite de moitié mais les dommages sont plus importants.', 0x088fbe02, '1', 'Agressive'),
(12815, 'Distillation', 'Occasionne des dommages Eau et applique l\'état Distillation sur les ennemis en zone :\n• Applique un poison Eau de début de tour à retardement en zone sur 2 tours.\n• Les dommages du poison sont plus importants sur le deuxième tour.\nLes poisons ne sont pas réappliqués sur les cibles déjà dans l\'état Distillation.\n\nSi le lanceur est dans l\'état Saoul : occasionne des dommages Eau en zone.\n\nN\'affecte pas le lanceur.', 0x0890be0208f8dd03, '1', 'Agressive'),
(12816, 'Brassage', 'Augmente les dommages subis par la cible.\n\nSi le lanceur est dans l\'état Saoul :\n• Applique l\'état Pesanteur sur la cible.\n• Applique l\'état Brassage sur le lanceur, qui empêche l\'utilisation du sort s\'il est Saoul.\n\nLa portée du sort est modifiable dans l\'état Sobre, mais elle est réduite de moitié dans l\'état Saoul.', 0x0891be02, '1', 'Agressive'),
(12817, 'Prohibition', 'Applique l\'état Insoignable sur la cible et la rend Invulnérable aux dommages en mêlée.\n\nSur le lanceur :\n• Rend Invulnérable en mêlée.\n• Applique l\'état Sobre.\n• Applique l\'état Prohibition, qui empêche l\'entrée dans l\'état Saoul et l\'application des effets des Tonneaux sur lui.\n• Applique l\'état Insoignable au début du prochain tour.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0892be02, '1', 'Agressive'),
(12819, 'Fermentation', 'Applique immédiatement un bouclier sur le lanceur et au tour suivant.\n\nNécessite l\'état Saoul.', 0x0894be0208b1fd0308b2fd03, '1', 'Buff'),
(12820, 'Absinthe', 'Applique l\'état Saoul sur le lanceur et vole de la vie dans l\'élément Feu.', 0x0895be02, '1', 'Agressive'),
(12821, 'Bistouille', 'Applique l\'état Saoul sur le lanceur et vole de la vie dans l\'élément Terre en zone.\n\nN\'affecte pas le lanceur.', 0x0896be02, '1', 'Agressive'),
(12822, 'Cascade', '', 0x0897be02, '0', 'Agressive'),
(12823, 'Cascade', 'Jette la cible sur la case ciblée, soigne les alliés et occasionne des dommages Eau aux ennemis en zone.\nRepousse également les entités survolées.\n\nNécessite l\'état Porteur.', 0x0898be02, '1', 'Agressive'),
(12824, 'Bambou', 'Invoque un Bambou qui sert d\'obstacle.\nIl peut porter le lanceur dans l\'état Sobre si ce dernier l\'attaque en mêlée.\n\nLe Bambou réduit de 80% les dommages immédiats alliés.\n\nLe coût en PA des sorts Karcham et Chamrak est remboursé si le lanceur porte un de ses Bambous.', 0x0899be02, '1', 'Summon'),
(12825, 'Bambouseraie', '', 0x089abe0208bedf03089ee603, '0', 'Buff'),
(12826, 'Ébriété', 'Invoque un Tonneau de l\'Éméché qui augmente la Puissance de son invocateur lorsqu\'il est porté et lui applique l\'état Saoul quand il est jeté.\nLe lanceur occasionne également des dommages dans son meilleur élément d\'attaque aux ennemis dans un cercle de 2 cases autour du point d\'impact.\n\nLe coût en PA des sorts Karcham et Chamrak est remboursé si le lanceur porte son Tonneau.\n\nSi le Tonneau du lanceur est encore en vie et que le sort est relancé, l\'ancien est tué pour laisser place au nouveau.', 0x089bbe02089efe03089ffe03, '1', 'Agressive'),
(12828, 'Brancard', '', 0x089dbe02, '0', 'Agressive'),
(12829, 'Potion Magique', '', 0x089ebe0208fedd0308ffdd03, '1', 'Agressive'),
(12830, 'La Chopine de Pandawa', '', 0x08a0be020893df030894df030895df030896df030897df03, '0', 'Agressive'),
(12831, 'Bambouseraie', '', 0x08a5be0208a6be0208c9df03, '0', 'None'),
(12832, 'Karcham', '', 0x08a9be0208aabe0208abbe02, '0', 'Buff'),
(12833, 'Chamrak', '', 0x08acbe0208ecd502, '0', 'Buff'),
(12835, 'Picole', '', 0x08aebe02, '0', 'None'),
(12836, 'Karchamrak', '', 0x08afbe0208b0be0208cfdf03, '0', 'Buff'),
(12840, 'Roulette', 'Invoque une Roulette qui procure un bonus aléatoire à tout le monde au début de son tour.\n\nIl ne peut y avoir qu\'une seule Roulette par équipe. Si la Roulette est encore en vie et que celle-ci est réinvoquée, l\'ancienne est tuée pour laisser place à la nouvelle.', 0x08b9be0208babe0208bbbe02, '1', 'Agressive'),
(12841, 'Pile ou Face', 'Occasionne des dommages Terre.\nLes dommages du sort sont plus faibles au tour suivant.', 0x08b6be0208b7be0208b8be02, '1', 'Agressive'),
(12842, 'Chance d\'Ecaflip', 'Réduit immédiatement les dommages subis par l\'allié ciblé mais les augmente au tour suivant.', 0x08bcbe0208bdbe0208bebe02, '1', 'Buff'),
(12843, 'Trèfle', 'Transfère les chances de Critique de la Pièce d\'Ecaflip du lanceur à la cible pendant 2 tours.\n\nRetire les effets de la Pièce d\'Ecaflip sur le lanceur.', 0x08bfbe02088ad602088bd602, '1', 'Debuff'),
(12844, 'Bond du Félin', 'Augmente les PM de la cible.', 0x08c2be0208c3be0208c4be02, '1', 'Buff'),
(12845, 'Roue de la Fortune', 'Augmente la Puissance des sorts de la cible.', 0x08c5be0208c6be0208c7be02, '1', 'Buff'),
(12846, 'Topkaj', 'Occasionne des dommages Feu.', 0x08c8be0208c9be0208cabe02, '1', 'Agressive'),
(12847, 'Esprit Félin', 'Occasionne des dommages Terre aux ennemis et téléporte le lanceur symétriquement par rapport à la cible.', 0x08cbbe0208ccbe0208cdbe02, '1', 'Agressive'),
(12848, 'Bluff', 'Érode la cible et occasionne des dommages Eau.\nLe cumul de l\'Érosion est partagé avec les sorts Réflexes, Face ou Pile et Miaouch.', 0x08cebe0208cfbe0208d0be02, '1', 'Agressive'),
(12849, 'Griffe Joueuse', 'Occasionne des dommages Eau en zone.', 0x08d1be0208d2be02, '1', 'Agressive'),
(12850, 'Contrecoup', 'Applique immédiatement un bouclier sur la cible mais réduit ses dommages finaux au tour suivant.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08d4be0208d5be0208d6be02, '1', 'Agressive'),
(12851, 'Griffe de Ceangal', 'Repousse la cible, rapproche le lanceur et occasionne des dommages Air aux ennemis.', 0x08d7be0208d8be02, '1', 'Agressive'),
(12852, 'Perception', 'Soigne l\'allié ciblé pour chaque ennemi dans la zone d\'effet et dévoile les invisibles en zone.', 0x08dabe0208dbbe0208dcbe02, '1', 'Agressive'),
(12853, 'Rekop', 'Occasionne des dommages Feu, Terre, Air et Eau à retardement au début du tour du lanceur.\nLes dommages sont plus importants selon le retardement.\n\nUne partie du coût en PA peut être remboursée au lancer selon le retardement :\n• 100% des dommages dans 1 tour : + 2 PA.\n• 150% des dommages dans 2 tours : + 1 PA.\n• 200% des dommages dans 3 tours : aucun PA remboursé.', 0x08ddbe0208debe02, '1', 'Agressive'),
(12854, 'Odorat', 'Retire immédiatement des PA non esquivables pour augmenter les PM en zone.\nRetire des PM non esquivables pour augmenter les PA au tour suivant.\n\nLe retrait de PA n\'affecte pas le lanceur.', 0x08e0be0208e1be0208e2be02, '1', 'Debuff'),
(12855, 'Langue Râpeuse', 'Retire immédiatement de la Portée et occasionne des dommages Feu aux ennemis en zone.\nAugmente leur Portée au tour suivant.\n\nSur les alliés : augmente immédiatement la Portée mais en retire au tour suivant.', 0x08e3be0208e4be0208e5be02, '1', 'Agressive'),
(12856, 'Griffe Invocatrice', 'Invoque un Chaton Enragé maîtrisable qui vole de la vie dans l\'élément Eau.\nÀ chaque fois qu\'il attaque, le Chaton Enragé augmente la Puissance de son invocateur. Cet effet ne peut pas être désenvoûté.', 0x08e6be0208e7be0208e8be02, '1', 'Summon'),
(12857, 'Réflexes', 'Érode les cibles et occasionne des dommages Air en zone.\nLe cumul de l\'Érosion est partagé avec les sorts Bluff, Face ou Pile et Miaouch.', 0x08e9be0208eabe0208ebbe02, '1', 'Agressive'),
(12858, 'Tout ou Rien', 'Sur les ennemis en zone : occasionne immédiatement des dommages Eau en zone et soigne les cibles au tour suivant.\n\nSur les alliés en zone : soigne immédiatement les cibles en zone et occasionne des dommages Eau au tour suivant.\n\nLe lanceur est toujours affecté en premier, qu\'il soit ou non dans la zone d\'effet.', 0x08ecbe0208edbe0208eebe02, '1', 'Agressive'),
(12859, 'Destin d\'Ecaflip', 'Occasionne des dommages Terre aux ennemis, attire et repousse la cible.\nPendant 1 tour, si l\'ennemi ciblé subit des dommages de poussée, lui retire des PM.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08efbe0208f0be02, '1', 'Agressive'),
(12860, 'Chatataque', 'Vole de la vie dans l\'élément Eau et augmente la Puissance de l\'invocateur.\nLa Puissance ne peut pas être désenvoûtée.', 0x08f2be0208f3be0208f4be02, '1', 'Agressive'),
(12861, 'Félintion', 'Vole de la vie dans l\'élément Eau aux ennemis et repousse la cible.', 0x08f5be0208f6be02, '1', 'Agressive'),
(12863, 'Aubaine', 'Soigne l\'allié ciblé mais augmente ses dommages subis.', 0x08febe020882d602, '1', 'Healing'),
(12864, 'Toupet', 'Occasionne des dommages Air et réduit les Résistances Poussée.', 0x08ffbe020883d602, '1', 'Agressive'),
(12865, 'Entrechat', 'Téléporte le lanceur sur la case ciblée et augmente la Fuite des alliés en zone.', 0x0880bf020884d602, '1', 'Teleport'),
(12866, 'Face ou Pile', 'Érode la cible et occasionne des dommages Terre.\nLe cumul de l\'Érosion est partagé avec les sorts Bluff, Réflexes et Miaouch.', 0x0881bf020880d602, '1', 'Agressive'),
(12867, 'Rugissement', 'Augmente la Puissance du lanceur pour chaque ennemi dans la zone d\'effet et dévoile les invisibles en zone.', 0x0882bf020888d602, '1', 'Agressive'),
(12868, 'Corollaire', 'Érode les ennemis en zone.', 0x0883bf02, '1', 'Debuff'),
(12869, 'Caresse Invocatrice', 'Invoque un Chaton Guérisseur maîtrisable qui soigne les alliés.', 0x0884bf020886d602, '1', 'Summon'),
(12870, 'Péril', 'Occasionne des dommages Eau aux invocations et soigne les cibles qui ne sont pas des invocations en zone.\nN\'affecte pas le lanceur.', 0x0885bf02, '1', 'Agressive'),
(12871, 'Coup du Sort', 'Invoque un Coup du Sort qui donne un bonus aléatoire à son attaquant lorsqu\'il est attaqué.\nDonne un bonus aléatoire à son invocateur lorsqu\'il est invoqué.\n\nIl ne peut y avoir qu\'un seul Coup du Sort par équipe. Si le Coup du Sort est encore en vie et que celui-ci est réinvoqué, l\'ancien est tué pour laisser place au nouveau.', 0x0886bf02, '1', 'Agressive'),
(12872, 'Feulement', 'Occasionne des dommages Feu aux ennemis et soigne les alliés en zone.', 0x0887bf020885d602, '1', 'Agressive'),
(12873, 'Lapement', 'Occasionne des dommages Terre et retire des PM.\nDonne 1 PM à la cible au tour suivant.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0888bf02, '1', 'Agressive'),
(12874, 'Mistigri', 'Soigne immédiatement l\'allié ciblé puis à chaque début de tour du lanceur pendant 2 tours.\nLes soins sont plus faibles sur le lanceur.', 0x0889bf02, '1', 'Healing'),
(12875, 'Coussinets', 'Éloigne le lanceur de la cible et occasionne des dommages Feu aux ennemis.', 0x088abf02, '1', 'Agressive'),
(12876, 'Bonne Étoile', 'Soigne la cible.\n\nPendant 2 tours, soigne l\'allié ciblé (hors lanceur) s\'il est attiré, poussé ou transposé.\nLes soins peuvent être déclenchés 3 fois par tour.', 0x088bbf02, '1', 'Healing'),
(12877, 'Redistribution', 'Rend Intaclables les cibles en zone et leur applique l\'état Pesanteur au tour suivant.', 0x088cbf02, '1', 'Agressive'),
(12878, 'Fanfaronnade', 'Augmente les Dommages Poussée du lanceur pour chaque ennemi dans la zone d\'effet et occasionne des dommages Air en zone.\nLes dommages n\'affectent pas le lanceur.', 0x088dbf02, '1', 'Agressive'),
(12879, 'Mésaventure', 'Occasionne des dommages Terre dans un anneau de 2 cases.\nSi le lanceur effectue un coup critique, le prochain lancer vole également de la vie dans l\'élément Terre à l\'intérieur de l\'anneau.\n\nN\'affecte pas le lanceur.', 0x088ebf02, '1', 'Agressive'),
(12880, 'Infortune', 'Occasionne des dommages Eau et donne 1 PM au lanceur.', 0x088fbf02, '1', 'Agressive'),
(12881, 'Tromperie', 'Occasionne des dommages Terre, Air, Eau ou Feu.\nLe coût en PA, les dommages et l\'élément d\'attaque sont modifiés aléatoirement à chaque lancer et à chaque fois que le lanceur effectue un coup critique :\n• Terre : 5 PA\n• Air : 4 PA\n• Eau : 3 PA\n• Feu : 2 PA', 0x0890bf02, '1', 'Agressive'),
(12882, 'Audace d\'Ecaflip', 'Repousse la cible, rapproche le lanceur et occasionne des dommages Terre aux ennemis.\nPendant 1 tour, si la cible subit des dommages de poussée, augmente la Puissance du lanceur.', 0x0891bf02, '1', 'Agressive'),
(12883, 'Kraps', 'Occasionne des dommages Eau aux ennemis en zone et repousse les cibles depuis le centre de la zone.', 0x0892bf02, '1', 'Agressive'),
(12884, 'Ronronnement', 'Soigne la cible.', 0x0893bf020894bf020895bf020896bf020897bf020898bf02, '1', 'Healing'),
(12885, 'Coup du Sort', '', 0x0899bf02, '1', 'Buff'),
(12886, 'Coup du Sort', '', 0x089abf02089bbf02, '1', 'Buff'),
(12887, 'Coup du Sort', '', 0x089cbf02, '0', 'Agressive'),
(12888, 'Tromperie', '', 0x089dbf02089ebf02089fbf0208a0bf02, '0', 'Buff'),
