(12892, 'Audace d\'Ecaflip', '', 0x08a4bf0208f8dc020884eb03, '0', 'None'),
(12893, 'Fanfaronnade', '', 0x08a5bf02, '0', 'Buff'),
(12894, 'Rugissement', '', 0x08a6bf020887d602, '0', 'Buff'),
(12896, 'Lapement', '', 0x08a8bf020882eb03, '1', 'None'),
(12899, 'Perception', '', 0x08abbf02, '0', 'Healing'),
(12900, 'Roulette', '', 0x08acbf0208adbf0208aebf0208afbf0208b0bf0208b1bf02, '0', 'Buff'),
(12901, 'Bonne Étoile', '', 0x08b2bf0208d3e00308e9ea03, '0', 'None'),
(12902, 'Truanderie', 'Occasionne des dommages Terre.', 0x08b3bf0208b4bf0208b5bf02, '1', 'Agressive'),
(12903, 'Concentration de Chakra', 'Pendant 1 tour, si l\'ennemi ciblé subit des dommages de pièges, vole de la vie dans le meilleur élément d\'attaque du lanceur.\n\nDissipe l\'invisibilité du lanceur.', 0x08b6bf0208b7bf0208b8bf02, '1', 'Agressive'),
(12904, 'Coup Sournois', 'Occasionne des dommages Feu aux ennemis et repousse la cible.', 0x08b9bf0208babf0208bbbf02, '1', 'Agressive'),
(12905, 'Fourberie', 'Vole de l\'Intelligence et occasionne des dommages Feu en zone.\nN\'affecte pas le lanceur.', 0x08bcbf02, '1', 'Debuff'),
(12906, 'Piège Sournois', 'Pose un piège qui occasionne des dommages Feu aux ennemis et attire les entités vers son centre en zone.', 0x08bfbf0208c0bf0208c1bf02, '1', 'Mark'),
(12907, 'Poison Insidieux', 'Applique un poison Air de début de tour sur la cible.', 0x08c2bf0208c3bf0208c4bf02, '1', 'Agressive'),
(12908, 'Peur', 'Pousse la cible jusqu\'à la case ciblée.', 0x08c5bf0208c6bf0208c7bf02, '1', 'None'),
(12909, 'Fourvoiement', 'Érode les cibles et occasionne des dommages Air en zone.\nN\'affecte pas le lanceur.', 0x08c8bf0208c9bf0208cabf02, '1', 'Debuff'),
(12910, 'Piège d\'Immobilisation', 'Pose un piège qui retire des PM aux ennemis en zone.', 0x08cbbf0208ccbf0208cdbf02, '1', 'Mark'),
(12911, 'Arnaque', 'Vole de l\'Agilité et occasionne des dommages Air.', 0x08cebf0208cfbf02, '1', 'Debuff'),
(12913, 'Invisibilité', 'Rend l\'allié ciblé invisible et augmente ses PM.\n\nLorsqu\'un Sram est rendu visible, il gagne 10% de dommages finaux pour sa prochaine attaque pendant 1 tour.\nL\'effet peut être déclenché qu\'une seule fois par tour.', 0x08d4bf0208d5bf0208d6bf02, '1', 'Buff'),
(12914, 'Piège Répulsif', 'Pose un piège qui repousse les entités et occasionne des dommages Air aux ennemis en zone.', 0x08d7bf0208d8bf0208d9bf02, '1', 'Mark'),
(12915, 'Double', 'Invoque un double contrôlable qui possède les mêmes caractéristiques que l\'invocateur.\nIl n\'attaque pas et meurt à la fin de son troisième tour en échangeant de position avec son invocateur.', 0x08dabf0208dbbf0208dcbf02, '1', 'Summon'),
(12916, 'Piège Fangeux', 'Pose un piège qui occasionne des dommages Eau.\nSoigne les alliés à hauteur de 50% des dommages occasionnés à l\'entité qui le déclenche dans un cercle de 2 cases autour d\'elle.', 0x08ddbf0208debf0208dfbf02, '1', 'Mark'),
(12917, 'Attaque Mortelle', 'Occasionne des dommages Terre.\nLes dommages sont plus importants sur les cibles ayant moins de 25% de leurs points de vie.', 0x08e0bf0208e2bf02, '1', 'Agressive'),
(12918, 'Piège Insidieux', 'Pose un piège mono-cellule qui pose un glyphe de fin de tour sur un cercle de 3 cases qui occasionne des dommages Air aux ennemis.', 0x08e3bf0208e4bf0208e5bf02, '1', 'Mark'),
(12919, 'Cruauté', 'Occasionne des dommages Eau et donne 1 PM au lanceur.', 0x08e6bf0208e7bf0208e8bf02, '1', 'Agressive'),
(12920, 'Piège de Masse', 'Pose un piège mono-cellule qui occasionne des dommages Terre dans un cercle de 3 cases.\nN\'affecte pas l\'allié qui déclenche le piège.', 0x08e9bf0208eabf0208ebbf02, '1', 'Mark'),
(12921, 'Piège Mortel', 'Occasionne des dommages Terre.\nLes dommages sont plus importants sur les entités ayant moins de 25% de leurs points de vie.', 0x08ecbf0208eebf02, '1', 'Mark'),
(12922, 'Poisse', 'Vole de la vie dans l\'élément Eau et minimise les effets aléatoires de la cible.', 0x08efbf02, '1', 'Agressive'),
(12923, 'Piège d\'Immobilisation', '', 0x08f2bf0208f3bf0208f4bf02, '1', 'Debuff'),
(12924, 'Piège de Masse', '', 0x08f5bf0208f7940308f894030888b8030889b803088ab803, '1', 'Agressive'),
(12926, 'Piège Insidieux', '', 0x08fbbf0208fcbf0208fdbf0208b7c00208b8c00208b9c002, '1', 'Agressive'),
(12927, 'Piège Mortel', '', 0x08febf0208ffbf02, '1', 'Agressive'),
(12928, 'Piège Répulsif', '', 0x0881c0020882c0020883c002, '1', 'Agressive'),
(12929, 'Piège Sournois', '', 0x0884c0020885c0020886c002, '0', 'Agressive'),
(12930, 'Brume', 'Pose un glyphe-aura qui rend les alliés invisibles.\n\nLorsqu\'un Sram est rendu visible, il gagne 10% de dommages finaux pour sa prochaine attaque pendant 1 tour.\nL\'effet peut être déclenché qu\'une seule fois par tour.', 0x0887c002088fd602, '1', 'Mark'),
(12931, 'Piège Scélérat', 'Pose un piège mono-cellule qui attire les entités vers son centre et occasionne des dommages Eau aux ennemis dans une croix de 3 cases.', 0x0888c002088dd602, '1', 'Mark'),
(12932, 'Chausse-trappe', 'Occasionne des dommages Terre.\nLes dommages du sort sont augmentés pour chaque piège du lanceur déclenché.\nLes effets sont retirés après utilisation du sort.', 0x0889c002088cd602, '1', 'Agressive'),
(12933, 'Toxines', 'Applique un poison Air de fin de tour sur l\'ennemi ciblé.\n\nTant que le poison est actif, si l\'ennemi ciblé subit des dommages de pièges, les dommages du sort sont augmentés et le poison est réappliqué.\nCet effet peut être déclenché une seule fois par tour.\n\nIl ne peut y avoir qu\'un seul ennemi sous les effets du sort.\nLe poison est cumulable une fois maximum.', 0x088ac0020890d602, '1', 'Agressive');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(12934, 'Pillage', 'Vole de la vie dans l\'élément Eau.\nSoigne les alliés à hauteur de 50% des dommages occasionnés à l\'ennemi ciblé dans un cercle de 2 cases autour de lui. N\'affecte pas le lanceur.', 0x088bc0020891d602, '1', 'Agressive'),
(12935, 'Coupe-gorge', 'Occasionne des dommages Feu.\nAugmente la Puissance du lanceur et de ses alliés dans un cercle de 2 cases autour de lui.', 0x088cc0020892d602, '1', 'Agressive'),
(12936, 'Comploteur', 'Invoque un double contrôlable qui possède les mêmes caractéristiques que l\'invocateur.\nIl n\'attaque pas et meurt à la fin de son troisième tour en occasionnant des dommages dans le meilleur élément d\'attaque du lanceur aux entités à son contact.\nLes dommages à la mort du Comploteur augmentent pour chaque piège déclenché du lanceur.', 0x088dc0020894d602, '1', 'Summon'),
(12937, 'Larcin', 'Vole de la Chance et occasionne des dommages Eau en zone.\nN\'affecte pas le lanceur.', 0x088ec0020895d602, '1', 'Debuff'),
(12938, 'Extorsion', 'Vole de la Force et occasionne des dommages Terre.', 0x088fc002, '1', 'Debuff'),
(12939, 'Guet-apens', 'Occasionne des dommages Feu aux ennemis et attire la cible vers le double du lanceur.', 0x0890c00208e19d03, '1', 'Agressive'),
(12940, 'Injection Toxique', 'Applique un poison Air de début de tour sur la cible. \nLe temps de relance du sort est réduit pour chaque piège déclenché du lanceur.', 0x0891c002, '1', 'Agressive'),
(12941, 'Piège à Fragmentation', 'Pose un piège mono-cellule qui occasionne des dommages Feu dans un cercle de 3 cases.\nLes dommages sont plus importants selon la distance avec le piège.\nN\'affecte pas l\'allié qui déclenche le piège.', 0x0892c00208bbdd0208bcdd02, '1', 'Mark'),
(12942, 'Piège de Dérive', 'Pose un piège qui occasionne des dommages Feu aux ennemis et repousse les entités depuis le centre en zone.', 0x0893c002, '1', 'Mark'),
(12943, 'Épidémie', 'Applique un poison Air de fin de tour sur l\'ennemi ciblé et lui applique l\'état Épidémie :\n• À la fin du tour de la cible, propage le poison et l\'état sur les ennemis dans un cercle de 2 cases autour d\'elle.\nLe double du lanceur peut servir de cible pour propager le poison.\n\nN\'affecte pas les invocations statiques.\nLes effets ne peuvent pas être désenvoûtés.', 0x0894c002, '1', 'Agressive'),
(12945, 'Méprise', 'Échange les positions de la cible et du double du lanceur.\n\nDissipe l\'invisibilité du lanceur.', 0x0896c002, '1', 'Agressive'),
(12947, 'Perquisition', 'Repousse la cible et vole de la vie dans l\'élément Eau aux ennemis.\nSoigne les alliés à hauteur de 50% des dommages occasionnés à l\'ennemi ciblé dans un cercle de 2 cases autour de lui. N\'affecte pas le lanceur.', 0x0898c002, '1', 'Agressive'),
(12948, 'Piège Funeste', 'Pose un piège qui occasionne des dommages Terre.\nLes dommages du sort sont augmentés pour chaque ennemi dans un cercle de 2 cases autour du piège.', 0x0899c00208b4dd0208b5dd02, '1', 'Mark'),
(12949, 'Perfidie', 'Occasionne des dommages Terre.\nLe coût en PA du sort est réduit pour chaque piège déclenché du lanceur.\nLes effets sont retirés après utilisation du sort.', 0x089ac002, '1', 'Agressive'),
(12950, 'Calamité', 'Pose un piège mono-cellule qui occasionne des dommages Eau et retire de la Fuite aux ennemis dans un carré d\'une case.', 0x089bc002, '1', 'Mark'),
(12951, 'Brume', '', 0x089cc002, '0', 'Buff'),
(12952, 'Piège Scélérat', '', 0x089dc00208c4dd02, '0', 'Agressive'),
(12953, 'Guet-apens', '', 0x089ec00208c6b803, '0', 'Agressive'),
(12954, 'Piège à Fragmentation', '', 0x089fc00208bddd0208bedd02, '0', 'Agressive'),
(12955, 'Piège de Dérive', '', 0x08a0c00208b0dd02, '0', 'Agressive'),
(12956, 'Épidémie', '', 0x08a1c00208a2c00208aec00208ebb60308bffe03, '0', 'Agressive'),
