(12976, 'Typhon', 'Vole de l\'Agilité et occasionne des dommages Air en zone.', 0x08c3c00208c4c00208c5c002, '1', 'Debuff'),
(12977, 'Aveuglement', 'Retire des PA et occasionne des dommages Neutre en zone.\nN\'affecte pas le lanceur.', 0x08c6c00208c7c00208c8c002, '1', 'Debuff'),
(12978, 'Attaque Naturelle', 'Vole de l\'Intelligence et occasionne des dommages Feu.', 0x08c9c00208cac00208cbc002, '1', 'Debuff'),
(12979, 'Barricade', 'Rend l\'allié ciblé Invulnérable aux dommages en mêlée.\nPendant 1 tour, s\'il reçoit des dommages à distance, augmente ses PM.\n\nRetire les effets du sort Bastion sur l\'allié ciblé.', 0x08ccc00208cdc00208cec002, '1', 'Buff'),
(12980, 'Trêve', 'Réduit immédiatement tous les dommages subis par tout le monde et rend le lanceur Pacifiste au prochain tour.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08cfc00208d0c00208d1c002, '1', 'Buff'),
(12981, 'Rempart', 'Réduit les dommages reçus par le lanceur et par ses alliés en zone autour de lui.\nLa protection est plus importante sur le lanceur.', 0x08d2c00208d3c00208d4c002, '1', 'Debuff'),
(12982, 'Bouclier Féca', 'Réduit les dommages subis de la cible.', 0x08d5c00208d6c002, '1', 'Buff'),
(12983, 'Retour du Bâton', 'Vole de la Force et occasionne des dommages Terre.', 0x08d8c00208d9c00208dac002, '1', 'Debuff'),
(12984, 'Attaque Nuageuse', 'Vole de la Chance et occasionne des dommages Eau.', 0x08dbc00208dcc00208ddc002, '1', 'Debuff'),
(12985, 'Glyphe Enflammé', 'Pose un glyphe de début de tour qui occasionne des dommages Feu aux ennemis.\nRetire des PM aux entités présentes dans le glyphe.\n\nEmpêche l\'utilisation d\'autres glyphes élémentaires dans le même tour.', 0x08dec00208dfc002, '1', 'Mark'),
(12986, 'Téléglyphe', 'Téléporte le lanceur et déclenche ses glyphes-aura sur la case ciblée.', 0x08e1c00208e2c00208e3c002, '1', 'Teleport'),
(12987, 'Glyphe d\'Aveuglement', 'Pose un glyphe de début de tour qui occasionne des dommages Terre aux ennemis.\nRetire des PA aux entités présentes dans le glyphe.\n\nEmpêche l\'utilisation d\'autres glyphes élémentaires dans le même tour.', 0x08e4c00208e5c00208e6c002, '1', 'Mark'),
(12988, 'Glyphe de Répulsion', 'Pose un glyphe de fin de tour qui occasionne des dommages Feu, Eau, Terre et Air.', 0x08e7c00208e8c00208e9c002, '1', 'Mark'),
(12989, 'Frisson', 'Occasionne des dommages Air aux ennemis et attire les cibles en zone.', 0x08eac00208ebc00208ecc002, '1', 'Agressive'),
(12990, 'Glyphe Optique', 'Pose un glyphe de début de tour qui occasionne des dommages Eau aux ennemis.\nRéduit la Portée des entités présentes dans le glyphe.\n\nEmpêche l\'utilisation d\'autres glyphes élémentaires dans le même tour.', 0x08edc00208eec00208efc002, '1', 'Mark'),
(12991, 'Glyphe Gravitationnel', 'Pose un glyphe-aura qui applique les états Inébranlable et Pesanteur.', 0x08f0c00208f1c002, '1', 'Mark'),
(12992, 'Glyphe Agressif', 'Pose un glyphe de début de tour qui attire les cibles vers son centre et occasionne des dommages Air aux ennemis.\nRéduit les dommages occasionnés par les entités présentes dans le glyphe.\n\nEmpêche l\'utilisation d\'autres glyphes élémentaires dans le même tour.', 0x08f3c00208f4c00208f5c002, '1', 'Mark'),
(12993, 'Léthargie', 'Occasionne des dommages Feu et retire des PM.', 0x08f6c00208f7c00208f8c002, '1', 'Agressive'),
(12994, 'Bulle', 'Occasionne des dommages Eau et retire de la Portée.', 0x08f9c00208fac00208fbc002, '1', 'Agressive'),
(12995, 'Bastion', 'Rend l\'allié ciblé Invulnérable aux dommages à distance.\nPendant 1 tour, s\'il reçoit des dommages en melée, augmente sa Puissance.\n\nRetire les effets du sort Barricade sur l\'allié ciblé.', 0x08fcc00208fdc00208fec002, '1', 'Buff'),
(12996, 'Glyphe Enflammé', '', 0x08ffc0020880c102, '1', 'Agressive'),
(12997, 'Mise en Garde', 'Augmente la Puissance des Glyphes et la Puissance du lanceur.\nApplique l\'état Glyphor sur le lanceur, interdisant l\'utilisation des sorts de protection Féca.\nRetire les effets des sorts de protection Féca sur les alliés et tue l\'Égide du lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0882c1020883c102, '1', 'Debuff'),
(12998, 'Glyphe Optique', '', 0x0885c1020886c1020887c102, '1', 'Agressive'),
(12999, 'Glyphe Agressif', '', 0x0888c1020889c102088ac102, '1', 'Agressive'),
(13000, 'Glyphe d\'Aveuglement', '', 0x088bc102088cc102088dc102, '1', 'Agressive'),
(13001, 'Glyphe de Répulsion', '', 0x088ec102088fc102089fc102, '1', 'Agressive'),
(13002, 'Glyphe Agressif', '', 0x0890c1020891c1020892c102, '1', 'Debuff'),
