(13006, 'Glyphe Enflammé', '', 0x089cc102089dc102, '1', 'Debuff'),
(13007, 'Attraction Naturelle', 'Occasionne des dommages Feu aux ennemis et attire la cible.', 0x08a0c102088ed802, '1', 'Agressive'),
(13008, 'Éblouissement', 'Attire les cibles vers le centre et occasionne des dommages Terre aux ennemis en zone autour du lanceur.', 0x08a1c102088fd802, '1', 'Agressive'),
(13009, 'Fortification', 'Réduit les dommages reçus par l\'allié ciblé.', 0x08a2c102088dd802, '1', 'None'),
(13010, 'Bourrasque', 'Occasionne des dommages Air aux ennemis et repousse les cibles vers les extrémités en zone.', 0x08a3c1020890d802, '1', 'Agressive'),
(13011, 'Boursoufflure', 'Occasionne des dommages Air aux ennemis et repousse la cible.', 0x08a4c1020891d802, '1', 'Agressive'),
(13012, 'Manœuvre', 'Échange de position avec la cible.', 0x08a5c102, '1', 'Agressive'),
(13013, 'Glyphe Fulminant', 'Occasionne des dommages Air aux ennemis et pose un glyphe-aura sous la cible qui augmente les dommages en mêlée des alliés.\n\nEmpêche l\'utilisation d\'autres glyphes élémentaires dans le même tour.', 0x08a6c1020893d802, '1', 'Agressive'),
(13014, 'Atonie', 'Vole de l\'Intelligence et occasionne des dommages Feu.', 0x08a7c1020899d802, '1', 'Debuff'),
(13015, 'Attaque Orageuse', 'Occasionne des dommages Eau et réduit les chances de Critique en zone.\nN\'affecte pas le lanceur.', 0x08a8c102, '1', 'Agressive'),
(13016, 'Pavois', 'Invoque un bouclier statique Invulnérable aux dommages à distance.\nCe bouclier est détruit au prochain tour du lanceur.', 0x08a9c1020892d802, '1', 'Summon'),
(13017, 'Tétanie', 'Occasionne des dommages Neutre et retire des PA.', 0x08aac102, '1', 'Agressive'),
(13018, 'Égide', 'Invoque un bouclier statique qui subit les dommages à la place des alliés présents dans son glyphe-aura.\nCe bouclier est détruit 2 tours après son invocation.', 0x08abc102, '1', 'Summon'),
(13019, 'Barrière', 'Pose un glyphe autour de l\'ennemi ciblé et lui applique l\'état Pesanteur au début de son prochain tour.\nLe glyphe occasionne des dommages Feu, Eau, Terre et Air à l\'ennemi s\'il le traverse mais lui retire l\'état Pesanteur.', 0x08acc102, '1', 'Agressive'),
(13020, 'Renfort', 'Téléporte le lanceur sur la première case disponible entre l\'allié ciblé et lui.', 0x08adc102, '1', 'Agressive'),
(13021, 'Glyphe Protecteur', 'Occasionne des dommages Terre aux ennemis et pose un glyphe-aura sous la cible qui réduit les dommages subis par les alliés.\n\nEmpêche l\'utilisation d\'autres glyphes élémentaires dans le même tour.', 0x08aec102, '1', 'Agressive'),
(13022, 'Tension', 'Occasionne des dommages Eau aux ennemis et repousse la cible.', 0x08afc102, '1', 'Agressive'),
(13023, 'Glyphe d\'Itinérance', 'Occasionne des dommages Eau aux ennemis et pose un glyphe-aura sous la cible qui augmente la Fuite des alliés.\n\nEmpêche l\'utilisation d\'autres glyphes élémentaires dans le même tour.', 0x08b0c102, '1', 'Agressive'),
(13024, 'Glyphe d\'Excursion', 'Pose un glyphe-aura qui échange la position des alliés avec celle du lanceur.', 0x08b1c102, '1', 'Mark'),
(13025, 'Glyphe de Perception', 'Occasionne des dommages Feu aux ennemis et pose un glyphe-aura sous le lanceur qui augmente la Portée des alliés.\n\nEmpêche l\'utilisation d\'autres glyphes élémentaires dans le même tour.', 0x08b2c102, '1', 'Agressive'),
(13026, 'Inertie', 'Applique l\'état Pesanteur en zone et augmente le Tacle du lanceur pour chaque ennemi dans la zone d\'effet.\nL\'état Pesanteur n\'affecte pas le lanceur.', 0x08b3c102, '1', 'Agressive'),
(13027, 'Ataraxie', 'Applique l\'état Pesanteur sur l\'allié ciblé et réduit tout type de dommages subis sur la première attaque.\nLes effets du sort sont retirés si l\'allié subit des dommages.\n\nLes effets d\'interception et de partage de dommages sont incompatibles avec le sort.\nLes effets ne peuvent pas être désenvoûtés.', 0x08b4c102, '1', 'Agressive'),
(13028, 'Glyphe Fulminant', '', 0x08b5c102, '1', 'Buff'),
(13030, 'Barrière', '', 0x08b7c10208c5c10208c6c10208c9c102, '1', 'Debuff'),
(13032, 'Glyphe Protecteur', '', 0x08b9c102, '1', 'Buff'),
(13034, 'Glyphe d\'Itinérance', '', 0x08bbc102, '1', 'Buff'),
(13036, 'Glyphe d\'Excursion', '', 0x08bdc10208cdc102, '1', 'None'),
(13037, 'Glyphe de Perception', '', 0x08bec102, '1', 'Buff'),
(13039, 'Glyphe de Perception', '', 0x08c0c102, '1', 'Mark'),
