(13047, 'Flèche Magique', 'Occasionne des dommages Air et vole de la Portée aux ennemis.\nAugmente la Portée de l\'allié ciblé.', 0x08cfc10208d0c10208d1c102, '1', 'Agressive'),
(13049, 'Flèche Glacée', 'Vole de la vie dans l\'élément Feu et réduit les soins reçus par la cible.', 0x08d5c10208d6c10208d7c102, '1', 'Agressive'),
(13050, 'Flèche Cinglante', 'Érode l\'ennemi ciblé et repousse la cible.', 0x08d8c10208d9c102, '1', 'Agressive'),
(13051, 'Flèche Enflammée', 'Occasionne des dommages Feu aux ennemis et repousse les cibles en zone.', 0x08dbc10208dcc10208ddc102, '1', 'Agressive'),
(13052, 'Tir Puissant', 'Augmente la Puissance des sorts et les chances de Critique de la cible.', 0x08dec10208dfc10208e0c102, '1', 'Buff'),
(13053, 'Flèche d\'Expiation', 'Occasionne des dommages Eau.\nLes dommages du sort sont augmentés pour un tour au troisième tour après son lancer, et de nouveau au sixième tour après son lancer.', 0x08e1c10208e2c10208e3c102, '1', 'Buff'),
(13054, 'Œil de Taupe', 'Retire de la Portée, vole de la vie dans l\'élément Eau et dévoile les invisibles en zone.', 0x08e4c10208e5c10208e6c102, '1', 'Debuff'),
(13055, 'Flèche de Recul', 'Occasionne des dommages Air aux ennemis et repousse la cible.', 0x08e7c10208e8c10208e9c102, '1', 'Agressive'),
(13056, 'Flèche d\'Immobilisation', 'Occasionne des dommages Eau et vole des PM.', 0x08eac10208ebc10208ecc102, '1', 'Agressive'),
(13057, 'Flèche Punitive', 'Occasionne des dommages Terre.\nLes dommages du sort sont augmentés pour un tour au deuxième tour après son lancer, et de nouveau au quatrième tour après son lancer.', 0x08edc10208eec10208efc102, '1', 'Buff'),
(13058, 'Tir Éloigné', 'Augmente la Portée des alliés en zone.', 0x08f0c10208f1c10208f2c102, '1', 'Buff'),
(13059, 'Flèche Harcelante', 'Occasionne des dommages Air.', 0x08f3c10208f4c10208f5c102, '1', 'Agressive'),
(13060, 'Flèche Empoisonnée', 'Retire des PM et applique un poison Neutre de début de tour sur la cible.', 0x08f6c10208f7c10208f8c102, '1', 'Agressive'),
(13061, 'Flèche Destructrice', 'Occasionne des dommages Terre et réduit les Dommages.', 0x08f9c10208fac10208fbc102, '1', 'Agressive'),
(13062, 'Flèche Persécutrice', 'Occasionne des dommages Feu et Air.', 0x08fcc10208fdc10208fec102, '1', 'Agressive'),
(13063, 'Flèche Ralentissante', 'Retire des PA et occasionne des dommages Eau en zone.', 0x08ffc1020880c202, '1', 'Debuff'),
(13064, 'Flèche Absorbante', 'Vole de la vie dans l\'élément Air.', 0x0882c2020883c2020884c202, '1', 'Agressive'),
(13065, 'Flèche Explosive', 'Occasionne des dommages Feu en zone.', 0x0885c2020886c202, '1', 'Agressive'),
(13066, 'Maîtrise de l\'Arc', 'Augmente les Dommages de la cible.', 0x0888c2020889c20208ebd403, '1', 'Buff'),
(13067, 'Flèche de Dispersion', 'Repousse les cibles depuis le centre de la zone.', 0x088bc202088cc202088dc202, '1', 'Agressive'),
(13068, 'Flèche de Concentration', 'Attire les cibles vers le centre et occasionne des dommages Air aux ennemis en zone.', 0x088ec20208abdb02, '1', 'Agressive'),
(13069, 'Flèche Érosive', 'Érode la cible et occasionne des dommages Terre.', 0x088fc20208acdb02, '1', 'Debuff'),
(13070, 'Flèche de Repli', 'Éloigne le lanceur de la cible.', 0x0890c202, '1', 'Agressive'),
(13071, 'Flèche Paralysante', 'Occasionne des dommages Feu et retire des PA en zone.', 0x0891c20208aedb02, '1', 'Agressive'),
(13072, 'Flèche Répulsive', 'Occasionne des dommages Feu aux ennemis et repousse les cibles en zone.', 0x0892c20208afdb02, '1', 'Agressive'),
(13073, 'Acuité Absolue', 'Désactive la ligne de vue de tous les sorts du lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0893c20208b0db02, '1', 'Buff'),
(13074, 'Flèche de Rédemption', 'Occasionne des dommages Eau.\nLes dommages du sort sont augmentés au tour suivant.', 0x0894c20208b1db02, '1', 'Agressive'),
(13075, 'Flèche Écrasante', 'Occasionne des dommages Feu aux ennemis et applique l\'état Pesanteur sur les cibles en zone.', 0x0895c20208b2db02, '1', 'Agressive'),
(13076, 'Balise de Rappel', 'Invoque une Balise de Rappel qui échange de position avec le lanceur au tour suivant.\nElle est également détruite au tour suivant.\n\nLa Balise est insensible aux dommages des sorts Crâs nécessitant une cible.', 0x0896c202, '1', 'Summon'),
(13077, 'Flèche Assaillante', 'Augmente la Puissance du lanceur pour chaque entité dans la zone d\'effet et occasionne des dommages Eau en zone.', 0x0897c202, '1', 'Agressive'),
(13078, 'Flèche du Jugement', 'Occasionne des dommages Terre.\nOccasionne des dommages Terre supplémentaires selon les PM du lanceur : moins le lanceur a utilisé de PM durant son tour de jeu, plus les dommages supplémentaires seront importants.', 0x0898c202, '1', 'Agressive'),
(13079, 'Balise Tactique', 'Invoque une Balise Tactique qui peut servir d\'obstacle et de cible.\nElle subit deux fois moins de dommages des alliés, et elle est insensible aux dommages des sorts Crâs nécessitant une cible.\n\nIl ne peut y avoir qu\'une seule Balise Tactique par équipe. Si la Balise Tactique est encore en vie et que celle-ci est réinvoquée, l\'ancienne est détruite pour laisser place à la nouvelle.', 0x0899c202, '1', 'Agressive'),
(13080, 'Flèche Massacrante', 'Occasionne des dommages Air.\nLes dommages du sort sont augmentés au tour suivant.', 0x089ac202, '1', 'Agressive'),
(13082, 'Flèche Tyrannique', 'Occasionne des dommages Feu et Air.\n\nSur l\'ennemi ciblé pendant 2 tours : \n• Occasionne des dommages Feu s\'il subit des dommages de poussée.\n• Occasionne des dommages Air s\'il est poussé.\nLes dommages de chaque élément peuvent être déclenchés 3 fois maximum par tour.', 0x089cc202, '1', 'Agressive'),
(13083, 'Tir de Barrage', 'Occasionne des dommages Terre aux ennemis et repousse la cible.', 0x089dc202, '1', 'Agressive'),
(13084, 'Flèche Dévorante', 'Occasionne des dommages Air aux ennemis. Les lancers consécutifs sur une même cible augmentent les dommages du sort, jusqu\'à 3 fois max.\n\nChanger de cible réinitialise les dommages mais endommage encore plus la cible ennemie initiale.', 0x089ec202, '1', 'Agressive'),
(13085, 'Flèche Percutante', 'Occasionne des dommages Eau et applique l\'état Flèche Percutante sur la cible :\n• À la fin du tour de la cible, occasionne des dommages Eau plus importants et retire des PA aux ennemis (cumulable 1 fois) dans un cercle de 2 cases autour d\'elle et lui retire l\'état Flèche Percutante.', 0x089fc202, '1', 'Agressive'),
(13086, 'Flèche Fulminante', 'Occasionne des dommages Feu.\nRebondit sur l\'ennemi le plus proche dans un cercle de 2 cases.\nPeut également rebondir sur la Balise Tactique.\n\nLes dommages du sort sont augmentés pour chaque cible touchée.', 0x08a0c202, '1', 'Agressive'),
(13087, 'Sentinelle', 'Immobilise le lanceur pour augmenter ses dommages aux sorts et sa Portée pour le tour en cours.', 0x08a1c202, '1', 'Buff'),
(13088, 'Représailles', 'Applique l\'état Pesanteur et l\'état Représailles sur la cible :\n• Si la cible est un ennemi : retire des PM non esquivables à la cible si elle occasionne des dommages au lanceur.\n• Si la cible est un allié : retire des PM non esquivables à ses attaquants ennemis.\n\nN\'affecte pas les invocations alliées.\nLes états ne peuvent pas être désenvoûtés.', 0x08a2c20208addb02, '1', 'Agressive'),
(13089, 'Flèche Percutante', '', 0x08a3c2020897ea03, '0', 'None'),
(13090, 'Flèche Fulminante', '', 0x08a4c20208a6c202, '0', 'Agressive'),
(13091, 'Balise de Rappel', '', 0x08a5c20208a9c20208b6c202, '0', 'None'),
(13092, 'Flèche Dévorante', '', 0x08a7c20208b7c20208b8c202, '0', 'None'),
(13093, 'Balise Tactique', '', 0x08a8c202, '0', 'Buff'),
(13095, 'Flèche Répulsive', '', 0x08abc202, '0', 'Agressive'),
(13096, 'Flèche Tyrannique Feu', '', 0x08adc20208d7e00308e7ea03, '0', 'None'),
(13097, 'Flèche Tyrannique Air', '', 0x08acc20208d8e00308e8ea03, '0', 'None'),
