(13101, 'Flèche Explosive', '', 0x08b2c202, '0', 'None'),
(13102, 'Flèche Ralentissante', '', 0x08b3c202, '0', 'None'),
(13103, 'Sentinelle', '', 0x08b4c202, '0', 'Debuff'),
(13104, 'Flèche Écrasante', '', 0x08b5c202, '0', 'None'),
(13105, 'Flèche Assaillante', '', 0x08b9c202, '0', 'Buff'),
(13106, 'Pression', 'Érode la cible et occasionne des dommages Terre.', 0x08bac20208bbc20208bcc202, '1', 'Debuff'),
(13107, 'Bond', 'Téléporte le lanceur sur la case ciblée et augmente les dommages subis par les ennemis en zone.', 0x08bdc20208bec20208bfc202, '1', 'Teleport'),
(13108, 'Intimidation', 'Occasionne des dommages dans le meilleur élément d\'attaque du lanceur aux ennemis et repousse la cible.', 0x08c0c20208c1c20208c2c202, '1', 'Agressive'),
(13109, 'Duel', 'Rend le lanceur et l\'ennemi ciblé Invulnérables à distance, leur applique l\'état Pesanteur et les immobilise.\nL\'état Pesanteur du lanceur est conservé au tour suivant.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08c3c20208c4c20208c5c202, '1', 'Agressive'),
(13110, 'Épée Divine', 'Occasionne des dommages Air aux ennemis et augmente les dommages des alliés en zone.', 0x08c6c20208c7c20208c8c202, '1', 'Agressive'),
(13111, 'Épée du Destin', 'Occasionne des dommages Feu.\nLes dommages du sort sont augmentés pour un tour au deuxième tour après son lancer.', 0x08c9c20208cbc202, '1', 'Agressive'),
(13112, 'Massacre', 'Renvoie 75% des dommages de sorts subis par l\'ennemi ciblé aux ennemis à son contact.', 0x08ccc202, '1', 'Agressive'),
(13113, 'Friction', 'Attire la cible et lui applique l\'état Friction :\n• Si la cible est un ennemi, la rapproche de ses attaquants ennemis.\n• Si la cible est un allié, attire ses attaquants ennemis vers elle.', 0x08cfc20208d0c20208d1c202, '1', 'Agressive'),
(13114, 'Précipitation', 'Augmente les PA de l\'allié ciblé mais lui en retire au tour suivant.\nLui applique également l\'état Précipité, interdisant l\'utilisation des armes et du sort Colère de Iop.', 0x08d2c20208d3c20208d4c202, '1', 'Buff'),
(13115, 'Couperet', 'Occasionne des dommages Feu et retire des PM en zone.', 0x08d5c20208d6c202, '1', 'Agressive'),
(13116, 'Souffle', 'Repousse les cibles depuis le centre de la zone.', 0x08d8c20208d9c20208dac202, '1', 'Agressive'),
(13117, 'Épée du Jugement', 'Applique un bouclier sur le lanceur et occasionne des dommages Eau.\nLes dommages n\'affectent pas le lanceur.\n\nÀ chaque début de tour après son lancer :\n• Applique un bouclier sur le lanceur.\n• Le bouclier et les dommages du sort deviennent plus importants.\n• La zone d\'effet du sort devient une croix d\'une case, puis 2 et enfin 3 cases.\n\nLes effets sont réinitialisés si le sort est relancé, ou s\'il ne l\'est pas après 3 tours.', 0x08dbc202, '1', 'Agressive'),
(13118, 'Puissance', 'Augmente la Puissance.', 0x08dec20208dfc20208e0c202, '1', 'Buff'),
(13119, 'Épée Destructrice', 'Érode les cibles et occasionne des dommages Feu en zone.', 0x08e1c20208e2c20208e3c202, '1', 'Debuff'),
(13120, 'Vitalité', 'Augmente la Vitalité de la cible.\nLa Vitalité est plus importante sur le lanceur.', 0x08e4c20208e6c202, '1', 'Agressive'),
(13121, 'Tempête de Puissance', 'Occasionne des dommages Feu aux ennemis.\n\nOccasionne des dommages Feu supplémentaires sur la cible initiale si le sort est lancé sur une autre cible.\nLes dommages supplémentaires lors du changement de cible sont plus importants si le sort a été utilisé deux fois sur la cible initiale.', 0x08e7c20208e4de0208e5de02, '1', 'Agressive'),
(13122, 'Épée Céleste', 'Occasionne des dommages Air en zone.\nN\'affecte pas le lanceur.', 0x08eac20208ebc20208ecc202, '1', 'Agressive'),
(13123, 'Concentration', 'Occasionne des dommages Terre.\nLes dommages sont plus importants sur les invocations.', 0x08edc20208eec20208efc202, '1', 'Agressive'),
(13124, 'Colère de Iop', 'Occasionne des dommages Terre.\nLes dommages du sort sont augmentés pour un tour au troisième tour après son lancer.', 0x08f0c20208f2c202, '1', 'Agressive'),
(13125, 'Épée de Iop', 'Occasionne des dommages Terre en zone.\nN\'affecte pas le lanceur.', 0x08f3c20208f5c202, '1', 'Agressive'),
(13126, 'Déferlement', 'Rapproche le lanceur de la cible et occasionne des dommages Eau aux ennemis.', 0x08f6c20208f7c20208f8c202, '1', 'Agressive'),
(13127, 'Massacre', '', 0x08f9c202, '0', 'None'),
(13128, 'Friction', '', 0x08fac20208d6b80308bdea03, '1', 'None'),
(13130, 'Menace', 'Occasionne des dommages Eau aux ennemis et attire la cible.', 0x08fcc202, '1', 'Agressive'),
(13131, 'Tannée', 'Occasionne des dommages Air et retire des PM en zone.', 0x08fdc202, '1', 'Agressive'),
(13132, 'Détermination', 'Applique l\'état Indéplaçable sur le lanceur et réduit ses dommages subis.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08fec202, '1', 'Buff'),
(13133, 'Endurance', 'Occasionne des dommages Eau et applique un bouclier sur le lanceur.\n\nSur le lanceur : applique un bouclier.', 0x08ffc202, '1', 'Agressive'),
(13134, 'Fendoir', 'Applique un bouclier sur le lanceur pour chaque ennemi dans la zone d\'effet et occasionne des dommages Eau en zone.\nLes dommages n\'affectent pas le lanceur.', 0x0880c30208a2dc02, '1', 'Agressive'),
(13135, 'Anneau Destructeur', 'Occasionne des dommages Air aux ennemis et attire les cibles vers le centre en zone.', 0x0881c30208a3dc02, '1', 'Agressive'),
(13136, 'Rassemblement', 'Augmente le Tacle de l\'allié ciblé pour chaque ennemi dans la zone d\'effet et attire les ennemis vers le centre en zone.', 0x0882c30208a4dc0208d4b803, '1', 'Agressive'),
(13137, 'Violence', 'Augmente les Dommages Poussée du lanceur pour chaque ennemi dans la zone d\'effet et repousse les cibles en zone.', 0x0883c30208a5dc02, '1', 'Agressive'),
(13138, 'Accumulation', 'Occasionne des dommages Terre.\n\nSur le lanceur : augmente les dommages du sort.', 0x0884c30208e1de02, '1', 'Agressive'),
(13139, 'Fracture', 'Érode les cibles et occasionne des dommages Air en ligne jusqu\'à la case ciblée.', 0x0885c30208e0de02, '1', 'Debuff'),
(13140, 'Coup pour Coup', 'Repousse la cible et lui applique l\'état Coup pour Coup :\n• Si la cible est un ennemi, la repousse si elle attaque le lanceur.\n• Si la cible est un allié, repousse ses attaquants ennemis.', 0x0886c302, '1', 'Agressive'),
(13141, 'Emprise', 'Rend l\'ennemi ciblé Invulnérable et l\'immobilise.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0887c302, '1', 'Debuff'),
(13142, 'Vertu', 'Applique un bouclier sur les alliés en zone mais réduit la Puissance du lanceur.', 0x0888c30208d5b803, '1', 'Buff'),
(13143, 'Agitation', 'Augmente les PM de l\'allié ciblé et le rend Intaclable.\nRetire une partie de sa Fuite au tour suivant.', 0x0889c30208d3b803, '1', 'Buff'),
(13144, 'Tumulte', 'Augmente les dommages du sort pour chaque ennemi dans la zone d\'effet et occasionne des dommages Feu en zone.\n\nN\'affecte pas le lanceur.', 0x088ac302, '1', 'Agressive'),
(13145, 'Zénith', 'Occasionne des dommages Air en zone. \nOccasionne des dommages Air supplémentaires en zone selon les PM du lanceur : moins le lanceur a utilisé de PM durant son tour de jeu, plus les dommages supplémentaires seront importants.', 0x088bc302, '1', 'Agressive'),
(13146, 'Pugilat', 'Occasionne des dommages Terre en zone. N\'affecte pas le lanceur.\nLes dommages du sort sont augmentés après chaque lancer pour le tour en cours.', 0x088cc302, '1', 'Agressive'),
(13147, 'Sentence', 'Occasionne des dommages Feu et applique l\'état Sentence sur la cible :\n• À la fin du tour de la cible, occasionne des dommages Feu plus importants aux ennemis dans un cercle de 2 cases autour d\'elle et lui retire l\'état Sentence.\nLes dommages sont moins importants si la cible est le lanceur.\n\nLes dommages n\'affectent pas le lanceur.', 0x088dc302, '1', 'Agressive'),
(13148, 'Conquête', 'Invoque un Stratège Iop qui renvoie 50% des dommages de sorts qu\'il subit dans une zone de 2 cases autour de lui. Les dommages n\'affectent pas le lanceur.\n\nLe Stratège Iop réduit de 50% les dommages immédiats alliés.\n\nIl ne peut y avoir qu\'un seul Stratège Iop par équipe. Si le Stratège Iop est encore en vie et que celui-ci est ré-invoqué, l\'ancien est tué pour laisser place au nouveau.', 0x088ec30208a0dc02, '1', 'Agressive'),
(13149, 'Fendoir', '', 0x088fc30208fde003, '0', 'None'),
(13150, 'Rassemblement', '', 0x0890c30208a1c302, '0', 'Buff'),
(13151, 'Violence', '', 0x0891c30208d3dc02, '0', 'Buff'),
(13152, 'Coup pour Coup', '', 0x0892c30208a0c30208d7b803, '0', 'Agressive'),
(13154, 'Tumulte', '', 0x0894c302, '0', 'Buff'),
(13155, 'Sentence', '', 0x0895c30208d4ba030898ea03, '0', 'None'),
(13156, 'Fureur', 'Occasionne des dommages Terre.\nLes dommages du sort sont augmentés après chaque lancer. Le bonus de dommages est perdu si le sort n\'est pas relancé.', 0x0896c302, '1', 'Agressive'),
(13159, 'Accumulation', '', 0x089ac302, '0', 'None'),
(13160, 'Accumulation', '', 0x089bc302, '0', 'None'),
(13162, 'Fureur', '', 0x089dc302, '0', 'None'),
(13163, 'Fureur', '', 0x089ec302, '0', 'None'),
(13164, 'Coup pour Coup', '', 0x089fc302, '0', 'None'),
(13165, 'Duel', '', 0x08a4c302, '0', 'Debuff'),
(13175, 'Mot de Frayeur', 'Repousse la cible.\nLa poussée est plus importante sur les alliés dans l\'état Encouragé et sur les ennemis dans l\'état Moqué.', 0x08bcc30208bdc30208bec302, '1', 'Agressive'),
(13184, 'Mot d\'Envol', 'Échange de position avec l\'allié ciblé.\n• S\'il est dans l\'état Encouragé : retire l\'Encouragement et augmente ses soins reçus.\n• Si c\'est une Fée : la tue.', 0x08d7c30208d8c302, '1', 'Debuff'),
(13187, 'Mot de Reconstitution', 'Soigne totalement l\'allié ciblé mais le rend Insoignable.', 0x08e0c30208e1c302, '1', 'Healing'),
(13217, 'Mot de Ralliement', 'Rapproche le lanceur de l\'allié ciblé et l\'attire.\n• Si l\'allié est dans l\'état Encouragé : retire l\'Encouragement et augmente ses soins reçus.\n• Si c\'est une Fée : la tue.', 0x0896c402, '1', 'Debuff'),
(13219, 'Mot de Solidarité', 'Transfère 10% des points de vie de l\'allié ciblé ou 90% des points de vie d\'une Fée du lanceur à tous les alliés dans l\'état Encouragé et à toutes les Fées du lanceur.\n\nSur un allié dans l\'état Encouragé : transfère 10% des points de vie de tous les alliés dans l\'état Encouragé et 90% des points de vie de toutes les Fées du lanceur à la cible.', 0x0898c402, '1', 'Agressive'),
(13232, 'Mot de Solidarité', '', 0x08a7c40208b1c40208ed8104, '0', 'None'),
(13233, 'Mot de Solidarité', '', 0x08a8c402, '0', 'Agressive'),
(13234, 'Mot de Solidarité', '', 0x08a9c40208ee8104, '0', 'Agressive'),
(13242, 'Ralentissement', 'Occasionne des dommages Eau.\nSi la cible est un ennemi, lui retire également des PA.\nLe retrait de PA est plus important sur les ennemis dans l\'état Téléfrag.', 0x08b6c40208b7c40208b8c402, '1', 'Agressive'),
(13243, 'Rembobinage', 'Téléporte l\'allié ciblé à sa position de début de tour à la fin de son tour.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08b9c40208bac40208bbc402, '1', 'Agressive'),
(13244, 'Aiguille', 'Occasionne des dommages Feu.\nSi la cible est un ennemi, lui applique également l\'état Aiguille :\n• Occasionne des dommages Feu et retire l\'état Aiguille en sortie d\'état Téléfrag.', 0x08bcc40208bdc40208bec402, '1', 'Agressive'),
(13245, 'Gelure', 'Occasionne des dommages Air aux ennemis et téléporte la cible à sa position précédente.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08bfc40208c0c40208c1c402, '1', 'Agressive'),
(13246, 'Flou', 'Retire immédiatement des PA non esquivables en zone pour les augmenter au tour suivant.\nLe retrait de PA n\'affecte pas le lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08c2c40208c3c40208c4c402, '1', 'Debuff'),
(13247, 'Synchro', 'Invoque une Synchro statique qui meurt en occasionnant des dommages Air aux ennemis dans un cercle de 3 cases lorsqu\'elle entre dans l\'état Téléfrag. Les dommages ne diminuent pas avec la distance.\n\nElle est soignée et ses dommages finaux occasionnés sont augmentés pour chaque Téléfrag qui est généré par le lanceur.\nCet effet ne peut être déclenché qu\'une fois par tour, et qu\'une fois par sort.\n\nLa Synchro est immunisée contre les sorts Momification et Embaumement, et ne peut pas s\'activer avec le sort Rembobinage.\n\nIl ne peut y avoir qu\'une seule Synchro par équipe. Si la Synchro est encore en vie et que celle-ci est ré-invoquée, l\'ancienne est tuée pour laisser place à la nouvelle.', 0x08c5c40208c6c40208c7c402, '1', 'Agressive'),
(13248, 'Démotivation', 'Occasionne des dommages Terre aux ennemis.\n\nSur une cible dans l\'état Téléfrag : réduit la durée des effets sur la cible, lui applique l\'état Démotivation et occasionne des dommages Terre aux ennemis.\n\nLe désenvoûtement ne peut pas être appliqué si la cible est déjà dans l\'état Démotivation.\n\nConsomme l\'état {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08c8c40208c9c40208cac402, '1', 'Agressive'),
(13249, 'Téléportation', 'Téléporte le lanceur symétriquement par rapport à la cible.\n\nFixe le temps de relance du sort à 0 lorsqu\'un Téléfrag est généré ou consommé par le lanceur.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08cbc40208ccc40208cdc402, '1', 'Agressive'),
(13250, 'Paradoxe Temporel', 'Sur le Complice ou le Cadran de Xélor du lanceur :\n• Applique l\'état Indeplaçable.\n• Téléporte les entités symétriquement par rapport à eux dans un cercle de 4 cases autour d\'eux.\n• Fixe le temps de relance des sorts Complice et Cadran de Xélor du lanceur à 1 tour.\n• Au début du tour du Complice ou du Cadran, téléporte de nouveau ces entités.\n\nLa téléportation n\'affecte pas une Synchro et le lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08cec40208cfc40208d0c402, '1', 'Agressive'),
(13251, 'Fuite', 'Augmente la Fuite de l\'allié ciblé.\nTéléporte la cible à sa position précédente au tour suivant.\n\nLes effets ne peuvent pas être désenvoûtés.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08d1c40208d3c402, '1', 'Buff'),
(13252, 'Frappe de Xélor', 'Téléporte la cible symétriquement par rapport au lanceur et occasionne des dommages Terre aux ennemis.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08d4c40208d5c40208d6c402, '1', 'Agressive'),
(13253, 'Rayon Obscur', 'Occasionne des dommages Terre.\nLes dommages sont doublés sur les cibles dans l\'état Téléfrag.\n\nConsomme l\'état {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08d7c40208d9c402, '1', 'Agressive'),
(13254, 'Flétrissement', 'Occasionne des dommages Air.\nLes dommages sont plus importants sur les cibles dans l\'état Téléfrag.', 0x08dac40208dbc40208dcc402, '1', 'Agressive'),
(13255, 'Contre', 'Sur les alliés en zone : renvoie une partie des dommages subis en mêlée à l\'attaquant.', 0x08ddc40208dec40208dfc402, '1', 'Agressive'),
(13256, 'Horloge', 'Vole de la vie dans l\'élément Eau.\n\nSur un ennemi dans l\'état Téléfrag : vole de la vie dans l\'élément Eau et retire des PA (cumulable 1 fois).\n\nDonne 1 PA au lanceur au tour suivant.\n\nConsomme l\'état {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08e0c40208e2c402, '1', 'Agressive'),
(13257, 'Poussière Temporelle', 'Occasionne des dommages Feu aux ennemis.\n\nSur des cibles dans l\'état Téléfrag en zone : téléporte les cibles symétriquement par rapport au centre et occasionne des dommages Feu aux ennemis.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08e3c40208e4c40208e5c402, '1', 'Agressive'),
(13258, 'Cadran de Xélor', 'Invoque un Cadran qui retire des PA aux ennemis dans l\'état Téléfrag et augmente les PA des alliés dans l\'état Téléfrag en zone.\nLorsqu\'il est ré-invoqué, il ré-applique le bonus de PA aux alliés qui l\'avaient déjà.\n\nIl ne peut y avoir qu\'un seul Cadran de Xélor par équipe. Si le Cadran est encore en vie et que celui-ci est ré-invoqué, l\'ancien est tué pour laisser place au nouveau.', 0x08e6c40208e1db02, '1', 'Agressive'),
(13259, 'Vol du Temps', 'Occasionne des dommages Eau aux ennemis en zone.\n\nSur des ennemis dans l\'état Téléfrag : vole des PA et occasionne des dommages Eau en zone.\n\nConsomme les états {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>} des cibles.', 0x08e7c40208e8c40208e9c402, '1', 'Agressive'),
(13260, 'Momification', 'Augmente les PM et l\'Esquive PA du lanceur et applique l\'état Téléfrag sur tout le monde.', 0x08eac40208ecc402, '1', 'Buff'),
(13261, 'Sablier de Xélor', 'Occasionne des dommages Feu et retire des PA aux ennemis.\n\nSur une cible dans l\'état Téléfrag : occasionne des dommages Feu et retire des PA aux ennemis dans un cercle de 2 cases.\n\nConsomme l\'état {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>} de la cible.', 0x08edc40208eec40208efc402, '1', 'Agressive'),
(13262, 'Raulebaque', 'Téléporte tout le monde à sa position précédente.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08f0c40208f1c40208f2c402, '1', 'Agressive'),
(13263, 'Téléportation', '', 0x08f3c40208dfd8030895e9030896e9030897e9030898e903, '0', 'Agressive'),
(13264, 'Contre', '', 0x08f4c4020888c5020889c50208d4e803, '0', 'None'),
(13265, 'Téléfrag', '', 0x08f5c40208abdf0208b2950308d09503, '0', 'None'),
(13266, 'Paradoxe Temporel', '', 0x08f6c40208f7c402, '1', 'Agressive'),
(13268, 'Fuite', '', 0x08f9c40208808304, '0', 'None'),
(13269, 'Oscillation', 'Sort lancé par le Cadran qui affecte les personnages en états Téléfrag Allié ou Téléfrag Ennemi.', 0x08fac402, '1', 'Agressive'),
(13270, 'Synchronisation', '', 0x08fcc40208fdc40208fec40208ffc4020880c5020881c50208e6ee03, '0', 'None'),
(13271, 'Fin des Temps', '', 0x0882c5020883c5020884c5020885c5020886c5020887c502, '1', 'Agressive'),
(13272, 'Téléportation', '', 0x088ac5020899c502, '0', 'Buff'),
(13273, 'Rembobinage', '', 0x088bc5020898c502, '0', 'Buff'),
