(13275, 'Poussière Temporelle', '', 0x088dc5020896c502, '0', 'Buff'),
(13276, 'Fuite', '', 0x088ec5020895c502, '0', 'Buff'),
(13277, 'Paradoxe Temporel', '', 0x088fc5020894c502, '0', 'Buff'),
(13278, 'Frappe de Xélor', '', 0x0890c5020893c502, '0', 'Buff'),
(13279, 'Raulebaque', '', 0x0891c5020892c502, '0', 'Buff'),
(13281, 'Souvenir', 'Occasionne des dommages Terre aux ennemis et téléporte la cible à sa position précédente.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x089cc50208dbdb02, '1', 'Agressive'),
(13282, 'Retour Spontané', 'Téléporte la cible à sa position précédente.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x089dc50208dddb02, '1', 'Agressive'),
(13283, 'Rouage', 'Donne 1 PA au lanceur au tour suivant et occasionne des dommages Eau.', 0x089ec50208dcdb02, '1', 'Agressive'),
(13284, 'Dessèchement', 'Occasionne des dommages Air aux ennemis.\nRebondit sur l\'ennemi le plus proche dans un cercle de 2 cases.\nPeut également rebondir sur le Complice, sur le Cadran de Xélor et sur les alliés dans l\'état Téléfrag sans leur occasionner de dommages.\n\nLes dommages du sort sont augmentés pour chaque cible dans l\'état Téléfrag touchée.\n\nConsomme les états {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>} des cibles.', 0x089fc50208dedb02, '1', 'Agressive'),
(13285, 'Renvoi', 'Téléporte l\'ennemi ciblé à sa position de début de tour.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08a0c50208dfdb02, '1', 'Agressive'),
(13286, 'Rayon Ténébreux', 'Occasionne des dommages Terre aux ennemis.\n\nSur une cible dans l\'état Téléfrag : occasionne des dommages Terre aux ennemis dans un cercle de 2 cases.\n\nConsomme l\'état {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>} de la cible.', 0x08a1c502, '1', 'Agressive'),
(13287, 'Complice', 'Invoque un Complice qui sert d\'obstacle.\n\nSi le Complice du lanceur est encore en vie et que celui-ci est ré-invoqué, l\'ancien est tué pour laisser place au nouveau.', 0x08a2c50208d0c50208d1c502, '1', 'Agressive'),
(13288, 'Perturbation', 'Téléporte la cible symétriquement par rapport au lanceur, occasionne des dommages Feu aux ennemis et téléporte la cible à sa position précédente.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08a3c50208e2db02, '1', 'Agressive'),
(13289, 'Distorsion Temporelle', 'Occasionne des dommages Air aux ennemis et téléporte les cibles à leur position précédente en zone.\nN\'affecte pas le lanceur.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08a4c502, '1', 'Agressive'),
(13290, 'Pétrification', 'Occasionne des dommages Eau et retire des PA.\n\nSur une cible dans l\'état Téléfrag : réduit le coût en PA du sort, occasionne des dommages Eau et retire des PA.', 0x08a5c502, '1', 'Agressive'),
(13291, 'Conservation', 'Réduit immédiatement les dommages finaux occasionnés par les cibles en zone et réduit leurs dommages subis au tour suivant.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08a6c502, '1', 'Debuff'),
(13292, 'Suspension Temporelle', 'Occasionne des dommages Feu aux ennemis.\n\nSur une cible dans l\'état Téléfrag : réduit la durée des effets sur la cible, lui applique l\'état Suspension Temporelle et occasionne des dommages Feu aux ennemis.\n\nLe désenvoûtement ne peut pas être appliqué si la cible est déjà dans l\'état Suspension Temporelle.\n\nConsomme l\'état {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08a7c502, '1', 'Agressive'),
(13293, 'Prémonition', 'Pose une rune qui téléporte le lanceur ou échange sa position avec l\'entité sur la case ciblée au début de son prochain tour.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08a8c502, '1', 'Agressive'),
(13294, 'Pendule', 'Téléporte le lanceur symétriquement par rapport à la cible, occasionne des dommages Air aux ennemis dans un cercle de 2 cases autour du lanceur et le téléporte à sa position précédente.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08a9c502, '1', 'Agressive'),
(13295, 'Faille Temporelle', 'Échange de position avec la Complice ou le Cadran de Xélor du lanceur.\nÀ la fin du tour du lanceur, téléporte le Complice ou le Cadran à leur position précédente.\n\nEmpêche l\'application de l\'état Téléfrag sur la Synchro pour le tour en cours.\n\nLes effets ne peuvent pas être désenvoûtés.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08aac502, '1', 'Agressive'),
(13296, 'Désynchronisation', 'Pose un piège mono-cellule qui téléporte les entités symétriquement par rapport au piège dans un cercle de 2 cases.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08abc50208dadb02, '1', 'Mark'),
(13297, 'Bouclier Temporel', 'Applique l\'état Bouclier Temporel sur la cible :\n• Téléporte la cible et son attaquant à leur position précédente si elle subit des dommages.\n\nLes effets ne peuvent pas être désenvoûtés.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08acc502, '1', 'Agressive'),
(13298, 'Clepsydre', 'Occasionne des dommages Eau.\n\nSur une cible dans l\'état Téléfrag : donne 2 PA au lanceur au tour suivant et occasionne des dommages Eau.\n\nConsomme l\'état {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08adc502, '1', 'Agressive'),
(13299, 'Engrenage', 'Téléporte les cibles symétriquement par rapport au centre et occasionne des dommages Terre aux ennemis en zone.\nLes dommages ne diminuent pas avec la distance.\nN\'affecte pas le lanceur.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08aec50208e0db02, '1', 'Agressive'),
(13300, 'Glas', 'Occasionne des dommages Air, Eau, Terre et Feu aux ennemis en zone.\n\nLes dommages sont augmentés pour chaque Téléfrag consommé depuis son dernier lancer.\nLes effets sont retirés après utilisation du sort.\n\nNécessite de consommer au moins un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>} pour être utilisé.', 0x08afc502, '1', 'Agressive'),
(13301, 'Instabilité Temporelle', 'Pose un glyphe de début de tour qui téléportent les cibles à leur position précédente.\nRend les entités présentes dans le glyphe Intaclables.\n\nDéclenche le glyphe si le lanceur génère un Téléfrag.\n\nPeut générer un {spell,24510,1::<font color=\"#ebc304\">Téléfrag</font>}.', 0x08b0c502, '1', 'Mark'),
