(13327, 'Instabilité Temporelle', '', 0x08d7c502, '0', 'None'),
(13328, 'Sac Animé', 'Invoque un Sac Animé maîtrisable qui subit les dommages à la place de ses alliés situés dans sa zone d\'invocation.\nLe Sac Animé disparaît 3 tours après son invocation.\n\nQuand il est attaqué par un allié, ce dernier est soigné.', 0x08d8c50208d9c50208dac502, '1', 'Summon'),
(13329, 'Âge d\'Or', 'Rend Intaclable l\'allié ciblé.\nAugmente sa Puissance au tour suivant.', 0x08dbc502, '1', 'Buff'),
(13330, 'Lancer de Pelle', 'Occasionne des dommages Terre et retire de la Portée.', 0x08dec502, '1', 'Agressive'),
(13331, 'Roulage de Pelle', 'Occasionne des dommages Feu.', 0x08e1c50208e2c50208e3c502, '1', 'Agressive'),
(13332, 'Clef du Trésor', 'Réduit la Portée des ennemis ou augmente la Portée des alliés.\nLe bonus est réduit de moitié sur le lanceur.', 0x08e4c50208e5c50208e6c502, '1', 'Buff'),
(13333, 'Désinvocation', 'Occasionne des dommages Feu.\nOccasionne des dommages Feu supplémentaires aux invocations.', 0x08e7c50208e8c502, '1', 'Agressive'),
(13334, 'Boîte de Pandore', 'Soigne tous les alliés mais augmente les PM de tous les ennemis.', 0x08eac50208ebc50208ecc502, '1', 'Healing'),
(13335, 'Remblai', 'Occasionne des dommages Terre et retire de la Portée en zone.\nN\'affecte pas le lanceur.', 0x08edc50208eec50208efc502, '1', 'Agressive'),
(13336, 'Pelle Fantomatique', 'Réduit la durée des effets de la cible et occasionne des dommages Feu aux ennemis.', 0x08f0c50208f1c50208f2c502, '1', 'Debuff'),
(13337, 'Maladresse', 'Retire des PM.', 0x08f3c50208f4c50208f5c502, '1', 'Debuff'),
(13338, 'Lancer de Pièces', 'Occasionne des dommages Eau.', 0x08f6c50208f7c50208f8c502, '1', 'Agressive'),
(13339, 'Cupidité', 'Retire de la Puissance à tout le monde et augmente la Puissance du lanceur pour chaque entité touchée.', 0x08f9c50208fac50208fbc502, '1', 'Debuff'),
(13340, 'Force de l\'Âge', 'Occasionne des dommages Terre et donne 1 PM au lanceur.', 0x08fcc50208fdc50208fec502, '1', 'Agressive'),
(13342, 'Accélération', 'Augmente les PM de l\'allié ciblé.', 0x0882c6020883c6020884c602, '1', 'Buff'),
(13343, 'Pelle Aurifère', 'Occasionne des dommages Eau et retire des PM.', 0x0885c6020886c6020887c602, '1', 'Agressive'),
(13344, 'Pelle Animée', 'Invoque une Pelle Animée maîtrisable qui pousse ses cibles.\n\nQuand elle est attaquée par un allié, ce dernier est soigné.', 0x0888c6020889c602088ac602, '1', 'Summon');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(13345, 'Pelle des Anciens', 'Occasionne des dommages Eau aux ennemis et repousse la cible.', 0x088bc602088cc602, '1', 'Agressive'),
(13346, 'Corruption', 'Sur un allié : soigne la cible mais la rend Pacifiste.\nSur un ennemi : rend la cible Pacifiste mais Invulnérable.', 0x088ec602088fc602, '1', 'Healing'),
(13347, 'Coffre Animé', 'Invoque un Coffre Animé maîtrisable qui tacle les ennemis.\nIl occasionne des dommages Eau aux ennemis à son contact et dévoile les invisibles. Ses dommages sont plus importants selon ses points de vie manquants.\n\nQuand il est attaqué par un allié, ce dernier est soigné.', 0x0891c6020892c602, '1', 'Summon'),
(13348, 'Déblayage', 'Pousse la cible.', 0x0894c6020895c6020896c602, '1', 'Agressive'),
(13349, 'Retraite Anticipée', 'Immobilise les cibles et applique l\'état Pesanteur sur tout le monde. N\'affecte pas le lanceur.\nImmobilise le lanceur au tour suivant.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0897c6020898c602, '1', 'Debuff'),
(13350, 'Prospection', 'Occasionne des dommages Eau aux ennemis au contact du lanceur.\nOccasionne des dommages Eau supplémentaires aux ennemis à son contact selon les points de vie manquants du lanceur.\nDévoile également les invisibles en zone.', 0x089ac602089bc602089cc602, '1', 'Agressive'),
(13351, 'Sac Rifice', 'Permet de subir les dommages reçus par les alliés ciblés.', 0x089dc602, '1', 'Agressive'),
(13352, 'Éboulement', 'Occasionne des dommages Terre. \n\nPendant 2 tours, occasionne des dommages Terre si l\'ennemi ciblé subit un retrait de Portée.\nÀ chaque nouveau déclenchement, l\'amplitude minimale et maximale des dommages augmente.\n\nPeut être déclenché 3 fois par tour.', 0x089ec60208a1d502, '1', 'Agressive'),
(13353, 'Monnaie Sonnante', 'Occasionne des dommages Air. \n\nPendant 2 tours, occasionne des dommages Air si l\'ennemi ciblé subit une tentative de retrait de PA.\nÀ chaque nouveau déclenchement, l\'amplitude minimale et maximale des dommages augmente. \n\nPeut être déclenché 3 fois par tour.', 0x089fc602088cd503, '1', 'Agressive'),
(13354, 'Musette Animée', 'Invoque une Musette Animée maîtrisable qui soigne et partage les dommages entre tous les alliés situés dans sa zone d\'invocation.\nLa Musette Animée disparaît 2 tours après son invocation.\n\nQuand elle est attaquée par un allié, ce dernier est soigné.', 0x08a0c60208a2d502, '1', 'Summon'),
(13355, 'Feu de Mine', 'Occasionne des dommages Feu.\nLes entités qui attaquent la cible sont soignées d\'une partie des dommages occasionnés.', 0x08a1c60208dcbc03, '1', 'Agressive'),
(13356, 'Déambulation', 'Réduit la durée des effets de la cible et échange sa position avec le Sac Animé ou la Musette Animée du lanceur.', 0x08a2c60208a6d502, '1', 'Debuff'),
(13357, 'Boîte à Outils', 'Augmente les PA et les PM de l\'allié ciblé mais le rend Pacifiste.\nSi l\'allié n\'est pas une invocation, rend également toutes ses invocations Pacifistes.', 0x08a3c60208a7d502, '1', 'Agressive'),
(13358, 'Tourbière', 'Occasionne des dommages Terre en zone.\nLes dommages du sort sont augmentés pour chaque PM utilisé pour le tour en cours.', 0x08a4c602, '1', 'Agressive'),
(13359, 'Clef de Bras', 'Soigne la cible mais lui retire 1 PM non esquivable.', 0x08a5c602, '1', 'Healing'),
(13360, 'Obsolescence', 'Occasionne des dommages Eau et retire de l\'Esquive PM.', 0x08a6c602, '1', 'Agressive'),
(13361, 'Bêche Animée', 'Invoque une Bêche Animée maîtrisable qui vole de la vie dans l\'élément Air.\nLa Bêche augmente sa Fuite ainsi que celle de l\'Enutrof et de ses invocations lorsqu\'elle occasionne des dommages.\n\nQuand elle est attaquée par un allié, ce dernier est soigné.', 0x08a7c602, '1', 'Summon'),
(13362, 'Avarice', 'Retire des PM non esquivables mais augmente les PA en zone. N\'affecte pas le lanceur.', 0x08a8c602, '1', 'Debuff'),
(13363, 'Orpaillage', 'Occasionne des dommages Eau. \n\nPendant 2 tours, occasionne des dommages Eau si l\'ennemi ciblé subit une tentative de retrait de PM.\nÀ chaque nouveau déclenchement, l\'amplitude minimale et maximale des dommages augmente.\n\nPeut être déclenché 3 fois par tour.', 0x08a9c60208a4d502, '1', 'Agressive'),
(13364, 'Vivacité', 'Soigne l\'allié ciblé et échange de position avec la cible.', 0x08aac60208e8bc0308e9bc03, '1', 'Healing'),
(13365, 'Abattement', 'Occasionne des dommages Air et retire des PA.', 0x08abc60208a5d5020886d503, '1', 'Agressive'),
(13366, 'Opportunité', 'Occasionne des dommages Air et augmente la Puissance du lanceur.', 0x08acc60208a9d50208aad502, '1', 'Agressive'),
(13367, 'Bêche des Anciens', 'Occasionne des dommages Air aux ennemis et repousse les cibles depuis le centre en zone.', 0x08adc602, '1', 'Agressive'),
(13368, 'Coup de Grisou', 'Occasionne des dommages Feu aux ennemis en zone.\n\nPendant 2 tours, occasionne des dommages Feu aux ennemis dans un cercle de 2 cases autour de la cible si elle est soignée.\nÀ chaque nouveau déclenchement, l\'amplitude minimale et maximale des dommages augmente. \n\nPeut être déclenché 3 fois par tour.', 0x08aec602, '1', 'Agressive'),
(13369, 'Décadence', 'Sur un allié : augmente ses dommages finaux immédiatement mais les réduit au tour suivant.\nSur un ennemi : retire des PA immédiatement mais réduit les dommages qu\'il subit au tour suivant.', 0x08afc602, '1', 'Agressive'),
(13370, 'Tamisage', 'Occasionne des dommages Eau et retire des PM en zone.\nN\'affecte pas le lanceur.', 0x08b0c602, '1', 'Agressive'),
(13371, 'Malle Animée', 'Invoque une Malle Animée maîtrisable qui soigne les alliés autour d\'elle.\n\nQuand elle est attaquée par un allié, ce dernier est soigné.', 0x08b1c602, '1', 'Summon'),
(13372, 'Dernier Recours', 'Applique l\'état Pesanteur sur les ennemis en zone autour de l\'allié ciblé.\nSi l\'allié ciblé est une invocation Enutrof, occasionne également des dommages Neutre aux ennemis en zone selon les points de vie manquants de la cible.', 0x08b2c602, '1', 'Agressive'),
(13373, 'Butin Partagé', '', 0x08b3c602, '0', 'Agressive'),
(13375, 'Déambulation', '', 0x08b5c6020881c003, '0', 'None'),
(13376, 'Trésor d\'Enutrof', '', 0x08b6c602, '0', 'Buff'),
(13377, 'Bêchattaque', 'Vole de la vie dans l\'élément Air et augmente la Fuite du lanceur, de son invocateur et de ses invocations.', 0x08b7c602, '1', 'Agressive'),
(13378, 'Orpaillage', '', 0x08b8c60208a3d50208e6e00308e7e00308e6ea03, '0', 'None'),
(13379, 'Coup de Grisou', '', 0x08b9c602, '0', 'Agressive'),
(13381, 'Malle aux Trésors', 'Soigne les alliés en zone autour du lanceur.', 0x08bbc602, '1', 'Healing'),
(13382, 'Dernier Recours', '', 0x08bcc60208eabc03, '0', 'Agressive'),
(13383, 'Décadence', '', 0x08bdc6020887d503, '0', 'Agressive'),
(13384, 'Boîte à Outils', '', 0x08bec60208bfc6020889eb03088aeb03, '0', 'None'),
(13385, 'Diffraction', 'Applique un bouclier sur tout le monde selon la distance avec le lanceur :\n• 0 à 5 cases : 450% du niveau en bouclier.\n• 6 à 11 cases : 250% du niveau en bouclier.\n• 12 cases et plus : 50% du niveau en bouclier.\nLe bouclier est réduit de moitié sur les invocations.', 0x08c0c602, '1', 'Agressive'),
(13386, 'Masque de l\'Intrépide', 'Applique le Masque de l\'Intrépide sur le lanceur :\n• Applique l\'état Intrépide sur le lanceur.\n• Augmente les PA du lanceur et de ses alliés (hors Zobals) dans une croix d\'une case.\n• Attire les entités vers le centre en zone.', 0x08c1c60208f7c60208f8c602, '1', 'Agressive'),
(13387, 'Masque du Pleutre', 'Applique le Masque du Pleutre sur le lanceur :\n• Applique l\'état Pleutre sur le lanceur.\n• Augmente les PM et la Fuite du lanceur et de ses alliés (hors Zobals) en zone.', 0x08c2c60208f5c60208f6c602, '1', 'Agressive'),
(13388, 'Masque du Psychopathe', 'Applique le Masque du Psychopathe sur le lanceur :\n• Applique l\'état Psychopathe sur le lanceur.\n• Augmente les dommages en mêlée du lanceur et de ses alliés (hors Zobals) en zone.', 0x08c3c60208f9c60208fac602, '1', 'Agressive'),
(13389, 'Martelo', 'Occasionne des dommages Terre et retire des PM en zone.', 0x08c4c60208d4c602, '1', 'Agressive'),
(13390, 'Rétention', 'Vole de la vie dans l\'élément Air et retire des PA.', 0x08c5c602, '1', 'Agressive'),
(13391, 'Parafuso', 'Vole de la vie dans l\'élément Eau et retire de la Puissance.', 0x08c6c60208e3c60208e4c602, '1', 'Agressive'),
(13392, 'Distance', 'Occasionne des dommages Eau aux ennemis et repousse la cible.\n\nNécessite l\'état Pleutre.', 0x08c7c602, '1', 'Agressive'),
(13393, 'Apathie', 'Occasionne des dommages Terre et retire des PM.', 0x08c8c60208eb8b04, '1', 'Agressive'),
(13394, 'Furia', 'Occasionne des dommages Terre aux ennemis et augmente les Dommages du lanceur.', 0x08c9c60208f1c60208f2c602, '1', 'Agressive'),
(13395, 'Cabriole', 'Téléporte le lanceur sur la case ciblée ou symétriquement par rapport à la cible et occasionne des dommages Air aux ennemis en zone.', 0x08cac60208e1c60208e2c602, '1', 'Agressive'),
(13396, 'Boliche', 'Rapproche le lanceur de la cible, occasionne des dommages Eau aux ennemis et repousse la cible.', 0x08cbc60208eac602, '1', 'Agressive'),
(13397, 'Plastron', 'Applique un bouclier sur les alliés en zone.\nLe bouclier est réduit de moitié sur les invocations.', 0x08ccc60208dbc60208dcc602, '1', 'Buff'),
(13398, 'Tortoruga', 'Applique un bouclier sur l\'allié ciblé.\nLe bouclier est réduit de moitié sur les invocations.', 0x08cdc60208edc60208eec602, '1', 'Buff'),
(13399, 'Transe', 'Sacrifie temporairement une partie des points de vie du lanceur pour appliquer un bouclier aux alliés en zone.\nLe bouclier est réduit de moitié sur les invocations.\n\nNécessite l\'état Psychopathe.', 0x08cec60208e5c60208e6c602, '1', 'Debuff'),
(13400, 'Reuche', 'Rapproche le lanceur de la cible.\n\nNécessite l\'état Intrépide.', 0x08cfc60208d9c60208dac602, '1', 'Agressive'),
(13401, 'Débandade', 'Téléporte le lanceur sur la case ciblée et augmente ses PM.\n\nNécessite l\'état Pleutre.', 0x08d0c60208dfc60208e0c602, '1', 'Teleport'),
(13402, 'Fougue', 'Rend la cible Intaclable et Insoignable.\n\nNécessite l\'état Psychopathe.', 0x08d1c60208ddc60208dec602, '1', 'None'),
(13403, 'Appui', 'Éloigne le lanceur de la cible et occasionne des dommages Air, Eau, Terre et Feu aux ennemis.', 0x08d2c60208d6c60208d7c602, '1', 'Agressive'),
(13404, 'Mascarade', 'Occasionne des dommages Neutre au lanceur et à la cible :\n• Les dommages sur la cible dépendent des points de vie restants du lanceur.\n• Les dommages sur le lanceur dépendent de ses points de vie manquants.\n• Les effets sont permutés si le lanceur est à moins de 50% de ses points de vie.', 0x08d3c602, '1', 'Agressive'),
(13405, 'Picada', 'Occasionne des dommages Air et retire des PA.', 0x08d8c60208ebc602, '1', 'Agressive'),
(13406, 'Masque du Couard', 'Applique le Masque du Couard sur le lanceur :\n• Applique l\'état Pleutre sur le lanceur.\n• Augmente les dommages à distance du lanceur et de ses alliés (hors Zobals) en zone.', 0x08fbc60208acdc02, '1', 'Agressive'),
(13407, 'Agular', 'Réduit les soins reçus par les cibles et occasionne des dommages Air en zone.\nN\'affecte pas le lanceur.', 0x08fcc602, '1', 'Buff'),
(13408, 'Appeau', 'Attire la cible et vole de la vie dans l\'élément Feu aux ennemis.', 0x08fdc60208aedc02, '1', 'Agressive'),
(13409, 'Masque de l\'Infatigable', 'Applique le Masque de l\'Infatigable sur le lanceur :\n• Applique l\'état Intrépide sur le lanceur.\n• Réduit les dommages subis par le lanceur.\n• Augmente les PA du lanceur et de ses alliés (hors Zobals) en zone.', 0x08fec60208afdc02, '1', 'Agressive'),
(13410, 'Pivot', 'Téléporte le lanceur symétriquement par rapport à la cible.', 0x08ffc60208b0dc02, '1', 'Agressive'),
(13411, 'Armadur', 'Augmente les PM et la Fuite de la cible.', 0x08b1dc02, '1', 'Buff'),
(13412, 'Scudo', 'Applique un bouclier sur l\'allié ciblé.\nLe bouclier est réduit de moitié sur les invocations.', 0x0881c702, '1', 'Buff'),
(13414, 'Masque de l\'Hystérique', 'Applique le Masque de l\'Hystérique sur le lanceur :\n• Applique l\'état Psychopathe sur le lanceur.\n• Augmente les Dommages Poussée du lanceur et de ses alliés (hors Zobals) en zone.\n• Repousse les cibles en zone.', 0x0883c70208919003, '1', 'Agressive'),
(13415, 'Cavalcade', 'Rapproche le lanceur de la cible et occasionne des dommages Air aux ennemis.', 0x0884c702088c9003, '1', 'Agressive'),
(13417, 'Ginga', 'Réduit les dommages subis par la cible et lui applique l\'état Indéplaçable.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0886c702, '1', 'Buff'),
(13418, 'Comédie', 'Repousse et attire la cible.', 0x0887c702, '1', 'Agressive'),
(13419, 'Bocciara', 'Occasionne des dommages Eau aux ennemis et augmente les Dommages Poussée du lanceur.', 0x0888c702, '1', 'Agressive'),
(13420, 'Catalepsie', 'Vole de la vie dans l\'élément Terre et retire de la Fuite en zone.\nN\'affecte pas le lanceur.', 0x0889c7020887900308ec8b04, '1', 'Agressive'),
(13421, 'Apostasie', 'Éloigne le lanceur de la cible, la repousse et occasionne des dommages Feu aux ennemis.', 0x088ac702, '1', 'Agressive'),
(13422, 'Ponteira', 'Occasionne des dommages Eau et retire des Dommages.', 0x088bc70208f18b0408f28b04, '1', 'Agressive'),
(13423, 'Inferno', 'Occasionne des dommages Feu aux ennemis et augmente la Puissance du lanceur.', 0x088cc70208ef8b0408f08b04, '1', 'Agressive'),
(13424, 'Grimace', 'Invoque un Masque Grimaçant maîtrisable qui tacle les ennemis et partage ses dommages avec son invocateur tant qu\'il est en vie.\nQuand un ennemi se fait tacler par le Masque Grimaçant, le Masque et son invocateur gagnent du bouclier.\n\nSi le Masque Grimaçant du lanceur est encore en vie et que celui-ci est réinvoqué, l\'ancien est tué pour laisser place au nouveau.', 0x088dc7020894c702, '1', 'Agressive'),
(13425, 'Brincadeira', 'Occasionne des dommages Feu et retire de la Portée.', 0x088ec70208ed8b0408ee8b04, '1', 'Agressive'),
(13426, 'Névrose', 'Augmente la Puissance de l\'allié ciblé et applique l\'état Pesanteur sur la cible.', 0x088fc702, '1', 'Buff'),
(13427, 'Grimace', '', 0x0890c7020895c702, '0', 'Buff'),
(13428, 'Masque de l\'Hystérique', '', 0x0896c702, '0', 'Agressive'),
(13429, 'Roublabot', 'Invoque un robot contrôlable capable de pousser, attirer ou faire exploser les Bombes du lanceur.\nLe robot meurt à la fin de son tour de jeu.', 0x0897c70208d5c70208d6c702, '1', 'None'),
(13430, 'Rémission', '', 0x0898c7020899c702089ac70208d1ea03, '1', 'None'),
(13431, 'Roublardise', 'Applique un bouclier sur toutes les Bombes du lanceur.\nLe bouclier est également appliqué sur sa Mégabombe et sa Bombe Ambulante.\n\nCrée plusieurs images du lanceur pour tromper ses adversaires, et lui permet de se téléporter. Les images disparaissent si elles reçoivent des dommages.\nTermine le tour en cours du lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x089bc702089cc702089dc702, '1', 'Agressive'),
(13432, 'Détonateur', 'Ajoute 1 Combo à une Bombe du lanceur et déclenche son explosion sans ligne de vue.\nRend 1 PA au lanceur avant l\'explosion.', 0x089ec702089fc70208a0c702, '1', 'Agressive'),
(13433, 'Extraction', 'Vole de la vie dans l\'élément Feu.\nLe vol de vie est réduit de moitié sur les alliés.', 0x08a1c70208a2c70208a3c702, '1', 'Agressive'),
(13434, 'Botte', 'Applique un bouclier sur les Bombes du lanceur et les pousse depuis le centre en zone.\nPlus le sort est lancé à proximité d\'une Bombe du lanceur, plus elle est poussée.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.\n\nPousse les autres entités d\'une case seulement.\nN\'affecte pas le lanceur.', 0x08a4c70208a5c70208a6c702, '1', 'Agressive'),
(13435, 'Tornabombe', 'Pose une bombe qui occasionne des dommages Air et retire des PM selon son Combo dans un cercle de 2 cases à son explosion.\n• Combo I à IV : -1 PM\n• Combo V à IX : -2 PM\n• Combo X à XV : -3 PM\n• Mur d\'Air : -2 PM\n\nSi le sort est lancé sur une cible : occasionne des dommages Air et retire des PM dans un cercle de 2 cases sur la cible.\nSi la cible est une bombe du lanceur, ajoute 1 Combo à la bombe et déclenche son explosion.\n\nLe coût en PA du sort augmente de 1 pour chaque Tornabombe du lanceur présente sur le terrain.', 0x08a7c70208a8c70208a9c702, '1', 'Summon'),
(13436, 'Bombe à Eau', 'Pose une bombe qui occasionne des dommages Eau et retire des PA selon son Combo dans un cercle de 2 cases à son explosion.\n• Combo I à IV : -0 PA\n• Combo V à IX : -1 PA\n• Combo X à XV : -2 PA\n\nSi le sort est lancé sur une cible : occasionne des dommages Eau dans un cercle de 2 cases sur la cible.\nSi la cible est une bombe du lanceur, ajoute 1 Combo à la bombe et déclenche son explosion.\n\nLe mur de Bombes à Eau retire des PA uniquement aux entités qui commencent leur tour à l\'intérieur.\n• Mur d\'Eau : -2 PA\n\nLe coût en PA du sort augmente de 1 pour chaque Bombe à Eau du lanceur présente sur le terrain.', 0x08aac70208abc70208acc702, '1', 'Summon'),
(13437, 'Aimantation', 'Ajoute 1 Combo une fois par Bombe par tour en zone. N\'affecte pas la case centrale.\nAttire les Bombes du lanceur dans la zone d\'effet vers la cible. Le Combo ne s\'applique que si les Bombes sont effectivement déplacées.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.\n\nAttire les autres entités d\'une case seulement.\nN\'affecte pas le lanceur.', 0x08adc70208aec70208afc702, '1', 'Agressive'),
(13438, 'Dagues Boomerang', 'Érode les cibles et occasionne des dommages Air en zone.', 0x08b0c70208b1c70208b2c702, '1', 'Agressive'),
(13439, 'Entourloupe', 'Ajoute 1 Combo à une Bombe du lanceur, échange de position avec elle et lui applique l\'état Pesanteur.\nLes effets ne s\'appliquent que si l\'échange de positions peut s\'effectuer.\nPeut être utilisé sur sa Mégabombe.', 0x08b3c70208b4c70208b5c702, '1', 'Agressive'),
(13440, 'Espingole', 'Occasionne des dommages Air aux ennemis et repousse les cibles en zone.', 0x08b6c70208b7c70208e5a803, '1', 'Agressive'),
(13441, 'Poudre', 'Applique l\'état Indéplaçable sur une Bombe du lanceur.\nAjoute 2 Combo à la Bombe et déclenche son explosion si elle meurt.\n\nLes effets sont retirés si la Bombe est déclenchée par un effet d\'explosion et ne peuvent pas être désenvoûtés.', 0x08b9c70208bac702, '1', 'Agressive'),
(13442, 'Pulsar', 'Occasionne des dommages Feu aux ennemis et repousse les cibles en zone.\nN\'affecte pas le lanceur.', 0x08bcc70208bdc70208bec702, '1', 'Agressive'),
(13443, 'Resquille', 'Occasionne des dommages Eau et retire des PA en zone.\nN\'affecte pas le lanceur.\n\nSur des Bombes du lanceur : les téléporte symétriquement par rapport au centre de la zone.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.', 0x08bfc70208c0c702, '1', 'Agressive'),
(13444, 'Explobombe', 'Pose une bombe qui occasionne des dommages Feu dans un cercle de 2 cases à son explosion.\n\nSi le sort est lancé sur une cible : occasionne des dommages Feu dans un cercle de 2 cases sur la cible.\nSi la cible est une bombe du lanceur, ajoute 1 Combo à la bombe et déclenche son explosion.\n\nLe coût en PA du sort augmente de 1 pour chaque Explobombe du lanceur présente sur le terrain.', 0x08c2c70208c3c70208c4c702, '1', 'Summon'),
(13445, 'Rémission', 'Applique l\'état Rémission sur la cible :\n• Repousse les attaquants si la cible subit des dommages en mêlée.\n\nSur une Bombe du lanceur : réduit les dommages reçus à distance.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.', 0x08c5c70208c6c70208c7c702, '1', 'Agressive'),
(13446, 'Dernier Souffle', 'Réduit la Vitalité maximale du lanceur pour ajouter temporairement 3 Combo à ses Bombes.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08c8c70208c9c702, '1', 'Agressive'),
(13449, 'Tromblon', 'Érode les cibles et occasionne des dommages Eau en zone.', 0x08cfc702, '1', 'Debuff'),
(13450, 'Kaboom', 'Applique l\'état Kaboom sur les alliés en zone.\n\nSur des Bombes du lanceur : ajoute 1 Combo.', 0x08d2c70208d4c702, '1', 'Agressive'),
(13451, 'Poussette', 'Pousse une cible jusqu\'à la case ciblée.\nSi la cible est une Bombe du lanceur, lui ajoute également 1 Combo si elle est effectivement déplacée.', 0x08d7c70208d8c70208d9c702, '1', 'Agressive'),
(13452, 'Aspirateur', 'Attire une cible jusqu\'à la case ciblée.\nSi la cible est une Bombe du lanceur, lui ajoute également 1 Combo si elle est effectivement déplacée.', 0x08dac70208dbc70208dcc702, '1', 'Agressive'),
(13453, 'Détonation', 'Ajoute 1 Combo à une Bombe du lanceur et déclenche son explosion.', 0x08ddc70208dec70208dfc702, '1', 'Debuff'),
(13454, 'Initialisation', '', 0x08e0c702, '1', 'Agressive'),
(13455, 'Explosion Roublarde', '', 0x08e1c70208e2c70208e3c702, '0', 'Agressive'),
(13456, 'Explosion Roublarde', '', 0x08e4c70208e5c70208e6c702, '0', 'Agressive'),
(13457, 'Explosion Roublarde', '', 0x08e7c702088aa903088ba903088ca903088da903088ea903, '1', 'Debuff'),
(13458, 'Mur de Feu', '', 0x08edc70208eec70208efc702, '1', 'Agressive'),
(13459, 'Tornade Roublarde', '', 0x08f0c70208f1c70208f2c702, '0', 'Agressive'),
(13460, 'Tornade Roublarde', '', 0x08f3c70208fba80308fca80308fda80308fea80308ffa803, '1', 'Debuff'),
(13461, 'Mur d\'Air', '', 0x08f9c70208fac70208fbc702, '1', 'Agressive'),
(13462, 'Averse Roublarde', '', 0x08fcc70208fdc70208fec702, '0', 'Agressive'),
(13463, 'Averse Roublarde', '', 0x08ffc7020880c8020881c802, '0', 'Agressive'),
(13464, 'Averse Roublarde', '', 0x0882c8020885a9030886a9030887a9030888a9030889a903, '1', 'Debuff'),
(13465, 'Mur d\'Eau', '', 0x0888c8020889c802088ac802, '1', 'Agressive'),
(13467, 'Tornade Roublarde', '', 0x0891c8020892c8020893c802, '0', 'Agressive'),
(13468, 'Allumage', '', 0x0894c802, '1', 'Agressive'),
(13469, 'Oblitération', 'Occasionne des dommages Terre.\nLes dommages sont augmentés pour chaque explosion de Sismobombe ou de Bombe Collante.\n\nSur une Bombe du lanceur : ajoute du Combo pour chaque explosion de Sismobombe ou de Bombe Collante.\n\nLes effets sont retirés après utilisation du sort.', 0x0895c80208f5d702, '1', 'Agressive'),
(13470, 'Étoupille', 'Déclenche l\'explosion d\'une Bombe du lanceur.\nRend 3 PA au lanceur avant l\'explosion.', 0x0896c80208f4d702, '1', 'Agressive'),
(13471, 'Explobombe Résiliente', 'Pose une bombe qui occasionne des dommages Feu dans un cercle de 2 cases à son explosion.\n\nSi le sort est lancé sur une cible : occasionne des dommages Feu dans un cercle de 2 cases sur la cible.\nSi la cible est une bombe du lanceur, ajoute 1 Combo à la bombe et déclenche son explosion.\n\nUne Bombe Résiliente possède plus de points de vie qu\'une Bombe de base.', 0x0897c80208f6d702, '1', 'Summon'),
(13472, 'Ruse', 'Applique un bouclier sur une Bombe du lanceur et le rapproche d\'elle.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.\n\nSur un allié hors Bombes du lanceur : rapproche le lanceur de la cible.\nLe rapprochement est plus faible sur les alliés.', 0x0898c80208f7d702, '1', 'Agressive'),
(13473, 'Mousquet', 'Occasionne des dommages Terre.\nAjoute 1 Combo aux Bombes du lanceur au contact de la cible une fois par Bombe par tour.', 0x0899c80208ffd403, '1', 'Agressive'),
(13474, 'Tornabombe Résiliente', 'Pose une bombe qui occasionne des dommages Air et retire des PM selon son Combo dans un cercle de 2 cases à son explosion.\n• Combo I à IV : -1 PM\n• Combo V à IX : -2 PM\n• Combo X à XV : -3 PM\n• Mur d\'Air : -2 PM\n\nSi le sort est lancé sur une cible : occasionne des dommages Air et retire des PM dans un cercle de 2 cases sur la cible.\nSi la cible est une bombe du lanceur, ajoute 1 Combo à la bombe et déclenche son explosion.\n\nUne Bombe Résiliente possède plus de points de vie qu\'une Bombe de base.', 0x089ac80208f9d702, '1', 'Summon'),
(13475, 'Cadence', 'Occasionne des dommages Air.\nRetire des PM pour chaque Bombe, Mégabombe ou Bombe Ambulante du lanceur au contact de l\'ennemi ciblé.\n\nSur une Bombe du lanceur : occasionne des dommages Air et retire des PM aux ennemis dans une croix d\'une case.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.', 0x089bc802, '1', 'Agressive'),
(13476, 'Stratagème', 'Téléporte une Bombe du lanceur à sa position précédente et lui applique un bouclier.\n\nLe bouclier ne s\'applique que si la téléportation peut s\'effectuer.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.', 0x089cc802, '1', 'Debuff'),
(13477, 'Recel', 'Occasionne des dommages Eau aux ennemis et attire la cible.', 0x089dc80208b4a70308b5a703, '1', 'Agressive'),
(13478, 'Bombe à Eau Résiliente', 'Pose une bombe qui occasionne des dommages Eau et retire des PA selon son Combo dans un cercle de 2 cases à son explosion.\n• Combo I à IV : -0 PA\n• Combo V à IX : -1 PA\n• Combo X à XV : -2 PA\n\nSi le sort est lancé sur une cible : occasionne des dommages Eau dans un cercle de 2 cases sur la cible.\nSi la cible est une bombe du lanceur, ajoute 1 Combo à la bombe et déclenche son explosion.\n\nLe mur de Bombes à Eau retire des PA uniquement aux entités qui commencent leur tour à l\'intérieur.\n• Mur d\'Eau : -2 PA\n\nUne Bombe Résiliente possède plus de points de vie qu\'une Bombe de base.', 0x089ec802, '1', 'Summon'),
(13479, 'Bombe Collante', 'Pose une Bombe Collante sur la cible.\nSur une case libre : pose un piège qui pose une Bombe Collante sur l\'entité qui le déclenche ou déclenche l\'explosion d\'une Bombe du lanceur.\n\nLa Bombe peut être activée avec les sorts d\'activation ou les explosions de bombe.\nQuand elle est activée, elle occasionne des dommages dans le meilleur élément d\'attaque du lanceur dans un cercle de 2 cases.\n\nUne Bombe Collante ne peut pas être appliquée sur une Bombe, Mégabombe, ou Bombe Ambulante alliée.', 0x089fc802, '0', 'Agressive'),
(13480, 'Croisement', 'Ajoute 1 Combo une fois par Bombe par tour en zone. N\'affecte pas la case centrale.\nAttire les Bombes du lanceur dans la zone d\'effet vers la case ciblée. Le Combo ne s\'applique que si les Bombes sont effectivement déplacées.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.', 0x08a0c80208fbd702, '1', 'Agressive'),
(13482, 'Arquebuse', 'Réduit la durée des effets sur la cible et occasionne des dommages Terre aux ennemis.', 0x08a5c802, '1', 'Debuff'),
(13483, 'Mitraille', 'Occasionne des dommages Air et retire des PM aux ennemis en zone.', 0x08a6c802, '1', 'Agressive'),
(13484, 'Piège Magnétique', 'Pose un piège mono-cellule qui attire les cibles, ajoute 1 Combo aux Bombes du lanceur et déclenche leur explosion dans un cercle de 3 cases.', 0x08a7c802, '1', 'Mark'),
(13485, 'Piège Magnétique', '', 0x08a8c802, '0', 'Agressive'),
(13486, 'Sismobombe Résiliente', 'Pose une bombe qui occasionne des dommages Terre dans un cercle de 2 cases à son explosion.\n\nSi le sort est lancé sur une cible : occasionne des dommages Terre dans un cercle de 2 cases sur la cible.\nSi la cible est une bombe du lanceur, ajoute 1 Combo à la bombe et déclenche son explosion.\n\nUne Bombe Résiliente possède plus de points de vie qu\'une Bombe de base.', 0x08a9c802, '1', 'Summon'),
(13487, 'Bombe Ambulante', 'Invoque une Bombe contrôlable qui peut obtenir un élément et du Combo en ciblant une Bombe élémentaire.\nElle se détruit pour poser une Bombe dans l\'élément correspondant à la fin de son tour en lui ajoutant jusqu\'à 7 Combos de la Bombe ciblée.\nCette Bombe entre dans l\'état Pacifiste jusqu\'au début du prochain tour du lanceur.\n\nElle est détruite au bout de 2 tours si elle n\'a pas obtenu d\'élément.', 0x08aac80208c2af03, '1', 'Agressive'),
(13488, 'Plombage', 'Occasionne des dommages Feu aux ennemis.\n\nSur une Bombe du lanceur : occasionne des dommages Feu aux ennemis situés entre deux Bombes alignées.\nAjoute 1 Combo aux Bombes affectées une fois par Bombe par tour.', 0x08abc802, '1', 'Agressive'),
(13489, 'Imposture', 'Échange de positions avec la cible et applique l\'état Kaboom sur le lanceur.\n• Si la cible est un allié : lui applique également l\'état.\n• Si la cible est une Bombe du lanceur : ajoute également 1 Combo à la Bombe.\nApplique l\'état Imposture sur le lanceur et l\'allié ciblé au tour suivant, qui empêche l\'application de l\'état Kaboom.\n\nLe Combo et l\'état Kaboom ne s\'appliquent que si l\'échange de positions peut s\'effectuer.', 0x08acc802, '1', 'Agressive'),
(13490, 'Mégabombe', 'Invoque une Mégabombe contrôlable qui occasionne des dommages Neutre.\nSes dommages augmentent à chaque fois qu\'elle dévore une Bombe. Elle perd 1 PM par Bombe dévorée.\nLorsqu\'elle meurt, elle explose en ajoutant 1 Combo aux Bombes du lanceur et déclenche leur explosion dans une zone de 2 cases autour d\'elle.\n\nLa Mégabombe est sensible aux murs de bombes.', 0x08adc802, '1', 'None'),
(13491, 'Sismobombe', 'Pose une bombe qui occasionne des dommages Terre dans un cercle de 2 cases à son explosion.\n\nSi le sort est lancé sur une cible : occasionne des dommages Terre dans un cercle de 2 cases sur la cible.\nSi la cible est une bombe du lanceur, ajoute 1 Combo à la bombe et déclenche son explosion.\n\nLe coût en PA du sort augmente de 1 pour chaque Sismobombe du lanceur présente sur le terrain.', 0x08aec80208b0c80208b1a703, '1', 'Summon'),
(13493, 'Mimésis', '', 0x08b5c80208c0c80208dcd70308e1d803, '0', 'None'),
(13494, 'Mimésis', '', 0x08b6c80208b7c80208b8c80208b9c80208d7d703, '0', 'None'),
(13495, 'Mimésis', 'Attribue à la Bombe Ambulante le même élément que celui de la Bombe ciblée.\nPeut copier jusqu\'à 7 Combos de la Bombe ciblée.\n\nLa nouvelle Bombe entre dans l\'état Pacifiste jusqu\'au début du prochain tour de son invocateur.', 0x08bac802, '1', 'Agressive'),
(13496, 'Absorption Explosive', '', 0x08bbc80208fdd503, '0', 'None'),
(13497, 'Absorption Explosive', 'Attire une Bombe du lanceur et la tue. Augmente les dommages occasionnés et la Vitalité de la Mégabombe mais lui retire des PM.', 0x08bcc802, '1', 'Agressive'),
(13498, 'Mégattaque', 'Occasionne des dommages Neutre.', 0x08bdc802, '1', 'Agressive'),
(13499, 'Mégaboom', '', 0x08bec802, '0', 'Agressive'),
(13500, 'Mégaboom', '', 0x08bfc802, '0', 'Agressive'),
(13501, 'Mur de Terre', '', 0x08c2c80208c3c80208c4c802, '1', 'Agressive'),
(13502, 'Avalanche Roublarde', '', 0x08c5c8020880a9030881a9030882a9030883a9030884a903, '1', 'Debuff'),
(13503, 'Avalanche Roublarde', '', 0x08cbc80208ccc80208cdc802, '0', 'Agressive'),
(13504, 'Avalanche Roublarde', '', 0x08cec80208cfc80208d0c802, '0', 'Agressive'),
(13505, 'Cadence', '', 0x08d1c80208c0870408c18704, '0', 'Debuff'),
(13506, 'Mégamikaze', 'Tue la Mégabombe et déclenche son explosion :\n• Occasionne des dommages Neutre en zone.\n• Ajoute 1 Combo aux Bombes du lanceur et déclenche leur explosion en zone.', 0x08d2c802, '1', 'Agressive'),
(13507, 'Bombe Collante', '', 0x08d3c80208ddc802, '0', 'Agressive'),
(13510, 'Étoupille', '', 0x08dbc80208a0dd03, '0', 'Buff'),
(13511, 'Oblitération', '', 0x08dcc802, '0', 'Buff'),
(13514, 'Tremblement', 'Dans un cercle de 3 cases autour de chaque Arbre Feuillu du lanceur :\n• Attire les cibles vers le centre de la zone.\n• Occasionne des dommages Feu aux ennemis.\n• Dévoile les invisibles.', 0x08e0c80208e1c80208e2c802, '1', 'Agressive'),
(13515, 'Folle Transmutée', 'Remplace un Arbre Feuillu du lanceur par une Folle maîtrisable qui retire des PA aux ennemis et leur applique l\'état Infecté.\n\nSi un ennemi dans l\'état Infecté est ciblé par un sort monocible du Sadida : tous les ennemis dans l\'état Infecté sont affectés par ce sort.\n\nLes effets appliqués aux ennemis secondaires infectés ne prennent pas en compte les coups critiques et peuvent être déclenchés 3 fois par tour.\n\nÀ sa mort, la Folle redevient un Arbre Chétif.', 0x08e3c80208b9d702, '1', 'Agressive'),
(13516, 'Ronce', 'Occasionne des dommages Terre.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Terre à tous les ennemis dans l\'état Infecté.', 0x08e4c80208e5c80208e6c802, '1', 'Agressive'),
(13517, 'Feu de Brousse', 'Occasionne des dommages Feu et Eau.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Feu et Eau à tous les ennemis dans l\'état Infecté.', 0x08e7c80208e8c802, '1', 'Agressive'),
(13518, 'Herbe Folle', 'Retire des PM et occasionne des dommages Feu en zone.\nN\'affecte pas le lanceur et ses invocations.', 0x08eac80208ebc802, '1', 'Debuff'),
(13519, 'Arbre', 'Plante un Arbre.\n\nAprès 1 tour, un Arbre devient Feuillu et peut être utilisé comme intermédiaire pour lancer des sorts Sadida (mais ne peut plus être poussé ou attiré).', 0x08edc80208eec80208efc802, '1', 'Summon'),
(13520, 'Surpuissante Transmutée', 'Remplace un Arbre Feuillu du lanceur par une Surpuissante maîtrisable qui retire des PM aux ennemis en zone.\nElle retire des PM supplémentaires à tous les ennemis au contact des Arbres Feuillus du lanceur.\n\nÀ sa mort, la Surpuissante redevient un Arbre Chétif.', 0x08f0c802, '1', 'Agressive'),
(13521, 'Ronce Insolente', 'Réduit la durée des effets sur la cible.\n\nSur un ennemi dans l\'état Infecté : réduit la durée des effets sur tous les ennemis dans l\'état Infecté.', 0x08f1c80208f2c802, '1', 'Agressive'),
(13522, 'Sacrifiée Transmutée', 'Remplace un Arbre Feuillu du lanceur par une Sacrifiée maîtrisable qui meurt en appliquant l\'état Infecté et en occasionnant des dommages Eau.\nElle applique également l\'état Infecté sur tous les ennemis au contact des Arbres Feuillus du lanceur.\n\nPour chaque tour où la Sacrifiée reste en vie, sa Vitalité et ses dommages finaux occasionnés augmentent.\n\nÀ sa mort, la Sacrifiée redevient un Arbre Chétif.', 0x08f4c802, '1', 'Agressive'),
(13523, 'Gonflable Transmutée', 'Remplace un Arbre Feuillu du lanceur par une Gonflable maîtrisable qui soigne en zone donne des PM aux alliés.\nElle soigne également tous les alliés au contact des Arbres Feuillus du lanceur.\n\nÀ sa mort, la Gonflable redevient un Arbre Chétif.', 0x08f5c802, '1', 'Agressive'),
(13524, 'Ronces Multiples', 'Occasionne des dommages Terre en zone.\nN\'affecte pas le lanceur et ses invocations.', 0x08f6c80208f7c80208f8c802, '1', 'Agressive'),
(13525, 'Ronce Apaisante', 'Retire des PM aux ennemis ou soigne les alliés.\n\nSur un ennemi dans l\'état Infecté : retire des PM à tous les ennemis dans l\'état Infecté.\nLa perte de PM est plus faible sur les ennemis infectés autres que la cible.', 0x08f9c80208fac80208fbc802, '1', 'Agressive'),
(13526, 'Bloqueuse Transmutée', 'Remplace un Arbre Feuillu du lanceur par une Bloqueuse maîtrisable qui tacle les adversaires.\nElle peut également échanger sa position avec un Arbre Feuillu du lanceur et augmenter son Tacle si elle est dans l\'état Contrôlé.\n\nÀ sa mort, la Bloqueuse redevient un Arbre Chétif.', 0x08fcc80208cbd702, '1', 'Agressive'),
(13527, 'Ronces Agressives', 'Occasionne des dommages Terre.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Terre à tous les ennemis dans l\'état Infecté.\n\nDonne 1 PM au lanceur par ennemi touché.', 0x08fdc80208fec80208ffc802, '1', 'Agressive'),
(13528, 'Larme', 'Occasionne des dommages Eau.\n\nSur un Arbre du lanceur : le transforme en Arbre Feuillu.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Eau à tous les ennemis dans l\'état Infecté.', 0x0880c9020881c9020882c902, '1', 'Agressive'),
(13529, 'Vent Empoisonné', 'Tue une Poupée du lanceur pour la transformer en Arbre et appliquer l\'état Infecté sur les ennemis en zone.', 0x0883c9020884c9020885c902, '1', 'Agressive'),
(13530, 'Puissance Sylvestre', 'Remplace un Arbre Feuillu du lanceur par un Arbre contrôlable qui peut :\n• Repousser une cible.\n• Réduire la durée des effets sur une cible.\n• Soigner les alliés en zone.\n\nÀ la fin de son tour, il redevient un Arbre Chétif.', 0x0886c9020887c9020888c902, '1', 'Agressive'),
(13531, 'Sacrifice Poupesque', 'Vole de la vie dans l\'élément Eau aux alliés ou occasionne des dommages Eau aux ennemis.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Eau à tous les ennemis dans l\'état Infecté.\n\nSur une Poupée du lanceur :\n• Vole de la vie dans l\'élément Eau et tue la Poupée.\n• Soigne les alliés dans un cercle de 2 cases autour du lanceur.\n• Réduit le temps de relance de la Poupée ciblée de 1 tour.', 0x0889c902088ac902088bc902, '1', 'Agressive'),
(13532, 'Don Naturel', 'Tue un Arbre Feuillu ou une Poupée du lanceur pour partager les dommages entre les alliés et les soigner en zone.\nLe partage de dommages n\'affecte pas les invocations.', 0x088cc902088dc902088ec902, '1', 'Agressive'),
(13533, 'Poison Paralysant', 'Applique un poison Feu de fin de tour et l\'état Infecté sur l\'ennemi ciblé.', 0x088fc9020890c90208adbd03, '1', 'Agressive'),
(13534, 'Arbre de Vie', 'Transforme un Arbre Feuillu allié en Arbre de Vie et augmente sa Vitalité.\n\nPendant 2 tours :\n• Les alliés qui attaquent l\'Arbre de Vie sont soignés d\'une partie des dommages occasionnés.\n• Soigne les invocations Sadida alliées à chaque fin de tour du lanceur.\n\nL\'Arbre de Vie redevient un Arbre Feuillu 2 tours après sa transformation.', 0x0892c9020893c902, '1', 'Agressive'),
(13535, 'Feuillage', '', 0x0895c90208a0e70308a1e703, '1', 'Agressive'),
(13536, 'Poussée Sylvestre', 'Repousse la cible.', 0x0896c90208d8f80308d9f803, '1', 'Agressive'),
(13537, 'Tremblement', '', 0x0897c9020898c9020899c90208c0e703, '0', 'None'),
(13538, 'Désenvoûtement Sylvestre', 'Réduit la durée des effets sur la cible.', 0x089ac90208d0f80308d1f803, '1', 'Debuff'),
(13539, 'Soin Sylvestre', 'Soigne les alliés en zone.', 0x089bc90208d2f80308d3f803, '1', 'Healing'),
(13540, 'Arbre Chétif', '', 0x089cc902, '0', 'Agressive'),
(13541, 'Préparation Poupesque', 'À partir du deuxième tour de jeu de la Sacrifiée, augmente sa Vitalité et ses dommages finaux occasionnés sur 3 tours.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08a2c902, '1', 'Buff'),
(13544, 'Don Naturel', '', 0x08aac90208abc90208acc902, '0', 'Agressive'),
(13545, 'Larme', '', 0x08adc90208cfc90208d0c90208c5e40308c6e40308c7e403, '0', 'Agressive'),
(13546, 'Ronce Apaisante', '', 0x08aec90208afc90208b0c902, '0', 'Debuff'),
(13547, 'Ronce Insolente', '', 0x08b1c90208b2c902, '0', 'Debuff'),
(13549, 'Arbre Chétif', '', 0x08bdc902, '0', 'Agressive'),
(13550, 'Arbre Chétif', '', 0x08c3c902, '0', 'Summon'),
(13551, 'Arbre Chétif', '', 0x08c9c902, '0', 'Agressive'),
(13552, 'Ronce', '', 0x08d1c90208d2c90208d3c90208b7e40308b8e40308b9e403, '0', 'Agressive'),
(13553, 'Sacrifice Poupesque', '', 0x08d4c90208d5c90208d6c90208c2e40308c3e40308c4e403, '0', 'Agressive'),
(13554, 'Ronces Agressives', '', 0x08d7c90208d8c90208d9c90208aaca0208bde40308bee40308bfe403, '0', 'Agressive'),
(13555, 'Feu de Brousse', '', 0x08dac90208dbc90208c0e40308c1e403, '0', 'Agressive'),
(13557, 'Arbre Chétif', '', 0x08dec902, '0', 'Agressive'),
(13558, 'Feuillage', '', 0x08e9c90208a8ca0208d0d70208d1dd0208edb403, '0', 'Agressive'),
(13559, 'Broussaille Empoisonnée', 'Applique un poison Terre de début de tour sur l\'ennemi ciblé.\n\nSur un ennemi dans l\'état Infecté : applique un poison Terre de début de tour sur tous les ennemis dans l\'état Infecté.', 0x08eac90208b6d702, '1', 'Agressive'),
(13560, 'Arbre Feuillu', 'Plante un Arbre Feuillu qui peut être utilisé comme intermédiaire pour lancer des sorts Sadida (mais ne peut pas être poussé ou attiré).\n\nTous les Arbres invoqués par le lanceur se transforment immédiatement en Arbres Feuillus.', 0x08ebc90208b5d702, '1', 'Summon'),
(13561, 'Bloqueuse', 'Invoque une Bloqueuse maîtrisable qui tacle les adversaires.\nElle peut également échanger sa position avec un Arbre Feuillu du lanceur et augmenter son Tacle si elle est dans l\'état Contrôlé.', 0x08ecc902089fca0208a0ca02, '1', 'Summon'),
(13562, 'Poison de Proximité', 'Applique l\'état Infecté sur tous les ennemis dans un cercle de 2 cases autour d\'une Poupée ou d\'un Arbre Feuillu du lanceur.', 0x08edc90208e0d702, '1', 'Agressive'),
(13563, 'Montée de Sève', 'Vole de la vie dans l\'élément Eau aux ennemis en zone.\nSoigne les alliés dans la zone d\'effet à hauteur de 50% des dommages occasionnés aux ennemis.\n\nSur des Arbres du lanceur : les transforme également en Arbres Feuillus.', 0x08eec90208dfd702, '1', 'Agressive'),
(13564, 'Folle', 'Invoque une Folle maîtrisable qui retire des PA aux ennemis et leur applique l\'état Infecté.\n\nSi un ennemi dans l\'état Infecté est ciblé par un sort monocible du Sadida : tous les ennemis dans l\'état Infecté sont affectés par ce sort.\n\nLes effets appliqués aux ennemis secondaires infectés ne prennent pas en compte les coups critiques et peuvent être déclenchés 3 fois par tour.', 0x08efc902089dca02089eca02, '1', 'Summon'),
(13565, 'Rempotage', 'Téléporte un Arbre Feuillu du lanceur sur la première case disponible entre le lanceur et lui et plante un Arbre.', 0x08f0c90208e2d702, '1', 'Agressive'),
(13566, 'Influence Végétale', 'Remplace un Arbre Feuillu du lanceur par un Arbre contrôlable qui peut :\n• Attirer une cible.\n• Retirer des PM aux ennemis en leur appliquant l\'état Infecté en zone.\n\nÀ la fin de son tour, il redevient un Arbre Chétif.', 0x08f1c902, '1', 'Agressive'),
(13567, 'Sacrifiée', 'Invoque une Sacrifiée maîtrisable qui meurt en appliquant l\'état Infecté et en occasionnant des dommages Eau.\nElle applique également l\'état Infecté sur tous les ennemis au contact des Arbres Feuillus du lanceur.\n\nPour chaque tour où la Sacrifiée reste en vie, sa Vitalité et ses dommages finaux occasionnés augmentent.', 0x08f2c90208a1ca0208a2ca02, '1', 'Summon'),
(13568, 'Secousse', 'Dans un cercle de 3 cases autour de chaque Arbre Feuillu du lanceur :\n• Occasionne des dommages Air aux ennemis.\n• Donne 1 PM au lanceur par ennemi touché.', 0x08f3c902, '1', 'Agressive'),
(13569, 'Inoculation', 'Tue un Arbre Feuillu allié ou une Poupée du lanceur pour occasionner des dommages Air aux ennemis et leur appliquer l\'état Infecté en zone.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Air plus faibles aux ennemis et leur applique l\'état Infecté en zone.', 0x08f4c902, '1', 'Agressive'),
(13570, 'Force de la Nature', 'Occasionne des dommages Terre.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Terre à tous les ennemis dans l\'état Infecté.\n\nLes dommages du sort sont augmentés pour chaque Arbre Feuillu du lanceur présent sur le terrain.', 0x08f5c902, '1', 'Agressive'),
(13571, 'Fléau', 'Vole de la vie dans l\'élément Eau.\n\nSur un ennemi dans l\'état Infecté : vole de la vie dans l\'élément Eau à tous les ennemis dans l\'état Infecté.', 0x08f6c902, '1', 'Agressive'),
(13572, 'Altruisme Végétal', 'Tue un Arbre Feuillu du lanceur pour augmenter la Vitalité de ses Poupées et le soigner.', 0x08f7c902, '1', 'Agressive'),
(13573, 'Gonflable', 'Invoque une Gonflable maîtrisable qui soigne en zone et donne des PM aux alliés.\nElle soigne également tous les alliés au contact des Arbres Feuillus du lanceur.', 0x08f8c902089bca02089cca02, '1', 'Summon'),
(13574, 'Ronces Harcelantes', 'Occasionne des dommages Terre et retire des PM aux ennemis en zone autour d\'un Arbre Feuillu du lanceur.', 0x08f9c902, '1', 'Agressive'),
(13575, 'Contagion', 'Occasionne des dommages Air. \n\nSur un ennemi dans l\'état Infecté : propage l\'état Infecté dans un cercle de 2 cases autour de tous les ennemis dans l\'état Infecté et leur occasionne des dommages Air.', 0x08fac902, '1', 'Agressive'),
(13576, 'Malédiction Vaudou', 'Occasionne des dommages Feu et Eau aux ennemis.\n\nSur l\'ennemi pendant 2 tours :\n• Occasionne des dommages Feu s\'il subit une tentative de retrait de PM.\n• Occasionne des dommages Eau s\'il subit une tentative de retrait de PA.\nLes dommages de chaque élément peuvent être déclenchés 3 fois par tour.\n\nSur un ennemi dans l\'état Infecté : applique les effets du sort sur tous les ennemis dans l\'état Infecté.', 0x08fbc902, '1', 'Agressive'),
(13577, 'Ronce Paralysante', 'Occasionne des dommages Air et retire des PM.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Air et retire des PM à tous les ennemis dans l\'état Infecté.', 0x08fcc902, '1', 'Agressive'),
(13578, 'Surpuissante', 'Invoque une Surpuissante maîtrisable qui retire des PM aux ennemis en zone.\nElle retire des PM supplémentaires à tous les ennemis au contact des Arbres Feuillus du lanceur.', 0x08fdc9020899ca02, '1', 'Summon'),
(13579, 'Harmonie', 'Applique l\'état Enraciné sur le lanceur et l\'immobilise à la fin du tour pour le tour suivant.\nPartage les dommages entre le lanceur et ses Poupées présentes sur le terrain au lancer du sort.', 0x08fec902, '1', 'Debuff'),
(13580, 'Poison de Proximité', '', 0x08ffc90208bfe703, '0', 'None'),
(13581, 'Rempotage', '', 0x0880ca0208a3ca02, '0', 'Teleport'),
(13582, 'Secousse', '', 0x0881ca020882ca0208acb503, '0', 'None'),
(13583, 'Inoculation', '', 0x0883ca0208e8d702, '0', 'Agressive'),
