(13587, 'Contagion', '', 0x0887ca020888ca0208c9e40308c6e703, '0', 'None'),
(13589, 'Ronce Paralysante', '', 0x088bca0208a5ca0208cce403, '0', 'Agressive'),
(13590, 'Entrave Sylvestre', 'Retire des PM aux ennemis en zone et leur applique l\'état Infecté.', 0x088cca02, '1', 'Debuff'),
(13591, 'Attirance Sylvestre', 'Attire la cible.', 0x088dca02, '1', 'Agressive'),
(13592, 'Fléau', '', 0x088eca0208cbe403, '0', 'Agressive'),
(13593, 'Broussaille Empoisonnée', '', 0x088fca020890ca0208b7d70208b8d702, '0', 'Agressive'),
