(13599, 'Arbre de Vie', '', 0x0898ca0208e3e70308adf803, '0', 'None'),
(13600, 'Entrave Sylvestre', '', 0x08a6ca0208a7ca02, '0', 'None'),
(13601, 'Explosion Poupesque', '', 0x08abca0208acca02, '0', 'None'),
(13602, 'Infection Poupesque', '', 0x08adca02, '0', 'None'),
(13603, 'Infection Poupesque', '', 0x08aeca0208afca0208e08a0408e68a04, '0', 'Agressive'),
(13665, 'Rune de Feu', '', 0x08a9cb0208c5cb0208c6cb02, '0', 'Agressive'),
(13666, 'Lance-flamme', 'Pose une rune de Feu, occasionne des dommages Feu et applique l\'état Feu.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08aacb0208e7cb0208e8cb02, '1', 'Agressive'),
(13667, 'Stalagmite', 'Pose une rune d\'Eau, occasionne des dommages Eau et applique l\'état Eau.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08abcb0208e3cb0208e4cb02, '1', 'Agressive'),
(13668, 'Onde Tellurique', 'Pose une rune de Terre, occasionne des dommages Terre et applique l\'état Terre.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08accb0208e5cb0208e6cb02, '1', 'Agressive'),
(13669, 'Éther', 'Pose une rune d\'Air, occasionne des dommages Air et applique l\'état Air.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08adcb0208e1cb0208e2cb02, '1', 'Agressive'),
(13670, 'Runification', 'Déclenche toutes les runes du lanceur occupées par un ennemi :\n• Occasionne des dommages aux ennemis dans l\'élément de la rune.\n• Augmente les caractéristiques du lanceur selon l\'élément de la rune par ennemi touché.\n• Applique l\'état élémentaire de la rune.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08aecb0208f1cb0208f2cb02, '1', 'Agressive'),
(13671, 'Combinaison Élémentaire', '', 0x08afcb02, '0', 'Agressive'),
(13672, 'Drain Élémentaire', 'Vole des caractéristiques et occasionne des dommages selon l\'état élémentaire de l\'ennemi ciblé.\n\nConsomme l\'état élémentaire.', 0x08b0cb0208edcb0208eecb02, '1', 'Debuff'),
(13673, 'Rune d\'Eau', '', 0x08b1cb0208d3cb0208d4cb02, '0', 'Agressive'),
(13674, 'Orage', 'Pose des runes de Terre, vole de la vie dans l\'élément Terre et applique l\'état Terre en zone.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08b2cb0208dfcb0208e0cb02, '1', 'Agressive'),
(13675, 'Météore Percutant', 'Repousse la cible, pose une rune de Terre, occasionne des dommages Terre aux ennemis et applique l\'état Terre.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08b3cb0208decb02, '1', 'Agressive'),
(13676, 'Glacier', 'Pose des runes d\'Eau, vole de la vie dans l\'élément Eau et applique l\'état Eau en zone.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08b4cb0208dbcb0208dccb02, '1', 'Agressive'),
(13677, 'Éclats Glacés', 'Attire la cible, pose une rune d\'Eau, occasionne des dommages Eau aux ennemis et applique l\'état Eau.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08b5cb0208e9cb0208eacb02, '1', 'Agressive'),
(13678, 'Rafale Transperçante', 'Pose des runes d\'Air, vole de la vie dans l\'élément Air et applique l\'état Air en zone.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08b6cb0208becb02, '1', 'Agressive'),
(13679, 'Lame Astrale', 'Sur un allié : augmente la Portée.\n\nSur un ennemi : retire de la Portée, pose une rune d\'Air, occasionne des dommages Air et applique l\'état Air.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08b7cb0208d9cb0208dacb02, '1', 'Agressive'),
(13680, 'Trait Ardent', 'Pose des runes de Feu, vole de la vie dans l\'élément Feu et applique l\'état Feu en zone.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08b8cb0208d7cb0208d8cb02, '1', 'Agressive'),
(13681, 'Déflagration', 'Réduit la durée des effets de la cible, pose une rune de Feu, occasionne des dommages Feu aux ennemis et applique l\'état Feu et l\'état Déflagration.\n\nLe désenvoûtement ne peut pas être appliqué si la cible est déjà dans l\'état Déflagration.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08b9cb0208d5cb0208d6cb02, '1', 'Agressive');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(13682, 'Bouclier Élémentaire', 'Augmente les résistances de l\'allié ciblé et lui applique l\'état Bouclier Élémentaire :\n• Si la cible subit des dommages, réduit ses résistances à l\'élément de l\'attaque subie et applique l\'état de cet élément sur son attaquant ennemi.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08bacb0208f3cb0208f4cb02, '1', 'Debuff'),
(13683, 'Traversée', 'Téléporte le lanceur sur la case ciblée et occasionne des dommages dans l\'état élémentaire des ennemis en ligne jusqu\'à la case ciblée.', 0x08bbcb0208ebcb0208eccb02, '1', 'Agressive'),
(13684, 'Traitement Runique', 'Soigne l\'allié ciblé pour chaque rune du lanceur.\nLes soins sont plus faibles sur le lanceur.\n\nConsomme toutes les runes du lanceur.', 0x08bccb0208efcb0208f0cb02, '1', 'Agressive'),
(13685, 'Rune d\'Air', '', 0x08bfcb0208cdcb0208cecb02, '0', 'Agressive'),
(13686, 'Rune de Terre', '', 0x08c0cb0208cfcb0208d0cb02, '0', 'Agressive'),
(13687, 'Rune de Feu', '', 0x08c1cb0208d1cb0208d2cb02, '0', 'Agressive'),
(13688, 'Rune d\'Eau', '', 0x08c2cb0208cbcb0208cccb02, '0', 'Agressive'),
(13689, 'Rune d\'Air', '', 0x08c3cb0208c9cb0208cacb02, '0', 'Agressive'),
(13690, 'Rune de Terre', '', 0x08c4cb0208c7cb0208c8cb02, '0', 'Agressive'),
(13691, 'Runes élémentaires', '', 0x08f5cb02, '0', 'None'),
(13692, 'Manifestation d\'Air', '', 0x08f6cb0208c5cc0208eeea0308feea03, '0', 'Agressive'),
(13693, 'Manifestation d\'Air', '', 0x08f7cb0208cacc02, '0', 'Agressive'),
(13694, 'Propagation', '', 0x08f8cb0208f9cb020896cc020897cc020898cc02, '0', 'Agressive'),
(13695, 'Propagation', 'Propage l\'état élémentaire de l\'ennemi ciblé sur tous les ennemis dans un cercle de 3 cases autour de lui.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08facb0208fccb02, '1', 'Agressive'),
(13696, 'Polarité', 'Applique des effets de déplacement selon l\'état élémentaire de l\'ennemi ciblé :\n• Terre : repousse la cible.\n• Feu : échange de position avec la cible.\n• Eau : attire la cible.\n• Air : téléporte le lanceur symétriquement par rapport à la cible.\n\nConsomme l\'état élémentaire.', 0x08fdcb0208fecb0208ffcb02, '1', 'Agressive'),
(13697, 'Empreinte', 'Pose une rune sous tous les ennemis affectés par un état élémentaire.', 0x0880cc020882cc02, '1', 'Agressive'),
(13698, 'Bouclier Élémentaire', '', 0x0883cc020884cc020885cc020886cc02, '0', 'Agressive'),
(13699, 'Polarité', '', 0x0887cc02, '0', 'Agressive'),
(13700, 'Contribution', '', 0x0888cc020889cc02088acc02088bcc02088ccc02, '0', 'None'),
(13701, 'Contribution', 'Applique des effets sur l\'allié ciblé selon les états élémentaires de tous les ennemis :\n• Terre : augmente les PM.\n• Feu : applique un bouclier.\n• Eau : augmente la Puissance.\n• Air : augmente les PA.\nChaque effet est cumulable 2 fois.\n\nConsomme les états élémentaires.', 0x088dcc02088ecc02088fcc02, '1', 'Agressive'),
(13702, 'Ébullition (Feu & Eau)', '', 0x0890cc02, '0', 'Buff'),
(13703, 'Carbonisation (Feu & Air)', '', 0x0891cc02, '0', 'Buff'),
(13704, 'Enlisement (Terre & Eau)', '', 0x0892cc02, '0', 'Buff'),
(13705, 'Assèchement (Air & Terre)', '', 0x0893cc02, '0', 'Buff'),
(13706, 'Cristallisation (Eau & Air)', '', 0x0894cc02, '0', 'Buff'),
(13707, 'Éruption (Terre & Feu)', '', 0x0895cc02, '0', 'Buff'),
(13708, 'Onde Céleste', 'Pose une rune de Terre, occasionne des dommages Air et Terre et applique les états Air et Terre.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x0899cc0208c8d602, '1', 'Agressive'),
(13709, 'Dard', 'Pose une rune d\'Eau, occasionne des dommages Terre et Eau et applique les états Terre et Eau.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x089acc0208c7d602, '1', 'Agressive'),
(13710, 'Manifestation', 'Déclenche la rune ciblée.\n\nSi la case est occupée par un ennemi :\n• Occasionne des dommages aux ennemis dans l\'élément de la rune.\n• Augmente les caractéristiques du lanceur selon l\'élément de la rune.\n• Applique l\'état élémentaire de la rune.\n\nSi la case est ou devient libre, invoque une Manifestation Élémentaire en appliquant des effets de déplacement :\n• Terre : repousse les entités depuis le centre dans un cercle de 3 cases autour de la Manifestation.\n• Feu : échange les positions du lanceur et de la Manifestation.\n• Eau : attire les entités vers le centre dans un cercle de 3 cases autour de la Manifestation.\n• Air : téléporte les entités symétriquement par rapport à la Manifestation dans un cercle de 3 cases autour d\'elle.\n\nLa Manifestation est détruite au prochain tour.\nÀ sa mort, la Manifestation applique l\'état de son élément dans un cercle de 3 cases autour d\'elle.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x089bcc0208c9d602, '1', 'None'),
(13711, 'Cataracte', 'Pose une rune de Feu, occasionne des dommages Eau et Feu et applique les états Eau et Feu.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x089ccc0208cad602, '1', 'Agressive'),
(13712, 'Tison', 'Pose une rune d\'Air, occasionne des dommages Feu et Air et applique les états Feu et Air.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x089dcc0208cbd602, '1', 'Agressive'),
(13713, 'Morph', 'Occasionne des dommages dans l\'état élémentaire de l\'ennemi ciblé.\n\nLes contraintes de lancer du sort sont modifiées selon l\'état élémentaire :\n• Eau : réduit le coût en PA du sort.\n• Terre : désactive la ligne de vue du sort.\n• Air : augmente la portée maximale du sort.\n• Feu : les dommages du sort sont augmentés.\nChaque effet est cumulable une fois.\n\nChange l\'état élémentaire selon son état actuel : \n• Eau -> Terre -> Air -> Feu -> Eau.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x089ecc0208ccd602, '1', 'Agressive'),
(13714, 'Ouragan', 'Pose une rune d\'Air, vole de la vie dans l\'élément Air et applique l\'état Air.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x089fcc02, '1', 'Agressive'),
(13715, 'Lame Tellurique', 'Sur un allié : augmente les chances de Critique.\n\nSur un ennemi : réduit les chances de Critique, pose une rune de Terre, occasionne des dommages Terre et applique l\'état Terre.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08a0cc0208ced602, '1', 'Agressive'),
(13716, 'Courant Quadramental', 'Applique des effets sur l\'ennemi ciblé selon son état élémentaire :\n• Terre : retire des PM.\n• Feu : retire des PA.\n• Eau : érode la cible.\n• Air : retire de la Portée.\nChaque effet est cumulable une fois.', 0x08a1cc02, '1', 'Agressive'),
(13717, 'Stalactite', 'Pose une rune d\'Eau, vole de la vie dans l\'élément Eau et applique l\'état Eau.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08a2cc02, '1', 'Agressive'),
(13718, 'Volcan', 'Pose une rune de Feu, vole de la vie dans l\'élément Feu et applique l\'état Feu.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08a3cc02, '1', 'Agressive'),
(13719, 'Piège Élémentaire', 'Pose un piège mono-cellule qui applique des effets sur les ennemis selon leur état élémentaire dans un cercle de 2 cases :\n• Terre : réduit la durée des effets.\n• Feu : réduit les soins reçus.\n• Eau : applique l\'état Pesanteur.\n• Air : applique l\'état Intacleur.\n\nLes effets ne peuvent pas être désenvoûtés.\nConsomme les états élémentaires des ennemis touchés.', 0x08a4cc02, '1', 'Mark'),
(13720, 'Gardien Élémentaire', 'Invoque un Gardien Élémentaire maîtrisable qui occasionne des dommages Neutre ou dans l\'état élémentaire de sa cible. \nLorsqu\'une combinaison élémentaire est générée par le lanceur, le Gardien gagne des effets selon la combinaison.\n\nIl ne peut y avoir qu\'un seul Gardien Élémentaire par équipe. Si le Gardien Élémentaire du lanceur est encore en vie et que celui-ci est réinvoqué, l\'ancien est tué pour laisser place au nouveau.', 0x08a5cc02, '1', 'Agressive'),
(13721, 'Déluge', 'Rapproche le lanceur de la cible, pose une rune d\'Eau, occasionne des dommages Eau aux ennemis et applique l\'état Eau. \n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08a6cc02, '1', 'Agressive'),
(13722, 'Cycle Élémentaire', 'Change l\'état élémentaire de l\'ennemi ciblé selon son état actuel :\n• Terre -> Eau -> Feu -> Air -> Terre.\n\nLe coût en PA du sort est remboursé au premier lancer sur une cible.', 0x08a7cc02, '1', 'Agressive'),
(13723, 'Lance Solaire', 'Échange de position avec la cible, pose une rune de Feu, occasionne des dommages Feu aux ennemis et applique l\'état Feu.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08a8cc02, '1', 'Agressive'),
(13724, 'Surcharge Runique', 'Occasionne des dommages pour chaque rune du lanceur dans l\'élément des runes.\n\nConsomme toutes les runes du lanceur.', 0x08a9cc02, '1', 'Agressive'),
(13725, 'Brèche Tectonique', 'Pose une rune de Terre, vole de la vie dans l\'élément Terre et applique l\'état Terre.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08aacc0208cdd602, '1', 'Agressive'),
(13726, 'Comète', 'Éloigne le lanceur de la cible, pose une rune d\'Air, occasionne des dommages Air aux ennemis et applique l\'état Air.\n\nPeut générer des {spell,23876,1::<font color=\"#ebc304\">combinaisons élémentaires</font>}.', 0x08abcc02, '1', 'Agressive'),
(13727, 'Création', 'Pose une rune sur la case ciblée dans l\'élément de la dernière rune posée par le lanceur.', 0x08accc02, '1', 'Agressive'),
(13728, 'Répulsion Runique', 'Repousse les cibles en zone et les repousse de nouveau pour chaque rune du lanceur.\nLa poussée pour chaque rune consommée est plus faible.\n\nConsomme toutes les runes du lanceur.', 0x08adcc02, '1', 'Agressive'),
(13729, 'Courant Quadramental', '', 0x08aecc02, '0', 'None'),
(13730, 'Courant Quadramental', '', 0x08afcc02, '0', 'None'),
(13731, 'Courant Quadramental', '', 0x08b0cc02, '0', 'None'),
(13732, 'Courant Quadramental', '', 0x08b1cc02, '0', 'None'),
(13733, 'Piège Élémentaire', '', 0x08b2cc02, '0', 'Debuff'),
(13734, 'Rayon Quadramental', 'Occasionne des dommages Neutre ou dans l\'état élémentaire de la cible.', 0x08b3cc02, '1', 'Agressive'),
(13735, 'Manifestation de Feu', '', 0x08b4cc0208c4cc0208efea0308ffea03, '0', 'Agressive'),
(13736, 'Manifestation de Feu', '', 0x08b5cc0208c8cc02, '0', 'Agressive'),
(13737, 'Manifestation d\'Eau', '', 0x08b6cc0208c6cc0208edea0308fdea03, '0', 'Agressive'),
(13738, 'Manifestation d\'Eau', '', 0x08b7cc0208cbcc02, '0', 'Agressive'),
(13739, 'Manifestation de Terre', '', 0x08b8cc0208c3cc0208ecea0308fcea03, '0', 'Agressive'),
(13740, 'Manifestation de Terre', '', 0x08b9cc0208c9cc02, '0', 'Agressive'),
(13741, 'Manifestation', '', 0x08bacc0208bbcc0208bccc0208bdcc02, '0', 'Summon'),
(13742, 'Morph', '', 0x08becc0208bfcc0208c0cc0208c1cc0208c7cc0208d28204, '0', 'None'),
(13743, 'Répulsion Runique', '', 0x08c2cc02, '0', 'Agressive'),
(13744, 'Création', '', 0x08cccc0208cdcc0208cecc0208cfcc02, '0', 'None'),
(13745, 'La Rage d\'Ouginak', '', 0x08d0cc0208d3cc0208d7ff03, '0', 'Agressive'),
(13746, 'Bestialité Ouginak', '', 0x08d1cc02, '0', 'Buff'),
(13747, 'Bestialité Ouginak', '', 0x08d2cc02, '0', 'Agressive'),
(13748, 'Proie', 'Applique l\'état Proie sur l\'ennemi ciblé.\nLes entités qui attaquent la cible sont soignées d\'une partie des dommages occasionnés.\n\nSi la Proie meurt, fixe le temps de relance du sort à 0.\n\nIl ne peut y avoir qu\'une seule Proie par équipe.\nSi le sort est lancé sur un autre ennemi, ses effets sont retirés de la cible précédente.', 0x08d4cc0208d5cc0208d6cc02, '1', 'Agressive'),
(13749, 'Flair', 'Téléporte le lanceur sur la première case disponible au contact de la Proie ennemie.\n\nSi la Proie est dans la zone d\'effet : téléporte le lanceur sur la case ciblée.\n\nNécessite et diminue la Rage du lanceur.', 0x08d7cc0208d8cc02, '1', 'Agressive'),
(13752, 'Accrocs', 'Vole de la vie dans l\'élément Neutre aux ennemis.\nLe vol de vie est plus important sur les invocations.', 0x08dccc0208ddcc0208decc02, '1', 'Agressive'),
(13753, 'Tétanisation', 'Occasionne des dommages Feu et retire des PM.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x08dfcc02, '1', 'Agressive'),
(13754, 'Rabattage', 'Occasionne des dommages Feu.\n\nSur la Proie ennemie : vole des PM et occasionne des dommages Feu.', 0x08e2cc0208e3cc0208e4cc02, '1', 'Agressive'),
(13755, 'Traque', 'Occasionne des dommages Feu.\n\nSur la Proie ennemie : rapproche le lanceur de la cible et occasionne des dommages Feu.\n\nLe sort n\'est pas soumis aux contraintes de lancer sous Forme Bestiale.', 0x08e5cc0208e6cc0208e7cc02, '1', 'Agressive'),
(13756, 'Molosse', 'Occasionne des dommages Terre aux ennemis et réduit les dommages subis par le lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x08e8cc0208e9cc0208eacc02, '1', 'Agressive'),
(13757, 'Dogue', 'Occasionne des dommages Terre.\n\nSur la Proie ennemie : vole de la vie dans l\'élément Terre et retire de la Fuite.', 0x08ebcc0208eccc0208edcc02, '1', 'Agressive'),
(13758, 'Cerbère', 'Applique un bouclier sur le lanceur et occasionne des dommages Terre aux ennemis en zone.\nLes dommages du sort sont plus importants mais la portée maximale est plus faible selon la Rage du lanceur :\n• Rage : -0 PO\n• Raage : -1 PO\n• Forme Bestiale : -2 PO et le bouclier n\'est pas appliqué.', 0x08eecc02, '1', 'Agressive'),
(13759, 'Cubitus', '', 0x08f1cc0208d9dc0308dfdc03, '0', 'None'),
(13760, 'Cubitus', 'Occasionne des dommages Eau.\nSi la cible est la Proie ennemie, donne également 1 PM au lanceur.\n\nLe sort n\'est pas soumis aux contraintes de lancer sous Forme Bestiale.', 0x08f2cc0208f3cc0208f4cc02, '1', 'Agressive'),
(13761, 'Os à Moelle', '', 0x08f5cc0208f6cc0208f7cc0208dcdc0308e1dc03, '0', 'None'),
(13762, 'Os à Moelle', 'Occasionne des dommages Eau.\nLes dommages du sort sont augmentés après chaque lancer si la cible est la Proie ennemie.', 0x08f8cc0208f9cc0208facc02, '1', 'Agressive'),
(13763, 'Tibia', 'Occasionne des dommages Eau aux ennemis et repousse les cibles en zone autour du lanceur.\n\nAugmente la Rage du lanceur.', 0x08fbcc0208fccc0208fdcc02, '1', 'Agressive'),
(13764, 'Limier', '', 0x08fecc02, '0', 'Agressive'),
(13765, 'Limier', 'Occasionne des dommages Air.\n\nSur la Proie ennemie : attire les entités vers la cible dans une croix de 3 cases et occasionne des dommages Air.\n\nLe sort n\'est pas soumis aux contraintes de lancer sous Forme Bestiale.', 0x0881cd020882cd02, '1', 'Agressive'),
(13766, 'Charogne', 'Érode la cible et occasionne des dommages Air.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x0884cd020885cd020886cd02, '1', 'Agressive'),
(13767, 'Carcasse', '', 0x0887cd020888cd020889cd0208d8dc0308e0dc03, '0', 'None'),
(13768, 'Carcasse', 'Occasionne des dommages Air.\nLes dommages du sort sont augmentés après chaque lancer si la cible est la Proie ennemie.', 0x088acd02088bcd02088ccd02, '1', 'Agressive'),
(13769, 'Apaisement', 'Soigne le lanceur.\nNécessite et diminue la Rage du lanceur.\n\nSi le lanceur est dans sa Forme Bestiale : retire les effets de la Forme Bestiale.', 0x088dcd02088ecd02088fcd02, '1', 'Agressive'),
(13770, 'Convergence', 'Sur un allié : rapproche le lanceur de la cible.\n\nSur un ennemi : attire la cible.', 0x0890cd020891cd020892cd02, '1', 'Agressive'),
(13771, 'Arcanin', 'Augmente la Puissance du lanceur.\n\nNécessite et diminue la Rage du lanceur.', 0x0893cd020894cd020895cd02, '1', 'Buff'),
(13772, 'Pelage Protecteur', 'Applique 2 boucliers et l\'état Pelage Protecteur sur l\'allié ciblé :\n• Retire le second bouclier appliqué et l\'état et augmente la Rage du lanceur si la cible subit des dommages de poussée.\n\nLes effets ne peuvent pas être désenvoûtés.\n\nNe peut pas être utilisé sous Forme Bestiale.', 0x0896cd020897cd020898cd02, '1', 'Agressive'),
(13773, 'Aboiement', 'Augmente les PM de la cible et lui applique les états Inébranlable et Aboiement :\n• Retire les états Inébranlable et Aboiement et augmente la Rage du lanceur si la cible subit des dommages en mêlée.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x0899cd02089acd02, '1', 'Agressive'),
(13774, 'Lance-roquet', 'Invoque un Roquet maîtrisable qui vole de la vie dans l\'élément Neutre aux ennemis.\nSon vol de vie est plus important sur les invocations.\n\nÀ chaque fois que son invocateur occasionne des dommages avec ses sorts de classe, le Roquet est attiré vers la Proie ennemie et l\'attaque s\'il est à portée.\nLes dommages sont réduits de moitié en-dehors de son tour de jeu.', 0x089ccd02089dcd02089ecd02, '1', 'Summon'),
(13776, 'Rage', '', 0x08a0cd02, '0', 'Buff'),
(13777, 'Raage', '', 0x08a1cd02, '0', 'Buff'),
(13778, 'Tibia', '', 0x08a2cd0208bfcd02, '0', 'Agressive'),
(13779, 'Flair', '', 0x08a3cd0208a4cd0208a5cd02, '0', 'Teleport'),
(13780, 'Panique', '', 0x08a6cd02, '0', 'Agressive'),
(13781, 'Panique', 'Sur le lanceur : repousse les ennemis en zone autour du lanceur.\n\nSur la Proie ennemie : repousse les ennemis en zone autour de la Proie et lui retire de la Fuite.', 0x08a9cd0208aacd02, '1', 'Agressive'),
(13782, 'Bestialité Ouginak', '', 0x08accd02, '0', 'Debuff'),
(13784, 'Traque', '', 0x08bdcd02, '0', 'None'),
(13785, 'Proie', '', 0x08becd02, '0', 'Buff'),
(13786, 'Gibier', 'Applique l\'état Proie sur l\'ennemi ciblé et augmente ses dommages subis.\n\nIl ne peut y avoir qu\'une seule Proie par équipe.\nSi le sort est lancé sur un autre ennemi, ses effets sont retirés de la cible précédente.', 0x08c0cd0208ddd602, '1', 'Agressive'),
(13787, 'Mâchoire', 'Retire de l\'Esquive PM et occasionne des dommages Feu aux ennemis.\n\nSur un allié : augmente l\'Esquive PM des alliés dans un cercle de 2 cases.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x08c1cd0208ded602, '1', 'Agressive'),
(13788, 'Calcanéus', 'Occasionne des dommages Eau aux ennemis et attire la cible.\nL\'attirance est plus importante sur la Proie ennemie.\n\nLe sort n\'est pas soumis aux contraintes de lancer sous Forme Bestiale.', 0x08c2cd02, '1', 'Agressive'),
(13789, 'Dépouille', 'Occasionne des dommages Air.\n\nSur la Proie ennemie : augmente les dommages du sort pour chaque allié au contact de la cible et occasionne des dommages Air.', 0x08c3cd0208e6d602, '1', 'Agressive'),
(13790, 'Aboi', 'Occasionne des dommages Feu et réduit les Résistances Poussée.\nLes dommages deviennent du vol de vie sur la Proie ennemie.', 0x08c4cd0208e8d60208c8ff03, '1', 'Agressive'),
(13791, 'Affection', 'Soigne le lanceur et l\'allié ciblé et échange de position avec lui.\nNécessite et diminue la Rage du lanceur.\n\nSi le lanceur est dans sa Forme Bestiale : retire les effets de la Forme Bestiale.', 0x08c5cd02, '1', 'Agressive'),
(13792, 'Gangrène', 'Érode l\'ennemi ciblé.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x08c6cd0208f1d602, '1', 'Agressive'),
(13793, 'Muselière', 'Occasionne des dommages Terre.\n\nSur la Proie ennemie : augmente les dommages du sort pour chaque ennemi au contact du lanceur et occasionne des dommages Terre.', 0x08c7cd0208f3d602, '1', 'Agressive'),
(13794, 'Humérus', 'Téléporte le lanceur symétriquement par rapport à la cible et occasionne des dommages Terre aux ennemis.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x08c8cd02, '1', 'Agressive'),
(13795, 'Chasse', 'Occasionne des dommages Feu aux ennemis et repousse la cible.\nLa poussée est plus importante sur la Proie ennemie.', 0x08c9cd02, '1', 'Agressive'),
(13796, 'Battue', 'Augmente la Puissance des alliés dans un cercle de 2 cases autour de la cible et occasionne des dommages Air aux ennemis.\nLa Puissance est plus importante si la cible est la Proie ennemie.', 0x08cacd02, '1', 'Agressive'),
(13797, 'Caninos', 'Soigne le lanceur.\n\nNécessite et diminue la Rage du lanceur.', 0x08cbcd02, '1', 'Healing'),
(13798, 'Férocité', 'Applique l\'état Férocité sur l\'allié ciblé :\n• Applique un bouclier si la cible est attiré, poussée, transposée, téléportée ou subit une tentative de retrait de PM.\n\nNe peut pas être utilisé sous Forme Bestiale.', 0x08cccd02, '1', 'Agressive'),
(13799, 'Radius', 'Échange de position avec la cible et occasionne des dommages Eau aux ennemis.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x08cdcd0208c7ff03, '1', 'Agressive'),
(13800, 'Vertèbre', 'Applique un poison Eau de début de tour sur l\'ennemi ciblé.\nLe poison ne peut pas être désenvoûté s\'il est appliqué sur la Proie ennemie.', 0x08cecd02, '1', 'Agressive'),
(13801, 'Poursuite', 'Pose un glyphe qui augmente les PM des alliés.\n\nSur la Proie ennemie : pose le glyphe et applique l\'état Poursuite sur la cible, qui pose de nouveau le glyphe sous elle au début de son tour.\nCet effet est appliqué uniquement si la cible est toujours la Proie et ne peut pas être désenvoûté.', 0x08cfcd02, '1', 'Mark'),
(13802, 'Amarok', 'Augmente les résistances en mêlée des alliés au contact de la cible et occasionne des dommages Terre aux ennemis.\nLes résistances sont plus importantes si la cible est la Proie ennemie.', 0x08d0cd0208c5ff0308c6ff03, '1', 'Agressive'),
(13803, 'Rogne', 'Augmente la Puissance, les Dommages Poussée et le Tacle du lanceur et lui applique l\'état Rogne :\n• Augmente ces mêmes caractéristiques si le lanceur subit des dommages.', 0x08d1cd02, '1', 'Buff'),
(13804, 'Dépeçage', 'Réduit les soins reçus par la cible et occasionne des dommages Air.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x08d2cd0208caff03, '1', 'Agressive'),
(13805, 'Acharnement', 'Applique l\'état Pesanteur sur l\'ennemi ciblé.\nSi l\'ennemi est la Proie :\n• Augmente également les dommages subis par la cible.\n• Téléporte les Roquets du lanceur à son contact.\n\nAugmente la Rage du lanceur (nécessite une cible).', 0x08d3cd02, '1', 'Agressive'),
(13806, 'Pistage', 'Repousse la cible et rapproche le lanceur d\'elle.', 0x08d4cd0208ead602, '1', 'Agressive'),
(13808, 'Dépouille', '', 0x08d6cd0208d7cd0208d1d70208d2d702, '0', 'Buff'),
(13809, 'Aboi', '', 0x08d8cd02, '0', 'None'),
(13811, 'Battue', '', 0x08dacd0208c9ff03, '0', 'Buff'),
(13812, 'Poursuite', '', 0x08dbcd0208e3cd0208cfff03088e8004, '0', 'None'),
(13813, 'Amarok', '', 0x08dccd0208c4ff03, '0', 'Buff'),
(13814, 'Mâchoire', '', 0x08ddcd02089e9003, '0', 'Buff'),
(13815, 'Férocité', '', 0x08decd0208cde00308e1ea03, '0', 'None'),
(13816, 'Affection', '', 0x08dfcd02, '0', 'Healing'),
(13817, 'Chasse', '', 0x08e0cd02, '0', 'None'),
(13818, 'Rogne', '', 0x08e1cd02, '0', 'None'),
(13819, 'Scaphandre', 'Augmente les PM, les Dommages et les Dommages Poussée des alliés en zone.', 0x08e4cd02088ece02088fce02, '1', 'Buff'),
(13820, 'Marée', 'Échange de position avec la cible et occasionne des dommages Air aux ennemis.', 0x08e5cd020894ce020895ce02, '1', 'Agressive'),
(13821, 'Ressac', 'Occasionne des dommages Terre aux ennemis et repousse la cible.', 0x08e6cd020892ce020893ce02, '1', 'Agressive'),
(13822, 'Courant', 'Occasionne des dommages Eau aux ennemis et attire la cible.', 0x08e7cd02088ace02088bce02, '1', 'Agressive'),
(13823, 'Flibuste', 'Vole de la vie dans l\'élément Feu.', 0x08e8cd020886ce020887ce02, '1', 'Agressive'),
(13824, 'Selpâtre', 'Occasionne des dommages Feu et retire des Dommages.', 0x08a1ce02, '1', 'Agressive'),
(13825, 'Écume', 'Occasionne des dommages Eau aux ennemis et repousse les cibles en zone.', 0x08eacd0208a5ce02, '1', 'Agressive'),
(13826, 'Vapor', 'Occasionne des dommages Feu et réduit les chances de Critique en zone.', 0x08ebcd020896ce020897ce02, '1', 'Agressive'),
(13827, 'Ancrage', 'Occasionne des dommages Terre.', 0x08eccd020884ce020885ce02, '1', 'Agressive'),
(13828, 'Foène', 'Occasionne des dommages Terre.\n\nPendant 2 tours, occasionne des dommages Terre si l\'ennemi ciblé subit des dommages de poussée.\nPeut être déclenché 3 fois par tour.', 0x08edcd0208a7ce02, '1', 'Agressive'),
(13829, 'Harponneuse', 'Pose une Tourelle offensive qui vole de la vie dans l\'élément Terre, Feu, Eau ou Air.\nSon vol de vie est plus important selon son niveau d\'évolution et plus faible sur les alliés.\n\nÀ partir de l\'Évolution II, la Harponneuse peut appliquer des effets sur son invocateur (voir Mécaniques de classe).\n\nEn Évolution III, son sort spécial peut être activé :\n• Boomboom : réduit la durée des effets de l\'ennemi ciblé et lui vole de la vie dans le meilleur élément d\'attaque de la Tourelle.\n\nIl ne peut y avoir qu\'une seule Harponneuse par équipe. Si la Harponneuse est encore en vie et que celle-ci est ré-invoquée, l\'ancienne est tuée pour laisser place à la nouvelle.', 0x08eecd020882ce020883ce02, '1', 'Agressive'),
(13830, 'Gardienne', 'Pose une Tourelle défensive qui soigne.\nSes soins sont plus importants selon son niveau d\'évolution et plus faibles sur les ennemis.\n\nÀ partir de l\'Évolution II, la Gardienne peut appliquer des effets sur son invocateur (voir Mécaniques de classe).\n\nEn Évolution III, son sort spécial peut être activé :\n• Intervention : soigne l\'allié ciblé.\n\nIl ne peut y avoir qu\'une seule Gardienne par équipe. Si la Gardienne est encore en vie et que celle-ci est ré-invoquée, l\'ancienne est tuée pour laisser place à la nouvelle.', 0x08efcd020890ce020891ce02, '1', 'Agressive'),
(13831, 'Tactirelle', 'Pose une Tourelle tactique qui repousse les cibles en zone.\nLa taille de sa zone et sa poussée sont plus importantes selon son niveau d\'évolution.\n\nÀ partir de l\'Évolution II, la Tactirelle peut appliquer des effets sur son invocateur (voir Mécaniques de classe).\n\nEn Évolution III, son sort spécial peut être activé :\n• Transko : échange de position avec la cible.\nFonctionne également avec les Tourelles.\n\nIl ne peut y avoir qu\'une seule Tactirelle par équipe. Si la Tactirelle est encore en vie et que celle-ci est ré-invoquée, l\'ancienne est tuée pour laisser place à la nouvelle.', 0x08f0cd02089ace02089bce02, '1', 'Agressive'),
(13832, 'Évolution', 'Sur une Tourelle du lanceur : évolue la Tourelle.\nLa soigne également si son niveau d\'évolution augmente.\n\nSur un allié : augmente la Puissance.\n\nIl ne peut y avoir qu\'une seule Tourelle en Évolution III par Steamer. Si une autre Tourelle atteint son troisième niveau d\'évolution, alors la précédente repasse en Évolution II.', 0x08f1cd020888ce020889ce02, '1', 'Agressive'),
(13833, 'Cuirasse', 'Sur les alliés en zone : applique l\'état Cuirasse et les immunise contre les dommages des Tourelles offensives et du sort Court-circuit, ainsi que contre les déplacements des Tourelles tactiques.\n\nSur les ennemis en zone : applique l\'état Corselet et les immunise contre les soins et les boucliers des Tourelles défensives.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08f2cd0208a9ce02, '1', 'None'),
(13834, 'Armure de Sel', 'Sur une Tourelle alliée : augmente les résistances à distance et applique l\'état Inébranlable.\n\nSur un allié : augmente les résistances à distance.\nLes résistances sont plus faibles sur les alliés.', 0x08f3cd02088cce02088dce02, '1', 'Buff'),
(13835, 'Embuscade', 'Active les sorts spéciaux des Tourelles offensives du lanceur sur la cible.\n\nOccasionne des dommages Feu, Eau, Terre et Air.', 0x08f4cd0208a2ce0208a3ce02, '1', 'Agressive'),
(13836, 'Secourisme', 'Active les sorts spéciaux des Tourelles défensives du lanceur sur la cible.\n\nSoigne la cible.', 0x08f5cd02089ece02089fce02, '1', 'Agressive'),
(13837, 'Longue Vue', 'Active les sorts spéciaux des Tourelles tactiques du lanceur sur la cible.\n\nOccasionne des dommages Eau aux ennemis ou augmente la Portée de l\'allié ciblé.', 0x08f6cd02089cce02089dce02, '1', 'Agressive'),
(13838, 'Aspiration', 'Rapproche le lanceur de l\'allié ciblé.\nLe rapprochement est plus important sur les tourelles.', 0x08f7cd020898ce020899ce02, '1', 'Agressive'),
(13839, 'Boum', 'Vole de la vie dans l\'élément Feu.\nLe vol de vie est plus important selon le niveau d\'évolution et plus faible sur les alliés.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.\nEn Évolution III, n\'affecte plus les alliés.', 0x08f8cd0208acce0208adce02, '1', 'Agressive'),
(13840, 'Boum', 'Vole de la vie dans l\'élément Eau.\nLe vol de vie est plus important selon le niveau d\'évolution et plus faible sur les alliés.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.\nEn Évolution III, n\'affecte plus les alliés.', 0x08f9cd0208aace0208abce02, '1', 'Agressive'),
(13841, 'Boum', 'Vole de la vie dans l\'élément Terre.\nLe vol de vie est plus important selon le niveau d\'évolution et plus faible sur les alliés.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.\nEn Évolution III, n\'affecte plus les alliés.', 0x08facd0208aece0208afce02, '1', 'Agressive'),
(13844, 'Cinétik', 'Repousse les cibles en zone.\nLa taille de la zone et la poussée sont plus importantes selon le niveau d\'évolution.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.', 0x08fdcd02, '1', 'Agressive'),
(13847, 'Maintenance', 'Soigne la cible.\nLes soins sont plus importants selon le niveau d\'évolution et plus faibles sur les ennemis.\n\nN\'affecte pas les ennemis dans l\'état Corselet.\nEn Évolution III, n\'affecte plus les ennemis.', 0x0880ce0208b6ce0208b7ce02, '1', 'Healing'),
(13848, 'Intervention', 'Soigne l\'allié ciblé.', 0x0881ce0208b8ce0208b9ce0208c6dd0208c7dd0208c8dd02088ce103, '1', 'None'),
(13849, 'Brise l\'Âme', 'La Tourelle alliée ciblée subit les dommages en mêlée à la place des alliés à son contact.', 0x08bace0208bcce02, '1', 'Agressive'),
(13850, 'Brise l\'Âme', '', 0x08bdce02, '0', 'Healing'),
(13851, 'Évolution II', '', 0x08c3ce02, '1', 'None'),
(13852, 'Évolution III', '', 0x08c4ce0208afed03, '1', 'None'),
(13853, 'Transko', 'Échange de position avec la cible.\nFonctionne également avec les Tourelles.', 0x08c5ce02, '1', 'Agressive'),
(13857, 'Amarrage', 'Occasionne des dommages Terre.', 0x08d5ce0208f2d502, '1', 'Agressive'),
(13858, 'Sabordage', 'Occasionne des dommages Feu.', 0x08d6ce0208f1d502, '1', 'Agressive'),
(13859, 'Chalutier', 'Pose une Tourelle tactique qui attire les cibles en zone autour d\'elle et qui peut tacler.\nLa taille de sa zone et son attirance sont plus importantes selon son niveau d\'évolution.\n\nÀ partir de l\'Évolution II, le Chalutier peut appliquer des effets sur son invocateur (voir Mécaniques de classe).\n\nEn Évolution III, son sort spécial peut être activé :\n• Chaluchava : retire des PM aux ennemis.\n\nIl ne peut y avoir qu\'un seul Chalutier par équipe. Si le Chalutier est encore en vie et que celui-ci est ré-invoqué, l\'ancien est tué pour laisser place au nouveau.', 0x08d7ce0208f3d502, '1', 'Agressive'),
(13860, 'Transition', 'Sur une Tourelle du lanceur : évolue la Tourelle.\nLa soigne également si son niveau d\'évolution augmente.\n\nSur un allié : augmente la Puissance.\n\nIl ne peut y avoir qu\'une seule Tourelle en Évolution III par Steamer. Si une autre Tourelle atteint son troisième niveau d\'évolution, alors la précédente repasse en Évolution II.', 0x08d8ce0208f4d502, '1', 'Agressive'),
(13861, 'Harmattan', 'Occasionne des dommages Air et réduit les Résistances Poussée.', 0x08d9ce0208f5d502, '1', 'Agressive'),
(13862, 'Assistance', 'Téléporte l\'allié ciblé sur la première case disponible entre le lanceur et lui. \nSi l\'allié ciblé est une Tourelle du lanceur, la soigne également.', 0x08dace0208f6d502, '1', 'Agressive'),
(13863, 'Blindage', 'Applique un bouclier sur l\'allié ciblé. \nLe bouclier est plus important sur les Tourelles.', 0x08dbce0208f7d502, '1', 'Buff'),
(13864, 'Foreuse', 'Pose une Tourelle offensive qui occasionne des dommages Terre, Feu, Eau ou Air.\nSes dommages sont plus importants selon son niveau d\'évolution et plus faibles sur les alliés.\n\nÀ partir de l\'Évolution II, la Foreuse peut appliquer des effets sur son invocateur (voir Mécaniques de classe).\n\nEn Évolution III, son sort spécial peut être activé :\n• Excavation : érode l\'ennemi ciblé et lui occasionne des dommages dans le meilleur élément d\'attaque de la Tourelle.\n\nIl ne peut y avoir qu\'une seule Foreuse par équipe. Si la Foreuse est encore en vie et que celle-ci est ré-invoquée, l\'ancienne est tuée pour laisser place à la nouvelle.', 0x08dcce0208f8d502, '1', 'Agressive'),
(13865, 'Torpille', 'Occasionne des dommages Air aux ennemis et repousse la cible.', 0x08ddce0208efd50208f0d502, '1', 'Agressive'),
(13866, 'Corrosion', 'Occasionne des dommages Air et retire des PM.', 0x08dece02, '1', 'Agressive'),
(13867, 'Soupape', 'Occasionne des dommages Feu aux ennemis et augmente les Soins du lanceur.', 0x08dfce02, '1', 'Agressive'),
(13868, 'Surtension', 'Évolue au maximum une Tourelle du lanceur mais la tue à la fin de son tour.\nFixe l\'intervalle de relance de cette Tourelle à 1 tour.', 0x08e0ce02, '1', 'Agressive'),
(13869, 'Bathyscaphe', 'Pose une Tourelle défensive qui applique un bouclier.\nSon bouclier est plus important selon son niveau d\'évolution et plus faible sur les ennemis.\n\nÀ partir de l\'Évolution II, le Bathyscaphe peut appliquer des effets sur son invocateur (voir Mécaniques de classe).\n\nEn Évolution III, son sort spécial peut être activé :\n• Décompression : applique un bouclier sur l\'allié ciblé et augmente ses PA.\n\nIl ne peut y avoir qu\'un seul Bathyscaphe par équipe. Si le Bathyscaphe est encore en vie et que celui-ci est ré-invoqué, l\'ancien est tué pour laisser place au nouveau.', 0x08e1ce02, '1', 'Agressive'),
(13870, 'Périscope', 'Active les sorts spéciaux des Tourelles tactiques du lanceur sur la cible.\n\nOccasionne des dommages Eau aux ennemis.', 0x08e2ce02, '1', 'Agressive'),
(13871, 'Sauvetage', 'Active les sorts spéciaux des Tourelles défensives du lanceur sur la cible.\n\nSoigne la cible.', 0x08e3ce02, '1', 'Agressive'),
(13872, 'Court-circuit', 'Tue une Tourelle du lanceur pour occasionner des dommages Air en zone.\nFixe le temps de relance de la Tourelle détruite à 1 tour.', 0x08e4ce02, '1', 'Agressive'),
(13873, 'Sonar', 'Active les sorts spéciaux des Tourelles offensives du lanceur sur la cible.\n\nRepousse les cibles depuis le centre de la zone.\nN\'affecte pas le lanceur.', 0x08e5ce02, '1', 'Agressive'),
(13874, 'Nautile', 'Occasionne des dommages Eau et retire des PM.', 0x08e6ce02, '1', 'Agressive'),
(13875, 'Arraisonnage', 'Occasionne des dommages Terre aux ennemis en zone.', 0x08e7ce02, '1', 'Agressive'),
(13876, 'Récursivité', 'Repousse la cible.\n\nSi la cible termine son déplacement au contact d\'une Tourelle alliée, la Tourelle la téléporte symétriquement et lui réapplique les effets du sort.\n\nSi le lanceur lance le sort sur lui-même, il se déplace également avec les Tourelles s\'il est au contact de l\'une d\'entre elles.', 0x08e8ce02, '1', 'Agressive'),
(13877, 'Compas', 'Échange les positions des cibles.\nFonctionne également avec les Tourelles.', 0x08e9ce02, '1', 'Agressive'),
(13878, 'Assistance', '', 0x08eace020885cf02, '0', 'Teleport'),
(13879, 'Court-circuit', '', 0x08ebce020887cf02, '0', 'Buff'),
(13880, 'Sonar', '', 0x08ecce02, '0', 'Agressive'),
(13881, 'Récursivité', '', 0x08edce0208f9ce020884cf020888cf020889cf0208c5da03, '0', 'None'),
(13882, 'Compas', '', 0x08eece0208f8ce0208a0db03, '0', 'None'),
(13883, 'Chalutage', 'Attire les cibles en zone.\nLa taille de la zone et l\'attirance sont plus importantes selon le niveau d\'évolution.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.', 0x08efce02, '1', 'Agressive'),
(13885, 'Chaluchava', 'Retire des PM à l\'ennemi ciblé.', 0x08f1ce0208cbdd0208ccdd0208cddd020887e103, '1', 'None'),
(13888, 'Excavation', 'Érode l\'ennemi ciblé et lui occasionne des dommages dans le meilleur élément d\'attaque du lanceur.', 0x08f4ce0208badd0208bfdd0208c0dd02088be103, '1', 'None'),
(13889, 'Bathyscaphandre', 'Applique un bouclier sur la cible.\nLe bouclier est plus important selon le niveau d\'évolution et plus faible sur les ennemis.\n\nN\'affecte pas les ennemis dans l\'état Corselet.\nEn Évolution III, n\'affecte plus les ennemis.', 0x08f5ce02, '1', 'Buff'),
(13891, 'Décompression', 'Augmente les PA de l\'allié ciblé et lui applique un bouclier.', 0x08f7ce0208cadd02, '1', 'Buff'),
(13892, 'Boum', 'Vole de la vie dans l\'élément Air.\nLe vol de vie est plus important selon le niveau d\'évolution et plus faible sur les alliés.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.\nEn Évolution III, n\'affecte plus les alliés.', 0x08face0208fbce0208fcce02, '1', 'Agressive'),
(13893, 'Boumboum', 'Réduit la durée des effets de l\'ennemi ciblé et lui vole de la vie dans le meilleur élément d\'attaque du lanceur.', 0x08fdce0208fece0208ffce0208b1dd0208b2dd0208b3dd02088de103, '1', 'None'),
(13894, 'Forage', 'Occasionne des dommages Feu.\nLes dommages sont plus importants selon le niveau d\'évolution et plus faibles sur les alliés.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.\nEn Évolution III, n\'affecte plus les alliés.', 0x0880cf02, '1', 'Agressive'),
(13895, 'Forage', 'Occasionne des dommages Eau.\nLes dommages sont plus importants selon le niveau d\'évolution et plus faibles sur les alliés.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.\nEn Évolution III, n\'affecte plus les alliés.', 0x0881cf02, '1', 'Agressive'),
(13896, 'Forage', 'Occasionne des dommages Terre.\nLes dommages sont plus importants selon le niveau d\'évolution et plus faibles sur les alliés.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.\nEn Évolution III, n\'affecte plus les alliés.', 0x0882cf02, '1', 'Agressive'),
(13897, 'Forage', 'Occasionne des dommages Air.\nLes dommages sont plus importants selon le niveau d\'évolution et plus faibles sur les alliés.\n\nN\'affecte pas les alliés dans l\'état Cuirasse.\nEn Évolution III, n\'affecte plus les alliés.', 0x0883cf02, '1', 'Agressive'),
(13898, 'Foène', '', 0x088acf02088bcf0208919703089297030896ea03, '0', 'None'),
(13908, 'Morsure Albinos', 'Retire des PM et applique l\'état Mordu.\n\nSur une cible dans l\'état Mordu : occasionne des dommages Terre.', 0x089fcf0208c1d20208c2d202, '1', 'Debuff'),
