(14115, 'Gambette', 'Téléporte le lanceur symétriquement par rapport à la cible et occasionne des dommages Air aux ennemis.', 0x08add202, '1', 'Agressive'),
(14116, 'Béco Albinos', '', 0x08b0d202, '1', 'Debuff'),
(14117, 'Transpofu', 'Échange de position avec la cible.', 0x08b3d202, '1', 'Agressive'),
(14118, 'Distofu', 'Repousse la cible et rapproche le lanceur.', 0x08b4d202, '1', 'Agressive'),
(14119, 'Bécompresseur', '', 0x08b5d20208b6d20208b7d202, '1', 'Debuff'),
(14120, 'Morsure Mélanique', 'Occasionne des dommages Terre.', 0x08bad20208bbd20208bcd202, '1', 'Agressive'),
(14121, 'Morsure Précipitée', 'Attire la cible et occasionne des dommages Terre.\n\nEmpêche l\'utilisation du sort Attirance Laineuse pour le tour en cours.', 0x08bdd202, '1', 'Agressive'),
(14122, 'Projection Baveuse', 'Occasionne des dommages Eau aux ennemis en zone.', 0x08bed20208bfd20208c0d202, '1', 'Agressive'),
(14123, 'Tir Sélectif', 'Occasionne des dommages Eau et augmente la Puissance du lanceur.', 0x08c3d20208c7d20208c8d202, '1', 'Agressive'),
(14124, 'Crachat Albinos', 'Retire de l\'Esquive PM aux ennemis en zone.', 0x08c4d20208c5d20208c6d202, '1', 'Buff'),
(14125, 'Morsure Anticipée', 'Rapproche le lanceur de la cible, retire des PM et applique l\'état Mordu.\n\nSur une cible dans l\'état Mordu : rapproche le lanceur de la cible et occasionne des dommages Terre.', 0x08c9d202, '1', 'Agressive'),
(14126, 'Projection Lointaine', 'Occasionne des dommages Eau.', 0x08cad20208cbd20208ccd202, '1', 'Agressive'),
(14127, 'Crapoison', 'Applique un poison Eau de début de tour sur l\'ennemi ciblé.', 0x08ced20208cfd20208d0d202, '1', 'Agressive'),
(14128, 'Mémoire Amphibienne', 'Occasionne des dommages Eau.', 0x08d1d20208d2d20208d3d202, '1', 'Agressive'),
(14130, 'Crapoison Initiateur', 'Applique un poison Eau de début de tour sur l\'ennemi ciblé et lui occasionne des dommages Eau.', 0x08d4d202, '1', 'Agressive'),
(14131, 'Focus Laineux', 'Réduit les dommages à distance de la cible et les résistances en mêlée du lanceur.\n\nLes effets sur le lanceur ne peuvent pas être désenvoûtés.', 0x08d5d202, '1', 'Debuff'),
(14132, 'Toison Pesante', 'Applique l\'état Pesanteur sur la cible. \nNe fonctionne qu\'un tour sur deux sur la même cible.', 0x08d6d202, '1', 'Agressive'),
(14133, 'Crapoussée', 'Occasionne des dommages Eau aux ennemis et repousse la cible.', 0x08d7d20208ded20208dfd202, '1', 'Agressive'),
(14134, 'Ogive Salivaire', 'Occasionne des dommages Eau aux ennemis en zone.', 0x08d8d20208a49003, '1', 'Agressive'),
(14136, 'Dragofeu X', 'Occasionne des dommages Feu.', 0x08dad20208dbd20208dcd202, '1', 'Agressive'),
(14138, 'Diagofeu', 'Soigne les alliés au contact de la cible et occasionne des dommages Feu.\nLes soins sont réduits de moitié sur l\'invocateur.', 0x08e2d20208e6d20208e7d202, '1', 'Agressive'),
(14139, 'Diagofeu', '', 0x08e3d20208e4d20208e5d202, '1', 'Healing'),
(14140, 'Brasier', 'Occasionne des dommages Feu en zone.', 0x08e8d20208e9d20208ead202, '1', 'Agressive'),
(14141, 'Dragofeu Incandescent', '', 0x08ebd20208ecd20208edd202, '1', 'Healing'),
(14142, 'Dragofeu Incandescent', 'Soigne les alliés au contact de la cible et occasionne des dommages Feu.\nLes soins sont réduits de moitié sur l\'invocateur et n\'affectent pas le lanceur.', 0x08eed20208efd20208f0d202, '1', 'Agressive'),
(14143, 'Inversion Dragonique', '', 0x08f1d20208f2d20208f3d202, '1', 'Healing'),
(14144, 'Inversion Dragonique', 'Soigne l\'allié ciblé et occasionne des dommages Feu aux ennemis à son contact.\nLes soins sont plus importants si un ennemi est touché.\nLes soins sont réduits de moitié sur l\'invocateur.', 0x08f4d20208f5d202, '1', 'Agressive'),
(14145, 'Embrasement du Dragon', 'Occasionne des dommages Feu aux ennemis et soigne les alliés en zone.\nLes soins sont réduits de moitié sur l\'invocateur.', 0x08f6d202, '1', 'Agressive'),
(14146, 'Dragofeu Curatif', 'Soigne les alliés.\nLes soins sont réduits de moitié sur l\'invocateur.', 0x08f7d20208f8d20208f9d202, '1', 'Healing'),
(14147, 'Dragobstruction', 'Soigne les alliés.\nSi le lanceur est dans l\'état Contrôlé, réduit la durée des effets sur la cible.\nLes soins sont réduits de moitié sur l\'invocateur.', 0x08fad20208fbd202, '1', 'Healing'),
(14153, 'Le Fouet d\'Osamodas', '', 0x0889d3020890ea03, '1', 'None'),
(14155, 'Le Fouet d\'Osamodas', '', 0x08a4d30208a5d30208a6d30208a7d302, '1', 'None'),
(14157, 'Le Fouet d\'Osamodas', '', 0x08a9d30208aad30208abd30208acd30208cad502, '1', 'None'),
(14159, 'Ascendant Tofu', 'Tue l\'Informo pour donner une Tofucharge à son invocateur. Ce dernier lance sur la case de mort de l\'Informo le sort d\'invocation ainsi libéré (Prime, Second, etc...).', 0x08b1d30208d5d40208d6d402, '1', 'Agressive'),
(14160, 'Ascendant Bouftou', 'Tue l\'Informo pour donner une Bouftocharge à son invocateur. Ce dernier lance sur la case de mort de l\'Informo le sort d\'invocation ainsi libéré (Prime, Second, etc...).', 0x08b2d30208b9d30208bad302, '1', 'Agressive'),
(14161, 'Ascendant Crapaud', 'Tue l\'Informo pour donner une Crapocharge à son invocateur. Ce dernier lance sur la case de mort de l\'Informo le sort d\'invocation ainsi libéré (Prime, Second, etc...).', 0x08b3d30208b7d30208b8d302, '1', 'Agressive'),
(14162, 'Ascendant Dragonnet', 'Tue l\'Informo pour donner une Dragocharge à son invocateur. Ce dernier lance sur la case de mort de l\'Informo le sort d\'invocation ainsi libéré (Prime, Second, etc...).', 0x08b4d30208b5d30208b6d302, '1', 'Agressive'),
