(14306, 'Revêtement', 'Sur les alliés en zone : applique l\'état Cuirasse et les immunise contre les dommages des Tourelles offensives et du sort Court-circuit, ainsi que contre les déplacements des Tourelles tactiques.\n\nSur les ennemis en zone : applique l\'état Corselet et les immunise contre les soins et les boucliers des Tourelles défensives.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08e4d502, '1', 'None'),
(14307, 'Alcoshu', 'Applique l\'état Saoul sur le lanceur et vole de la vie dans l\'élément Eau.', 0x08e6d50208e7d502, '1', 'Agressive'),
(14308, 'Piston', 'Repousse l\'allié ciblé. \nLa poussée est plus importante sur les Tourelles.', 0x08e9d50208ead502, '1', 'Agressive'),
(14309, 'Pandjiu', 'Occasionne des dommages Feu aux ennemis et attire la cible.', 0x08f9d502, '1', 'Agressive'),
(14310, 'Pelotage', 'Occasionne des dommages Air.', 0x08fcd50208fdd50208fed502, '1', 'Agressive'),
(14311, 'Miaouch', 'Érode la cible et occasionne des dommages Feu.\nLe cumul de l\'Érosion est partagé avec les sorts Bluff, Réflexes et Face ou Pile.', 0x08ffd5020881d602, '1', 'Agressive'),
(14312, 'Dérobade', 'Rend l\'allié ciblé Intaclable.\n\nPendant 1 tour, si l\'allié subit des dommages en mêlée :\n• Se fait pousser par son attaquant.\n• Augmente ses PM.\n• Le rend invisible.\n\nLe lanceur ne peut pas déclencher les effets du sort sur lui-même avec ses pièges.\n\nLorsqu\'un Sram est rendu visible, il gagne 10% de dommages finaux pour sa prochaine attaque pendant 1 tour.\nL\'effet peut être déclenché qu\'une seule fois par tour.', 0x088ed6020897d602, '1', 'Agressive'),
(14313, 'Marque Mortuaire', 'Érode la cible.\nL\'Érosion est plus importante selon le nombre de pièges déclenchés du lanceur.\n\nDissipe l\'invisibilité du lanceur.', 0x0893d602, '1', 'Debuff'),
(14314, 'Fosse Commune', 'Pose un piège mono-cellule qui applique l\'état Pesanteur dans un cercle de 2 cases.', 0x0896d602, '1', 'Mark'),
(14315, 'Coupe-gorge', '', 0x0898d6020899d602, '1', 'Buff'),
