(14383, 'Soin Poupesque', 'Soigne les alliés en zone autour du lanceur.\nSoigne également tous les alliés au contact des Arbres Feuillus de l\'invocateur.', 0x08a5d70208e0f80308e1f803, '1', 'Healing'),
(14384, 'Explosion Poupesque', '', 0x08a6d70208a7d70208b5ef03088ff7030891f703, '0', 'None'),
(14385, 'Explosion Poupesque', 'Applique l\'état Infecté sur l\'ennemi ciblé et occasionne des dommages Eau aux ennemis.\nApplique également l\'état Infecté sur tous les ennemis au contact des Arbres Feuillus de l\'invocateur.\nTue le lanceur.', 0x08a8d70208a9d70208aad702, '1', 'Agressive'),
(14386, 'Bouture (Arbre Feuillu)', '', 0x08abd70208bde70308c4e7030892f00308cdf90308cef90308cff903, '0', 'None'),
(14387, 'Bouture', 'Retire des PM aux ennemis en zone.\nRetire des PM supplémentaires aux ennemis au contact des Arbres Feuillus de l\'invocateur.', 0x08acd70208acf803, '1', 'Debuff'),
(14388, 'Sac Rifice', 'Permet de subir les dommages reçus par les alliés ciblés.', 0x08add702, '1', 'Healing'),
(14389, 'Sac Animé', 'Invoque un Sac Animé qui subit les dommages à la place de ses alliés.\nLe Sac Animé disparaît après 4 tours.\nQuand il est attaqué par un allié, ce dernier est soigné.', 0x08aed70208afd70208b0d702, '1', 'Summon'),
(14390, 'Fureur Bestiale', '', 0x08b2d702, '1', 'Debuff'),
(14391, 'Galerie Animation', '', 0x08b3d702, '1', 'None'),
(14393, 'Braises Épineuses', 'Occasionne des dommages Feu. \n\nSur un Arbre Feuillu du lanceur : occasionne des dommages Feu aux ennemis dans un cercle de 2 cases autour de l\'Arbre.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Feu à tous les ennemis dans l\'état Infecté.', 0x08bad70208bbd70208bcd702, '1', 'Agressive'),
(14394, 'Braises Épineuses', '', 0x08bdd70208bed70208bfd70208bae40308bbe40308bce403, '0', 'Agressive'),
(14396, 'Mangrove', 'Occasionne des dommages Eau aux ennemis en zone.\n\nSur un Arbre Feuillu du lanceur : occasionne des dommages Eau plus importants aux ennemis dans une croix de 2 cases autour de l\'Arbre.', 0x08c6d70208c7d702, '1', 'Agressive'),
