(14411, 'Grenaille', 'Vole de la vie dans l\'élément Feu en zone.\nLe vol de vie est réduit de moitié sur les alliés.', 0x08e7d702, '1', 'Agressive'),
(14412, 'Casemate', 'Rend une Bombe du lanceur Invulnérable.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.', 0x08ead702, '1', 'None'),
(14413, 'Galerie Déclenché', '', 0x08ebd702, '1', 'Agressive'),
(14414, 'Shrapnel', 'Occasionne des dommages Eau.\nRetire des PA pour chaque Bombe, Mégabombe ou Bombe Ambulante du lanceur au contact de l\'ennemi ciblé.\n\nSur une Bombe du lanceur : occasionne des dommages Eau aux ennemis et retire des PA dans un carré d\'une case autour d\'elle.\nPeut être utilisé sur sa Mégabombe ou sa Bombe Ambulante.', 0x08ecd70208fed403, '1', 'Agressive'),
(14415, 'Bombarde', 'Occasionne des dommages Terre aux ennemis et repousse les cibles en zone.', 0x08edd70208f3d70208b2a703, '1', 'Agressive'),
