(14574, 'Portail', 'Pose un portail.\n\nLorsque plusieurs portails sont actifs, ils permettent de se téléporter ou de projeter des sorts.\nLes dommages et soins des sorts projetés sont augmentés par les portails.\n\nLes ennemis (hors invocations) ne peuvent pas emprunter un portail au premier tour de jeu.', 0x08b3da0208b4da0208b5da02, '1', 'None'),
(14575, 'Affront', 'Occasionne des dommages Air aux ennemis et repousse les cibles en zone.', 0x08b6da0208b7da0208b8da02, '1', 'Agressive'),
(14576, 'Poing Fulgurant', 'Occasionne des dommages Eau aux ennemis et repousse la cible.\nLa poussée est plus importante si le sort est projeté dans un portail.', 0x08b9da0208bada0208bbda02, '1', 'Agressive'),
(14577, 'Distribution', 'Pendant 1 tour, si la cible reçoit des dommages de sorts, soigne les alliés d\'une partie des dommages occasionnés dans un cercle de 2 cases autour d\'elle.', 0x08bcda0208bdda0208beda02, '1', 'Agressive'),
(14578, 'Distribution', '', 0x08bfda0208c0da0208c1da0208ead90308ebd90308ecd903, '0', 'None'),
(14579, 'Rayon de Wakfu', 'Occasionne des dommages Feu aux ennemis et soigne les alliés en zone.', 0x08c2da0208c3da0208c4da02, '1', 'Agressive'),
(14580, 'Étirement', 'Sacrifie temporairement une partie des points de vie du lanceur pour : \n• Augmenter la Portée des sorts Portail et Portail Flexible du lanceur.\n• Augmenter la Portée de l\'allié ciblé.', 0x08c5da0208c6da0208c7da02, '1', 'Buff'),
(14581, 'Thérapie', 'Attire la cible et occasionne des dommages Terre aux ennemis.', 0x08c8da0208c9da0208cada02, '1', 'Agressive'),
(14582, 'Neutral', 'Désactive un portail allié et rend 1 PA au lanceur.', 0x08cbda0208ccda0208cdda02, '1', 'Buff'),
(14583, 'Commotion', 'Occasionne des dommages Terre aux ennemis et attire les cibles vers le centre en zone.', 0x08ceda0208cfda0208d0da02, '1', 'Agressive'),
(14584, 'Affliction', 'Applique un poison Eau de début de tour sur la cible.\n\nProjeté dans un portail : applique un poison Eau de début de tour sur la cible et occasionne des dommages Eau.', 0x08d1da0208d2da0208d3da02, '1', 'Agressive'),
(14585, 'Stupeur', 'Pose un piège qui pose et active un portail.', 0x08d4da0208d5da0208d6da02, '1', 'Mark'),
(14586, 'Stupeur', '', 0x08d7da0208d8da0208d9da02, '1', 'None'),
(14587, 'Cicatrisation', 'Soigne les alliés en zone.', 0x08dada0208dbda0208dcda02, '1', 'Healing'),
(14588, 'Offense', 'Occasionne des dommages Feu.', 0x08ddda0208deda0208dfda02, '1', 'Agressive'),
(14589, 'Odyssée', 'Éloigne le lanceur de la cible et attire la cible.', 0x08e0da0208e1da0208e2da02, '1', 'Agressive'),
(14590, 'Camouflet', 'Occasionne des dommages Terre.\n\nProjeté dans un portail : réduit la durée des effets sur la cible, lui applique l\'état Camouflet et occasionne des dommages Terre aux ennemis.\n\nLe désenvoûtement ne peut pas être appliqué si la cible est déjà dans l\'état Camouflet.', 0x08e3da02, '1', 'Agressive'),
(14591, 'Focus', 'Augmente la Puissance de l\'allié ciblé.\nLa Puissance est plus importante si le sort est projeté dans un portail.', 0x08e6da0208e7da02, '1', 'Buff'),
(14592, 'Brimade', 'Occasionne des dommages Air aux ennemis en zone et repousse les cibles depuis le centre de la zone.\n\nLa poussée affecte le lanceur uniquement s\'il est projeté dans un portail.', 0x08e9da0208eada0208ebda02, '1', 'Agressive'),
(14593, 'Audace', 'Rapproche le lanceur de la cible et occasionne des dommages Eau aux ennemis.\n\nProjeté dans un portail : occasionne uniquement des dommages Eau.', 0x08ecda0208edda0208eeda02, '1', 'Agressive'),
(14594, 'Parasite', 'Occasionne des dommages Feu.\n\nProjeté dans un portail : occasionne des dommages Feu et applique un poison Feu de fin de tour sur la cible.', 0x08efda0208f0da02, '1', 'Agressive'),
(14595, 'Raillerie', 'Occasionne des dommages Air.\n\nProjeté dans un portail : occasionne des dommages Air et retire des PM.', 0x08f2da02, '1', 'Agressive'),
(14596, 'Entraide', 'Sur tout le monde pendant 2 tours, si une entité (hors lanceur) emprunte un portail : \n• Augmente les PA du lanceur.\n• Soigne le lanceur et ses alliés dans un cercle de 2 cases autour de lui.', 0x08f5da0208f6da02, '1', 'Agressive'),
(14597, 'Téléportail réussi', '', 0x08f8da02, '1', 'None'),
(14598, 'Entraide', '', 0x08f9da0208fada0208fbda02, '0', 'Healing'),
(14599, 'Parasite', '', 0x08fcda0208fdda0208d4dd0208d5dd02, '0', 'Agressive'),
(14602, 'Mépris', 'Occasionne des dommages Air aux ennemis et attire les cibles en zone.', 0x0888db0208c3db02, '1', 'Agressive'),
(14603, 'Tribulation', 'Occasionne des dommages Eau aux ennemis et attire les cibles vers le centre en zone.', 0x0889db0208c4db02, '1', 'Agressive'),
(14604, 'Portail Flexible', 'Pose un portail.\n\nLorsque plusieurs portails sont actifs, ils permettent de se téléporter ou de projeter des sorts.\nLes dommages et soins des sorts projetés sont augmentés par les portails.\n\nLes ennemis (hors invocations) ne peuvent pas emprunter un portail au premier tour de jeu.', 0x088adb0208c2db02, '1', 'None'),
(14605, 'Convulsion', 'Occasionne des dommages Terre aux ennemis et repousse les cibles en zone.', 0x088bdb0208c5db02, '1', 'Agressive'),
(14606, 'Faisceau', 'Occasionne des dommages Feu en zone.\n\nProjeté dans un portail : vole de la vie dans l\'élément Feu en zone.', 0x088cdb0208c6db02, '1', 'Agressive'),
(14607, 'Interruption', 'Désactive tous les portails alliés.', 0x088ddb0208c7db02, '1', 'None'),
(14608, 'Outrage', 'Occasionne des dommages Feu.\nLes dommages deviennent du vol de vie si le sort est projeté dans un portail.', 0x088edb02, '1', 'Agressive'),
(14609, 'Contraction', 'Pose et active un portail sur une case occupée.', 0x088fdb0208c9db02, '1', 'Agressive'),
(14610, 'Sinécure', 'Occasionne des dommages Air et réduit les Résistances Poussée.', 0x0890db0208c0db02, '1', 'Agressive'),
(14611, 'Diffusion', 'Pendant 1 tour, renvoie 50% des dommages subis par la cible aux ennemis dans un cercle de 2 cases autour d\'elle.', 0x0891db02, '1', 'Agressive'),
(14612, 'Distorsion', 'Invoque un Totem qui soigne les alliés (hors invocations) qui empruntent un portail.\nLorsqu\'il est attaqué par un allié, il pose et active un portail sur la case de son attaquant.\n\nIl ne peut y avoir qu\'un seul Totem Eliotrope par équipe. Si le Totem est encore en vie et que celui-ci est ré-invoqué, l\'ancien est tué pour laisser place au nouveau.', 0x0892db02, '1', 'Agressive'),
(14613, 'Sermon', 'Repousse la cible et occasionne des dommages Air aux ennemis.\nLa poussée est plus importante si le sort est projeté dans un portail.', 0x0893db02, '1', 'Agressive'),
(14614, 'Conjuration', 'Pendant 2 tours, si la cible emprunte un portail ou si le sort est projeté directement dans un portail, augmente les dommages de la prochaine attaque subie par la cible.\n\nL\'augmentation des dommages sur la prochaine attaque ne peut pas être désenvoûtée.', 0x0894db02, '1', 'Agressive'),
(14615, 'Paume Curative', 'Soigne la cible. \nLes soins sont plus importants si le sort est projeté dans un portail.', 0x0895db0208bedb0208bfdb02, '1', 'Healing'),
(14616, 'Exode', 'Téléporte le lanceur symétriquement par rapport à la cible.', 0x0896db02, '1', 'Agressive'),
(14617, 'Cabale', 'Augmente les PM des alliés en zone.\nLe bonus est plus important si le sort est projeté dans un portail.', 0x0897db02, '1', 'Buff'),
(14618, 'Aplomb', 'Occasionne des dommages Eau.\n\nProjeté dans un portail : occasionne des dommages Eau et donne 1 PM au lanceur.', 0x0898db0208888b04, '1', 'Agressive'),
(14619, 'Virus', 'Occasionne des dommages Feu aux ennemis en zone.\nSoigne les alliés dans la zone d\'effet à hauteur de 50% des dommages occasionnés aux ennemis.\nN\'affecte pas le lanceur.', 0x0899db02, '1', 'Agressive'),
(14620, 'Persiflage', 'Occasionne des dommages Terre.\n\nProjeté dans un portail : occasionne des dommages Terre et retire de la Portée.', 0x089adb02, '1', 'Agressive'),
(14621, 'Coalition', 'Augmente les PA de l\'allié ciblé.\nLe bonus est plus important si le sort est projeté dans un portail.', 0x089bdb02, '1', 'Buff'),
(14622, 'Conflagration', 'Soigne l\'allié ciblé et réduit les dommages finaux occasionnés par les ennemis en zone.', 0x089cdb02, '1', 'Healing'),
