(15014, '_SPAWN INVOC', '', 0x0892e1020893e1020894e1020895e1020896e1020897e102, '1', 'Summon'),
(15016, 'Concentration Trahison', 'Occasionne des dommages Terre.\nLes dommages sont augmentés contre les Invocations.', 0x0899e102, '1', 'Agressive'),
(15017, '_HUB', '', 0x089ae102, '1', 'Agressive'),
(15018, 'Épée Céleste Trahison', 'Occasionne des dommages Air en zone.', 0x089be102, '1', 'Agressive'),
(15019, 'Tempête de Puissance Trahison', 'Occasionne des dommages Feu. Occasionne des dommages Feu supplémentaires sur la cible initiale lorsque le sort est lancé sur une autre cible. \n\nLes dommages supplémentaires lors du changement de cible sont augmentés si le sort a d\'abord été utilisé deux fois sur la cible initiale.\n\nN\'inflige pas de dommages aux alliés.', 0x089ce102, '1', 'Agressive'),
(15020, 'Épée du Jugement Trahison', 'Occasionne des dommages Eau sans ligne de vue. Les dommages sont augmentés à chaque lancer. Si le lanceur subit des dommages en mêlée, les bonus de dommages sont retirés.', 0x089fe102, '1', 'Agressive'),
(15021, '_TRIGGER STATE + DMG', '', 0x08a0e102, '1', 'Agressive'),
(15022, 'Flèche d\'Abolition Trahison', 'Occasionne des dommages Air. Les dommages occasionnés sont augmentés sur les invocations.', 0x08a1e102, '1', 'Agressive'),
(15023, 'Flèche Fulminante Trahison', 'Occasionne des dommages Feu.\nSe propage sur l\'ennemi le plus proche dans un rayon de 2 cellules. Peut rebondir sur la Balise Tactique.\nÀ chaque cible supplémentaire, les dommages du sort sont augmentés.', 0x08a2e102, '1', 'Agressive'),
(15024, 'Flèche de Rédemption Trahison', 'Occasionne des dommages Eau qui sont augmentés si le sort est relancé le tour suivant.', 0x08a3e102, '1', 'Agressive'),
(15025, 'Flèche Destructrice Trahison', 'Occasionne des dommages Terre et réduit les dommages occasionnés par la cible.', 0x08a4e102, '1', 'Agressive'),
