(15040, 'Trahison Sacrieur', '', 0x08b3e102, '1', 'Agressive'),
(15041, 'Ronces Agressives Trahison', 'Occasionne des dommages Terre et donne 1PM au lanceur.\n\nSur un ennemi dans l\'état Infecté : exécute le sort sur tous les ennemis dans l\'état Infecté.', 0x08b4e102, '1', 'Agressive'),
(15042, 'Larme Trahison', 'Occasionne des dommages Eau. \n\nSur un Arbre allié qui vient d\'apparaître : le transforme en Arbre Feuillu et le rend exploitable avec les autres sorts du Sadida.\nSi la cible est dans l\'état Infecté : occasionne des dommages Eau à tous les ennemis dans l\'état Infecté.', 0x08b5e102, '1', 'Agressive'),
(15043, 'Ronce Paralysante Trahison', 'Occasionne des dommages Air et retire des PM.', 0x08b6e102, '1', 'Agressive'),
(15044, 'Braises Épineuses Trahison', 'Occasionne des dommages Feu. Sur un Arbre Feuillu, enlève le feuillage de l\'Arbre.\n\nSur un ennemi dans l\'état Infecté : occasionne des dommages Feu à tous les ennemis dans l\'état Infecté.', 0x08b7e102, '1', 'Agressive'),
(15045, 'Dragonique Trahison', 'Occasionne des dommages Feu aux ennemis et soigne les entités qui les attaquent. Augmente les soins reçus par le lanceur et par l\'allié ciblé. Confère une charge Dragonnet (nécessite une cible).', 0x08b8e102, '1', 'Agressive'),
(15046, 'Onde Aquatique Trahison', 'Occasionne des dommages Eau.\nAugmente les dommages occasionnés sur la cible par les invocations.', 0x08b9e102, '1', 'Agressive'),
(15047, 'Canine Trahison', 'Occasionne des dommages Air et retire du Tacle aux ennemis. Augmente les PM du lanceur et de l\'allié ciblé. Confère une charge Tofu (nécessite une cible).', 0x08bae102, '1', 'Agressive'),
(15048, 'Fossile Trahison', 'Occasionne des dommages Terre et retire des PM aux ennemis. Augmente le Tacle du lanceur et de l\'allié ciblé. Confère une charge Bouftou (nécessite une cible).', 0x08bbe102, '1', 'Agressive'),
(15049, '_STATE COUNTER +', '', 0x08bce102, '1', 'None'),
