(15056, 'Arnaque Trahison', 'Vole de l\'Agilité et occasionne des dommages Air.', 0x08c3e102, '1', 'Agressive'),
(15057, '_STATE COUNTER -', '', 0x08c4e102, '1', 'None'),
(15058, 'Cruauté Trahison', 'Occasionne des dommages Eau et augmente les PM du lanceur.', 0x08c5e102, '1', 'Agressive'),
