(15061, 'Dessèchement Trahison', 'Occasionne des dommages Air. \nOccasionne des dommages Air supplémentaires aux ennemis autour de la cible au début de son prochain tour.', 0x08c8e102, '1', 'Agressive'),
(15062, 'Aiguille Trahison', 'Occasionne des dommages Feu. Occasionne ensuite des dommages Feu supplémentaires lorsqu\'un Téléfrag est généré sur la cible pendant 1 tour, 4 fois maximum.', 0x08c9e102, '1', 'Agressive'),
