(15072, 'Souffle Alcoolisé Trahison', 'Occasionne des dommages Air et pousse la cible.\nL\'état Saoul est nécessaire.', 0x08d3e102, '1', 'Agressive'),
(15073, '_GLYPH SPELL DMG + RES', '', 0x08d4e102, '1', 'Agressive'),
(15074, 'Ethylo Trahison', 'Occasionne des dommages Eau.\nApplique un malus au retrait de PA.', 0x08d5e102, '1', 'Agressive'),
(15075, 'Pulsar Trahison', 'Occasionne des dommages Feu.\nMoins le lanceur a utilisé de PM pendant son tour de jeu, plus les dommages occasionnés sont importants.', 0x08dbe102, '1', 'Agressive'),
(15076, 'Mitraille Trahison', 'Occasionne des dommages Air.\nRepousse la cible.', 0x08dce102, '1', 'Agressive'),
(15077, 'Recel Trahison', 'Occasionne des dommages Eau aux ennemis.\nAttire la cible.', 0x08dde102, '1', 'Agressive'),
(15078, 'Arquebuse Trahison', 'Occasionne des dommages Terre sur les ennemis.\nRéduit la durée des effets actifs de 1 tour.', 0x08dee102, '1', 'Agressive'),
