(15086, 'Nautile Trahison', 'Occasionne des dommages Eau et retire des PM.', 0x08e7e102, '1', 'Agressive'),
(15087, 'Météore Percutant Trahison', 'Occasionne des dommages Terre et fixe l\'état Terre aux ennemis. Repousse la cible.\nPose une rune Terre à l\'emplacement de la cible.\n\nL\'état élémentaire de la cible modifie les effets qu\'elle subit :\n• Air : vole 3 Portée (1 tour)\n• Eau : - 2 PM (1 tour)\n• Feu : + 20% dommages subis (1 tour)', 0x08e8e102, '1', 'Agressive'),
(15088, 'Déluge Trahison', 'Occasionne des dommages Eau et fixe l\'état Eau. Rapproche le lanceur de sa cible.\nPose une rune d\'Eau à l\'emplacement de la cible.\n\nL\'état élémentaire de la cible modifie les effets qu\'elle subit :\n• Air : - 25% dommages (1 tour)\n• Feu : - 50 Fuite (1 tour)\n• Terre : - 2 PM (1 tour)', 0x08e9e102, '1', 'Agressive'),
(15089, 'Lance-Flamme Trahison', 'Occasionne des dommages Feu et fixe l\'état Feu. Pose une rune de Feu à l\'emplacement de la cible.\n\nL\'état élémentaire de la cible modifie les effets qu\'elle subit :\n• Eau : - 50 Fuite (1 tour)\n• Air : - 3 PA (1 tour)\n• Terre : + 20% dommages subis (1 tour)', 0x08eae102, '1', 'Agressive'),
(15090, 'Lame Astrale Trahison', 'Occasionne des dommages Air et fixe l\'état Air aux ennemis.\nRéduit la portée des ennemis, augmente la portée des alliés.\nPose une rune d\'Air à l\'emplacement de la cible.\n\nSuivant l\'état élémentaire de la cible, elle subit les effets suivants :\n• Eau : - 25% dommages (1 tour)\n• Feu : - 3 PA (1 tour)\n• Terre : vole 3 Portée (1 tour)', 0x08ebe102, '1', 'Agressive'),
(15091, 'Mâchoire Trahison', 'Occasionne des dommages Feu. \nAugmente la puissance des alliés à proximité de la cible. Le lanceur n\'est pas affecté.\nAugmente la Rage.', 0x08ece102, '1', 'Agressive'),
(15092, 'Cubitus Trahison', 'Occasionne des dommages Eau.\nSi la cible est la Proie, le lanceur gagne 1 PM.', 0x08ede102, '1', 'Agressive'),
(15093, 'Battue Trahison', 'Occasionne des dommages Air.\nSi la cible est dans l\'état Proie, les alliés à son contact gagnent 1 PM.', 0x08eee102, '1', 'Agressive'),
(15094, 'Muselière Trahison', 'Occasionne des dommages Terre.\nSi la cible est dans l\'état Proie, le lanceur gagne du tacle.', 0x08efe102, '1', 'Agressive'),
(15095, 'Trahison Pandawa', '', 0x08f0e102, '1', 'Agressive'),
