(15781, 'Rempart', 'Réduit les dommages reçus.\nLa protection sur les alliés est plus faible.', 0x0886eb02, '1', 'Agressive'),
(15782, 'Retour du Bâton', 'Occasionne des dommages Terre et vole de la Force.', 0x0887eb02, '1', 'Agressive'),
(15783, 'Trêve', 'Réduit tous les dommages subis par les alliés et les ennemis pendant 1 tour.\nLe lanceur ne peut pas occasionner de dommages pendant son tour suivant.', 0x0888eb02, '1', 'Agressive'),
(15784, 'Glyphe Enflammé', 'Pose un glyphe qui occasionne des dommages Feu.\nLes ennemis et alliés perdent des PM tant qu\'ils sont présents dans la zone d\'effet du glyphe.', 0x0889eb02, '1', 'Mark'),
(15785, 'Égide', 'Invoque un bouclier qui subit les dommages à la place des alliés présents dans son glyphe-aura.', 0x088aeb02, '1', 'Summon'),
(15787, 'Knadabra', 'Abra Knadabra n\'a pas de PM. Elle se déplace en occasionnant des dommages Feu et mord ses ennemis au corps à corps.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0893eb02, '1', 'Summon'),
(15788, 'Pelle Animée', 'Invoque une pelle qui repousse les ennemis et réduit leurs résistances aux pertes de PM.\nQuand elle est attaquée par un allié, ce dernier est soigné.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0894eb02, '1', 'Summon'),
(15789, 'Pelle Fantomatique', 'Réduit la durée des effets et occasionne des dommages Feu.', 0x0895eb02, '1', 'Debuff'),
(15790, 'Maladresse', 'Retire des PM.', 0x0896eb02, '1', 'Agressive'),
(15791, 'Retraite Anticipée', 'Interdit l\'utilisation des sorts de déplacement et empêche d\'utiliser des PM.\nLe lanceur du sort est affecté au tour suivant.\nLes effets ne peuvent pas être désenvoûtés.', 0x0897eb02, '1', 'Debuff'),
(15792, 'Corruption', 'Sur Allié : soigne et fixe l\'état Pacifiste pendant 1 tour\nSur Ennemi : fixe l\'état Pacifiste et Invulnérable pendant 1 tour\nLes effets du sort ne peuvent pas être désenvoûtés.', 0x0898eb02, '1', 'Healing'),
(15793, 'Coffre Animé', 'Invoque un Coffre Animé qui tacle les ennemis.\nIl occasionne des dommages en zone autour de lui et détecte les invisibles. Moins il a de vie et plus ses dommages sont importants.\nQuand il est attaqué par un allié, ce dernier est soigné.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0899eb02, '1', 'Summon'),
(15794, 'Hyènifer', 'Hyènifer occasionne des dommages Terre en se déplaçant et augmente les dommages de mêlée de ses alliés.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x089aeb02, '1', 'Summon'),
(15797, 'Poison insidieux', 'Empoisonne la cible pendant 2 tours en occasionnant des dommages Terre.', 0x089deb02, '1', 'Agressive'),
(15798, 'Nem', 'Nem empoisonne les ennemis et occasionne des dommages dans l\'élément Eau.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x089eeb02, '1', 'Summon'),
(15800, 'Explosion de masse', 'Utilisé pour le sort de sram piège de masse.', 0x08a0eb02, '1', 'Agressive'),
