(15893, 'Bouftou Mélanique', 'Le Bouftou Mélanique attire les ennemis et occasionne des dommages Terre.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x08e2ed02, '1', 'Summon'),
(15894, 'Flèche Tyrannique', '', 0x08e3ed0208a9a603, '0', 'Agressive'),
(15895, 'Flèche Tyrannique', 'Occasionne des dommages Feu et Air.\nOccasionne des dommages Feu supplémentaires si la cible subit des dommages de poussée, et des dommages Air si la cible est attirée, poussée ou transposée.\nLes dommages de chaque élément peuvent être déclenchés 2 fois par tour au maximum.', 0x08e4ed02, '1', 'Agressive'),
(15896, 'Herbe Folle', 'Occasionne des dommages Air et retire des PM en zone.', 0x08e5ed02, '1', 'Agressive'),
