(15900, 'Sacrifice', 'Cible des alliés en zone pour recevoir les dommages à leur place.', 0x08e9ed02, '1', 'Healing'),
(15901, 'Punition', 'Occasionne des dommages dans le meilleur élément d\'attaque du lanceur, plus des dommages Neutre selon ses PV érodés.', 0x08eaed02, '1', 'Agressive'),
(15902, 'Poing Enflammé', 'Occasionne des dommages Feu.', 0x08ebed02, '1', 'Agressive'),
(15903, 'Libre', '', 0x08eced0208eded0208eeed0208efed0208f0ed0208f1ed0208f2ed0208f3ed0208f4ed0208f5ed0208f6ed0208f7ed02, '1', 'Buff'),
