(15944, 'Scaphandre', 'Augmente les PM, les dommages et les dommages de poussée du lanceur et des alliés ciblés.', 0x08c7ee02, '1', 'Agressive'),
(15945, 'Slaïe', 'Slaïe occasionne des dommages Feu en zone à courte distance.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x08c8ee02, '1', 'Summon'),
(15946, 'Pulsion Croissante', 'Pousse la cible de 1 case. La distance augmente à chaque lancer (8 max).', 0x08c9ee02, '1', 'Agressive'),
(15948, 'Croc Husky', 'Le Croc Husky occasionne des dommages dans plusieurs éléments et augmente les chances de Critique de son invocateur.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x08cbee02, '1', 'Summon'),
