(16488, 'Foudroiement', 'Occasionne des dommages Feu en zone.', 0x08e6f702, '1', 'Agressive'),
(16489, 'Invocation de Chaferfu', 'Invoque un Chaferfu qui attaque aléatoirement les alliés et les ennemis.\nPeut invoquer un Chaferfu Lancier qui retire des PM à la place.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x08e7f702, '1', 'Summon'),
(16490, 'Maîtrise d\'Arme', 'Augmente les dommages infligés par les armes.', 0x08e8f702, '1', 'None'),
(16491, 'Rien de rien', 'Retire 1 PA à la cible. L\'invocateur gagne 2 PA tous les deux retraits réussis.', 0x08ebf702, '1', 'Agressive'),
