(16508, 'La Sacrifiée', 'La Sacrifiée se sacrifie pour occasionner des dommages Air en zone. Les dommages qu\'elle occasionne augmentent à chaque tour.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0893f802, '1', 'Summon'),
(16509, 'Roukewl', 'Roukewl occasionne des dommages Air en roucoulant et occasionne des dommages Air aux ennemis adjacents quand il subit des dommages de poussée.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0894f802, '1', 'Summon'),
(16510, 'Yitim Michiwi', 'Yitim confère un bouclier à son invocateur quand il est attaqué et vice versa. Il peut aussi augmenter ses points de vie pour une courte durée.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0895f802, '1', 'Summon'),
(16511, 'Nealin Nealang', 'Nealin soigne ses alliés, occasionne des dommages Feu à distance et des dommages Terre en mêlée.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0896f802, '1', 'Summon'),
(16512, 'Phorum', 'Le Phorum pousse et se rapproche de ses ennemis, occasionne des dommages Terre et des dommages Air qui déplacent ses cibles.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0897f802, '1', 'Summon'),
(16513, 'Rei', 'Rei occasionne des dommages Eau en zone et des dommages Feu au corps à corps en s\'éloignant de sa cible. Elle régénère une partie de ses points de vie à chaque fois que son invocateur occasionne des dommages Eau ou Feu.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x0898f802, '1', 'Summon'),
(16514, 'Modou', 'Soigne un allié de 8% de ses points de vie.', 0x0899f802, '1', 'Healing'),
(16515, 'Corina', 'Le Corina empoisonne ses ennemis dans l\'élément Eau et occasionne des dommages Terre à tous les ennemis empoisonnés. Il peut aussi se sacrifier pour empoisonné les ennemis aux alentours.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x089af802, '1', 'Summon'),
(16516, 'Grobus', 'Le Grobus occasionne des dommages Feu et des dommages Air en zone. Il peut aussi tuer des invocations alliées pour se régénérer.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x089bf802, '1', 'Summon'),
(16517, 'Tulhassible', 'Occasionne des dommages Feu à distance.', 0x089cf802, '1', 'Agressive'),
(16518, 'Charbender', 'Le Charbender réduit les dommages occasionnés par les ennemis et attire les cibles à son corps à corps. Soigne les alliés qui l\'attaquent de 100% des dommages occasionnés en ne subissant que 50% de ces dommages. Chacune de ces attaques a 15% de chance de soigner intégralement l\'invocation et de la transformer temporairement en Charbender agressif.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x089df802, '1', 'Summon'),
(16519, 'Koudkoko', 'Occasionne des dommages Terre au corps à corps.', 0x089ef802, '1', 'Agressive'),
(16520, 'Phaute', 'Pousse la cible d\'une case et se rapproche de trois.', 0x089ff802, '1', 'Agressive'),
(16521, 'Bavaute', 'Occasionne des dommages Terre à distance.', 0x08a0f802, '1', 'Agressive'),
(16522, 'Phloud', 'Occasionne des dommages Air et attire les entités ciblées vers le centre de la zone.', 0x08a1f802, '1', 'Agressive'),
(16523, 'Phloud', '', 0x08a2f80208a3f802, '1', 'Agressive'),
(16524, 'Reisistance', 'Regagne 8% de sa vie quand son invocateur occasionne des dommages Eau ou Feu.', 0x08a4f802, '1', 'Agressive'),
