(16528, 'Contagion', 'Empoisonne l\'ennemi ciblé dans l\'élément Eau pendant 3 tours.', 0x08a8f802, '1', 'Agressive'),
(16529, 'Aggravement', 'Occasionne des dommages Terre aux cibles empoisonnées.', 0x08a9f802, '1', 'Agressive'),
(16530, 'Propagation', 'Se suicide pour empoisonner tous les ennemis alentours. \nLe poison n\'est pas désenvoûtable.', 0x08aaf802, '1', 'Agressive'),
(16531, 'Assimilation', 'Tue une invocation du même invocateur pour se soigner intégralement. Les trois premières utilisations de ce sort augmentent aussi la Vitalité de 30%.', 0x08aff802, '1', 'Agressive'),
(16532, 'Assimilation', '', 0x08b0f802, '1', 'Healing'),
(16533, 'Grobustion', 'Occasionne des dommages Feu en zone.', 0x08b1f802, '1', 'Agressive'),
(16534, 'Dysfonctionnement', 'Occasionne des dommages Air aux ennemis en zone.', 0x08b2f802, '1', 'Agressive'),
(16535, 'Chacrifice', 'Soigne les alliés qui l\'attaquent de 100% des dommages occasionnés et ne subit que 50% de ces dommages. Chacune de ces attaques a 15% de chance de soigner l\'invocation intégralement et de la transformer en Charbender Garou (2 tours).', 0x08b3f802, '1', 'Agressive'),
(16536, 'Gare au grou grou', '', 0x08b4f80208b5f80208b6f802, '1', 'Buff'),
(16537, 'Déséquilibrage', 'Réduit les dommages occasionnés par la cible de 10% (2 tours). \nGarou : occasionne des dommages dans le meilleur élément.', 0x08b7f802, '1', 'Agressive'),
(16538, 'Charrier', 'Garou uniquement : attire les cibles à son corps à corps.', 0x08b8f802, '1', 'Agressive'),
(16539, 'Croque-biscuit', 'Occasionne des dommages dans trois éléments aléatoires et augmente les chances de Critique de son invocateur.', 0x08baf802, '1', 'Agressive'),
