(18587, 'Respiration du Wukang', '', 0x088c8f03088d8f0308db930308ec930308ed930308ee930308f09403, '0', 'None'),
(18629, 'Dofus Ébène', 'Occasionner des dommages à distance et en mêlée pendant son propre tour de jeu déclenche le pouvoir du Dofus Ébène : la prochaine attaque, toujours dans le même tour, applique un poison (2 tours).\nCette attaque a un temps de recharge de 2 tours. Le poison est cumulable 2 fois.', 0x08e38f03, '1', 'Agressive'),
(18630, 'Dofus Ébène', '', 0x08e48f03, '1', 'Debuff'),
(18631, 'Dofus Ébène', '', 0x08e58f03, '1', 'Agressive'),
