(18645, 'Dofus Ébène', '', 0x08fb8f0308809003088190030882900308839003, '1', 'Agressive'),
(18646, 'Maîtrise des Invocations', 'Si le sort est sélectionné dans le livre de sorts, le lanceur contrôle par défaut ses invocations maîtrisables.\n\nLancer le sort permet de laisser ces invocations jouer par elles-mêmes jusqu\'au prochain lancer du sort. Affecte également les prochaines invocations.\nLe coût en PA du sort est remboursé.', 0x08859003, '1', 'Agressive'),
(18647, 'Maîtrise des Invocations', '', 0x08869003, '1', 'Agressive'),
(18648, 'Maîtrise des Invocations', '', 0x08889003088d9003, '1', 'None'),
(18649, 'Maîtrise des Invocations', '', 0x088b9003, '1', 'None'),
(18650, 'Transfiguration', 'Applique l\'état Transfiguration sur le lanceur et l\'ennemi ciblé, en appliquant des effets sur l\'ennemi selon le masque porté :\n• État Intrépide : réduit les dommages finaux occasionnés.\n• État Pleutre : réduit les résistances à distance.\n• État Psychopathe : réduit les résistances en mêlée.\nLe cumul est partagé entre les effets.\n\nChaque changement de masque diminue l\'intervalle de relance du sort d\'un tour et réapplique les effets du sort si le lanceur est dans l\'état Transfiguration.', 0x08939003, '1', 'Agressive'),
(18651, 'Carnavalo', 'Applique un bouclier sur le lanceur, occasionne des dommages dans son meilleur élément d\'attaque aux ennemis et repousse la cible.\nChaque effet devient plus important selon le masque porté par le lanceur :\n• État Intrépide : le bouclier est plus important.\n• État Pleutre : la poussée est plus importante.\n• État Psychopathe : les dommages sont plus importants.\n\nChaque changement de masque diminue l\'intervalle de relance du sort d\'un tour.', 0x0895900308f48b04, '1', 'Agressive'),
(18652, 'Aimantation', '', 0x08999003089a9003089b9003, '0', 'Agressive'),
(18653, 'COLOR INITIAL', '', 0x089f900308a0900308a1900308a2900308a6900308a7900308a8900308a9900308aa900308ab900308ac900308ad900308ae900308af900308b0900308b1900308b2900308b3900308b4900308b59003, '1', 'Summon'),
(18654, 'Croassement', 'Occasionne des dommages Eau aux ennemis en zone et attire les entités vers la cible.', 0x08a39003, '1', 'Agressive'),
(18655, 'Marque Dragonique', 'Occasionne des dommages Feu.\nLes attaquants sont soignés d\'une partie des dommages occasionnés.', 0x08a59003, '1', 'Agressive'),
(18656, 'Préserve Naturelle', 'Augmente les PM de toutes les invocations Osamodas du lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08b69003, '1', 'Agressive'),
