(19137, 'As de Cœur', 'Inflige des dommages Eau à distance et applique l\'état Cœur au lanceur.\n\n<font color=\"#6D6D6D\"><u>État Cœur</u> : Dure 1 tour (non dissipable). Si l\'envoûtement arrive à son terme sans avoir été retiré par un autre sort, alors le lanceur de ce sort soigne le porteur de l\'état de 5% de ses PV.</font>', 0x08cd9703, '1', 'Agressive'),
(19138, 'As de Cœur', 'Soigne et applique l\'état Cœur. Si la cible était déjà dans cet état, elle gagne des Critiques.\n\n<font color=\"#6D6D6D\"><u>État Cœur</u> : Dure 1 tour (non dissipable). Si l\'envoûtement arrive à son terme sans avoir été retiré par un autre sort, alors le lanceur de ce sort soigne le porteur de l\'état de 5% de ses PV.</font>', 0x08ce9703, '1', 'Healing'),
(19139, 'As de Carreau', 'Soigne un pourcentage de la vie et applique l\'état Carreau. Si la cible était déjà dans cet état, elle gagne des Critiques.\n\n<font color=\"#6D6D6D\"><u>État Carreau</u> : Dure 1 tour (non dissipable). Si l\'envoûtement arrive à son terme sans avoir été retiré par un autre sort, alors le lanceur de ce sort donne de la Puissance au porteur de l\'état. La valeur augmente avec le niveau du lanceur.</font>', 0x08cf9703, '1', 'Healing'),
(19140, 'As de Cœur', 'Soigne et applique l\'état Cœur. Si la cible était déjà dans cet état, elle gagne un atout.\n\n<font color=\"#6D6D6D\"><u>État Cœur</u> : Dure 1 tour (non dissipable). Si l\'envoûtement arrive à son terme sans avoir été retiré par un autre sort, alors le lanceur de ce sort soigne le porteur de l\'état de 5% de ses PV.</font>', 0x08d09703, '1', 'Agressive'),
