(20073, 'Antidote', 'Enlève l\'état Infecté de l\'ennemi ciblé.', 0x08fda103, '1', 'None'),
(20074, 'Infection', '', 0x08ffa103, '1', 'Agressive'),
(20075, 'Prestesse', 'Le lanceur se rapproche de la cible. Le coût du sort est remboursé les tours où les effets d\'Épéiste sont augmentés.', 0x0880a2030881a2030882a203, '1', 'Agressive');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(20076, 'Distant', 'Au début de leur tour, les Crâs gagnent l\'état Intaclable et 2 PM (1 tour) s\'ils ont subi une attaque ennemie au corps à corps depuis le dernier tour. Sinon, ils gagnent +1 Portée (infini, cumulable 8 fois).', 0x0883a20308d9bd03, '1', 'Agressive'),
(20077, 'Distant', '', 0x0884a203, '1', 'Agressive'),
(20078, 'Distant', '', 0x0885a203, '1', 'None'),
(20079, 'Zobal Masqué', 'Chaque tour, les Zobals peuvent choisir quel masque porter et bénéficier ainsi d\'un bonus. Cette action est remboursée tant qu\'ils changent de masque à chaque tour.', 0x0886a203, '1', 'Agressive'),
(20080, 'Masque du Pleutre', 'Le lanceur revêtit le masque du Pleutre et gagne des PM. Le coût du sort est remboursé si le masque est différent du tour précédent.', 0x0887a20308f8a703, '1', 'Buff'),
(20081, 'Masque de l\'Intrépide', 'Le lanceur revêtit le masque de l\'Intrépide et gagne un bouclier. Le coût du sort est remboursé si le masque est différent du tour précédent.', 0x0888a203, '1', 'Buff'),
(20082, 'Masque du Psychopathe', 'Le lanceur revêtit le masque du Psychopathe et gagne de la Puissance. Le coût du sort est remboursé si le masque est différent du tour précédent.', 0x0889a20308f9a70308faa70308fba703, '1', 'Buff'),
(20083, 'Distant', '', 0x088aa20308a5a303, '1', 'Buff'),
(20084, 'Distant', '', 0x088ba203, '1', 'Agressive'),
(20085, 'Quadramental', 'Tenter d\'occasionner des dommages dans un élément puis dans un autre crée une combinaison élémentaire de ces deux éléments. Réaliser une combinaison fait gagner l\'état Exalté pour le tour en cours et 9-25 Puissance (en fonction du niveau) pour le reste du combat. L\'élément Neutre ne compte pas.\n\nL\'état Exalté est non-cumulable et donne +2 PA et 20-100 Puissance (en fonction du niveau).', 0x088ca203, '1', 'Agressive'),
(20086, 'Quadramental', '', 0x088da203088fa2030890a2030891a20308e1a303, '1', 'Buff'),
(20087, 'Quadramental', '', 0x088ea203, '1', 'Agressive'),
(20088, 'Quadramental', '', 0x0892a203088ca803088da803088ea803088fa8030890a8030891a8030892a8030893a803, '1', 'Buff'),
(20089, 'Quadramental', '', 0x0893a2030884a8030885a8030886a8030887a8030888a8030889a803088aa803088ba803, '1', 'Buff'),
(20090, 'Neutralisation', 'Réinitialise les combinaisons élémentaires et leurs effets. Soigne de 10% des PV + 9% pour chaque combinaison élémentaire créée.\n\nLe délai de relance de ce sort est réduit de 1 tour à chaque fois que le lanceur tente d\'occasionner des dommages Neutre.', 0x0894a203, '1', 'Healing'),
(20091, 'Portail', 'Pose un portail.\nLorsque plusieurs portails sont actifs, ils permettent de se téléporter ou de projeter des sorts.\nLes dommages et soins des sorts projetés sont augmentés par les portails.\nLes ennemis (hors invocation) ne peuvent pas passer au travers d\'un portail au premier tour de jeu.', 0x0895a2030896a2030897a2030898a203, '1', 'None'),
(20092, 'Neutral', 'Désactive un Portail pendant 1 tour.', 0x0899a203089aa203089ba203, '1', 'None'),
(20093, 'Longue tranche', '', 0x089ca203, '1', 'Agressive'),
(20101, 'Partie de Go', '', 0x08afa203, '1', 'Agressive'),
(20102, 'Dressage', 'Le lanceur augmente la Vitalité d\'une invocation de parchomancie alliée et lui transmet 50% de sa Puissance (100% s\'il s\'agit de sa propre invocation). Si l\'invocation meurt pendant la durée de l\'envoûtement (2 tours), le lanceur gagne 2 PA.', 0x08b0a20308eda70308eea703, '1', 'Buff'),
(20103, 'Dressage', '', 0x08b1a203, '1', 'Buff'),
(20104, 'Envol', 'Le lanceur échange de place avec une invocation de parchomancie alliée.', 0x08b2a20308eba70308eca703, '1', 'Agressive'),
(20105, 'Feu Sacrificiel', 'L\'invocation de parchomancie alliée ciblée distribue la moitié de ses PV à son invocateur, et le reste au lanceur. Elle meurt.', 0x08b3a203, '1', 'Agressive'),
(20106, 'Feu Sacrificiel', '', 0x08b4a203, '1', 'None'),
