(20133, 'Ivresse', '', 0x08e2a20308e6a203, '1', 'None'),
(20134, 'Ivresse', 'Sur un Tonneau Magique, échange de place avec l\'entité dans l\'état Saoul la plus proche dans un rayon de 4 cases et retire l\'état. \n\nSur une autre entité, applique Saoul (1 tour).', 0x08e5a20308f3a70308f4a703, '1', 'Agressive'),
(20135, 'Tonneaux', '', 0x08e7a203, '1', 'None'),
(20136, 'Pollentourloupe', 'Echange la place du monstre avec celle de la bombe ciblée.', 0x08e9a203, '1', 'Agressive'),
(20137, 'Aucun effet', '', 0x08efa203, '1', 'None'),
(20138, 'Tourelle', 'Invoque une Tourelle. Lorsque deux tourelles sont alignées, elles créent un marquage au sol qui donne des PM aux alliés et en retire aux ennemis.', 0x08f0a203, '1', 'Summon'),
(20140, 'Périmètre de Sécurité', '', 0x08f2a203, '1', 'Buff'),
(20141, 'Mise à jour', 'Échange de place avec une Tourelle du lanceur.', 0x08f3a20308fca70308fda703, '1', 'Agressive'),
(20142, 'Désassemblage', 'Détruit une Tourelle pour conférer un bouclier en zone autour du lanceur.', 0x08f4a2030881a8030882a8030883a803, '1', 'Agressive'),
