(20159, 'Amortissement', 'Tout le monde passe son prochain tour.\n\nCoûte 10 Kamas de combat.', 0x0894a303, '1', 'Agressive'),
(20160, 'Double', 'Invoque un double contrôlable qui possède les mêmes caractéristiques que l\'invocateur.\nIl n\'attaque pas et meurt après avoir joué 3 tours en échangeant de place avec son invocateur.\nUn allié qui attaque le double se soigne de 50% des dommages infligés.', 0x0895a303, '1', 'Summon'),
(20161, 'Double', '', 0x0898a303, '0', 'Agressive'),
(20162, 'Double', '', 0x0899a303, '0', 'Agressive'),
(20163, 'Infinisibilité', 'Aligne les chakras du lanceur et de l\'allié ciblé. Pendant 2 tours, le lanceur devient invisible et la cible réduit de 50% les dommages reçus. En contrepartie, la cible occasionne 50% des dommages qui lui sont occasionnés au lanceur. Si l\'un des deux meurt, si le lanceur relance le sort ou s\'il devient lui-même une cible de ce sort, l\'effet est dissipé.\n\n<font color=\"#6D6D6D\"><u>Infinisibilité</u> : cette invisibilité spéciale n\'est pas perdue lorsque le lanceur occasionne des dommages mais attention, comme les Srams avisés le savent déjà, la position d\'un invisible est révélée à l\'équipe adverse à chaque fois que celui-ci lance un sort ou utilise une arme.</font>', 0x089aa303, '1', 'Agressive'),
(20164, 'Infinisibilité', '', 0x089ba303, '1', 'Buff'),
(20165, 'Infinisibilité', '', 0x089ca303, '1', 'Debuff'),
(20166, 'Disciple', '', 0x089da303089ea303, '0', 'Agressive'),
(20167, 'Bombe', 'Les Roublards se transforment en bombe à la fin de leur tour. Au prochain tour, ils peuvent détonner pour occasionner des dommages autour d\'eux. Les dommages augmentent à chaque fois que la bombe subit des dommages ennemis (max. 10 fois).', 0x089fa303, '1', 'Agressive'),
(20168, 'Bombe', '', 0x08a0a303, '1', 'Agressive'),
(20169, 'Bombe', '', 0x08a1a303, '1', 'Agressive'),
(20170, 'Explosion', 'Le lanceur-bombe explose pour occasionner des dommages, puis redevient lui-même. Le lanceur regagne 1 PA.\n\nLes dommages augmentent à chaque fois que la bombe subit des dommages ennemis (max. 4 fois).', 0x08a2a30308f5a70308f6a703, '1', 'Agressive'),
(20172, 'Explosoin', 'Le lanceur-bombe explose pour soigner les alliés, puis redevient lui-même. Le lanceur regagne 1 PA.', 0x08a4a303, '1', 'Debuff'),
(20173, 'Châtiment', 'Les Sacrieurs gagnent des bonus quand ils subissent des dommages ennemis. +1 PM (1 tour) à distance, +1 PA (1 tour) en mêlée, cumulables 4 fois chacun.', 0x08a6a303, '1', 'Agressive'),
(20174, 'Indulgence', 'Le lanceur regagne une partie de ses PV.', 0x08a7a303, '1', 'Healing'),
(20175, 'Châtiment', '', 0x08a8a30308a9a303, '1', 'Buff'),
(20176, 'Intimidation', 'Les Ouginaks réduisent de 25% les dommages des ennemis au contact desquels ils finissent leur tour et leur appliquent l\'état Proie. Pour chaque ennemi déjà dans l\'état Proie, les Ouginaks regagnent 8% de leurs PV. L\'état Proie dure un peu plus d\'un tour et se termine au début du tour de l\'ennemi.', 0x08aaa303, '1', 'Agressive'),
(20177, 'Intimidation', '', 0x08aba303, '1', 'Agressive'),
(20178, 'Intimidation', '', 0x08aca303, '1', 'Healing'),
(20179, 'Intimidation', '', 0x08ada303, '1', 'None'),
(20180, 'Chasse', 'Le lanceur gagne 3 PM si aucun ennemi n\'est présent à 3 cases ou moins. Révèle les invisibles ennemis dans la zone.\n\nCe sort peut être relancé après avoir subi des dommages de mêlée ennemis.', 0x08aea303, '1', 'Agressive'),
(20181, 'Chasse', '', 0x08afa30308b0a303, '1', 'Buff'),
(20182, 'Intimidation', '', 0x08b1a30308b2a303, '1', 'None'),
(20205, 'Lancer de Râteau', 'Occasionne des dommages Air.', 0x08c9a303, '1', 'Agressive'),
(20209, 'Délivrance', 'Occasionne des dommages Eau et retire du Tacle.', 0x08cda303, '1', 'Agressive'),
(20210, 'Miasme', 'Occasionne des dommages Air en zone', 0x08cea303, '1', 'Agressive'),
(20211, 'Distant', '', 0x08cfa303, '1', 'None'),
(20214, 'Soufflosion', 'Le lanceur-bombe explose pour repousser les entités à son corps à corps, puis redevient lui-même. Le lanceur regagne 1 PA.', 0x08d2a303, '1', 'Debuff'),
(20217, 'Sangulaire', 'Occasionne des dommages Eau en zone.', 0x08d5a303, '1', 'Agressive'),
(20220, 'Muret', 'Occasionne des dommages Terre en zone.', 0x08d8a303, '1', 'Agressive'),
(20222, 'Châtiment', '', 0x08daa30308dba303, '1', 'Agressive'),
(20224, 'La Brise', 'Inflige des dommages Air et gagne 3 PA pour le tour suivant.', 0x08dda303, '1', 'Agressive'),
(20225, 'Le Roc', 'Inflige des dommages Terre et gagne 3 PA pour le tour suivant.', 0x08dea303, '1', 'Agressive'),
