(20291, 'Distribe', '', 0x08aaa403, '0', 'Buff'),
(20292, 'Mot de Régénération', 'La cible alliée est soignée à retardement : au début du prochain tour du lanceur, et au tour suivant.', 0x08ada403, '1', 'Healing'),
(20293, 'Concentration', 'Occasionne des dommages Air.\nLes dommages sont augmentés contre les Invocations.', 0x08aea403, '1', 'Agressive'),
(20294, 'Mutilation', 'Le lanceur sacrifie 10% de ses PV pour gagner de la Puissance pendant 1 tour, et ainsi de suite à chaque début de tour tant que le sort est actif. \nRelancer Mutilation arrête ses effets et lance Coagulation.\n\nCoagulation : applique du bouclier au lanceur pour 2 tours selon le nombre de tours où la Mutilation a été active.', 0x08afa403, '1', 'Agressive'),
