(20581, 'Générosité Vampirique', 'Occasionne des dommages Air aux ennemis, à la fin de son tour le lanceur soigne ses alliés en zone autour de lui. Chaque ennemi touché par le sort augmente la puissance du soin.', 0x08bea703, '1', 'Agressive'),
(20584, 'Générosité Vampirique', '', 0x08c1a70308c2a703, '1', 'Healing'),
(20585, 'Soin percutant', 'Soigne l\'allié ciblé de 8% de ses PV à la fin de son prochain tour. Lorsque le soin est appliqué le lanceur occasionne des dommages Air aux ennemis en zone autour de l\'allié.', 0x08c3a703, '1', 'Agressive'),
(20586, 'Soin percutant', '', 0x08c4a703, '1', 'Agressive'),
(20589, 'Décharge spasmodique', 'Applique un poison Air de fin de tour à la cible pendant 1 tour. La cible retire 50 d\'Agilité à ses alliés autour d\'elle en fin de tour.', 0x08c7a703, '1', 'Agressive'),
(20590, 'Grabataire', '', 0x08c8a70308c9a70308caa70308cba70308cca70308cda70308cea70308cfa70308d0a70308d1a70308d2a70308d3a70308d4a70308d5a70308d6a70308d7a70308d8a70308d9a70308daa703, '1', 'Debuff'),
(20591, 'Décharge spasmodique', '', 0x08dba703, '1', 'Agressive'),
(20593, 'Bourre soufflée', 'Occasionne des dommages Air en zone et applique l\'état intacleur aux ennemis pendant 1 tour.', 0x08f7a703, '1', 'Agressive'),
(20621, 'Aspiration', 'Occasionne des dommages Air en zone autour du lanceur et pose un glyphe au sol sous le lanceur pendant 2 tours, qui augmente de 2 les PM des alliés qui marchent dessus pendant 1 tour. Le bonus PM ne touche pas le lanceur.', 0x08ada803, '1', 'Agressive'),
(20622, 'Aspiration', '', 0x08aea803089aa903, '1', 'Agressive'),
(20623, 'Venthylo', 'Occasionne des dommages Air aux ennemis, les alliés alignés à 2 cases derrière l\'ennemi gagnent 150 dommages de poussée pendant 1 tour. (non cumulable)', 0x08b0a803, '1', 'Agressive'),
(20624, 'Venthylo', '', 0x08b3a803, '1', 'Agressive'),
(20625, 'Boucharde', 'Occasionne des dommages Terre aux ennemis. Les alliés alignés à 2 cases derrière l\'ennemi gagnent 100 de puissance pour 1 tour.', 0x08b4a803, '1', 'Agressive'),
(20626, 'Boucharde', '', 0x08b5a803, '1', 'Agressive'),
(20627, 'Bauge', 'Pose un piège monocible. Occasionne des dommages Terre et pose un glyphe en zone qui dure un tour. Le glyphe retire 2 PM esquivable et 30 de tacle aux ennemis qui marchent dedans.', 0x08b6a803, '1', 'Mark'),
(20628, 'Bauge', '', 0x08b7a803, '1', 'Agressive'),
(20629, 'Bauge', '', 0x08b8a803, '1', 'Agressive'),
(20630, 'Poussée Tellurique', 'Occasionne des dommages Terre, repousse de 3 cases, puis téléporte la cible à sa position précédente. ', 0x08b9a803, '1', 'Agressive'),
(20631, 'Requiem', '', 0x08baa803, '1', 'Buff'),
(20632, 'Cuisson lente', 'Applique un poison Feu de fin de tour pendant 2 tours.', 0x08bba803, '1', 'Agressive'),
(20633, 'Réchauffement Chaotique', 'Occasionne des dommages Feu et réduit les résistances de poussée des ennemis de 100 pendant 1 tour en zone. ', 0x08bca803, '1', 'Agressive'),
(20634, 'Ann Eau', 'Occasionne des dommages Eau aux ennemis de 2 à 3 PO autour du lanceur, les alliés dans la zone gagnent 150 de chance pendant 1 tour.', 0x08bea803, '1', 'Agressive'),
(20635, 'Eau vive', 'Occasionne des dommages Eau aux ennemis et leur retire 2 PA esquivable, pendant 1 tour. Si la cible est un allié, il gagne 20 de fuite et 1 PO pendant 1 tour.', 0x08c0a803, '1', 'Agressive'),
(20636, 'Capillarité', 'Le lanceur occasionne des dommages Eau aux ennemis puis les réappliquent à la fin de son tour. Les dommages réappliqués sont augmentés pour chaque ennemi ciblé.\nSi la cible est un allié elle gagne 100 de puissance pendant 1 tour, elle est soignée à la fin du tour du lanceur. Les soins sont augmentés pour chaque allié ciblé. ', 0x08c1a803, '1', 'Agressive'),
(20637, 'Capillarité', '', 0x08c2a80308c3a80308c4a803, '1', 'Agressive'),
(20638, 'Bouclier statique', 'Applique l\'état pesanteur, lourd, indéplaçable, 25 de tacle et une réduction des dommages, de mêlée de 12% et à distance de 8% à la cible pendant 2 tours. Les effets sont retirés si la cible utilise un PM pour se déplacer.', 0x08c6a803, '1', 'Buff'),
(20639, 'Bouclier statique', '', 0x08c7a803, '1', 'Debuff'),
(20640, 'Lien liant', 'L\'allié ciblé et le lanceur partagent les dommages reçut pendant 2 tours. En contre-partie ils perdent 1 PA et 1 PM pendant toute la durée des effets. ', 0x08c8a803, '1', 'Debuff'),
(20641, 'Garde-fou', 'Applique 200% du niveau du lanceur en bouclier au lanceur pendant 1 tour et pose un glyphe aura en zone boomerang 2 qui repousse les ennemis de 2 cases et leur retire 1 PM (esquivable) lorsqu\'ils marchent dessus. ', 0x08caa803, '1', 'Agressive'),
(20642, 'Garde-fou', '', 0x08cba803, '1', 'Agressive'),
(20643, 'Mousquet', '', 0x08cca803, '1', 'Agressive'),
(20644, 'Flèche croisée', 'Occasionne des dommages dans le meilleur élément aux premières cibles alignées avec le lanceur et les attire d\'une case. ', 0x08cda803, '1', 'Agressive'),
(20645, 'Saute-Bouftou', '', 0x08cea80308cfa803, '1', 'Agressive'),
(20646, 'Couardise', 'Augmente la fuite de 10 et soigne la cible de 5% de ses PDV', 0x08d0a803, '1', 'Healing'),
(20647, 'Fatigue Hasardeuse', 'Occasionne des dommages dans le meilleur élément puis fait un effet aléatoire pendant 1 tour sur la cible : \n+10% de dommages finaux subis\n+20% de dommages mêlée subis\n+20% de dommages distance subis\n-150 résistances critiques\n-200 résistances aux dommages de poussée', 0x08d1a803, '1', 'Debuff'),
(20648, 'Frappe Récursive', 'Occasionne des dommages dans le meilleur élément et repousse la cible de 5 cases. Si la cible termine son tour au contact d\'un allié, il la téléporte symétriquement et lui réapplique l\'effet du sort. La cible ne peut être repoussée que 3 fois maximum.', 0x08d2a803, '1', 'Agressive'),
(20649, 'Frappe récursive', '', 0x08d3a80308d4a80308d5a803, '1', 'Agressive'),
(20650, 'Prise d\'appui', 'Occasionne des dommages dans le meilleur élément, repousse le lanceur par rapport à la cible et augmente de 1 les PM du lanceur pour le tour en cours.', 0x08d6a803, '1', 'Agressive'),
(20651, 'Piège Confusant', 'Pose un piège sur la cellule ciblée. Le lanceur se téléporte symétriquement par rapport au point d\'impact et inflige des dommages aux ennemis dans le meilleur élément en zone après la téléportation. L\'ennemi qui déclenche le piège subit des dommages dans le meilleur élément et échange de place avec le lanceur. Ce dernier occasionne des dommages aux ennemis qui sont à 2 cases ou moins de lui.', 0x08d7a803, '1', 'Agressive'),
(20652, 'Piège confusant', '', 0x08d8a80308d9a803, '1', 'Agressive'),
(20653, 'Guérignon', 'Occasionne des dommages dans le dernier élément d\'attaque aux ennemis. Les alliés derrière l\'ennemi de 1 à 4 PO sont soignés de 14% de leurs PV.', 0x08daa803, '1', 'Agressive'),
(20655, 'Shrapnel', '', 0x08dca803, '1', 'None'),
(20656, 'Saute-Bouftou', 'Téléporte le lanceur symétriquement par rapport à la cible, puis téléporte la cible symétriquement par rapport au lanceur. ', 0x08dda803, '1', 'Agressive'),
(20657, 'Flèche croisée', 'Occasionne des dommages dans le meilleur élément aux premières cibles alignées avec le lanceur et les attirent d\'une case. ', 0x08dea803, '1', 'Agressive'),
(20658, 'Yaularakne', 'Petite Arakne qui inflige des dommages Neutre au corps à corps.\n\n<font color=\"#6D6D6D\">\n• Limité à 3 invocations par équipe.\n• Limité à 1 exemplaire de chaque invocation par équipe.\n• Compatible avec le sort Maîtrise des Invocations.\n• Le délai de relance commence à la mort de l\'invocation.\n</font>', 0x08dfa803, '1', 'Summon'),
