(21958, 'Chanceux', 'Les Altérés des Ecaflips ont plus de chances d\'effectuer un coup critique dès leur invocation.\n\nLorsqu\'un Altéré d\'un Ecaflip effectue un coup critique, sa Puissance augmente.', 0x08bbbd03, '0', 'Agressive'),
(21959, 'Veinardise', 'Applique aléatoirement un effet sur les Altérés alliés en zone :\n• Augmente la Puissance.\n• Augmente les PA.\n• Augmente les PM.\n• Applique des points de bouclier.', 0x08bcbd0308bdbd0308bebd0308bfbd0308c0bd03, '1', 'Buff'),
(21960, 'Chance d\'Ecaflip', 'Réduit les dommages subis par un Altéré allié immédiatement, mais augmente ces derniers et les PM au tour suivant.', 0x08c2bd0308c3bd0308c4bd03, '1', 'Buff'),
(21961, 'Bond du Félin', 'Téléporte le lanceur sur la case ciblée.\n\nSur un allié : augmente ses PM.\nN\'affecte pas le lanceur.', 0x08c6bd0308c7bd0308c8bd03, '1', 'Teleport'),
