(22019, 'Le serment de l\'ambre', 'Pour déjouer l\'embuscade des Malters, trouvez-les et associez-les deux par deux. Pour former une paire, il vous faut trouver deux Malters du même type. Commencez par sonder leur présence autour de vous grâce au sort Prescience de Terrakourial. Révélez-les ensuite à l\'aide de Perception ambrée. \n\nMéfiez-vous du Malter démoniaque et des Malters révélés, ils vous attaqueront si vous terminez votre tour en ligne de vue avec eux ! ', 0x08aabe03, '1', 'None'),
(22021, 'Moskitoxique', '', 0x08aebe03, '1', 'None'),
(22027, 'Chamrak', '', 0x08b8be0308b9be03, '1', 'None'),
(22028, 'Chamrak', '', 0x08babe0308cbc20308ccc20308cdc203089ec303089fc303, '1', 'Agressive'),
(22029, 'Flèche de Dispersion', 'Pousse les cibles depuis le centre de la zone.', 0x08bbbe0308bcbe0308bdbe03, '1', 'Agressive'),
(22031, 'Flèche à Retardement', 'Applique l\'état Chargé sur un Altéré allié :\n• Réduit ses dommages à distance et lui retire des PM non esquivables immédiatement.\n• Les augmente au tour suivant.\n\nLes effets ne peuvent pas être appliqués sur un Altéré étant déjà dans l\'état Chargé et ne peuvent pas être désenvoûtés.', 0x08c1be0308c2be0308c3be03, '1', 'Debuff'),
(22032, 'Neutral', 'Désactive un portail allié.', 0x08c7be0308c8be0308c9be03, '1', 'None'),
(22033, 'Portail', 'Pose un portail.\n\nLorsque plusieurs portails sont actifs, ils permettent de se téléporter ou de projeter des sorts.\nLes dommages et soins des sorts projetés sont augmentés par les portails.\n\nLes ennemis (hors invocations) ne peuvent traverser un portail au premier tour de jeu.', 0x08cabe0308e1d50308e2d503, '1', 'None'),
(22034, 'Téléportail', 'Les Altérés des Eliotropes gagnent de la Puissance et des PA (cumulable 1 fois) et sont soignés lorsqu\'ils traversent un portail.', 0x08cebe0308d1be0308d7be0308d8be0308d9be03, '0', 'Agressive'),
(22035, 'Téléportail', '', 0x08d2be0308d3be0308d4be0308d5be0308d6be03, '1', 'Agressive'),
(22036, 'Jouvence', 'Les Altérés des Eniripsas sont soignés au début de chacun de leur tour.\n\nLorsqu\'un Altéré d\'un Eniripsa subit des dommages, il reçoit du soin supplémentaire au début de son prochain tour.', 0x08dfbe0308e0be0308e8be0308e9be0308eabe0308ebbe03, '0', 'Agressive'),
(22037, 'Jouvence', '', 0x08e1be0308e3be0308e4be0308e5be0308e6be0308e7be03, '1', 'Agressive'),
(22038, 'Mot de Frayeur', 'Pousse la cible.\n\nSi la cible est un ennemi, lui applique également l\'état Mot de Frayeur :\n• Réduit la durée de ses effets.\n• L\'érode.\nCes effets ne sont pas appliqués si l\'ennemi ciblé est déjà dans l\'état Mot de Frayeur.', 0x08f2be0308febe0308ffbe03, '1', 'Debuff'),
(22039, 'Mot Stimulant', 'Applique l\'état Stimulé sur un Altéré allié :\n• Augmente ses PA, sa Puissance et ses soins reçus.\n\nLes effets ne peuvent pas être appliqués sur un Altéré étant déjà dans l\'état Stimulé.', 0x08f5be0308f8be0308f9be0308fabe03, '1', 'Buff'),
(22040, 'Mot Fulminant', 'Soigne un Altéré allié.\nRebondit sur l\'Altéré allié le plus proche dans une zone de 2 cases.', 0x08fbbe0308b0d10308b1d103, '1', 'Agressive'),
(22041, 'Mot Fulminant', '', 0x08fcbe0308fdbe0308b2d10308b3d10308b4d10308b5d103, '0', 'Agressive'),
(22042, 'Protecteur', 'Les Altérés des Fécas posent un glyphe-aura à la fin de leur tour qui applique des points de bouclier sur les alliés et réduit les dommages finaux des ennemis dans une zone d\'une case en carré (cumulable 1 fois).', 0x0880bf03, '0', 'Agressive'),
(22043, 'Jouvence', '', 0x0884bf0308a4ce0308a5ce0308a6ce0308a7ce0308a8ce0308a9ce0308aace0308abce0308acce0308adce0308aece03, '1', 'Agressive'),
(22044, 'Téléportail', '', 0x0890bf030891bf030892bf030893bf030894bf03, '1', 'Agressive'),
(22045, 'Téléportail', '', 0x089abf03089bbf03089cbf03089dbf03089ebf03, '1', 'Buff'),
(22046, 'Distant', '', 0x08a2bf0308a3bf03, '1', 'Buff'),
(22047, 'Téléportail', '', 0x08a7bf0308a8bf0308a9bf0308aabf0308abbf03, '1', 'Agressive'),
(22048, 'Bouclier Féca', 'Applique l\'état Protégé sur l\'allié ciblé :\n• Réduit les dommages subis par la cible.\n• S\'il subit des dommages ennemis : augmente ses dommages finaux (cumulable 3 fois).\n\nLes effets ne peuvent pas être appliqués sur un allié étant déjà dans l\'état Protégé.', 0x08aebf0308b0bf0308b1bf03, '1', 'Agressive'),
(22049, 'Téléprotection', 'Téléporte le lanceur sur la case ciblée et réduit les dommages reçus par les alliés en zone.', 0x08b2bf0308b5bf0308b6bf03, '1', 'Teleport'),
(22050, 'Barristion', 'Immédiatement :\n• Rend un Altéré allié Invulnérable aux dommages en mêlée.\n• Pendant 1 tour, s\'il subit des dommages à distance, augmente ses PM.\n\nAu tour suivant : \n• Rend l\'Altéré Invulnérable aux dommages à distance.\n• Pendant 1 tour, s\'il subit des dommages en mêlée, augmente sa Puissance.', 0x08b7bf0308f4bf0308f5bf03, '1', 'Buff'),
(22051, 'Protecteur', '', 0x08bbbf0308bcbf03, '1', 'Agressive'),
(22053, 'Chanceux', '', 0x08c5bf0308c6bf0308c7bf0308c8bf03, '1', 'Buff'),
(22054, 'Distant', '', 0x08c9bf0308cabf030888c303, '1', 'Buff'),
(22055, 'Maîtrise des Éléments', 'Les Altérés des Huppermages appliquent à leur invocateur et à eux-mêmes un état selon l\'élément des dommages qu\'ils tentent d\'occasionner.\nLes états élémentaires durent 2 tours, et ne se cumulent pas sur les Altérés.\n\nLorsque deux états élémentaires différents sont appliqués à un Huppermage, il les consomme pour appliquer des effets sur tous ses Altérés selon la combinaison :\n• Terre & Feu : augmente le Tacle.\n• Feu & Eau : augmente les résistances.\n• Feu & Air : augmente les chances d\'effectuer un coup critique.\n• Eau & Terre : applique des points de bouclier.\n• Eau & Air : augmente la Fuite.\n• Air & Terre : augmente les Dommages Poussée.\n\nChaque effet se cumule une fois.', 0x08cbbf030897c0030898c0030899c003089ac003089bc003, '0', 'Agressive'),
(22056, 'Maîtrise des Éléments', '', 0x08ccbf0308cdbf03089cc003089dc003089ec003089fc00308a0c00308a1c00308a2c00308a3c00308a4c00308a5c003, '1', 'Agressive'),
(22057, 'Maîtrise des Éléments', '', 0x08cebf030880cd030881cd030882cd030883cd030884cd03, '1', 'Agressive'),
(22058, 'Maîtrise des Éléments', '', 0x08d0bf0308d1bf0308d2bf0308d3bf03, '1', 'Debuff'),
(22059, 'Tallurisme', '', 0x08d4bf0308d5bf03, '1', 'Summon'),
(22060, 'Rassemblement', '', 0x08d7bf03, '0', 'None'),
(22061, 'Épéiste', 'Les Altérés des Iops gagnent des dommages en mêlée dès leur invocation.\n\nLorsqu\'un Altéré d\'un Iop débute son tour en n\'ayant aucun ennemi à son contact, ses PM augmentent. Sinon, il gagne des points de bouclier.\n\nLorsqu\'il occasionne des dommages en mêlée, ses dommages en mêlée augmentent également (cumulable 5 fois).', 0x08d8bf03, '0', 'Agressive'),
(22062, 'Épéiste', '', 0x08d9bf0308dabf03, '1', 'Agressive'),
(22063, 'Épéiste', '', 0x08dbbf0308dcbf03, '1', 'Buff'),
(22064, 'Épéiste', '', 0x08ddbf0308debf0308dfbf0308e0bf03, '1', 'Buff'),
(22065, 'Intimidation', 'Pousse la cible.\nSi la cible est un allié, augmente son Tacle.\nSi la cible est un ennemi, l\'érode.', 0x08e1bf0308e4bf0308e5bf03, '1', 'Agressive'),
(22066, 'Parade du Duelliste', 'Pendant 1 tour, si la cible subit des dommages, lui applique des points de bouclier (cumulable 3 fois).\n\nLe déclenchement ne peut pas être désenvoûté.', 0x08e6bf0308eebf0308efbf03, '1', 'Agressive'),
(22067, 'Parade du Duelliste', '', 0x08e7bf0308eabf0308ebbf03, '1', 'Agressive'),
(22068, 'Parade du Duelliste', '', 0x08e9bf0308ecbf0308edbf03, '1', 'Buff'),
(22069, 'Poutch', 'Réduit les résistances en mêlée de l\'ennemi ciblé.', 0x08f0bf0308f1bf0308f2bf03, '1', 'Debuff'),
(22070, 'Barristion', '', 0x08f3bf03, '1', 'None'),
(22071, 'Bouclier Féca', '', 0x08f6bf0308f7bf0308f8bf03, '1', 'Buff'),
(22072, 'Proie', 'Applique l\'état Proie sur l\'ennemi ciblé.\n\nIl ne peut y avoir qu\'un ennemi dans l\'état Proie.\nRelancer le sort sur la Proie ou sur une autre cible retire les effets du sort de la cible initiale.', 0x08f9bf03, '1', 'Debuff'),
(22073, 'Meute', 'Les Altérés des Ouginaks rendent plus vulnérable leur Proie pour chaque attaque qu\'ils lui occasionnent. \n\nLorsque la Proie est attaquée, elle subit plus de dommages et son attaquant est soigné d\'une partie des dommages qu\'il lui a occasionnés.', 0x08fabf03, '0', 'Agressive'),
(22074, 'Meute', '', 0x08fdbf0308febf030880c003, '1', 'None'),
