(22094, 'Nomade', '', 0x08f7c003, '1', 'Debuff'),
(22096, 'Maladresse', 'Retire des PM.', 0x08f9c00308fac00308fbc003, '1', 'Debuff'),
(22097, 'Chance', 'Augmente la Fuite d\'un Altéré allié.\nAugmente sa Puissance au tour suivant.', 0x08fcc0030882c1030883c103, '1', 'Buff'),
(22098, 'Accélération', 'Applique l\'état Accéléré et augmente les PM.\n\nLes effets ne peuvent pas être appliqués sur une cible étant déjà dans l\'état Accéléré.', 0x08ffc0030885c1030886c103, '1', 'Buff'),
(22100, 'Exaltation', '', 0x0887c1030888c1030889c103088ac103088bc103088cc103, '1', 'Healing'),
