(22105, 'Proie', 'Applique l\'état Proie sur l\'ennemi ciblé.\n\nIl ne peut y avoir qu\'un ennemi dans l\'état Proie.\nRelancer le sort sur la Proie ou sur une autre cible retire les effets du sort de la cible initiale.', 0x08b3c10308c1c103, '1', 'Agressive'),
(22106, 'Proie', 'Applique l\'état Proie sur l\'ennemi ciblé.\n\nIl ne peut y avoir qu\'un ennemi dans l\'état Proie.\nRelancer le sort sur la Proie ou sur une autre cible retire les effets du sort de la cible initiale.', 0x08b4c103, '1', 'Agressive'),
(22107, 'Proie', 'La cible devient la Proie.\nIl ne peut y avoir qu\'une seule Proie à la fois, replacer la Proie sur une autre cible retire la dernière placée précédemment.', 0x08b6c103, '1', 'Agressive'),
(22108, 'Proie', 'Applique l\'état Proie sur l\'ennemi ciblé.\n\nIl ne peut y avoir qu\'un ennemi dans l\'état Proie.\nRelancer le sort sur la Proie ou sur une autre cible retire les effets du sort de la cible initiale.', 0x08b7c10308b8c10308b9c10308bac10308bbc10308bcc10308bdc10308bec10308bfc10308c0c103, '1', 'Buff'),
(22109, 'Flair', 'Sur un ennemi dans l\'état Proie : érode la cible, échange de position avec elle et augmente les PM du lanceur.', 0x08c3c103, '1', 'Agressive'),
(22110, 'Appel de la Meute', 'Sur un ennemi dans l\'état Proie : attire tous les Altérés du lanceur vers la cible.', 0x08c5c103, '1', 'Agressive'),
(22111, 'Rogne', 'Applique l\'état Rogné sur un Altéré allié :\n• Augmente ses Dommages Poussée, sa Puissance et son Tacle.\n• Pendant 2 tours, s\'il subit des dommages à distance, augmente ces mêmes caractéristiques.\n\nLes effets ne peuvent pas être appliqués sur un Altéré étant déjà dans l\'état Rogné.', 0x08c6c10308cdc10308cec10308cfc103, '1', 'Buff'),
(22112, 'Appel de la Meute', 'Sur un ennemi dans l\'état Proie : attire tous les Altérés du lanceur vers la cible.', 0x08c7c103, '1', 'Agressive'),
(22113, 'Flair', 'Sur un ennemi dans l\'état Proie : érode la cible, échange de position avec elle et augmente les PM du lanceur.', 0x08c8c103, '1', 'Debuff'),
(22114, 'Rogne', '', 0x08c9c103, '0', 'None'),
(22115, 'Fouet', 'Attire les Altérés alliés vers le centre de la zone.\nSi la case est occupée, téléporte les Altérés alliés symétriquement par rapport à la cible.', 0x08d0c103, '1', 'Agressive'),
(22116, 'Piqûre Motivante', 'Applique l\'état Piqué Motivé sur un Altéré allié :\n• Augmente ses dommages finaux, sa Vitalité, ses PA, ses PM et sa taille.\n\nLes effets ne peuvent pas être appliqués sur un Altéré étant déjà dans l\'état Piqué Motivé.', 0x08d2c10308d8c10308d9c103, '1', 'Buff'),
(22118, 'Harmonie Animale', 'Partage les dommages entre les Altérés alliés en zone.', 0x08dec103, '1', 'Buff'),
(22121, 'Fouet', '', 0x08dfc103, '1', 'Agressive'),
(22122, 'Laisse Spirituelle', 'Les Altérés des Osamodas peuvent être ressuscités.\nAu début du prochain tour d\'un Osamodas, son dernier Altéré mort est ressuscité sur la première case disponible autour de lui.\nL\'Altéré est ressuscité avec la moitié de ses points de vie et moins de résistances.\n\nCet effet est appliqué une fois pour tout le combat.', 0x08e1c103, '0', 'Agressive'),
(22123, 'Laisse Spirituelle', '', 0x08e2c10308e3c103, '1', 'Agressive'),
(22124, 'Laisse Spirituelle', '', 0x08e4c10308e6c10308e7c10308bbd203, '1', 'Debuff'),
(22125, 'Laisse Spirituelle', '', 0x08ecc103, '1', 'None'),
(22171, 'Alcoolique', '', 0x08a8c20308d3c60308d4c60308d5c60308d6c603, '1', 'Buff'),
(22173, 'Alcoolique', '', 0x08abc20308cfc60308d0c60308d1c60308d2c603, '1', 'Buff'),
(22185, 'Souillure', 'Applique l\'état Souillé sur la cible :\n• Réduit la durée de ses effets.\n• Si la cible est un ennemi, lui retire de la Puissance.\n• Si la cible est un Altéré allié Ivre, augmente ses résistances.\n• Si la cible est un Altéré allié Sobre, augmente sa Puissance.\n\nLes effets ne peuvent pas être appliqués sur une cible étant déjà dans l\'état Souillé.', 0x08ddc2030892c3030893c3030894c3030895c303, '1', 'Debuff'),
(22186, 'Stabilisation', 'Applique l\'état Enraciné sur la cible et augmente son Esquive PM.\n\nSi la cible est un Altéré allié Ivre, augmente également ses PA et son Esquive PA.\nSi la cible est un Altéré allié Sobre, augmente également ses PM.', 0x08e0c20308ebc20308ecc203, '1', 'Buff'),
(22197, 'Bombe', 'Les Altérés des Roublards se transforment en Bombe à la fin de leur tour jusqu\'au début de leur prochain tour.\nLes Bombes Altérées gagnent un Combo à partir de leur deuxième tour de jeu si elles n\'ont pas été activées.', 0x088fc303, '0', 'Agressive'),
(22198, 'Bombe', '', 0x0890c3030891c303, '1', 'Agressive'),
(22199, 'Bombe', '', 0x0896c303, '1', 'Agressive'),
(22200, 'Bombe', '', 0x0898c303, '1', 'Buff'),
(22201, 'Bombe', '', 0x0899c30308c6d203, '1', 'None'),
(22202, 'Explosion', 'Sur une Bombe Altérée alliée, déclenche son explosion :\n• Occasionne des dommages dans son meilleur élément d\'attaque aux ennemis dans une zone de 2 cases autour de lui.\n• Déclenche l\'explosion des Bombes Altérées alliées dans sa zone d\'explosion.\n\nLes dommages sont plus importants selon le Combo de l\'Altéré.\nLes Altérés explosés redeviennent eux-mêmes.', 0x089ac30308a6c30308a7c303, '1', 'Agressive'),
(22203, 'Explosoin', 'Sur une Bombe Altérée alliée, déclenche son explosion :\n• Soigne les alliés et augmente la Puissance des Altérés alliés dans une zone de 2 cases.\n• Déclenche l\'explosion des Bombes Altérées alliés dans sa zone d\'explosion.\n\nLes effets sont plus importants selon le Combo de l\'Altéré.\nLes Altérés explosés redeviennent eux-mêmes.', 0x089dc30308adc30308aec303, '1', 'Agressive'),
(22204, 'Botte', 'Applique des points de bouclier sur les Bombes Altérées et pousse les cibles depuis le centre de la zone.\nLa poussée est plus importante sur les Bombes Altérées alliées.\nN\'affecte pas le lanceur.', 0x08a0c30308b9c30308bac303, '1', 'Agressive'),
(22205, 'Croisement', 'Attire les Bombes Altérées alliées dans la zone d\'effet vers la case ciblée.', 0x08a3c303, '1', 'Agressive'),
(22206, 'Explosion', '', 0x08a5c30308c3c30308c4c303, '1', 'Agressive'),
(22207, 'Explosoin', '', 0x08aac30308bec30308bfc303, '1', 'Healing'),
(22209, 'Explosion', '', 0x08b3c30308b4c30308b5c303, '1', 'Agressive'),
(22210, 'Explosoin', '', 0x08b6c30308b7c30308b8c303, '1', 'Agressive'),
(22211, 'Bombe', '', 0x08bbc303, '1', 'None'),
(22212, 'Carafon', '', 0x08c0c303, '0', 'Agressive'),
(22213, 'Carafon', 'Invoque l\'Altéré Carafon.\n\nVos caractéristiques sont transmises à cet Altéré.', 0x08c6c303, '1', 'Summon'),
