(22215, 'Bastortue', 'Invoque l\'Altéré Bastortue.\n\nVos caractéristiques sont transmises à cet Altéré.', 0x08c8c303, '1', 'Summon'),
(22216, 'Châtiment', 'Les Altérés des Sacrieurs gagnent de la Puissance dès qu\'ils subissent des dommages ennemis (cumulable 5 fois).\n\nLorsqu\'un Altéré d\'un Sacrieur subit des dommages à distance : augmente ses PM et son Esquive PM au début de son prochain tour.\nS\'il subit des dommages en mêlée : augmente ses PA et sa Vitalité au début de son prochain tour.\n\nChacun de ces effets sont cumulables 3 fois et seule la Vitalité peut être désenvoûtée.', 0x08c9c30308cdc30308cec30308cfc30308d0c303, '0', 'Agressive'),
(22217, 'Châtiment', '', 0x08cac30308cbc30308d3c30308d4c30308d5c30308d6c30308d7c30308d8c30308d9c30308dac303, '1', 'Agressive'),
