(22278, 'Piège Scélérat', 'Pose un piège mono-cellule qui attire les entités vers son centre et retire de la Fuite aux ennemis dans une zone de 3 cases en croix.', 0x08dbc40308eac40308ebc403, '1', 'Mark'),
(22279, 'Peur', 'Pousse la cible jusqu\'à la case ciblée.', 0x08ddc40308e4c40308e5c403, '1', 'None'),
(22280, 'Brume', 'Pose un glyphe-aura qui rend les alliés invisibles et applique l\'état Pesanteur sur les ennemis en zone.', 0x08e0c40308e3c403, '1', 'Mark'),
(22281, 'Insaisissable', 'Les Altérés des Srams gagnent des dommages finaux lorsqu\'ils sont invisibles.\n\nLorsqu\'un Altéré d\'un Sram devient visible, il devient Intaclable et ses PM augmentent.\n\nLes effets se cumulent 1 fois.', 0x08ecc403, '0', 'Agressive'),
(22282, 'Brume', '', 0x08e2c403, '0', 'Buff'),
