(22285, 'Insaisissable', '', 0x08f2c40308f3c403, '1', 'Debuff'),
(22287, 'Pistoufu', '', 0x08f8c403, '0', 'Agressive'),
(22288, 'Pistoufu', 'Invoque l\'Altéré Pistoufu.\n\nVos caractéristiques sont transmises à cet Altéré.', 0x08f9c403, '1', 'Summon'),
(22289, 'Scaphandre', 'Augmente les Dommages et les Dommages Poussée des Altérés alliés en zone.\nLes effets sont plus importants selon le niveau d\'Évolution des Altérés.\n\nConsomme un niveau d\'Évolution.', 0x08fac4030892c5030893c503, '1', 'Buff'),
(22290, 'Boufondu', '', 0x08fbc403, '0', 'Agressive'),
(22291, 'Secourisme', 'Soigne un Altéré allié.\nLes soins sont plus importants selon le niveau d\'Évolution de l\'Altéré.\n\nConsomme un niveau d\'Évolution.', 0x08fcc4030899c503089ac503, '1', 'Healing'),
(22292, 'Boufondu', 'Invoque l\'Altéré Boufondu.\n\nVos caractéristiques sont transmises à cet Altéré.', 0x08ffc403, '1', 'Summon'),
(22293, 'Tourellification', 'Applique l\'état Tourellifié sur un Altéré Steamer allié sous Évolution III :\n• Le transforme en Tourelle.\n• Lui applique des points de bouclier.\n• L\'immobilise.\n• Augmente sa Portée.\n• Désactive la ligne de vue de tous ses sorts.\n• Consomme tous les niveaux d\'Évolution en sortie de Tourellification.\n\nLes effets ne peuvent pas être appliqués sur un Altéré étant déjà dans l\'état Tourellifié.', 0x0885c503088dc503088ec503088fc5030890c503, '1', 'Agressive'),
(22294, 'Sporganik', '', 0x0880c503, '0', 'Agressive'),
(22295, 'Évolution', 'Les Altérés des Steamers gagnent un niveau d\'Évolution à partir de leur deuxième tour de jeu.\nCes niveaux d\'Évolution augmentent la Puissance des Altérés.', 0x0894c503089ec503089fc50308a0c50308a1c503, '0', 'Agressive'),
(22296, 'Sporganik', 'Invoque l\'Altéré Sporganik.\n\nVos caractéristiques sont transmises à cet Altéré.', 0x0881c503, '1', 'Summon'),
(22297, 'Boxelet', '', 0x0882c503, '0', 'Agressive'),
