(22309, 'Évolution', '', 0x089cc503, '1', 'None'),
(22310, 'Évolution', '', 0x089dc50308a2c50308a5c50308a6c50308a7c50308a8c50308a9c50308aac50308abc50308acc503, '1', 'Agressive'),
(22311, 'Évolution', '', 0x08a3c50308b3c50308b4c50308b5c50308b6c503, '1', 'Agressive'),
(22312, 'Liberté des Invocations', 'Si le sort est sélectionné dans le livre de sorts, les invocations maîtrisables du lanceur sont par défaut libres de jouer par elles-mêmes.\n\nLancer le sort permet de reprendre le contrôle de ces invocations jusqu\'au prochain lancer du sort. Affecte également les prochaines invocations.\nLe coût en PA du sort est remboursé.', 0x08adc503, '1', 'Agressive'),
(22313, 'Évolution', '', 0x08aec50308afc50308b0c50308b1c50308b2c503, '1', 'Buff'),
(22314, 'Tonification', 'Applique l\'état Tonifié sur un Altéré Steamer allié :\n• Augmente son niveau d\'Évolution.\n• Empêche la consommation de son Évolution (hors Tourellification).\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08b7c503, '1', 'Agressive'),
(22315, 'Boufilou', '', 0x08b8c503, '0', 'Agressive'),
(22316, 'Boufilou', 'Invoque l\'Altéré Boufilou.\n\nVos caractéristiques sont transmises à cet Altéré.', 0x08b9c503, '1', 'Summon'),
(22317, 'Crapostiche', '', 0x08bac503, '0', 'Agressive'),
(22318, 'Flou', 'Si la cible est un ennemi :\n• Lui retire des PA immédiatement.\n• Augmente les PA des alliés en zone au tour suivant.', 0x08bbc50308afce0308b0ce0308b1ce0308b2ce0308b3ce03, '1', 'Debuff'),
(22319, 'Contre', 'Pendant 2 tours, si les alliés dans la zone d\'effet subissent des dommages en mêlée :\n• Renvoie une partie des dommages subis aux ennemis dans une zone de 2 cases autour d\'eux.\n• Augmente leurs PA (cumulable 3 fois).', 0x08bec50308c8c50308c9c503, '1', 'Agressive'),
(22320, 'Fuite', 'Augmente la Fuite de l\'allié ciblé.\nAu début du prochain tour du lanceur, téléporte la cible sur sa position précédente.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08c1c50308d7c50308d8c503, '1', 'Buff'),
(22321, 'Crapostiche', 'Invoque l\'Altéré Crapostiche.\n\nVos caractéristiques sont transmises à cet Altéré.', 0x08c3c503, '1', 'Summon'),
