(22329, 'Scarossé', '', 0x08d2c503, '0', 'Agressive'),
(22330, 'Scarossé', 'Invoque l\'Altéré Scarossé.\n\nVos caractéristiques sont transmises à cet Altéré.', 0x08d3c503, '1', 'Summon'),
(22331, 'Fuite', '', 0x08d6c503, '1', 'Debuff'),
(22332, 'Oracle', 'Les Altérés des Xélors gagnent des PA et du Retrait PA dès leur invocation.\n\nLorsqu\'un Altéré d\'un Xélor retire des PA :\n• Ses PA augmentent.\n• Sa Puissance augmente pour son prochain tour.\nLes effets se cumulent 5 fois.', 0x08d9c50308dcc50308ddc50308dec503, '0', 'Agressive'),
