(22342, 'Zobal Masqué', 'Les Altérés des Zobals gagnent des bonus selon la combinaison de Masques appliqués :\n• Intrépide & Pleutre : augmente leurs résistances et les soigne.\n• Intrépide & Psychopathe : augmente leurs dommages en mêlée.\n• Pleutre & Psychopathe : augmente leurs dommages à distance.', 0x08f4c503, '0', 'Agressive'),
(22343, 'Masque de l\'Intrépide', 'Le lanceur revêtit le Masque de l\'Intrépide :\n• Applique des points de bouclier sur le lanceur et ses Altérés et augmente leur Tacle en zone.', 0x08f5c5030883c6030884c603, '1', 'Debuff'),
(22344, 'Masque du Psychopathe', 'Le lanceur revêtit le Masque du Psychopathe :\n• Augmente la Puissance de ses Altérés en zone.', 0x08f6c5030887c6030888c603, '1', 'Debuff'),
(22345, 'Masque du Pleutre', 'Le lanceur revêtit le Masque du Pleutre :\n• Augmente les PM et la Fuite du lanceur et de ses Altérés en zone.', 0x08fac5030885c6030886c603, '1', 'Debuff'),
(22346, 'Débandade', 'Téléporte le lanceur sur la case ciblée et augmente ses PM.', 0x08fcc503, '1', 'Teleport'),
(22347, 'Gestion des masques', '', 0x08ffc5030880c6030881c6030882c603, '1', 'Buff'),
