(22372, 'Couronne d\'Épines', 'Pendant 1 tour, renvoie 50% des dommages subis en mêlée aux ennemis dans une zone de 2 cases autour de l\'allié ciblé.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08aac603, '1', 'Agressive');
INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(22373, 'Chamrak', 'Porte et jette la cible marquée par le sort Karcham.\n\n• Si la cible est un Altéré Ivre, lui applique des points de bouclier et attire les ennemis vers le point d\'impact dans une zone de 3 cases en croix.\n• Si la cible est un Altéré Sobre, la soigne et pousse les ennemis adjacents depuis le point d\'impact.\n• Si la cible est un ennemi, augmente ses dommages subis.', 0x08abc603, '1', 'Agressive'),
(22376, 'Karcham', '', 0x08afc603, '1', 'Debuff'),
(22377, 'Vigicoffre', '', 0x08b0c603, '1', 'Summon'),
(22378, 'Karcham', '', 0x08b1c603, '1', 'Debuff'),
(22379, 'Vigicoffre', '', 0x08b2c603, '1', 'Summon'),
(22380, 'Vigicoffre', '', 0x08b3c603, '1', 'Summon'),
(22381, 'Vigicoffre', '', 0x08b4c603, '1', 'Summon'),
(22382, 'Vigicoffre', '', 0x08b5c60308b6c60308b7c60308b8c603, '1', 'Agressive'),
(22383, 'Karcham', 'Applique l\'état Porteur sur le lanceur :\n• Empêche l\'utilisation de tous ses sorts.\n• L\'immobilise.\n• Marque la cible.\n• Autorise l\'utilisation du sort Chamrak.\n\nLes effets se dissipent naturellement à la fin de son tour.', 0x08b9c603, '1', 'Agressive'),
(22384, 'Alcoolique', 'Les Altérés des Pandawas sont Ivres les tours pairs ou Sobres les tours impairs.\n\nLorsqu\'un Altéré d\'un Pandawa est Ivre :\n• Ses PA et son Tacle augmentent.\nLorsqu\'il est Sobre :\n• Ses PM et sa Fuite augmentent.', 0x08bac60308bbc60308bcc60308bdc60308bec603, '0', 'Agressive'),
(22385, 'Alcoolique', '', 0x08bfc60308c0c60308c5c60308c6c60308c7c60308c8c60308c9c60308cac60308cbc60308ccc603, '1', 'Agressive'),
(22386, 'Vigicoffre', '', 0x08c1c60308c2c60308c3c60308c4c603, '1', 'Agressive'),
(22387, 'Serrurericrac', '', 0x08cdc603, '1', 'Buff'),
(22388, 'Serrurericrac', '', 0x08cec603, '1', 'Agressive'),
(22389, 'Appel du Malterego', '', 0x08d7c603, '1', 'None'),
