(22391, 'Plumage', 'Occasionne des dommages Eau.\nLes dommages sont augmentés après chaque lancer. Si le lanceur subit des dommages, les effets du sort sont retirés.', 0x08d9c603, '1', 'Agressive'),
(22392, 'Écume', 'Occasionne des dommages Eau aux ennemis en zone.', 0x08dac603, '1', 'Agressive'),
(22393, 'Éboulis', 'Occasionne des dommages Neutre et réduit les Résistances Poussée.', 0x08dbc603, '1', 'Agressive'),
(22394, 'Crevasse', 'Augmente le Tacle du lanceur.\nPendant 2 tours, s\'il est poussé, augmente ses PM.', 0x08dcc603, '1', 'Buff'),
(22395, 'Brèche', 'Repousse la cible et réduit les chances d\'effectuer un coup critique de l\'ennemi ciblé.', 0x08ddc603, '1', 'Agressive'),
(22397, 'Dard-dard', 'Érode les cibles et occasionne des dommages Air en zone.', 0x08dfc603, '1', 'Debuff'),
(22398, 'Butinage', 'Occasionne des dommages Air et rend Intacleurs les ennemis en zone.', 0x08e0c603, '1', 'Agressive'),
(22399, 'Essaim', 'Téléporte le lanceur sur la case ciblée.\n\nPendant 1 tour, augmente ses chances d\'effectuer un coup critique et les dommages de tous ses sorts s\'il subit des dommages à distance.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08e1c603, '1', 'Teleport'),
(22400, 'Nounch\'', 'Attire l\'ennemi ciblé et augmente les dommages en mêlée du lanceur.', 0x08e3c603, '1', 'Agressive'),
(22401, 'Caraboom', 'Vole de la vie dans l\'élément Feu.', 0x08e4c603, '1', 'Agressive'),
