(22403, 'Feu Primordial', '', 0x08e6c603, '1', 'None'),
(22404, 'Carabistouille', 'Occasionne des dommages Feu en zone autour du lanceur et augmente ses dommages en mêlée pour chaque ennemi dans la zone d\'effet.', 0x08e7c603, '1', 'Agressive'),
(22405, 'Carabistouille', 'Occasionne des dommages Feu en zone autour du lanceur et augmente ses dommages en mêlée pour chaque ennemi dans la zone d\'effet.', 0x08e8c60308eed703, '1', 'Buff'),
