(22408, 'Capotage', 'Occasionne des dommages Feu et vole des chances d\'effectuer un coup critique.', 0x08f2c603, '1', 'Agressive'),
(22409, 'Brise', 'Échange de position avec la cible et augmente les dommages à distance du lanceur.', 0x08f3c603, '1', 'Agressive'),
