(22412, 'Soricci', 'Occasionne des dommages Air.', 0x08fac603, '1', 'Agressive'),
(22413, 'Vent\'Art', 'Occasionne des dommages Air.', 0x08fbc603, '1', 'Agressive'),
(22414, 'Houle', 'Vole de la vie dans l\'élément Air aux ennemis en zone.', 0x08fcc603, '1', 'Agressive'),
(22415, 'Blizzard', 'Occasionne des dommages Air aux ennemis et réduit leurs résistances à distance en zone.', 0x08fdc603, '1', 'Agressive'),
(22416, 'Forage', 'Augmente le Tacle du lanceur, le rapproche de la cible et retire de la Fuite aux ennemis en zone autour d\'elle.', 0x08fec603, '1', 'Buff'),
(22417, 'Perforage', 'Augmente le Tacle du lanceur, le rapproche de la cible et retire de la Fuite aux ennemis en zone autour d\'elle.', 0x08ffc603, '1', 'Buff'),
(22418, 'Poinçon', 'Occasionne des dommages Terre aux ennemis et réduit leurs résistances en mêlée en zone.', 0x0880c703, '1', 'Agressive'),
(22419, 'Fouille', 'Inflige des dommages Terre et retire des PM.', 0x0881c703, '1', 'Agressive'),
(22420, 'Excavation', 'Occasionne des dommages Terre et vole des PM.', 0x0882c703, '1', 'Agressive'),
(22421, 'Taraudage', 'Occasionne des dommages Terre et réduit les résistances en mêlée.\nLes dommages du sort sont augmentés après chaque lancer.', 0x0883c703, '1', 'Agressive'),
(22422, 'Patinage', 'Augmente les PM du lanceur et le rend Intaclable.', 0x0884c703, '1', 'Buff'),
(22423, 'Plume Punitive', 'Occasionne des dommages Eau.\nLes dommages du sort sont augmentés pour un tour au deuxième tour après son lancer, et de nouveau au quatrième tour après son lancer.', 0x0885c703, '1', 'Buff'),
(22424, 'Vaglace', 'Occasionne des dommages Eau et retire des PA en zone.\nN\'affecte pas le lanceur.', 0x0886c703, '1', 'Agressive'),
(22425, 'Éboulement', 'Occasionne des dommages Neutre et réduit les Résistances Poussée.', 0x0887c703, '1', 'Agressive'),
(22426, 'Fissure', 'Repousse la cible. \nPlus les points de vie du lanceur sont bas, plus la poussée est importante.', 0x0888c703, '1', 'Agressive'),
(22427, 'Peau de Pierre', 'Augmente le Tacle de la cible. \nRenvoie 15% des dommages subis par la cible à son attaquant.', 0x0889c703, '1', 'Buff'),
(22428, 'Peau de Pierre', 'Augmente le Tacle de la cible. \nRenvoie 15% des dommages subis par la cible à son attaquant.', 0x088ac703, '1', 'None'),
(22429, 'Podkol', 'Rapproche le lanceur de la cible et occasionne des dommages Eau aux ennemis.', 0x088bc703, '1', 'Agressive'),
(22430, 'Moustapage', 'Vole de la vie dans l\'élément Eau.', 0x088cc703, '1', 'Agressive'),
(22431, 'Lézardage', 'Occasionne des dommages Terre en zone.', 0x088dc703, '1', 'Agressive'),
(22432, 'Pincette', 'Vole de la vie dans l\'élément Feu et retire des PA.', 0x088ec703, '1', 'Agressive'),
(22433, 'Pincement', 'Vole de la vie dans l\'élément Feu (hors lanceur) et retire des PA.', 0x088fc703, '1', 'Agressive'),
(22434, 'Magma', 'Occasionne des dommages Feu en zone.\n\nPendant 1 tour, réduit les dommages finaux occasionnés par les cibles si elles subissent des dommages de début de tour, de fin de tour, de piège ou de glyphe.', 0x0890c703, '1', 'Agressive'),
(22435, 'Miasme', 'Occasionne des dommages Air en zone.', 0x0891c703, '1', 'Agressive'),
(22436, 'Frappe Hantée', 'Occasionne des dommages Air aux ennemis en zone.\n\nSi aucun ennemi n\'est dans la zone d\'effet, la zone devient un cercle et sa taille augmente d\'une case (cumulable 3 fois).\nLes effets sont retirés si un ennemi est touché.', 0x0892c703, '1', 'Agressive'),
