(23241, 'Pyrotechnie', 'Augmente les dommages finaux du lanceur et de l\'Altéré allié ciblé.', 0x08eecf03, '1', 'Agressive'),
(23242, 'Pyrotechnie', 'Augmente les Dommages du lanceur et de l\'allié ciblé.', 0x08efcf03, '1', 'Debuff'),
(23243, 'Enchaînement', 'Occasionne des dommages Feu.\n\nPendant 1 tour, applique un poison Feu sur réception de dommages Terre.', 0x08f0cf03, '1', 'Agressive'),
(23244, 'Mégapoing', 'Termine le tour en cours du lanceur ou passe le prochain tour de l\'allié ciblé pour augmenter ses dommages sur la prochaine attaque.', 0x08f1cf03, '1', 'Debuff'),
(23245, 'Kickboxon', 'Applique l\'état Pesanteur sur les ennemis en zone.\nRetire également de la Portée aux ennemis n\'ayant initialement pas l\'état.', 0x08f2cf03, '1', 'Debuff'),
(23246, 'Sève', 'Pendant 2 tours, à la fin du tour de la cible, soigne les alliés à son contact.', 0x08f3cf03, '1', 'Agressive'),
(23247, 'Sève', 'Pendant 2 tours, à la fin du tour de la cible, soigne les alliés à son contact.', 0x08f4cf03, '1', 'Healing'),
(23248, 'Collagène', 'Applique l\'état Collagène sur la cible.\nAu début du prochain tour du lanceur, si la cible est toujours dans l\'état Collagène, consomme l\'état pour téléporter sur la première case disponible au contact de la cible.', 0x08f5cf03, '1', 'Agressive'),
(23249, 'Collagène', 'Applique l\'état Collagène sur la cible.\nAu début du prochain tour du lanceur, si la cible est toujours dans l\'état Collagène, consomme l\'état pour téléporter sur la première case disponible au contact de la cible.', 0x08f6cf0308f7cf03, '1', 'Teleport'),
(23250, 'Carapatrouille', 'Applique des points de bouclier sur le lanceur pour chaque ennemi présent dans une zone de 2 cases autour de lui et augmente son Retrait PA.', 0x08f8cf03, '1', 'Agressive'),
(23251, 'Carapatrouille', 'Applique des points de bouclier sur le lanceur pour chaque ennemi présent dans une zone de 2 cases autour de lui et augmente son Retrait PA.', 0x08f9cf03, '1', 'Buff'),
(23252, 'Vaccin', 'Augmente les PA de l\'allié ciblé.\nRebondit sur l\'allié le plus proche et en ligne de vue de l\'allié ciblé dans une zone de 2 cases.\nLes effets peuvent rebondir 2 fois et n\'affectent pas le lanceur.', 0x08facf03, '1', 'Agressive'),
(23253, 'Vaccin', 'Augmente les PA de l\'allié ciblé.\nRebondit sur l\'allié le plus proche et en ligne de vue de l\'allié ciblé dans une zone de 2 cases.\nLes effets peuvent rebondir 2 fois et n\'affectent pas le lanceur.', 0x08fbcf0308fccf0308fdcf0308fecf0308ffcf03, '0', 'Buff'),
(23254, 'Épidémiracle', 'Augmente les PA et la Puissance de l\'allié ciblé.\nRebondit sur l\'allié le plus proche et en ligne de vue de l\'allié ciblé dans une zone de 2 cases.\nN\'affecte pas le lanceur.', 0x0880d003, '1', 'Agressive'),
(23255, 'Épidémiracle', 'Augmente les PA et la Puissance de l\'allié ciblé.\nRebondit sur l\'allié le plus proche et en ligne de vue de l\'allié ciblé dans une zone de 2 cases.\nN\'affecte pas le lanceur.', 0x0881d0030882d003, '0', 'Buff'),
