(23262, 'Lance Immortelle', '', 0x08aed00308e7e903, '0', 'Agressive'),
(23263, 'Lance à Incendie', 'Invoque la Lance, rapproche le lanceur de sa Lance et occasionne des dommages Feu aux ennemis en ligne jusqu\'à la case ciblée et dans un demi-cercle de 2 cases.\n\nApplique un Éclat de Surt sur les ennemis touchés.', 0x08afd00308d1e1030895f903, '1', 'Agressive'),
(23268, 'Jormun', 'Téléporte la Lance du lanceur sur la première case disponible entre le lanceur et elle et occasionne des dommages Eau aux ennemis en ligne jusqu\'à la case ciblée.\n\nSur le lanceur : rappelle sa Lance et occasionne des dommages Eau aux ennemis dans un cercle de 2 cases autour d\'elle et du lanceur.\n\nLes dommages ne diminuent pas avec la distance, et sont plus faibles si la cible est le lanceur.\nLes effets ne sont appliqués qu\'une seule fois par lancer.', 0x08b4d00308d7e103, '1', 'Agressive'),
(23269, 'Jormun', '', 0x08b5d00308d1e203, '0', 'Agressive'),
