(23385, 'Armé', '', 0x088cd303, '0', 'Debuff'),
(23386, 'Parade', 'Rappelle la Lance du lanceur et applique l\'état Parade sur le lanceur. À la fin de son tour :\n• Rappelle de nouveau sa Lance.\n• Applique l\'état Indéplaçable sur le lanceur.\n• Réduit les dommages de la prochaine attaque qu\'il subit en mêlée.\n• S\'il subit des dommages en mêlée, occasionne des dommages dans son meilleur élément d\'attaque à son attaquant et le repousse.\nLes effets sont retirés après réception de dommages en mêlée par le lanceur.\n\nLes effets d\'interception et de partage de dommages sont incompatibles avec le sort.\nLes effets ne peuvent pas être désenvoûtés.', 0x088dd30308f1e103, '1', 'Agressive'),
(23387, 'Parade', '', 0x088ed30308a1e803, '0', 'Agressive'),
(23389, 'Bouquet d\'escampette', '• Sur un allié : repousse de 2 cases\n• Sur soi : Augmente la fuite de 200 pendant 1 tour, retire les effets des sorts Triste Cire et Fatalité.\n\nEmpêche d\'obtenir les butins de Cire Momore', 0x0890d303, '1', 'Debuff'),
(23390, 'Rédemption', '', 0x0894d303, '1', 'None'),
(23391, 'Octave', 'Augmente la Portée du lanceur et occasionne des dommages Eau aux ennemis.\n\nSi le lanceur est dans l\'état Désarmé : éloigne le lanceur de la cible.', 0x0896d303, '1', 'Agressive'),
(23392, 'Javelot-Foudre', 'Invoque la Lance et occasionne des dommages Eau aux ennemis en ligne jusqu\'à la case ciblée.\nSi la case ciblée est occupée par un ennemi, rebondit également sur l\'ennemi le plus proche n\'étant pas dans la zone d\'effet dans un cercle de 2 cases (3 fois maximum).', 0x0897d30308cbe103, '1', 'Agressive'),
(23393, 'Trident de la Mer', 'Attire les cibles et occasionne des dommages Eau aux ennemis en zone.', 0x0898d30308e5e10308e6e103, '1', 'Agressive'),
(23396, 'Elding', 'Invoque la Lance, attire les cibles vers le centre et occasionne des dommages Eau aux ennemis en zone.\nN\'affecte pas le lanceur.', 0x089bd303, '1', 'Agressive'),
(23401, 'Poinçon', 'Invoque la Lance en lui appliquant l\'état Poinçon :\n• Permet à la Lance de tacler.\n• Augmente le Tacle et la Vitalité de la Lance.\n• Applique l\'état Indéplaçable sur les cibles en zone.\nLes effets sont retirés à la destruction de la Lance.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08a1d30308a0e803, '1', 'Agressive'),
