(23409, 'Mutation', '', 0x08a9d30308aad303, '1', 'Buff'),
(23410, 'Génome', 'Si le lanceur est dans l\'état Proto : attire la cible jusqu\'à la case ciblée.\n\nSi le lanceur est dans l\'état Neutro : pousse la cible jusqu\'à la case ciblée.', 0x08abd303, '1', 'Agressive'),
(23411, 'Enzyme', 'Occasionne des dommages dans le meilleur élément d\'attaque du lanceur et vole de la Portée.', 0x08add303, '1', 'Agressive'),
(23412, 'Folklore', 'Vole de la vie dans le meilleur élément d\'attaque du lanceur et augmente ses dommages en mêlée.', 0x08aed303, '1', 'Agressive'),
