(23415, 'Aliénation', 'Repousse les cibles depuis le centre de la zone.', 0x08b1d303, '1', 'Agressive'),
(23416, 'Frénésie', 'Vole des chances d\'effectuer un coup critique et occasionne des dommages dans le meilleur élément d\'attaque du lanceur.', 0x08b2d303, '1', 'Debuff'),
(23418, 'Matourbillon', 'Échange de position avec l\'allié ciblé, lui applique des points de bouclier et en applique au lanceur.', 0x08b4d303, '1', 'Debuff'),
