(23420, 'Nématode', 'Occasionne des dommages Air aux ennemis.\nÀ la fin du tour du lanceur, le téléporte sur la première case disponible autour de la cible.', 0x08b6d303, '1', 'Agressive'),
(23421, 'Nématode', 'Occasionne des dommages Air aux ennemis.\nÀ la fin du tour du lanceur, le téléporte sur la première case disponible autour de la cible.', 0x08b7d303, '1', 'Teleport'),
(23422, 'Symbiote', 'Occasionne des dommages Air et Eau et vole de l\'Agilité et de la Chance.', 0x08b8d303, '1', 'Agressive'),
(23423, 'Lividité', 'Vole des résistances et occasionne des dommages Terre et Eau.', 0x08b9d303, '1', 'Agressive'),
(23424, 'Sauvagerie', 'Occasionne des dommages Air.\nLe coût en PA et les dommages du sort sont augmentés après chaque lancer.', 0x08bad303, '1', 'Buff'),
(23425, 'Glyfuneste', 'Pose un glyphe de début de tour qui occasionne des dommages dans le meilleur élément d\'attaque du lanceur et retire des Résistances Poussée aux ennemis.', 0x08bbd303, '1', 'Mark'),
