(23614, 'Plaquage', '', 0x08ecd6030881ea03, '1', 'Agressive'),
(23617, 'Brutalité du Trool', 'Brutalité du Trool (niveau 200) :\n• Au début du combat, le porteur sacrifie 1% de dommages finaux par ennemi pour gagner 2% de dommages finaux à chaque mort d\'un ennemi (hors invocations) présent au début du combat (cumulable 5 fois).', 0x08f0d60308f1d603, '1', 'Buff'),
