(23624, 'Camaraderie', '', 0x08fcd603, '1', 'Agressive'),
(23625, 'Camaraderie', '', 0x08fdd603, '1', 'Teleport'),
(23626, 'Faiblesse eau', '', 0x08fed60308ebe803, '0', 'Debuff'),
(23627, 'Faiblesse air', '', 0x08ffd60308ece803, '0', 'Debuff'),
(23628, 'Faiblesse terre', '', 0x0880d70308efe803, '0', 'Debuff'),
(23629, 'Faiblesse neutre', '', 0x0881d70308ede80308f9eb0308fbeb03, '0', 'Debuff'),
(23630, 'Faiblesse feu', '', 0x0882d70308f0e803, '0', 'Debuff'),
(23631, 'Dofus du Cauchemar', 'Pendant le tour de jeu d\'un Altéré du porteur, s\'il applique ou reçoit un bouclier, les alliés à 3 cases ou moins de lui sont soignés de 7% de leurs PV.\nS\'il désenvoûte une cible, les alliés à 3 cases ou moins gagnent 150 Puissance pour 1 tour (cumul 1, non dissipable).\nChaque effet ne peut être déclenché qu\'une fois par tour, mais si les deux le sont dans le même tour, l\'Altéré subit 10% de dommages supplémentaires pendant 1 tour (non dissipable).', 0x0883d7030884d7030885d703, '1', 'Agressive'),
(23632, 'Faiblesse prysmatique', '', 0x0886d70308eee803, '0', 'Debuff'),
(23633, 'Dofus Ocre', 'Donne 1 PA à un Altéré du porteur si aucune attaque occasionnant des dommages n\'a été subie par ce dernier depuis le précédent tour de jeu.', 0x0887d7030888d7030889d703, '0', 'Agressive'),
(23634, 'Dofus Ébène', 'Occasionner des dommages à distance et en mêlée pendant le tour de jeu d\'un Altéré du porteur déclenche le pouvoir du Dofus Ébène : la prochaine attaque de ce même Altéré, toujours dans le même tour, applique un poison (2 tours).\nCette attaque a un temps de recharge de 2 tours. Le poison est cumulable 2 fois.', 0x088ad703088bd703088cd703, '1', 'Agressive'),
(23635, 'Dofus Nébuleux', '1 tour sur 2, les dommages d\'un Altéré du porteur sont augmentés de 20%. Sinon, ils sont réduits de 10%.\nLe cycle commence dès son invocation par le bonus.', 0x088dd703088ed703088fd703, '1', 'Agressive'),
(23636, 'Dofus Forgelave', 'Confère 100% du niveau en points de bouclier à un Altéré du porteur, 1 fois maximum par tour pour les dommages de poussée et 1 fois pour chaque type de déplacement : \n- Dommages de poussée\n- Poussée / Attirance\n- Échange de positions / Téléportation / Portail Eliotrope\n- Portage Pandawa\n\nL\'effet ne peut être déclenché que par les ennemis.', 0x0890d7030891d7030892d703, '1', 'Agressive'),
(23637, 'Dofus Ivoire', 'Les Altérés du porteur réduisent de 50% les dommages d\'une attaque sur cinq. La réduction est perdue s\'ils sont sacrifiés.', 0x0895d7030896d7030897d703, '0', 'Agressive'),
(23638, 'Dofus Tacheté', 'Si un Altéré du porteur inflige des dommages pendant son tour de jeu, les alliés porteurs du Dorigami et lui-même gagnent 20 dommages pendant 1 tour.\n\nS\'il n\'inflige pas de dommages, les alliés porteurs du Domakuro et lui-même gagnent 150% de leur niveau en bouclier pendant 1 tour.', 0x0898d7030899d703089ad703, '1', 'Agressive'),
(23639, 'Dofus Abyssal', 'À chaque début de tour, si aucun ennemi n\'est au contact d\'un Altéré du porteur, cet Altéré gagne 1 PM. Sinon, il gagne 1 PA.', 0x089bd703089cd703089dd703, '0', 'Agressive'),
(23640, 'Dofus Vulbis', 'Les dommages occasionnés d\'un Altéré du porteur sont augmentés de 10% pendant 1 tour s\'il n\'a subi aucune attaque depuis son précédent tour de jeu. Sinon, il gagne 20 Tacle.', 0x089ed703089fd70308a0d703, '0', 'Agressive'),
(23641, 'Dofus Argenté Scintillant', 'Dès qu\'un Altéré du porteur descend en dessous de 20% de ses points de vie, il déclenche l\'effet du Dofus Argenté Scintillant.\nAu début de son prochain tour : soigne 30% de la vie et donne 20% de dommages finaux pour 1 tour (1 fois par combat).', 0x08a1d70308a2d70308a3d703, '1', 'Agressive'),
(23642, 'Dofus Turquoise', 'Pour chaque coup critique occasionné par un Altéré du porteur, ses dommages finaux sont augmentés de 1% pendant 3 tours. Cumulable 10 fois.', 0x08a4d70308a5d70308a6d703, '0', 'Agressive'),
(23643, 'Domakuro', 'À partir du cinquième tour après son invocation, un Altéré du porteur gagne jusqu\'à 64 dommages pour le reste du combat.\nCe bonus est réduit à chaque fois qu\'il occasionne des dommages pendant son tour à un adversaire pour chacun des 4 premiers tours après son invocation :\n\nAucune attaque : 16 dommages\n1 attaque : 8 dommages.\n2 attaques et + : 0 dommage.', 0x08a7d70308a8d70308a9d703, '1', 'Agressive'),
(23644, 'Dorigami', 'À chaque début de tour d\'un Altéré du porteur pendant ses 5 premiers tours de jeu, lui applique 100% de son niveau en bouclier.\nPendant ces 5 tours, si un Altéré du porteur tue une invocation, il gagne 100% de son niveau en bouclier pour 1 tour (4 fois max), et 300% (2 fois max) pour un monstre ou un joueur.\nLes boucliers ne s\'obtiennent que pendant le tour de jeu de l\'Altéré.', 0x08aad70308abd70308acd703, '1', 'Agressive'),
(23645, 'Dofus Pourpre', 'Pour chaque attaque à distance reçue sur un Altéré du porteur, ses dommages finaux occasionnés sont augmentés de 1% pendant 1 tour.\nLes effets peuvent se cumuler 10 fois.', 0x08add70308aed70308afd703, '0', 'Agressive'),
(23646, 'Dofus des Veilleurs', 'Au début du tour d\'un Altéré du porteur, rend 7% de points de vie aux alliés alignés.', 0x08b0d70308b1d70308b2d703, '1', 'Agressive'),
(23647, 'Dofus Cawotte', 'Donne 25 Esquive PA à un Altéré du porteur s\'il subit un malus PM, ou 25 Esquive PM s\'il subit un malus PA.\nLes deux effets ne sont pas cumulables et durent 1 tour.', 0x08b3d70308b4d70308b5d703, '0', 'Agressive'),
(23648, 'Dokoko', 'Tous les 3 tours à partir du quatrième tour après son invocation, rend 10% de ses points de vie maximum à un Altéré du porteur.', 0x08b6d70308b7d70308b8d703, '0', 'Agressive'),
(23649, 'Dofus Argenté', 'Dès qu\'un Altéré du porteur descend en dessous de 20% de ses points de vie, il déclenche l\'effet du Dofus Argenté.\nAu début de son prochain tour : soigne 20% de la vie (1 fois par combat).', 0x08b9d70308bad70308bbd703, '1', 'Agressive'),
(23650, 'Dofus Cacao', 'Chaque attaque à distance subie par un Altéré du porteur lorsque qu\'il est au corps à corps d\'un ennemi confère une Marque Chocolatée.\n\nCes marques sont consommées à la fin de son tour et donnent chacune 25% de son niveau en bouclier pendant 1 tour.', 0x08bcd70308bdd70308bed703, '1', 'Agressive'),
(23651, 'Dofus Émeraude', 'À la fin du tour d\'un Altéré du porteur, confère à l\'Altéré 100% de son niveau en points de bouclier pour chaque ennemi au contact.\nLes invocations ne sont pas comptabilisées.', 0x08bfd70308c0d70308c1d703, '0', 'Agressive'),
(23652, 'Flèche Cinglante', '', 0x08c2d703, '0', 'None'),
(23653, 'Flèche Cinglante', '', 0x08c4d703, '0', 'None'),
(23654, 'Flèche de Repli', '', 0x08c5d703, '0', 'None'),
(23655, 'Flèche de Repli', '', 0x08c6d703, '0', 'None'),
(23656, 'Désactive la ligne de vue de tous les sorts', '', 0x08ced70308cfd703, '1', 'Buff'),
(23657, 'Piqûre Motivante', 'Applique l\'état Piqué Motivé sur un Altéré allié :\n• Augmente ses dommages finaux, sa Vitalité, ses PA, ses PM et sa taille.\n\nLes effets ne peuvent pas être appliqués sur un Altéré étant déjà dans l\'état Piqué Motivé.', 0x08d0d703, '1', 'Buff'),
(23661, 'Oblitération', '', 0x08d9d703, '1', 'None'),
(23662, 'Oblitération', '', 0x08dad703, '1', 'None'),
(23663, 'Oblitération', '', 0x08dbd703, '1', 'Agressive'),
(23665, 'Trigger + masque U', '', 0x08ded70308dfd70308e0d703, '1', 'Agressive'),
(23667, 'Veuillez patienter, chargement en cours...', 'Vous disposez d\'une version incomplète du jeu. Le programme de lancement (Uplauncher) n\'a pas pu être trouvé. Le téléchargement de la version complète du jeu ne pourra pas être effectué. Veuillez relancer le jeu en conservant le programme de lancement ouvert pour permettre le téléchargement automatique de la version complète du jeu.', 0x08e3d703, '0', 'Agressive'),
(23668, 'Nounch&apos;', 'Attire&nbsp;l&apos;ennemi&nbsp;cibl&eacute;&nbsp;et&nbsp;augmente&nbsp;les&nbsp;dommages&nbsp;en&nbsp;m&ecirc;l&eacute;e&nbsp;du&nbsp;lanceur.', 0x08e4d703, '1', 'Agressive'),
(23669, 'NotOK en TESTING', 'Ça part en prod.', 0x08e5d703, '1', 'Agressive'),
(23670, 'Ronces Agressives', 'Occasionne des dommages Feu aux ennemis et soigne les alliés en zone.', 0x08e6d703, '1', 'Agressive'),
(23671, 'Rêve de Rakoopeur', 'Lorsqu\'un défenseur applique un bouclier, tous les défenseurs gagnent un bouclier équivalent à 20% de leurs PDV maximum.', 0x08e7d70308e8d70308abef03, '1', 'Buff'),
(23672, 'Paradoxe de Rakoopeur', 'Les défenseurs gagnent 2 PM et 20% de dommages finaux pour 1 tour à chaque fois qu\'ils subissent des dommages à distance. Cumulable 3 fois.', 0x08e9d70308ead703, '1', 'Buff'),
(23673, 'Ch▯timent_PL_42', 'Este hechizo permite que su lanzador aumente su sabedoria cada vez que pierde PdV.', 0x08ebd703, '1', 'Buff'),
(23674, 'Cauchemar de Rakoopeur', 'Chaque fois qu\'un attaquant tue une entité, ses alliés situés en cercle inversé de taille 3 autour de lui subissent un malus de -25% de résistance dans tous les éléments jusqu\'à la fin du combat, cumulable 2 fois.', 0x08ecd70308edd703, '1', 'Debuff'),
(23675, 'Bouclier Féca', 'Applique l\'état Protégé sur l\'allié ciblé :\n• Réduit les dommages subis par la cible.\n\nLes effets ne peuvent pas être appliqués sur un allié étant déjà dans l\'état Protégé.', 0x08efd70308f0d7030893d803, '1', 'Buff'),
(23676, 'Chataîgne', '', 0x08f1d703, '1', 'Agressive'),
(23677, 'Veuillez patienter, chargement en cours...', '', 0x08f2d70308f3d70308f6d70308f8d703, '1', 'Agressive'),
