(23687, 'Insanité', '', 0x089dd803, '1', 'Debuff'),
(23688, 'Guano', 'Occasionne des dommages Eau aux ennemis et repousse les cibles en zone autour du lanceur.\nAugmente également les Dommages Poussée du lanceur pour chaque ennemi présent dans la zone d\'effet.', 0x089ed803, '1', 'Buff'),
(23689, 'Flibusterie', 'Vole de la vie dans l\'élément Eau aux ennemis et repousse la cible.', 0x089fd803, '1', 'Agressive'),
(23690, 'Wotka', '', 0x08a1d803, '1', 'Buff'),
(23691, 'Neutronc', 'Occasionne des dommages Terre aux ennemis et pose un glyphe-aura qui téléporte les entités symétriquement par rapport au lanceur.', 0x08a2d803, '1', 'Agressive'),
