(23717, 'Liane attirante', '', 0x08fad803088edf03088fdf03, '1', 'Agressive'),
(23719, 'Lance-Pierre', 'Occasionne des dommages Terre aux ennemis en zone et invoque la Lance.\nLes dommages ne diminuent pas avec la distance.', 0x08fed80308cde10308cee103, '1', 'Agressive'),
(23720, 'Épieu Sismique', 'Occasionne des dommages Terre aux ennemis en zone.\nSi la case est ou devient libre, invoque la Lance.\nLes dommages ne diminuent pas avec la distance.', 0x08ffd80308f6e103, '1', 'Agressive'),
(23723, 'Ydra', 'Échange de position avec la Lance du lanceur, occasionne des dommages Terre aux ennemis en zone et rappelle la Lance.\nLes effets ne s\'appliquent que si l\'échange de positions peut s\'effectuer.\n\nSur le lanceur : occasionne des dommages Terre aux ennemis en zone autour de lui et rappelle sa Lance.\n\nLes dommages ne diminuent pas avec la distance.', 0x0882d903, '1', 'Agressive'),
(23726, 'Talon d\'Argile', 'Échange de position avec la cible et occasionne des dommages Terre aux ennemis.\nSi la cible est la Lance du lanceur, la rappelle également.', 0x0885d90308c2e30308dae703, '1', 'Agressive'),
(23729, 'Lance-Cyclone', 'Invoque la Lance, occasionne des dommages Air aux ennemis et repousse les cibles en ligne jusqu\'à la case ciblée.', 0x088cd90308daf80308dbf803, '1', 'Agressive'),
(23731, 'Soulèvement', 'Téléporte les cibles symétriquement par rapport au lanceur et occasionne des dommages Terre aux ennemis en zone.\nLes dommages ne diminuent pas avec la distance.', 0x088ed903, '1', 'Agressive'),
(23734, 'Javeline de Myr', 'Occasionne des dommages Air aux ennemis et repousse la cible.\nSi la case ciblée est ou devient libre, invoque la Lance.', 0x0891d90308f3e10308cce703, '1', 'Agressive'),
(23735, 'Noa', 'Occasionne des dommages Air aux ennemis et leur applique l\'état Noa :\n• Occasionne des dommages Air aux ennemis dans un carré de 2 cases et retire l\'état Noa si la cible subit des dommages de poussée.', 0x0894d903, '1', 'Agressive'),
(23736, 'Effondrement', 'Occasionne des dommages Terre aux ennemis et attire les cibles jusqu\'au centre en zone.\nLes dommages ne diminuent pas avec la distance.\n\nSi le lanceur est dans l\'état Désarmé : la portée du sort est infinie et les effets peuvent être appliqués uniquement autour de sa Lance.', 0x0895d90308cde70308cee703, '1', 'Agressive'),
(23738, 'Terre du Milieu', 'Augmente la Puissance du lanceur pour chaque ennemi dans la zone d\'effet et occasionne des dommages Terre en zone.\n\nSi le lanceur est dans l\'état Désarmé : la portée du sort est infinie et les effets peuvent être appliqués uniquement autour de sa Lance.\n\nLes dommages n\'affectent pas le lanceur.', 0x0897d90308f4f803, '1', 'Agressive'),
(23741, 'Volée d\'Airain', 'Occasionne des dommages Air aux ennemis et repousse les cibles en zone.', 0x089ad90308ede10308d6e703, '1', 'Agressive'),
(23742, 'Moulin à Vent', 'Téléporte les cibles symétriquement par rapport au centre et occasionne des dommages Air aux ennemis en zone.\n\nSi le lanceur est dans l\'état Désarmé : la portée du sort est infinie et les effets peuvent être appliqués uniquement autour de sa Lance.\n\nN\'affecte pas le lanceur.', 0x089bd903, '1', 'Agressive'),
(23743, 'Dégagement', 'Occasionne des dommages Air aux ennemis et repousse les cibles depuis le centre en zone.\n\nSi le lanceur est dans l\'état Désarmé : la portée du sort est infinie et les effets peuvent être appliqués uniquement autour de sa Lance.', 0x089cd90308aff803, '1', 'Agressive'),
(23744, 'Lance-Cyclone', '', 0x089fd90308c7ec03, '0', 'Agressive'),
(23745, 'Pévépé', '', 0x08a3d90308add903, '1', 'Buff'),
(23747, 'Maelstrom', 'Invoque ou téléporte la Lance sur la case ciblée et occasionne des dommages Feu aux ennemis en zone.\nSi la case est occupée, rappelle la Lance.\nLes dommages ne diminuent pas avec la distance.\n\nRetire les Éclats de Surt à tous les ennemis et en applique un sur ceux dans la zone d\'effet.\n\nLes effets ne sont appliqués que si l\'invocation, la téléportation ou le rappel sont effectués.', 0x08a5d90308befa0308bffa03, '1', 'Agressive'),
(23750, 'Muspel', 'Invoque ou téléporte la Lance sur la case ciblée et occasionne des dommages Feu aux ennemis en zone.\n\nLes dommages ne diminuent pas avec la distance et ne sont occasionnés que si l\'invocation ou la téléportation sont effectuées.\n\nApplique 2 Éclats de Surt sur les ennemis touchés.', 0x08a8d903, '1', 'Agressive'),
(23751, 'Muspel', '', 0x08a9d903, '0', 'Agressive'),
(23752, 'Arbre Contrôlé', '', 0x08aad903, '0', 'Agressive'),
(23753, 'Fente', 'Téléporte le lanceur sur la case ciblée et occasionne des dommages Feu aux ennemis en zone.\n\nApplique un Éclat de Surt sur les ennemis touchés.', 0x08acd903, '1', 'Agressive'),
(23754, 'Estoc Brûlant', 'Occasionne des dommages Feu aux ennemis en zone.\n\nApplique un Éclat de Surt sur les ennemis touchés.', 0x08aed90308ebe10308ece103, '1', 'Agressive'),
(23755, 'Moulin Rouge', 'Occasionne des dommages Feu aux ennemis et attire les cibles jusqu\'au centre de la zone.\nSur le lanceur ou sur sa Lance, les effets sont appliqués dans une croix de 3 cases.\n\nSi le lanceur est dans l\'état Désarmé : la portée du sort est infinie et les effets peuvent être appliqués uniquement autour de sa Lance.\n\nApplique un Éclat de Surt sur les ennemis touchés.', 0x08afd90308dfe703, '1', 'Agressive'),
(23756, 'Fer Rouge', 'Occasionne des dommages Feu aux ennemis dans un carré sans diagonale de 2 cases.\n\nSi le lanceur est dans l\'état Désarmé : la portée du sort est infinie et les effets peuvent être appliqués uniquement autour de sa Lance.\n\nLes dommages des Éclats de Surt sont augmentés pour chaque ennemi touché jusqu\'au prochain retrait d\'Éclats.', 0x08b0d9030896f903, '1', 'Agressive'),
(23758, 'Transfusion', 'Occasionne des dommages Feu et applique un Poison Feu sur tentative de retrait de PM.', 0x08b2d903, '1', 'Agressive'),
(23760, 'Bond tactique', '', 0x08b6d90308b7d90308bad903, '1', 'Buff'),
