(23822, 'Conflagration', '', 0x08acda03, '0', 'None'),
(23823, 'Kyrja', 'Téléporte le lanceur sur la case ciblée, vole de la Fuite et vole de la vie dans le meilleur élément d\'attaque du lanceur aux ennemis en ligne jusqu\'à la case ciblée.', 0x08adda0308dbe10308dce103, '1', 'Agressive'),
(23824, 'Charge Héroïque', 'Rapproche le lanceur de la cible. Si le lanceur arrive à son contact, occasionne des dommages dans son meilleur élément d\'attaque aux ennemis et repousse la cible.\nSi la cible est la Lance du lanceur, la rappelle également.\n\nLa poussée est plus importante selon la distance entre le lanceur et la cible.', 0x08aeda0308d5e10308d6e103, '1', 'Agressive'),
(23825, 'Charge Héroïque', '', 0x08afda030899e803089ae803, '0', 'Agressive'),
(23826, 'Chevalerie', 'Soigne le lanceur et augmente ses PM.\nSi le lanceur est dans l\'état Désarmé, rappelle également sa Lance.', 0x08b0da0308e9e103, '1', 'Agressive'),
(23828, 'Oriflamme', 'Invoque ou téléporte la Lance sur la case ciblée, applique un bouclier sur les alliés et augmente leurs Résistances Critiques en zone.', 0x08b3da03, '1', 'Agressive'),
(23829, 'Vajra', 'Téléporte le lanceur sur la case ciblée, vole de la vie dans le meilleur élément d\'attaque du lanceur aux ennemis et réduit leurs dommages finaux occasionnés en zone.', 0x08b4da03, '1', 'Agressive'),
(23831, 'Évolution', '', 0x08b7da03, '1', 'None'),
(23832, 'Soupape', '', 0x08b9da03, '1', 'None'),
(23834, 'Éclipse', 'Applique l\'état Éclipse sur le lanceur :\n• Applique l\'état Désarmé sur le lanceur.\n• Applique un bouclier sur le lanceur et ses alliés dans un cercle de 3 cases autour de lui.\n• Retire de la Portée à tout le monde.\n\nAu tour suivant sur la case ciblée :\n• Si la case est occupée par le lanceur, lance le sort Croissant de Mani.\n• Sinon, lance le sort Disque de Sigel.\n\nLe retrait de Portée ne peut pas être désenvoûté.', 0x08bbda0308c6e303, '1', 'Agressive'),
(23835, 'Éclipse', '', 0x08bcda0308c7e303, '1', 'Agressive'),
(23836, 'Disque de Sigel', 'Occasionne des dommages dans le meilleur élément d\'attaque du lanceur aux ennemis en zone.\nSi la case ciblée est ou devient libre, invoque la Lance.', 0x08bdda0308bbe20308c4e30308c5e3030895e4030896e403, '1', 'Agressive'),
(23837, 'Croissant de Mani', 'Applique l\'état Pesanteur sur les cibles en zone.', 0x08bfda03, '1', 'Agressive'),
(23838, 'Étreinte de Valkyr', 'Réduit les dommages reçus par l\'allié ciblé et lui applique l\'état Étreinte de Valkyr :\n• Érode les attaquants ennemis de la cible.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08c1da03, '1', 'Agressive'),
(23839, 'Arraisonnage', '', 0x08c2da03, '1', 'None'),
(23841, 'Prélude au Fer', 'Réduit la durée des effets sur les ennemis et augmente la Puissance des alliés en zone.\n\nSi le lanceur est dans l\'état Désarmé : la portée du sort est infinie et les effets peuvent être appliqués uniquement autour de sa Lance.', 0x08c7da0308f7fa0308f8fa03, '1', 'Agressive'),
(23842, 'Crépuscule', 'Érode les ennemis et leur retire de la Portée en zone.\n\nSi le lanceur est dans l\'état Désarmé : la portée du sort est infinie et les effets peuvent être appliqués uniquement autour de sa Lance.', 0x08c8da03, '1', 'Agressive'),
(23844, '+1 {spell,23996,1::<font color=\"#ebc304\">Évolution</font>}', '', 0x08cada03, '1', 'None'),
(23846, 'Holmgang', 'Applique les états Indéplaçable et Holmgang sur le lanceur :\n• Réduit les dommages qu\'il subit à distance.\n• Pose un glyphe-aura qui attire les ennemis qui le traversent et leur occasionne des dommages dans le meilleur élément d\'attaque du lanceur (une fois par ennemi par tour).\n• Termine le tour en cours du lanceur.', 0x08ccda03, '1', 'Agressive'),
(23847, 'Holmgang', '', 0x08cdda03, '0', 'Agressive'),
(23849, 'Épilogue', '', 0x08d0da0308d7e50308f4ec03, '0', 'None'),
(23850, 'Boumboum', '', 0x08d4da0308d5da03, '1', 'Agressive'),
(23851, 'Intervention', '', 0x08dada0308dbda03, '1', 'Agressive'),
(23852, 'Transko', '', 0x08ddda03, '1', 'Agressive'),
(23853, 'Chaluchava', '', 0x08e0da0308e1da03, '1', 'Agressive'),
(23854, 'Excavation', '', 0x08e2da0308e3da03, '1', 'Agressive'),
(23855, 'Décompression', '', 0x08e4da0308f9da03, '1', 'Agressive'),
(23857, 'Étreinte de Valkyr', '', 0x08e8da0308efec03, '0', 'None'),
(23869, 'Rêve de Belladone', 'Si un allié commence son tour avec un ennemi aligné en diagonale, ces derniers échangent de position et lui vole 2 PM pendant 1 tour (n\'affecte pas Belladone en phase 1 et 3).', 0x0887db030888db03089bdb03089cdb03, '1', 'Debuff'),
(23870, 'Paradoxe de Belladone', 'À chaque fois qu\'un ennemi est poussé, transposé ou attiré, Belladone gagne 10% de dommages finaux (Infini).', 0x0889db03088adb03088bdb03089adb03, '1', 'Buff'),
(23871, 'Cauchemar de Belladone', 'Belladone tue tous les ennemis qui ne sont pas en ligne de vue avec elle.', 0x088cdb03088ddb03088edb03089ddb03089edb03, '1', 'Agressive'),
(23872, 'Activation Steamer', '', 0x0890db030894db030895db030896db030897db030898db03, '0', 'Agressive'),
(23874, 'Agular', '', 0x089fdb03, '0', 'None'),
(23875, 'Expédition de la Bravoure', '', 0x08a1db03, '0', 'Agressive'),
(23876, 'Combinaisons Élémentaires', 'Augmente la Puissance du lanceur et applique des effets sur les ennemis selon la combinaison d\'états élémentaires générée :\n• Éruption (Terre & Feu) : augmente les dommages subis par la cible.\n• Enlisement (Terre & Eau) : retire des PM.\n• Ébullition (Feu & Eau) : retire de la Fuite.\n• Carbonisation (Feu & Air) : retire des PA.\n• Cristallisation (Eau & Air) : réduit les dommages finaux occasionnés par la cible.\n• Assèchement (Air & Terre) : vole de la Portée.\n\nLa Puissance ne peut pas être désenvoûtée.\n\nLes effets sont cumulables une fois pour chaque combinaison élémentaire.\nConsomme les états élémentaires après combinaison.', 0x08a2db03, '0', 'Debuff'),
