(23987, 'Aboiement', '', 0x08e3dc0308d0ff03, '0', 'None'),
(23988, 'Bestialité Ouginak', 'Réduit les dommages subis par le lanceur pour chaque état de Rage et autorise l\'utilisation de certains sorts.\n\nLorsque le troisième état de Rage est atteint, transforme le lanceur en Bête :\n• Le rend Intaclable et Affaibli.\n• Augmente ses PM.\n• Augmente ses dommages finaux occasionnés.\n• Fixe la portée maximale de tous ses sorts offensifs Ouginak ayant plus de 2 PO à 2.\n• Empêche l\'utilisation des sorts défensifs Ouginak.', 0x08e4dc03, '0', 'Buff'),
(23989, 'Rabattage', '', 0x08e7dc03, '1', 'None'),
(23990, 'Vertèbre', '', 0x08e8dc03, '1', 'None'),
(23991, 'Dogue', '', 0x08e9dc03, '1', 'None'),
(23992, 'Cerbère', '', 0x08eadc03, '1', 'None'),
(23993, 'Calcanéus', '', 0x08ebdc03, '1', 'None'),
(23994, '<font color=\'#E6893D\'>Pour chaque état de Rage :</font>', '', 0x08f1dc03, '0', 'None'),
(23995, '<br><font color=\'#E6893D\'>Sous Forme Bestiale :</font>', '', 0x08f2dc03, '0', 'None'),
(23996, 'Évolutions Steamer', 'Rend une Tourelle plus puissante à chaque niveau d\'évolution.\n\nÉvolution II : la Tourelle débloque la possibilité à la fin de son tour de jeu d\'appliquer des effets sur son invocateur s\'il est dans un cercle de 7 cases et en ligne de vue d\'elle.\n\nÉvolution III : la Tourelle débloque la possibilité d\'être activée par son invocateur durant son tour de jeu.\n\nIl ne peut y avoir qu\'une seule Tourelle en Évolution III par Steamer. Si une autre Tourelle atteint son troisième niveau d\'évolution, alors la précédente repasse en Évolution II.', 0x08f3dc03, '1', 'Agressive'),
(23997, '<b>Évolution II :</b>', '', 0x08f4dc03, '1', 'None'),
(23998, '<br><b>Évolution III :</b>', '', 0x08f5dc03, '1', 'None'),
(23999, 'Débloque l\'application d\'effets à la fin du tour de la Tourelle', '', 0x08f6dc03, '1', 'None'),
(24000, 'Débloque l\'activation de la Tourelle', '', 0x08f7dc03, '1', 'None'),
(24001, 'Empêche l\'utilisation des sorts défensifs', '', 0x0880dd03, '0', 'None'),
(24002, 'Oh c\'est nouveau ça !', '', 0x0881dd030887dd030888dd0308f6e00308f7e00308f8e003, '1', 'Buff'),
(24003, 'Concentration de Chakra', '', 0x0889dd03088add03088bdd03, '0', 'Agressive'),
(24004, 'Accrocs', '', 0x088ddd03088edd03088fdd03, '1', 'Agressive'),
(24006, 'Flamèche', 'Occasionne des dommages dans le pire élément d\'attaque du lanceur.', 0x08a4dd0308a5dd0308a6dd03, '1', 'None'),
(24007, 'Boomerang de Diamantine', 'Occasionne des dommages dans un élément aléatoire et attire la cible.', 0x08a9dd0308aadd03, '1', 'Agressive'),
(24009, 'Enchaînement', 'Occasionne des dommages Feu.\n\nPendant 1 tour, applique un poison Feu sur réception de dommages Terre.', 0x08afdd03, '1', 'Agressive'),
(24010, 'Marteau de Darkli Moon', 'Occasionne des dommages Air et vole de la Portée.', 0x08b1dd0308b2dd03, '1', 'Agressive'),
(24011, 'Mantiscroc', 'Augmente la Fuite du lanceur pour chaque ennemi dans la zone d\'effet et occasionne des dommages Terre aux ennemis en zone.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08b3dd0308b4dd0308b5dd03, '1', 'Agressive'),
(24012, 'Mantiscroc', '', 0x08b6dd0308b7dd0308b8dd03, '1', 'Buff'),
(24013, 'Dard Moklès', 'Augmente le Tacle du lanceur pour chaque ennemi dans la zone d\'effet et occasionne des dommages Terre aux ennemis en zone autour du lanceur.\n\nLes effets ne peuvent pas être désenvoûtés.', 0x08b9dd0308badd03, '1', 'Agressive'),
(24014, 'Dard Moklès', '', 0x08bbdd0308bcdd03, '1', 'Buff'),
(24015, 'Kannibulle', 'Occasionne des dommages Eau et retire des Dommages Critiques.', 0x08bddd0308bedd0308bfdd03, '1', 'Agressive'),
(24016, 'Ebilition', 'Occasionne des dommages Eau et augmente les chances d\'effectuer un coup critique du lanceur.', 0x08c0dd0308c1dd03, '1', 'Agressive'),
(24017, 'Leçon de Grunob', 'Occasionne des dommages Feu et réduit les soins reçus par les ennemis.\nRebondit sur l\'ennemi le plus proche dans un cercle de 2 cases (5 fois maximum).', 0x08c4dd0308cbdd03, '1', 'Agressive'),
(24018, 'Leçon de Grunob', '', 0x08c5dd0308c6dd03, '0', 'None'),
(24019, 'Leçon de Grunob', '', 0x08c7dd0308c8dd0308cadd0308f1dd0308c1e00308c2e003, '0', 'Agressive'),
(24020, '+2 {spell,23996,1::<font color=\"#ebc304\">Évolutions</font>}', '', 0x08ccdd03, '1', 'None'),
(24021, 'Glyphe Savouweux', '', 0x08cfdd0308d0dd03, '1', 'Mark'),
(24022, 'Cawotte Chawnue', 'Invoque une Cawotte qui s\'applique un bouclier à chaque début de tour.\nLorsqu\'elle subit des dommages, elle applique un bouclier sur son attaquant.\n\nLe bouclier sur attaque est plus important que le bouclier à chaque début de tour.', 0x08d1dd0308d2dd03, '1', 'Summon'),
(24023, 'Cawotte Chawnue', '', 0x08d3dd0308d4dd030898e1030899e10308bbe103, '1', 'Debuff'),
(24024, '<font color=\"#e6893d\">État Sobre :</font>', '', 0x08d5dd03, '0', 'None'),
(24025, '<font color=\"#e6893d\">État Saoul :</font>', '', 0x08d6dd03, '0', 'None'),
(24026, '{spell,23996,1::<font color=\"#ebc304\">Évolutions Steamer</font>}', '', 0x08d7dd03, '0', 'None'),
(24027, 'Invocation de l\'Arakne Majeure', 'Invoque une Arakne Majeure maîtrisable qui occasionne des dommages Terre et retire des PA.\n\nPeut invoquer une Arakne maîtrisable qui occasionne des dommages Terre.', 0x08dadd0308dbdd03, '1', 'Summon'),
(24028, 'Invocation de Chaferfu Lancier', 'Invoque un Chaferfu Lancier qui occasionne des dommages Terre et retire des PM.\n\nPeut invoquer un Chaferfu qui occasionne des dommages Terre aléatoirement aux alliés ou aux ennemis.', 0x08dedd0308dfdd03, '1', 'Summon'),
(24029, 'Provocation', 'Rapproche le lanceur de la cible et l\'attire.', 0x08e2dd0308e3dd03, '1', 'Agressive'),
(24030, 'Maladresse d\'Arme', 'Pendant 2 tours, si le lanceur subit des dommages d\'armes, réduit les dommages d\'armes de son attaquant.', 0x08e6dd0308e7dd03, '1', 'Agressive'),
(24031, 'Maladresse d\'Arme', '', 0x08e8dd0308e9dd03, '1', 'Debuff'),
(24036, 'Saoul', '• Retire les effets de l\'état {spell,24037,1::<font color=\"#ebc304\">Sobre</font>}.\n• Retire 1 PM non esquivable.\n• Réduit les dommages subis par le lanceur.', 0x08f5dd03, '0', 'Debuff'),
(24037, 'Sobre', 'Retire les effets de l\'état {spell,24036,1::<font color=\"#ebc304\">Saoul</font>}.', 0x08f6dd03, '0', 'Debuff'),
