(24626, 'Lance Immortelle', 'Invoque la Lance Immortelle qui applique l\'état Désarmé sur le lanceur et pose un glyphe-aura qui réduit les dommages subis par les alliés autour d\'elle.\nLa Lance peut être récupérée par reprise de volée si le lanceur est dans le glyphe.\n\nÀ sa mort, la Lance réapplique l\'état Armé sur le lanceur.', 0x089dea03, '0', 'None'),
(24627, '{spell,24626,1::<font color=\"#ebc304\">Invoque la Lance Immortelle</font>}', '', 0x089eea03, '0', 'None'),
(24628, 'Vaguelette', '', 0x089fea03, '1', 'Agressive'),
(24629, 'Armé', 'Le lanceur entre en Garde en-dehors de son tour de jeu :\n• Réduit les dommages subis par le lanceur.', 0x08a0ea03, '0', 'None'),
(24630, 'Désarmé', 'Si le lanceur se trouve dans le glyphe de sa Lance, il entre dans l\'état Reprise de Volée. Cet état lui permet d\'utiliser ses sorts nécessitant l\'état Armé en récupérant la Lance.\n\nLes sorts utilisables à la fois dans les états Armé et Désarmé n\'occasionnent plus de dommages élémentaires tant que le lanceur est dans l\'état Désarmé sans Reprise de Volée.', 0x08a1ea03, '0', 'None'),
