(25156, 'Redressement', 'Augmente la Vitalité du lanceur.\n\nSur un allié : augmente la Vitalité du lanceur et de l\'allié ciblé.\nLe bonus est réduit de moitié.', 0x08ebf20308f7f20308f8f203, '1', 'Debuff'),
(25157, 'Redressement', '', 0x08ecf20308edf20308eef20308eff20308f5fc03, '1', 'None'),
(25158, 'Taxation', 'Réduit tout type de dommages subis par les alliés sur la première attaque en zone, mais augmente tout type de dommages subis par le lanceur.\n\nLes effets du sort sont retirés si un des alliés subit des dommages.', 0x08f0f20308f5f20308f6f203, '1', 'Buff'),
(25159, 'Fraude', 'Applique un bouclier sur le lanceur pour chaque ennemi présent dans un cercle de 2 cases autour de lui.', 0x08f1f20308f3f20308f4f203, '1', 'Agressive'),
(25160, 'Fraude', '', 0x08f2f203, '1', 'Buff'),
(25161, 'Coupobol', 'Réduit les chances d\'effectuer un coup critique des ennemis en zone et augmente celles du lanceur pour chaque ennemi présent dans la zone d\'effet.', 0x08f9f2030882f3030883f303, '1', 'Debuff'),
