(25175, 'Bedaine', 'Retire de l\'Esquive PA aux ennemis dans la ligne de vue du lanceur en zone.', 0x0896f30308b0f30308b1f303, '1', 'Buff'),
(25176, 'Vibration', 'Augmente le Retrait PA et l\'Esquive PA des alliés en zone.', 0x0897f30308aef30308aff303, '1', 'Buff'),
(25177, 'Acoustique', 'Retire autant de PA que de distance entre le lanceur et la cible, occasionne des dommages Eau et attire la cible.\n\nLe sort ne peut pas être projeté dans un Portail.', 0x0898f30308b2f30308b3f303, '1', 'Agressive'),
