(25208, 'Ignition', 'Si le lanceur est dans l\'état Ardent :\n• Occasionne des dommages Feu.\n\nSi le lanceur est dans l\'état Ectoplasmique :\n• Vole de la vie dans l\'élément Feu.\n\nSi le lanceur est dans l\'état Flamboyant :\n• Applique un poison Feu de début de tour sur la cible.', 0x08e7f30308ecf30308edf303, '1', 'Agressive'),
(25209, 'Éclat', 'Si le lanceur est dans l\'état Ardent :\n• Occasionne des dommages Feu dans un cercle de 2 cases.\n\nSi le lanceur est dans l\'état Ectoplasmique :\n• Vole de la vie dans l\'élément Feu dans une croix d\'une case.\n\nSi le lanceur est dans l\'état Flamboyant :\n• Applique un poison Feu de fin de tour sur les cibles dans une croix d\'une case.', 0x08e8f30308eef30308eff303, '1', 'Agressive'),
(25210, 'Lueur', 'Si le lanceur est dans l\'état Ardent :\n• Augmente la Puissance des alliés en zone.\n\nSi le lanceur est dans l\'état Ectoplasmique :\n• Soigne en zone.\n\nSi le lanceur est dans l\'état Flamboyant :\n• Applique un bouclier sur les alliés en zone.', 0x08e9f30308eaf30308ebf303, '1', 'Buff'),
(25211, 'Flibusterie', 'Occasionne des dommages Terre et Neutre.\n\nEn coup critique, applique également un poison Neutre de début de tour sur la cible.', 0x08f0f30308fef30308fff303, '1', 'Agressive'),
(25212, 'Forbandit', 'Occasionne des dommages Terre et Neutre.\n\nEn coup critique, augmente également la Puissance du lanceur.', 0x08f1f30308fcf30308fdf303, '1', 'Agressive'),
(25213, 'Taloche', 'Occasionne des dommages Terre et Neutre en zone.\n\nEn coup critique, vole de la vie dans l\'élément Terre et Neutre en zone.', 0x08f2f30308faf30308fbf303, '1', 'Agressive'),
(25214, 'Abordanse', 'Occasionne des dommages Terre et Neutre et vole des chances d\'effectuer un coup critique.\n\nEn coup critique, augmente également les Dommages Critiques.', 0x08f3f30308f8f30308f9f303, '1', 'Agressive'),
