(25364, 'Surprise Puissante', '', 0x08a4f60308a5f60308a6f603, '1', 'Buff'),
(25366, 'Surprise Explosive', 'Invoque une Surprise Explosive statique.\n\nÀ sa mort, la Surprise Explosive occasionne des dommages Neutre aux ennemis dans un cercle de 2 cases autour d\'elle.\n\nPendant 3 tours, pour chaque tour où la Surprise Explosive reste en vie, les dommages de son explosion augmentent.', 0x08b6f603, '1', 'Summon'),
(25367, 'Surprise Explosive', '', 0x08b9f60308baf603089cfc03, '1', 'Agressive'),
(25368, 'Kadommage', 'Occasionne des dommages Eau et Feu.\n\nLe coup en PA du sort est remboursé si la cible est une Surprise alliée.', 0x08c1f60308ccf60308cdf603, '1', 'Agressive'),
(25369, 'Kadommage', '', 0x08c2f603, '1', 'Buff'),
(25370, 'Poussurprise', 'Pousse une Surprise alliée.', 0x08c5f60308c8f60308c9f603, '1', 'Agressive'),
