(25373, 'Obscurantisme', 'Échange de position avec la cible.\nSi c\'est un allié, augmente sa Puissance. Si c\'est un ennemi, lui en retire.', 0x08dbf60308e6f60308e7f603, '1', 'Agressive'),
(25374, 'Souffle de Saverne', 'Augmente immédiatement la Puissance de tous les alliés et en retire à tous les ennemis au tour suivant.', 0x08e1f60308e4f60308e5f603, '1', 'Buff'),
