(25742, 'Mot Stimulant', 'Augmente les PA de l\'allié ciblé et lui applique l\'état Encouragé.\nLe cumul est partagé entre les Encouragements Eniripsa.\n\nSur une case libre : invoque une Fée Stimulante.', 0x0893800408e1810408e28104, '1', 'Agressive'),
(25743, 'Mot de Jouvence', 'Réduit la durée des effets sur l\'allié ciblé, le soigne immédiatement et en début de tour et lui applique l\'état Encouragé.\nLe cumul est partagé entre les Encouragements Eniripsa.\n\nSur une case libre : invoque une Fée de Jouvence.', 0x0896800408e3810408e48104, '1', 'Agressive'),
(25744, 'Mot Vivifiant', 'Augmente les PM et la Fuite de l\'allié ciblé et lui applique l\'état Encouragé.\nLe cumul est partagé entre les Encouragements Eniripsa.\n\nSur une case libre : invoque une Fée Vivifiante.', 0x0899800408df810408e08104, '1', 'Agressive'),
(25745, 'Mot Galvanisant', 'Augmente la Puissance de l\'allié ciblé et lui applique un bouclier et l\'état Encouragé.\nLe cumul est partagé entre les Encouragements Eniripsa.\n\nSur une case libre : invoque une Fée Galvanisante.', 0x089b8004, '1', 'Agressive'),
(25746, 'Mot de Déclin', 'Réduit la durée des effets sur l\'ennemi ciblé, lui réduit ses soins reçus et lui applique l\'état Moqué.\nLe cumul est partagé entre les Moqueries Eniripsa.\n\nSur une case libre : invoque un Feu de Déclin.', 0x089c800408e78104, '1', 'Agressive'),
(25747, 'Mot Décourageant', 'Retire de l\'Esquive PA et des PA à l\'ennemi ciblé et lui applique l\'état Moqué.\nLe cumul est partagé entre les Moqueries Eniripsa.\n\nSur une case libre : invoque un Feu Décourageant.', 0x089e8004, '1', 'Agressive'),
(25748, 'Mot Déprimant', 'Retire de la Puissance et des Dommages à l\'ennemi ciblé et lui applique l\'état Moqué.\nLe cumul est partagé entre les Moqueries Eniripsa.\n\nSur une case libre : invoque un Feu Déprimant.', 0x08a08004, '1', 'Agressive'),
(25749, 'Mot Accablant', 'Retire de l\'Esquive PM et des PM à l\'ennemi ciblé et lui applique l\'état Moqué.\nLe cumul est partagé entre les Moqueries Eniripsa.\n\nSur une case libre : invoque un Feu Accablant.', 0x08a3800408e5810408e68104, '1', 'Agressive'),
(25751, '{spell,25753,1::<font color=\"#ebc304\">Invoque une Fée Stimulante</font>}', '', 0x08a58004, '0', 'None'),
(25752, '{spell,25754,1::<font color=\"#ebc304\">Invoque un Feu Décourageant</font>}', '', 0x08a68004, '0', 'None'),
(25753, 'Fée', 'Invoque une Fée contrôlable qui peut :\n• Soigner dans son meilleur élément les alliés.\n• Échanger de position avec un allié dans l\'état Encouragé.\n• Appliquer son Encouragement sur un allié.\n\nLa Fée meurt après l\'utilisation d\'un sort, au moindre dommage subi, ou à la fin de son deuxième tour de jeu.\n\nInvoquer une Fée empêche l\'invocation d\'une autre Fée dans le même tour.', 0x08a7800408a8800408a9800408aa8004, '1', 'None'),
(25754, 'Feu Follet', 'Invoque un Feu Follet contrôlable qui peut :\n• Occasionner des dommages dans son meilleur élément d\'attaque aux ennemis.\n• Échanger de position avec un ennemi dans l\'état Moqué.\n• Appliquer sa Moquerie sur un ennemi.\n\nLe Feu Follet meurt après l\'utilisation d\'un sort, au moindre dommage subi, ou à la fin de son deuxième tour de jeu.\n\nInvoquer un Feu Follet empêche l\'invocation d\'un autre Feu Follet dans le même tour.', 0x08ab800408ac800408ad800408ae8004, '1', 'None'),
(25755, '{spell,25754,2::<font color=\"#ebc304\">Invoque un Feu de Déclin</font>}', '', 0x08af8004, '0', 'None'),
(25756, '{spell,25754,3::<font color=\"#ebc304\">Invoque un Feu Accablant</font>}', '', 0x08b08004, '0', 'None'),
(25757, '{spell,25754,4::<font color=\"#ebc304\">Invoque un Feu Déprimant</font>}', '', 0x08b18004, '0', 'None'),
