(25770, 'Compliment', 'Soigne l\'allié ciblé dans le meilleur élément du lanceur et tue la Fée.', 0x08bf8004089f830408a08304, '1', 'Agressive'),
(25771, 'Espièglerie', 'Échange de position avec l\'allié ciblé et tue la Fée.\nN\'affecte pas l\'invocateur.\n\nSur une Fiole de l\'invocateur : détruit la Fiole et tue la Fée.', 0x08c08004, '1', 'Agressive'),
