(25777, 'Insulte', 'Occasionne des dommages dans le meilleur élément d\'attaque du lanceur aux ennemis et tue le Feu Follet.', 0x08c98004089d8304089e8304, '1', 'Agressive'),
(25778, 'Moquerie Décourageante', 'Applique les effets du sort Mot Décourageant sur l\'ennemi ciblé et tue le Feu Follet.', 0x08ca8004, '1', 'Agressive'),
(25779, 'Moquerie de Déclin', 'Applique les effets du sort Mot de Déclin sur l\'ennemi ciblé et tue le Feu Follet.', 0x08cb8004, '1', 'Agressive'),
