INSERT INTO `spells` (`Id`, `Name`, `Description`, `SpellLevels`, `Verbose`, `Category`) VALUES
(25826, 'Potion Alchimique', 'Consomme le contenu de la Fiole pour soigner et augmenter les caractéristiques dans l\'élément du contenu.\n\nChaque effet se cumule une fois.', 0x08d4810408d58104, '1', 'None'),
