(25830, '{spell,25831,2::<font color=\"#ebc304\">Explosion de la Fiole</font>}', '', 0x08d98104, '1', 'None'),
(25831, 'Explosion Alchimique', 'Occasionne des dommages dans l\'élément du contenu de la Fiole aux ennemis et aux Fioles du lanceur en zone.', 0x08da810408db8104, '1', 'None'),
(25832, 'Scalpel', 'Érode l\'ennemi ciblé et lui occasionne des dommages dans le meilleur élément d\'attaque du lanceur.\nLes effets sont retirés après le lancer du sort.\n\nSur un allié : réduit la Vitalité maximale de la cible et la soigne dans le meilleur élément du lanceur.', 0x08ef810408f18104, '1', 'Debuff'),
(25833, 'Scalpel', '', 0x08f08104, '0', 'Debuff'),
(25834, 'Mot Alchimique', '', 0x08f28104, '1', 'None'),
