(25854, 'Couronne d\'Épines', '', 0x08938204, '1', 'None'),
(25855, 'Pilori', '', 0x08948204, '1', 'Agressive'),
(25856, 'Vacarme', 'Occasionne des dommages Feu aux ennemis et soigne les alliés en zone.', 0x0896820408d68204, '1', 'Agressive'),
(25857, 'Cri Assourdissant', 'Occasionne des dommages Feu et retire des PA.', 0x0897820408d58204, '1', 'Agressive'),
(25858, 'Mot Tapageur', 'Occasionne des dommages Feu aux ennemis et soigne les alliés en zone.', 0x0898820408d8820408d98204, '1', 'Agressive'),
(25859, 'Chapardage', 'Vole de la Portée à la cible et vole de la vie dans l\'élément Feu aux ennemis.', 0x0899820408db820408dc8204, '1', 'Agressive'),
(25860, 'Mot Turbulent', 'Soigne les alliés, occasionne des dommages Feu aux ennemis et leur applique l\'état Turbulent en zone :\n• À la fin du tour de la cible, repousse les entités à son contact et lui retire l\'état.', 0x089a82040893830408948304, '1', 'Agressive'),
(25861, 'Chœur Strident', 'Occasionne des dommages Feu.\nLes dommages sont augmentés à l\'application d\'une Moquerie par le lanceur (une fois par tour) ou à la mort d\'un de ses Feux Follets.\n\nLes bonus se décrémentent après utilisation du sort.', 0x089b8204, '1', 'Agressive'),
(25862, 'Mot Distrayant', 'Attire les entités vers la cible dans une croix de 3 cases et occasionne des dommages Feu à l\'ennemi ou soigne l\'allié ciblé.\nL\'attirance n\'affecte pas le lanceur.', 0x089c8204, '1', 'Agressive'),
(25863, 'Cri de Guerre', 'Augmente les Dommages Poussée du lanceur pour chaque ennemi dans la zone d\'effet et leur occasionne des dommages Terre en zone autour de lui.\n\nLes dommages ne diminuent pas avec la distance.', 0x089d82040895830408968304, '1', 'Agressive'),
(25864, 'Mot Rituel', 'Pose un glyphe-aura qui applique l\'état Peinture en zone.\nOccasionne également des dommages Terre aux ennemis dans la zone d\'effet et soigne les alliés à l\'intérieur de l\'anneau.', 0x089e8204, '1', 'Agressive'),
(25865, 'Mot Furieux', 'Occasionne des dommages Terre aux ennemis et repousse les cibles en zone.', 0x089f8204, '1', 'Agressive'),
(25866, 'Pinceau Brutal', 'Applique l\'état Peinture sur la cible.\n\nSur une cible dans l\'état : propage l\'état, occasionne des dommages Terre aux ennemis et soigne les alliés dans un cercle de 2 cases.\n\nSur le lanceur : consomme toutes les Peintures pour occasionner des dommages Terre à tous les ennemis dans l\'état.\nLes dommages sont augmentés pour chaque état consommé.', 0x08a0820408988304, '1', 'Agressive'),
(25867, 'Juron', 'Occasionne des dommages Terre aux ennemis et repousse la cible.', 0x08a1820408898304088a8304, '1', 'Agressive'),
(25868, 'Peinture de Guerre', 'Applique l\'état Peinture sur la cible et occasionne des dommages Terre aux ennemis ou soigne les alliés.\n\n<b>État Peinture :</b>\n• Si c\'est un ennemi : réduit ses Résistances Poussée.\n• Si c\'est un allié : le soigne au début de son tour.', 0x08a28204088d8304088e8304, '1', 'Agressive'),
(25869, 'Onguent Ancestral', 'Occasionne des dommages Terre aux ennemis ou soigne les alliés.\nLes entités qui attaquent l\'ennemi ciblé sont soignées d\'une partie des dommages occasionnés.', 0x08a3820408978304, '1', 'Agressive'),
(25870, 'Mot Vampirique', 'Vole de la vie dans l\'élément Eau aux ennemis ou transfère une partie des points de vie du lanceur à l\'allié ciblé.', 0x08a4820408e1820408e28204, '1', 'Agressive'),
(25871, 'Lamentations', 'Occasionne des dommages Eau aux ennemis en zone.\nSoigne les alliés dans la zone d\'effet à hauteur de 50% des dommages occasionnés aux ennemis.', 0x08a5820408e78204089c8304, '1', 'Agressive'),
(25872, 'Sanglots', 'Réduit les soins reçus par l\'ennemi ciblé et lui occasionne des dommages Eau.\nSoigne les alliés à hauteur de 50% des dommages occasionnés à l\'ennemi ciblé dans un cercle de 2 cases autour de lui.', 0x08a6820408e58204, '1', 'Agressive'),
(25873, 'Mot Interdit', 'Réduit la durée des effets sur la cible et occasionne des dommages Eau aux ennemis.', 0x08a7820408e3820408e48204, '1', 'Agressive'),
(25874, 'Fontaine de Jouvence', 'Pose un glyphe de début de tour qui occasionne des dommages Eau aux ennemis et soigne les alliés.\nRend le lanceur Intaclable et augmente les soins reçus par les alliés présents dans le glyphe.', 0x08a88204, '1', 'Mark'),
(25875, 'Cryothérapie', 'Occasionne des dommages Eau aux ennemis et applique l\'état Cryothérapie sur la cible :\n• Applique un bouclier et retire de la Fuite.\n• Si la cible perd l\'état, occasionne des dommages Eau aux ennemis et soigne les alliés dans un cercle de 2 cases.', 0x08a9820408dd8204, '1', 'Agressive'),
(25876, 'Mot Défendu', 'Occasionne des dommages Eau aux ennemis et attire les cibles en zone.', 0x08aa8204, '1', 'Agressive'),
(25877, 'Mot Espiègle', 'Occasionne des dommages Air et retire des PM.', 0x08ab820408ed820408ee8204, '1', 'Agressive'),
(25878, 'Mot Malicieux', 'Occasionne des dommages Air et applique l\'état Malice sur la cible :\n• Retire de la Puissance à la cible pour chaque PM qu\'elle utilise (cumulable 10 fois).', 0x08ac820408ea8204, '1', 'Agressive'),
(25879, 'Mot Farceur', 'Occasionne des dommages Air aux ennemis ou soigne les alliés et applique l\'état Farce sur la cible :\n• À la fin du tour de la cible, la téléporte à sa position précédente.', 0x08ad820408eb820408ec8204, '1', 'Agressive'),
(25880, 'Mot Fleuri', 'Occasionne des dommages Air aux ennemis en zone et applique l\'état Floraison sur la cible :\n• À la fin du tour de la cible, soigne les alliés dans une étoile de 2 cases et lui retire l\'état.', 0x08ae820408e98204, '1', 'Agressive'),
(25881, 'Bosquet Enchanté', 'Occasionne des dommages Air aux ennemis et soigne les alliés en zone.\nLa zone s\'étend autour des Fées du lanceur et les effets ne sont appliqués qu\'une seule fois par lancer.', 0x08af8204, '1', 'Agressive'),
(25882, 'Mot Secret', 'Occasionne des dommages Air aux ennemis et soigne les alliés en zone.\nLes dommages et soins sont augmentés à chaque début de tour après son lancer.\n\nLes effets sont réinitialisés si le sort est relancé, ou s\'il ne l\'est pas après 4 tours.', 0x08b08204, '1', 'Agressive'),
(25883, 'Murmure', 'Occasionne des dommages Air et vole des PM aux ennemis.\n\nSur un allié : soigne la cible et augmente ses PM.\nLe lanceur n\'est pas affecté par le bonus de PM.', 0x08b18204, '1', 'Agressive'),
